ANCIENT_BLESSING_MAP = {b['id']: b for b in ANCIENT_BLESSING_POOL}

def ancient_blessing_tag(char):
    """已觉醒远古意识则返回「XX后人」称号字符串，否则返回 None。
    char 可以是 dict 或 sqlite3.Row，两者均用下标访问（Row 没有 .get）。"""
    keys = char.keys()
    if 'ancient_awakened' not in keys or not char['ancient_awakened']:
        return None
    b = ANCIENT_BLESSING_MAP.get(char['ancient_blessing_id']) if 'ancient_blessing_id' in keys else None
    return f"{b['figure']}后人" if b else None

