def _register_companion(key, name, title, rarity, description, effects):
    """把一个伙伴注册进伙伴清单（COMPANION_MAP等），不绑定任何池子。
    是否能被抽到完全由"池子管理"里的池子成员关系决定。"""
    if key in COMPANION_MAP:
        return
    tup = (key, name, title, rarity, description, effects)
    COMPANION_TYPES.append(tup)
    COMPANION_MAP[key] = tup
    COMPANION_BY_RARITY.setdefault(rarity, []).append(tup)

# CUSTOM_POOLS: {pool_id: {'id','name','icon','cost','pity_max','description',
#                           'is_active','is_default','items':[{'type':'companion','key':...,'rarity':...,'weight':...}]}}
CUSTOM_POOLS = {}

def _load_custom_companions(db):
    """启动时把后台新增的限定伙伴并入伙伴清单（不涉及池子归属）。"""
    rows = db.execute("SELECT * FROM custom_companions").fetchall()
    for r in rows:
        _register_companion(
            r['key'], r['name'], r['title'], r['rarity'], r['description'],
            json.loads(r['effects_json'] or '{}'))

def _load_custom_pools(db=None):
    """从数据库重建 CUSTOM_POOLS 内存结构。db 为空时用 q()（需在请求上下文内调用）。"""
    global CUSTOM_POOLS
    if db is not None:
        pools = db.execute("SELECT * FROM custom_pools").fetchall()
    else:
        pools = q("SELECT * FROM custom_pools")
    result = {}
    for p in pools:
        if db is not None:
            members = db.execute("SELECT * FROM custom_pool_companions WHERE pool_id=?", (p['id'],)).fetchall()
        else:
            members = q("SELECT * FROM custom_pool_companions WHERE pool_id=?", (p['id'],))
        items = []
        if p['include_regular']:
            items.extend(_COMP_REGULAR)
            items.extend(_MAT)
        for m in members:
            comp = COMPANION_MAP.get(m['companion_key'])
            if comp:
                items.append({'type': 'companion', 'key': m['companion_key'],
                               'rarity': comp[3], 'weight': m['weight']})
        expired = p['ends_at'] and now_ts() > p['ends_at']
        if expired and p['is_active']:
            if db is not None:
                db.execute("UPDATE custom_pools SET is_active=0 WHERE id=?", (p['id'],))
            else:
                run("UPDATE custom_pools SET is_active=0 WHERE id=?", (p['id'],))
        result[p['id']] = {
            'id': p['id'], 'name': p['name'], 'icon': p['icon'], 'cost': p['cost'],
            'pity_max': p['pity_max'], 'description': p['description'],
            'is_active': 0 if expired else p['is_active'], 'is_default': p['is_default'],
            'ends_at': p['ends_at'], 'items': items,
        }
    CUSTOM_POOLS = result

