XISUI_STEPS = {
    "五灵根":  {"material": "洗髓丹",   "mat_qty": 1, "rate": 0.70, "stones": 2000},
    "四灵根":  {"material": "洗髓丹",   "mat_qty": 2, "rate": 0.55, "stones": 5000},
    "三灵根":  {"material": "伐经丹",   "mat_qty": 1, "rate": 0.40, "stones": 12000},
    "双灵根":  {"material": "伐经丹",   "mat_qty": 2, "rate": 0.28, "stones": 30000},
    "变异灵根":{"material": "造化神液", "material_alt": "造化灵液", "mat_qty": 1, "rate": 0.15, "stones": 80000},
}

def xisui_resolve_material(step, char_id):
    """洗髓所需材料。若配置了 material_alt（如变异灵根一档神液/灵液都能用），
    优先选持有量充足的一种；都不足则返回主材料信息用于提示。
    返回 (材料名, 物品行, 持有数量)。"""
    names = [step['material']] + ([step['material_alt']] if step.get('material_alt') else [])
    fallback = None
    for name in names:
        item = q("SELECT * FROM items WHERE name=?", (name,), one=True)
        have = 0
        if item:
            inv = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                    (char_id, item['id']), one=True)
            have = inv['quantity'] if inv else 0
        if have >= step['mat_qty']:
            return name, item, have
        if fallback is None:
            fallback = (name, item, have)
    return fallback

