def _round_desc(rd, p_name, m_name):
    bits = []
    if rd.get('heal'): bits.append(f'吸血 +{rd["heal"]}')
    if rd.get('shield_gained'): bits.append(f'吸血溢出护盾 +{rd["shield_gained"]}')
    heal = f'（{"，".join(bits)}）' if bits else ''
    if rd.get('qi'):
        t = random.choice(_QI_P)
        return f'{t}【{m_name}】{rd["dmg"]} 点{heal}'
    if rd['actor'] == 'p':
        if rd['crit']:
            t = random.choice(_CRIT_P)
            return f'【{p_name}】{t}【{m_name}】{rd["dmg"]} 点！{heal}'
        t = random.choice(_ATK_P)
        return f'【{p_name}】{t}【{m_name}】，造成 {rd["dmg"]} 点伤害。{heal}'
    else:
        if rd['dodge']:
            return f'【{p_name}】{random.choice(_DODGE_P)}'
        t = random.choice(_M_ATK_P)
        if rd.get('shield'):
            return (f'【{m_name}】{t}【{p_name}】{rd["raw_dmg"]} 点伤害，'
                     f'吸血溢出护盾吸收 {rd["shield"]}，实际受到 {rd["dmg"]} 点。')
        return f'【{m_name}】{t}【{p_name}】{rd["dmg"]} 点伤害。'

