BONE_BEASTS = ['玄武', '青龙', '朱雀', '应龙', '白虎', '麒麟', '饕餮']

def _gen_bone_names():
    parts = []
    parts += ['额骨','左顶骨','右顶骨','左颞骨','右颞骨','枕骨','蝶骨','筛骨']  # 8 颅骨
    parts += ['左鼻骨','右鼻骨','左泪骨','右泪骨','左下鼻甲','右下鼻甲',
              '左颧骨','右颧骨','左上颌骨','右上颌骨','左腭骨','右腭骨',
              '犁骨','下颌骨']  # 14 面骨
    parts.append('舌骨')
    for side in ['左','右']:
        parts += [f'{side}锤骨', f'{side}砧骨', f'{side}镫骨']  # 6 听小骨
    parts += [f'颈椎{i}' for i in range(1, 8)]    # 7
    parts += [f'胸椎{i}' for i in range(1, 13)]   # 12
    parts += [f'腰椎{i}' for i in range(1, 6)]    # 5
    parts += ['骶骨', '尾骨']                      # 2
    parts += [f'{side}第{i}肋骨' for side in ['左','右'] for i in range(1, 13)]  # 24
    parts.append('胸骨')
    parts += ['左锁骨','右锁骨','左肩胛骨','右肩胛骨']
    for side in ['左','右']:
        parts.append(f'{side}肱骨'); parts.append(f'{side}桡骨'); parts.append(f'{side}尺骨')
        parts += [f'{side}第{i}腕骨' for i in range(1, 9)]    # 8
        parts += [f'{side}第{i}掌骨' for i in range(1, 6)]    # 5
        parts += [f'{side}第{i}指骨' for i in range(1, 15)]   # 14
    parts += ['左髋骨', '右髋骨']
    for side in ['左','右']:
        parts.append(f'{side}股骨'); parts.append(f'{side}髌骨')
        parts.append(f'{side}胫骨'); parts.append(f'{side}腓骨')
        parts += [f'{side}第{i}跗骨' for i in range(1, 8)]    # 7
        parts += [f'{side}第{i}跖骨' for i in range(1, 6)]    # 5
        parts += [f'{side}第{i}趾骨' for i in range(1, 15)]   # 14
    # 每块骨头的异兽归属随机七选一，而非按部位分组
    rng = random.Random(20260704)  # 固定种子，保证名单在重启后不变
    return [f'{rng.choice(BONE_BEASTS)}之{p}' for p in parts]

XIAN_BONE_NAMES = _gen_bone_names()  # 206 个，index 即 bone_id
BONE_TOTAL = len(XIAN_BONE_NAMES)

# ── 工具函数 ───────────────────────────────────────────────────────────────────

def realm_stats(idx):
    hp  = int(100 * (1.15 ** idx))
    atk = int(10  * (1.12 ** idx))
    dfs = int(5   * (1.12 ** idx))
    return hp, atk, dfs

def major_idx(realm_idx):
    return MAJOR_REALMS.index(REALMS[realm_idx]["major"])

def rand_spirit_root():
    keys = list(SPIRIT_ROOTS)
    w    = [SPIRIT_ROOTS[k]["weight"] for k in keys]
    return random.choices(keys, weights=w, k=1)[0]

def rand_elements(root):
    n = {"天灵根":1,"变异灵根":1,"双灵根":2,"三灵根":3,"四灵根":4,"五灵根":5}[root]
    return random.sample(ELEMENTS, n)

def fmt_exp(n):
    if n >= 1_000_000_000: return f"{n/1_000_000_000:.1f}亿"
    if n >= 10_000_000:    return f"{n/10_000_000:.0f}千万"
    if n >= 10_000:        return f"{n/10_000:.1f}万"
    return str(n)

# ── 数据库 ─────────────────────────────────────────────────────────────────────

def get_db():
    db = getattr(g, '_db', None)
    if db is None:
        db = g._db = sqlite3.connect(DB_PATH)
        db.row_factory = sqlite3.Row
        db.execute("PRAGMA journal_mode=WAL")
        db.execute("PRAGMA foreign_keys=ON")
    return db

@app.teardown_appcontext
def close_db(e=None):
    db = getattr(g, '_db', None)
    if db: db.close()

def q(sql, args=(), one=False):
    cur = get_db().execute(sql, args)
    return cur.fetchone() if one else cur.fetchall()

def run(sql, args=()):
    db = get_db()
    cur = db.execute(sql, args)
    db.commit()
    return cur

# ── 邀请码 ─────────────────────────────────────────────────────────────────────

def gen_invite_code():
    import secrets
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"  # 去掉易混字符
    return "LX-" + "".join(secrets.choice(alphabet) for _ in range(8))

def valid_invite(code):
    """返回未使用的邀请码行，无效返回 None。"""
    if not code:
        return None
    return q("SELECT * FROM invite_codes WHERE code=? AND used_by IS NULL",
             (code.strip().upper(),), one=True)

def consume_invite(code, uid):
    run("UPDATE invite_codes SET used_by=?, used_at=? WHERE code=?",
        (uid, now_ts(), code.strip().upper()))

def init_db():
    with app.app_context():
        db = get_db()
        db.executescript(open(os.path.join(os.path.dirname(__file__), 'schema.sql'), encoding='utf-8').read())
        db.commit()
        _migrate()
        _seed()
        _migrate_data()
        _ensure_admin()
        _seed_npcs()
        _seed_achievements()

def _seed_npcs():
    """植入可结缘的 NPC（道侣对象）。"""
    db = get_db()
    if db.execute("SELECT 1 FROM characters WHERE is_npc=1").fetchone():
        return
    npcs = [
        # name, root, realm_idx, elements, bio
        ("苏沐瑶",   "三灵根", 9,  ["木","水"],     "药谷传人，温婉善炼丹，眉间一点朱砂痣。"),
        ("凌霜仙子", "双灵根", 14, ["水","金"],     "寒潭剑修，性子清冷，剑意凛冽如霜雪。"),
        ("赤练",     "变异灵根",15,["火","土"],     "魔道女修，明艳张扬，一身赤红惑人心魄。"),
        ("云清",     "四灵根", 10, ["土","木"],     "山野散修，朴实憨厚，最是踏实可靠。"),
        ("风惊鸿",   "天灵根", 18, ["金","水"],     "白衣剑仙，惊才绝艳，引无数修士倾慕。"),
    ]
    for name, root, realm, elems, bio in npcs:
        # 占位 user（不可登录）
        cur = db.execute(
            "INSERT INTO users (username,password_hash,role,created_at) VALUES (?,?,'npc',?)",
            (f'__npc_{name}', '!', now_ts()))
        uid = cur.lastrowid
        max_hp, _, _ = realm_stats(realm)
        db.execute("""INSERT INTO characters
            (user_id,name,spirit_root,elements,realm_idx,exp,energy,energy_updated,
             hp,hp_updated,spirit_stones,age,age_updated,status,is_npc,bio)
            VALUES (?,?,?,?,?,?,100,?,?,?,0,?,?, 'alive',1,?)""",
            (uid, name, root, json.dumps(elems), realm, REALMS[realm]['exp'],
             now_ts(), max_hp, now_ts(), START_AGE+random.randint(20,200), now_ts(), bio))
    db.commit()

def _ensure_admin():
    """确保存在管理员账号（无角色，仅用于后台）。"""
    db = get_db()
    row = db.execute("SELECT id FROM users WHERE username=?", (ADMIN_USER,)).fetchone()
    if row:
        db.execute("UPDATE users SET password_hash=?, role='admin' WHERE username=?",
                   (generate_password_hash(ADMIN_PASS, method='pbkdf2:sha256'), ADMIN_USER))
    else:
        db.execute("INSERT INTO users (username,password_hash,role,created_at) VALUES (?,?,'admin',?)",
                   (ADMIN_USER, generate_password_hash(ADMIN_PASS, method='pbkdf2:sha256'), now_ts()))
    db.commit()

