    # 始终确保历史贡献 >= 当前贡献（修复旧数据未同步的问题）
    db.execute("UPDATE sect_members SET total_contribution=contribution WHERE total_contribution < contribution")
    # sects：宗门等级 + 总贡献
    scts = {c[1] for c in db.execute("PRAGMA table_info(sects)")}
