def custom_pool_gacha_draw(char_id, pool_id, count=1):
    """后台自建限定池的通用抽取逻辑。"""
    pool_meta = CUSTOM_POOLS.get(pool_id)
    if not pool_meta or not pool_meta['is_active']:
        return [], '该召唤池未开放。'
    if not pool_meta['items']:
        return [], '该召唤池还没有伙伴，请联系管理员添加。'
    char = q("SELECT * FROM characters WHERE id=?", (char_id,), one=True)
    if not char: return [], '角色不存在'
    cost = pool_meta['cost'] * count
    if count == 10:
        cost = int(pool_meta['cost'] * 10 * 0.9)  # 十连9折，与其余池子一致
    if (char['spirit_stones'] or 0) < cost:
        return [], f'灵石不足（需 {cost}，当前 {char["spirit_stones"] or 0}）'
    run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?", (cost, char_id))
    owned = {r['companion_key'] for r in q("SELECT companion_key FROM char_companions WHERE char_id=?", (char_id,))}
    prow = q("SELECT pity FROM char_custom_pool_pity WHERE char_id=? AND pool_id=?", (char_id, pool_id), one=True)
    pity = prow['pity'] if prow else 0
    results = []
    for _ in range(count):
        entry, pity = _companion_pool_draw(pool_meta['items'], pity, pool_meta['pity_max'])
        results.append(_deliver_pool_entry(entry, char_id, char['name'], owned, force_limited=True))
    run("""INSERT INTO char_custom_pool_pity (char_id,pool_id,pity) VALUES (?,?,?)
           ON CONFLICT(char_id,pool_id) DO UPDATE SET pity=excluded.pity""", (char_id, pool_id, pity))
    return results, None

# ── 抽卡 ───────────────────────────────────────────────────────────────────────

def gacha_draw(char_id, pool_id):
    """执行一次抽卡，返回 (item_type, item_id, item_name, rarity, err)。"""
    char = q("SELECT * FROM characters WHERE id=?", (char_id,), one=True)
    pool = q("SELECT * FROM gacha_pools WHERE id=? AND is_active=1", (pool_id,), one=True)
    if not char or not pool:
        return None, 0, '', 'common', '卡池不存在'
    if (char['lingfu'] or 0) < pool['cost']:
        return None, 0, '', 'common', f'灵符不足（需 {pool["cost"]}，当前 {char["lingfu"] or 0}）'

    run("UPDATE characters SET lingfu=lingfu-? WHERE id=?", (pool['cost'], char_id))

    items = q("SELECT * FROM gacha_pool_items WHERE pool_id=? AND is_active=1", (pool_id,))
    if not items:
        return None, 0, '', 'common', '卡池暂无奖品'

    pity = (char['gacha_pity'] or 0) + 1
    # 保底
    if pity >= pool['pity_max']:
        leg = [i for i in items if i['rarity'] == 'legendary']
        chosen = random.choice(leg) if leg else random.choices(items, weights=[i['weight'] for i in items], k=1)[0]
        pity  = 0
    else:
        chosen = random.choices(items, weights=[i['weight'] for i in items], k=1)[0]
        if chosen['rarity'] == 'legendary': pity = 0

    run("UPDATE characters SET gacha_pity=? WHERE id=?", (pity, char_id))

    # 发放奖励
    itype, iid, iname = chosen['item_type'], chosen['item_id'], chosen['item_name']
    if itype == 'item':
        it = q("SELECT * FROM items WHERE id=?", (iid,), one=True)
        if it:
            iname = it['name']
            ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (char_id, iid), one=True)
            if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?", (char_id, iid))
            else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)", (char_id, iid))
    elif itype == 'pet':
        pt = q("SELECT * FROM pet_types WHERE id=?", (iid,), one=True)
        if pt:
            iname = pt['name']
            run("INSERT INTO char_pets (char_id,pet_type_id,nickname,level,obtained_at) VALUES (?,?,'',1,?)",
                (char_id, iid, now_ts()))
    elif itype == 'exp':
        run("UPDATE characters SET exp=exp+? WHERE id=?", (iid, char_id))  # iid 存 exp 数量
    elif itype == 'stones':
        run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?", (iid, char_id))
    elif itype == 'lingfu':
        run("UPDATE characters SET lingfu=lingfu+? WHERE id=?", (iid, char_id))

    run("INSERT INTO gacha_records (char_id,pool_id,item_type,item_id,item_name,rarity,created_at) VALUES (?,?,?,?,?,?,?)",
        (char_id, pool_id, itype, iid, iname, chosen['rarity'], now_ts()))

    if chosen['rarity'] == 'legendary':
        world_log_add('gacha', f'✨【{char["name"]}】从【{pool["name"]}】抽出传说级【{iname}】！')
    return itype, iid, iname, chosen['rarity'], None

def break_daolv_on_death(deceased_id, deceased_name):
    """角色（玩家或NPC）身陨时，解除所有指向它的道侣关系（daolv_id/daolv2_id/daolv3_id），并通知对方缘尽于此。"""
    for slot in ('daolv_id', 'daolv2_id', 'daolv3_id'):
        rows = q(f"SELECT id FROM characters WHERE {slot}=?", (deceased_id,))
        for r in rows:
            run(f"UPDATE characters SET {slot}=NULL WHERE id=?", (r['id'],))
            log(r['id'], 'system', f'道侣【{deceased_name}】已仙逝，缘尽于此。')

# ── NPC 成长 ───────────────────────────────────────────────────────────────────

def tick_npcs():
    """每小时最多触发一次，推进所有 NPC 的修炼成长。"""
    last_row = q("SELECT value FROM site_config WHERE key='npc_last_tick'", one=True)
    if last_row and now_ts() - int(last_row['value']) < 3600:
        return
    run("INSERT OR REPLACE INTO site_config (key,value) VALUES ('npc_last_tick',?)", (str(now_ts()),))

    npcs = q("SELECT * FROM characters WHERE is_npc=1 AND status='alive'")
    for npc in npcs:
        elapsed = now_ts() - (npc['age_updated'] or now_ts())
        years   = elapsed // SECONDS_PER_YEAR
        if years <= 0: continue

        mult     = SPIRIT_ROOTS.get(npc['spirit_root'], {}).get('mult', 1.0)
        exp_gain = int(years * SECLUSION_ACTIVE_RATE * mult * 0.2)  # NPC 按玩家 20% 速度成长
        new_exp  = npc['exp'] + exp_gain
        new_age  = npc['age'] + years
        new_realm = npc['realm_idx']
        while new_realm < len(REALMS)-1 and new_exp >= REALMS[new_realm+1]['exp']:
            new_realm += 1
        if new_realm > npc['realm_idx']:
            world_log_add('npc', f'【{npc["name"]}】突破至{REALMS[new_realm]["name"]}！')
        new_hp, _, _ = realm_stats(new_realm)
        run("UPDATE characters SET exp=?,realm_idx=?,age=?,age_updated=age_updated+?,hp=? WHERE id=?",
            (new_exp, new_realm, new_age, years * SECONDS_PER_YEAR, new_hp, npc['id']))
        # 寿元检查
        npc_updated = q("SELECT * FROM characters WHERE id=?", (npc['id'],), one=True)
        if npc_updated and new_age > lifespan(npc_updated):
            run("UPDATE characters SET status='deceased' WHERE id=?", (npc['id'],))
            world_log_add('npc', f'【{npc["name"]}】寿元耗尽，含笑而逝……')
            break_daolv_on_death(npc['id'], npc['name'])

# ── 玩家关系 / 好感 / 双修 ──────────────────────────────────────────────────────

def _pair(a, b):
    """归一化一对角色 id，小的在前。"""
    return (a, b) if a <= b else (b, a)

def get_relationship(a, b):
    """取一对角色的关系行，不存在则创建。"""
    ca, cb = _pair(a, b)
    rel = q("SELECT * FROM relationships WHERE char_a=? AND char_b=?", (ca, cb), one=True)
    if not rel:
        run("INSERT OR IGNORE INTO relationships (char_a,char_b,affinity,updated_at) VALUES (?,?,0,?)",
            (ca, cb, now_ts()))
        rel = q("SELECT * FROM relationships WHERE char_a=? AND char_b=?", (ca, cb), one=True)
    return rel

def add_affinity(a, b, amount):
    ca, cb = _pair(a, b)
    get_relationship(a, b)
    bonus = perk_total(a, 'affinity_pct')
    if bonus:
        amount = int(amount * (1 + bonus))
    run("UPDATE relationships SET affinity=affinity+?, updated_at=? WHERE char_a=? AND char_b=?",
        (amount, now_ts(), ca, cb))

def affinity_label(val):
    label = AFFINITY_LEVELS[0][1]
    for thresh, name in AFFINITY_LEVELS:
        if val >= thresh:
            label = name
    return label

def _char_affinity_map(char_id):
    """返回 {对方char_id: {'val':好感值,'label':好感称谓}}，覆盖该角色已有的全部关系记录。"""
    rows = q("SELECT char_a, char_b, affinity FROM relationships WHERE char_a=? OR char_b=?",
             (char_id, char_id))
    result = {}
    for r in rows:
        other_id = r['char_b'] if r['char_a'] == char_id else r['char_a']
        result[other_id] = {'val': r['affinity'], 'label': affinity_label(r['affinity'])}
    return result

DAOLV_AFFINITY   = 500   # 结道侣所需好感（情投意合）
DAOLV_SHUANGXIU_BONUS  = 0.30  # 道侣双修额外 +30%
SHIFU_SHUANGXIU_MULT   = 2.0   # 与师父双修，徒弟收益 ×2
TONGXIN_PCT      = 0.30   # 战斗同心：取道侣攻防的比例

def get_daolv(char):
    """返回角色的道侣角色行（玩家或 NPC），无则 None。"""
    if not char['daolv_id']:
        return None
    return q("SELECT * FROM characters WHERE id=?", (char['daolv_id'],), one=True)

def is_daolv_pair(a, b):
    ca, cb = _pair(a, b)
    rel = q("SELECT is_daolv FROM relationships WHERE char_a=? AND char_b=?", (ca, cb), one=True)
    return bool(rel and rel['is_daolv'])

def wuxing_factor(elems_a, elems_b):
    """
    取两人五行的最佳关系系数。
    返回 (系数, 描述, 是否相克)。相生 ×1.5、同属 ×1.2、无关 ×1.0、相克 ×0.6。
    优先级：相生 > 同属 > 无关 > 相克（取对双方最有利的一对元素）。
    """
    if not elems_a or not elems_b:
        return 1.0, "无关", False
    def _base(e): return SPECIAL_ELEMENT_SOURCES.get(e, e)
    best = None
    rank = {"相生": 3, "同属": 2, "无关": 1, "相克": 0}
    for ea in elems_a:
        for eb in elems_b:
            ea, eb = _base(ea), _base(eb)
            if WUXING_SHENG.get(ea) == eb or WUXING_SHENG.get(eb) == ea:
                cand = (1.5, "相生", False)
            elif ea == eb:
                cand = (1.2, "同属", False)
            elif WUXING_KE.get(ea) == eb or WUXING_KE.get(eb) == ea:
                cand = (0.6, "相克", True)
            else:
                cand = (1.0, "无关", False)
            if best is None or rank[cand[1]] > rank[best[1]]:
                best = cand
    return best

def spell_max(realm_idx):
    for threshold, cap in SPELL_MAX_REALM:
        if realm_idx >= threshold:
            return cap
    return 1

def get_spell_bonuses(char_id):
    """汇总所有已学法术的战斗加成（按熟练度缩放）。"""
    spells = q("SELECT element, mastery FROM char_spells WHERE char_id=? AND learned=1", (char_id,))
    out = {'atk_pct': 0.0, 'def_pct': 0.0, 'crit_rate': 0.0, 'dodge': 0.0, 'lifesteal': 0.0}
    for sp in spells:
        eff = SPELL_ELEMENT_EFFECTS.get(sp['element'], {})
        m   = (sp['mastery'] or 0) / 100
        for k, v in eff.items():
            out[k] = round(out.get(k, 0) + v * m, 4)
    return out

def get_move_bonuses(char_id):
    """汇总所有法术招式的战斗加成。"""
    moves = q("SELECT buff1_key,buff1_val,buff2_key,buff2_val FROM char_spell_moves WHERE char_id=?", (char_id,))
    out = {'atk_pct':0.0,'def_pct':0.0,'crit_rate':0.0,'dodge':0.0,'lifesteal':0.0,'crit_dmg':0.0}
    for mv in moves:
        out[mv['buff1_key']] = round(out[mv['buff1_key']] + mv['buff1_val'], 4)
        out[mv['buff2_key']] = round(out[mv['buff2_key']] + mv['buff2_val'], 4)
    return out

def check_spells_on_xisui(char_id, new_elements):
    """洗髓改变灵根后，失效法术自动转换为随机可用属性，保留熟练度。"""
    new_set = set(new_elements)
    if not new_set:
        return
    spells = q("SELECT * FROM char_spells WHERE char_id=?", (char_id,))

    # 记录已有有效法术占用的属性，避免转换后重复
    used_elems = set()
    for sp in spells:
        elem = sp['element']
        base = SPECIAL_ELEMENT_SOURCES.get(elem, elem)
        if base in new_set or elem in new_set:
            used_elems.add(elem)

    for sp in spells:
        elem = sp['element']
        base = SPECIAL_ELEMENT_SOURCES.get(elem, elem)
        if base not in new_set and elem not in new_set:
            candidates = [e for e in new_elements if e not in used_elems]
            if not candidates:
                candidates = list(new_elements)
            new_elem = random.choice(candidates)
            used_elems.add(new_elem)
            run("UPDATE char_spells SET element=? WHERE id=?", (new_elem, sp['id']))
            old_name = sp['custom_name'] or SPELL_ELEMENT_NAMES.get(elem, '法术')
            new_name = SPELL_ELEMENT_NAMES.get(new_elem, new_elem)
            if sp['learned']:
                log(char_id, 'system',
                    f'灵根变化，法术【{old_name}】属性转化为【{new_name}】，熟练度保留。')
            else:
                log(char_id, 'system',
                    f'灵根变化，正在领悟的法术感应转化为【{new_name}】，继续领悟。')

def combat_wuxing(atk_elems, def_elems):
    """返回 (攻击方伤害倍率, 描述)。普通克制 +/-12%，特殊变体克制按 ×1.5 权重计算（更强）。"""
    if not atk_elems or not def_elems:
        return 1.0, ''
    # 特殊变体映射回基础元素用于克制判断
    def _base(e): return SPECIAL_ELEMENT_SOURCES.get(e, e)
    def_bases = [_base(e) for e in def_elems]
    atk_bases = [_base(e) for e in atk_elems]
    # 特殊变体克制权重 1.5，普通 1.0
    SPECIAL_W = 1.5
    ke     = sum((SPECIAL_W if ea in SPECIAL_ELEMENT_SOURCES else 1.0)
                 for ea in atk_elems if WUXING_KE.get(_base(ea)) in def_bases)
    be_ked = sum((SPECIAL_W if ed in SPECIAL_ELEMENT_SOURCES else 1.0)
                 for ed in def_elems if WUXING_KE.get(_base(ed)) in atk_bases)
    net = ke - be_ked
    if net > 0:
        m = min(1.5, 1.0 + net * 0.12)
        return m, f'克敌 +{int((m-1)*100)}%'
    elif net < 0:
        m = max(0.6, 1.0 + net * 0.12)
        return m, f'受克 {int((m-1)*100)}%'
    return 1.0, ''

def daily_count(char_id, key):
    day = datetime.now(TZ).strftime("%Y-%m-%d")
    row = q("SELECT count FROM daily_counters WHERE char_id=? AND key=? AND day=?",
            (char_id, key, day), one=True)
    return row['count'] if row else 0

def daily_inc(char_id, key, amount=1):
    day = datetime.now(TZ).strftime("%Y-%m-%d")
    run("""INSERT INTO daily_counters (char_id,key,day,count) VALUES (?,?,?,?)
        ON CONFLICT(char_id,key,day) DO UPDATE SET count=count+?""",
        (char_id, key, day, amount, amount))

def get_cauldron_bonus(char):
    """当前丹炉对炼丹成功率的加成（0.0 ~ 1.0）。"""
    if not char['cauldron_id']:
        return 0.0
    c = q("SELECT effect_json FROM items WHERE id=?", (char['cauldron_id'],), one=True)
    return json.loads(c['effect_json'] or '{}').get('success_rate', 0.0) if c else 0.0

def get_pet_bonus(char):
    """出战宠物的战斗加成。御灵修额外：+15%/等级的灵兽效果加成 + 双槽出战。"""
    out = {"atk_pct": 0, "def_pct": 0, "crit_rate": 0.0,
           "dodge_rate": 0.0, "lifesteal": 0.0, "pet": None, "pet2": None}

    beast_mult = 1.0
    try:
        if char['beast_token_id']:
            blv, _, _, _, _ = beast_level_info(char)
            beast_mult = 1.0 + blv * 0.15
    except (KeyError, IndexError):
        pass

    def _apply(pet_id, slot_key):
        pet = q("""SELECT p.*, pt.name as type_name, pt.effect_json, pt.rarity, pt.description
            FROM char_pets p JOIN pet_types pt ON pt.id=p.pet_type_id
            WHERE p.id=? AND p.char_id=?""", (pet_id, char['id']), one=True)
        if not pet:
            return
        eff   = json.loads(pet['effect_json'] or '{}')
        scale = (1 + (pet['level'] - 1) * 0.10) * beast_mult
        out["atk_pct"]    = round(out["atk_pct"]    + eff.get('atk_pct',    0) * scale, 1)
        out["def_pct"]    = round(out["def_pct"]     + eff.get('def_pct',    0) * scale, 1)
        out["crit_rate"]  = round(out["crit_rate"]   + eff.get('crit_rate',  0) * scale, 3)
        out["dodge_rate"] = round(out["dodge_rate"]  + eff.get('dodge',      0) * scale, 3)
        out["lifesteal"]  = round(out["lifesteal"]   + eff.get('lifesteal',  0) * scale * 100, 1)
        if pet['is_branded'] and pet['brand_buff_key']:
            bkey = pet['brand_buff_key']
            if bkey == 'atk_pct':
                out["atk_pct"] = round(out["atk_pct"] + BEAST_BRAND_BUFF_PCT * 100 * scale, 1)
            elif bkey == 'def_pct':
                out["def_pct"] = round(out["def_pct"] + BEAST_BRAND_BUFF_PCT * 100 * scale, 1)
            elif bkey == 'crit_rate':
                out["crit_rate"] = round(out["crit_rate"] + BEAST_BRAND_BUFF_PCT * scale, 3)
            elif bkey == 'lifesteal':
                out["lifesteal"] = round(out["lifesteal"] + BEAST_BRAND_BUFF_PCT * scale * 100, 1)
        out[slot_key] = pet

    if char['active_pet_id']:
        _apply(char['active_pet_id'], "pet")
    if char.get('active_pet2_id') and (char.get('beast_token_id') or char.get('spirit_pass_id')):
        _apply(char['active_pet2_id'], "pet2")

    return out

