def login_required(f):
    @wraps(f)
    def w(*a, **kw):
        if 'uid' not in S: return redirect(url_for('login'))
        return f(*a, **kw)
    return w

def admin_required(f):
    @wraps(f)
    def w(*a, **kw):
        if S.get('role') != 'admin':
            flash('无权访问', 'error')
            return redirect(url_for('dashboard'))
        return f(*a, **kw)
    return w

def me():
    uid = S.get('uid')
    row = q("SELECT * FROM characters WHERE user_id=?", (uid,), one=True) if uid else None
    return dict(row) if row else None

# 这些 endpoint 不触发时间推进 / 不被身陨拦截
_TICK_SKIP = {'static', 'logout', 'login', 'admin_login', 'register', 'index',
              'memorial', 'reincarnate', 'calendar', 'rankings'}

@app.route('/maintenance')
def maintenance_page():
    row = q("SELECT value FROM site_config WHERE key='maintenance_msg'", one=True)
    msg = row['value'] if row else '服务器维护中，请稍后再来。'
    return render_template('maintenance.html', msg=msg), 503

@app.before_request
def _tick_and_gate():
    # 停服维护模式：非管理员一律跳到维护页
    is_admin = S.get('role') == 'admin'
    is_public = request.endpoint in ('maintenance_page', 'static', 'login', 'admin_login', 'logout', 'register')
    is_admin_route = (request.path or '').startswith('/admin')
    if not is_admin and not is_public and not is_admin_route:
        maint = q("SELECT value FROM site_config WHERE key='maintenance_mode'", one=True)
        if maint and maint['value'] == '1':
            return redirect(url_for('maintenance_page'))
    if 'uid' not in S:
        return
    ep = request.endpoint
    if ep in _TICK_SKIP:
        return
    char = me()
    if not char:
        return
    if char['status'] == 'alive':
        # 闭关结算
        if char['seclusion_start'] and now_ts() >= (char['seclusion_end'] or 0):
            if resolve_seclusion(char['id']):
                char = me()
        # 子嗣成熟
        check_offspring_mature(char['id'])
        # 妖王超时结算
        boss_check_expired()
        # 宗门5天未晋内门弟子自动遣返
        _sm = q("""SELECT sm.*, s.id as sid, s.name as sname
            FROM sect_members sm JOIN sects s ON s.id=sm.sect_id
            WHERE sm.char_id=? AND sm.rank='member' AND (sm.cult_rank IS NULL OR sm.cult_rank=0)
            AND sm.joined_at>0 AND ?-sm.joined_at > 5*86400""",
            (char['id'], now_ts()), one=True)
        if _sm:
            run("DELETE FROM sect_members WHERE char_id=? AND sect_id=?", (char['id'], _sm['sid']))
            run("INSERT OR REPLACE INTO sect_join_cooldowns (char_id,sect_id,ban_until) VALUES (?,?,?)",
                (char['id'], _sm['sid'], now_ts() + 2*86400))
            log(char['id'], 'social',
                f'你加入宗门「{_sm["sname"]}」已满5天，未能晋升内门弟子，已被遣返。2天内不得重新加入。')
            world_log_add('sect', f'【{char["name"]}】因未能按时晋升，被宗门「{_sm["sname"]}」遣返。')
            char = me()
        # 仙人试炼自动结算
        _es = get_enlighten_session(char['id'])
        if _es and not _es['resolved'] and now_ts() >= _es['started_at'] + ENLIGHTEN_DURATION_SECS:
            resolve_enlighten(char['id'])
        tick_npcs()
        advance_time(char)
        char = me()
        # 成就检查（每5分钟一次）
        last = S.get('_ach_ts', 0)
        if now_ts() - last > 300:
            newly = check_achievements(char['id'])
            S['_ach_ts'] = now_ts()
            for a in newly:
                flash(f'🏆 成就达成：【{a["name"]}】{a["description"]} +{a["reward_stones"]} 灵石', 'success')
        # 丹修达「化神丹宗」及以上：每日 60% 概率获赠造化灵液一份（邮件发放），累计获赠满5份后不再获赠
        if (char['alchemy_level'] or 0) >= ALCHEMY_LIQUID_GIFT_LEVEL and daily_count(char['id'], ALCHEMY_LIQUID_GIFT_KEY) == 0:
            daily_inc(char['id'], ALCHEMY_LIQUID_GIFT_KEY)
            _gift_total_row = q("SELECT count FROM daily_counters WHERE char_id=? AND key=? AND day='total'",
                (char['id'], ALCHEMY_LIQUID_GIFT_TOTAL_KEY), one=True)
            _gift_total = _gift_total_row['count'] if _gift_total_row else 0
            if _gift_total < ALCHEMY_LIQUID_GIFT_MAX_TOTAL and random.random() < ALCHEMY_LIQUID_GIFT_CHANCE:
                liquid = q("SELECT id FROM items WHERE name='造化灵液'", one=True)
                if liquid:
                    run("""INSERT INTO daily_counters (char_id,key,day,count) VALUES (?,?,'total',1)
                        ON CONFLICT(char_id,key,day) DO UPDATE SET count=count+1""",
                        (char['id'], ALCHEMY_LIQUID_GIFT_TOTAL_KEY))
                    send_system_mail(char['id'], '🧪 丹道感应',
                        '你的丹道修为已臻化神丹宗之境，今日打坐炼丹之际偶有所感，'
                        '天地造化灵液自行凝聚一份，随信奉上。',
                        item_id=liquid['id'], item_qty=ALCHEMY_LIQUID_GIFT_QTY)
        # 修为硬上限：不论是否已飞升，任何途径多出的修为一律清回上限
        if (char['exp'] or 0) > GLOBAL_EXP_CAP:
            run("UPDATE characters SET exp=? WHERE id=?", (GLOBAL_EXP_CAP, char['id']))
            char = me()
        # 修为圆满倒计时：达真仙门槛后 12 个时辰内须突破飞升，否则灰飞烟灭
        if not is_ascended(char):
            if (char['exp'] or 0) >= XIAN_EXP_THRESHOLD:
                if not char['exp_cap_reached_at']:
                    run("UPDATE characters SET exp_cap_reached_at=? WHERE id=?", (now_ts(), char['id']))
                    log(char['id'], 'system',
                        f'✦ 修为已臻真仙门槛！十二个时辰内若不能突破飞升，恐将道基崩碎，灰飞烟灭！')
                elif now_ts() - char['exp_cap_reached_at'] > ASCEND_GRACE_SECS:
                    run("UPDATE characters SET status='deceased' WHERE id=?", (char['id'],))
                    log(char['id'], 'system', '修为盈满真仙门槛却未能及时突破飞升，道基崩碎，灰飞烟灭……')
                    world_log_add('system', f'【{char["name"]}】修为盈满真仙门槛却未能及时突破，灰飞烟灭，道消身陨。')
                    break_daolv_on_death(char['id'], char['name'])
                    char = me()
            elif char['exp_cap_reached_at']:
                run("UPDATE characters SET exp_cap_reached_at=0 WHERE id=?", (char['id'],))
        else:
            # 真仙神庙：每小时一次朝拜，代替际遇
            if now_ts() - (char['temple_last_worship'] or 0) >= TEMPLE_WORSHIP_INTERVAL:
                run("UPDATE characters SET temple_last_worship=? WHERE id=?", (now_ts(), char['id']))
                temple_generate_visit(char['id'])
    if char['status'] == 'deceased':
        return redirect(url_for('memorial'))
    if char['status'] == 'alive' and is_ascended(char) and ep in XIAN_LOCKED_ENDPOINTS:
        if ep == 'explore':
            return redirect(url_for('mortal_watch'))
        flash('道行已然圆满，此道对你已无需再行', 'info')
        return redirect(url_for('dashboard'))

# ── 日志 ───────────────────────────────────────────────────────────────────────

def log(char_id, typ, content):
    run("INSERT INTO char_logs (char_id,type,content,created_at) VALUES (?,?,?,?)",
        (char_id, typ, content, now_ts()))

# ── 年龄 / 寿元 / 奇遇 ──────────────────────────────────────────────────────────

def lifespan(char):
    """角色寿元上限（岁）= 境界基础 + 每重小境界增益 + 奇遇/感悟增益 - 已典当年数。"""
    major = REALMS[char['realm_idx']]['major']
    base  = LIFESPAN_BY_MAJOR.get(major, 120)
    return base + char['realm_idx'] * 20 + (char['lifespan_bonus'] or 0) - (char['life_sold_total'] or 0)

def apply_effects(char_id, effects):
    """对角色施加一组效果，返回描述文字列表。char_id 需重新取最新行。"""
    char = q("SELECT * FROM characters WHERE id=?", (char_id,), one=True)
    parts = []
    if not char or not effects:
        return parts

    if 'exp' in effects:
        amt = effects['exp']
        if amt >= 0:
            gained = int(amt * (1 + char['realm_idx'] * 0.1))
            run("UPDATE characters SET exp=exp+? WHERE id=?", (gained, char_id))
            parts.append(f'修为 +{gained}')
        else:
            from_exp = REALMS[char['realm_idx']]['exp']
            loss = int(-amt * (1 + char['realm_idx'] * 0.1))
            run("UPDATE characters SET exp=? WHERE id=?", (max(from_exp, char['exp'] - loss), char_id))
            parts.append(f'修为 -{loss}')

    if 'stones' in effects:
        amt = effects['stones']
        if amt < 0:
            amt = -min(-amt, char['spirit_stones'])  # 不扣成负
        run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?", (amt, char_id))
        parts.append(f'灵石 {"+" if amt>=0 else ""}{amt}')

    if 'hp_pct' in effects:
        max_hp, _, _ = realm_stats(char['realm_idx'])
        max_hp += bone_hp_bonus(char_id)
        delta  = int(max_hp * effects['hp_pct'] / 100)
        hp_now = cur_hp(char)
        set_hp(char_id, max(1, min(max_hp, hp_now + delta)))
        parts.append(f'气血 {"+" if delta>=0 else ""}{delta}')

    if 'energy' in effects:
        en = cur_energy(char)
        set_energy(char_id, max(0, min(energy_cap(char), en + effects['energy'])))
        parts.append(f'灵力 {"+" if effects["energy"]>=0 else ""}{effects["energy"]}')

    if 'lifespan' in effects:
        run("UPDATE characters SET lifespan_bonus=lifespan_bonus+? WHERE id=?", (effects['lifespan'], char_id))
        parts.append(f'寿元 +{effects["lifespan"]} 年')

    if 'item' in effects:
        it = q("SELECT * FROM items WHERE name=?", (effects['item'],), one=True)
        if it:
            ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (char_id, it['id']), one=True)
            if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?", (char_id, it['id']))
            else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)", (char_id, it['id']))
            parts.append(f'获得【{it["name"]}】')
        else:
            pt = q("SELECT * FROM pet_types WHERE name=?", (effects['item'],), one=True)
            if pt:
                run("INSERT INTO char_pets (char_id,pet_type_id,nickname,level,obtained_at) VALUES (?,?,'',1,?)",
                    (char_id, pt['id'], now_ts()))
                parts.append(f'收服灵兽【{pt["name"]}】')
    return parts

def _roll_outcome(option):
    """从一个选项里解析最终 effects 与文本（支持 outcomes 随机分支）。"""
    if 'outcomes' in option:
        outs = option['outcomes']
        chosen = random.choices(outs, weights=[o.get('weight', 1) for o in outs], k=1)[0]
        return chosen.get('effects', {}), chosen.get('text', '')
    return option.get('effects', {}), option.get('text', '')

def generate_encounter(char):
    """按角色境界从奇遇池抽取一个奇遇；即时型立即结算，选择型入队。"""
    pool = [e for e in ENCOUNTER_POOL
            if e['realm_min'] <= char['realm_idx'] <= e['realm_max']]
    if not pool:
        return
    e = random.choices(pool, weights=[x['weight'] for x in pool], k=1)[0]
    age = char['age']

    if e['kind'] == 'instant':
        parts  = apply_effects(char['id'], e.get('effects', {}))
        result = '；'.join(parts) if parts else '并无所获'
        run("""INSERT INTO encounters (char_id,age,kind,title,narrative,status,result_text,created_at)
            VALUES (?,?,?,?,?,'auto',?,?)""",
            (char['id'], age, 'instant', e['title'], e['narrative'], result, now_ts()))
        log(char['id'], 'encounter', f'{age}岁·{e["title"]}：{result}。')
    else:
        # 选择型：仅存选项标签供前端展示，效果在处理时结算
        opts = [{'label': o['label']} for o in e['options']]
        run("""INSERT INTO encounters (char_id,age,kind,title,narrative,status,options_json,created_at)
            VALUES (?,?,?,?,?,'pending',?,?)""",
            (char['id'], age, 'choice', e['title'], e['narrative'], json.dumps(opts), now_ts()))
        log(char['id'], 'encounter', f'{age}岁·{e["title"]}：一桩际遇待你抉择。')

def _find_pool_choice(title):
    for e in ENCOUNTER_POOL:
        if e['kind'] == 'choice' and e['title'] == title:
            return e
    return None

