def superior_auction_slots(db=None):
    """当前每日拍卖位数量：优先读取后台配置 site_config['superior_auction_slots']，否则用默认常量。
    db 传入现有连接时供后台线程使用（无 Flask 请求上下文，不能走 q()）。"""
    try:
        if db is not None:
            row = db.execute("SELECT value FROM site_config WHERE key='superior_auction_slots'").fetchone()
        else:
            row = q("SELECT value FROM site_config WHERE key='superior_auction_slots'", one=True)
        if row and row['value']:
            return max(1, int(row['value']))
    except Exception:
        pass
    return SUPERIOR_AUCTION_SLOTS

def superior_auction_bids(auction_id):
    """按出价从高到低返回该拍卖的所有出价（含全部竞拍者，用于结算与前三名展示）。"""
    return q("""SELECT b.*, c.name as char_name FROM superior_auction_bids b
        JOIN characters c ON c.id=b.char_id
        WHERE b.auction_id=? ORDER BY b.amount DESC""", (auction_id,))

def superior_auction_min_bid(auction_id, start_price):
    top = q("SELECT MAX(amount) as m FROM superior_auction_bids WHERE auction_id=?", (auction_id,), one=True)
    highest = top['m'] if top and top['m'] is not None else 0
    return max(start_price, highest + SUPERIOR_AUCTION_MIN_STEP)

