YUANSHEN_REALM_MIN  = 25     # 合体初期，realm_idx 从0起算
YUANSHEN_ENERGY_BASE = 200   # 每次温养基础灵力消耗
YUANSHEN_ENERGY_STEP = 20    # 每级额外增加的灵力消耗
YUANSHEN_MAT_BASE    = 10    # 基础材料总数（不含初级材料）
YUANSHEN_MAT_STEP    = 2     # 每级额外增加的材料总数
YUANSHEN_STONE_BASE  = 30_000   # 基础灵石消耗
YUANSHEN_STONE_STEP  = 30_000   # 每级额外增加的灵石消耗
YUANSHEN_ATK_PER_LV  = 15    # 每级增加的基础攻击（乘算buff之前直接相加）
YUANSHEN_DEF_PER_LV  = 15    # 每级增加的基础防御（乘算buff之前直接相加）
# 温养材料池：血参、寒玉
YUANSHEN_MATERIALS = ["血参", "寒玉"]

def yuanshen_unlocked(char):
    """搬迁至高级山峰后才开启元神系统入口。"""
    return (char['cave_peak'] or 0) in CAVE_PEAK_ADVANCED_IDS

def yuanshen_next_cost(level):
    """返回从 level 温养至 level+1 所需 (灵石, 灵力, [(材料名,数量),...])。"""
    nxt = level + 1
    stones = YUANSHEN_STONE_BASE * nxt
    energy = YUANSHEN_ENERGY_BASE + (nxt - 1) * YUANSHEN_ENERGY_STEP
    qty_total = YUANSHEN_MAT_BASE + (nxt - 1) * YUANSHEN_MAT_STEP
    i1 = (nxt - 1) * 2 % len(YUANSHEN_MATERIALS)
    i2 = (i1 + 1) % len(YUANSHEN_MATERIALS)
    m1, m2 = YUANSHEN_MATERIALS[i1], YUANSHEN_MATERIALS[i2]
    q1 = -(-qty_total // 2)  # 向上取整
    q2 = qty_total - q1
    mats = [(m1, q1)] if m1 == m2 else [(m1, q1), (m2, q2)]
    return stones, energy, mats

def get_yuanshen_bonus(char):
    """元神加成：直接相加的基础攻防，在百分比buff结算前生效。"""
    lv = char['yuanshen_level'] or 0
    return {'atk': lv * YUANSHEN_ATK_PER_LV, 'def': lv * YUANSHEN_DEF_PER_LV}

