def cave_pool_params(decor, advanced=False):
    """按豪华度返回珍宝池参数 (interval秒, drop_min, drop_max, pool_cap)。
    高级洞府无论处于哪一档，每次生成额外+3样，池子上限也相应+3。"""
    if decor >= 800:
        interval = 1 * 3600;     drop_min, drop_max = 4, 6; pool_cap = 60
    elif decor >= 700:
        interval = 1.5 * 3600;   drop_min, drop_max = 3, 5; pool_cap = 55
    elif decor >= 600:
        interval = 2 * 3600;     drop_min, drop_max = 3, 5; pool_cap = 50
    elif decor >= 500:
        interval = 2.5 * 3600;   drop_min, drop_max = 3, 4; pool_cap = 45
    elif decor >= 400:
        interval = 3 * 3600;     drop_min, drop_max = 2, 4; pool_cap = 40
    elif decor >= 300:
        interval = 3.5 * 3600;   drop_min, drop_max = 2, 3; pool_cap = 36
    elif decor >= 200:
        interval = 4.5 * 3600;   drop_min, drop_max = 1, 3; pool_cap = 33
    else:
        interval = 6 * 3600;     drop_min, drop_max = 1, 2; pool_cap = 30
    if advanced:
        drop_min += 3
        drop_max += 3
        pool_cap += 3
    return interval, drop_min, drop_max, pool_cap

def generate_cave_pool(char_id, decor):
    """为珍宝池生成新掉落，按豪华度决定频率和数量。"""
    if decor < CAVE_POOL_UNLOCK:
        return
    import sqlite3 as _sq3
    db2 = _sq3.connect(DB_PATH)
    db2.row_factory = _sq3.Row
    char = db2.execute("SELECT cave_pool_updated, cave_advanced FROM characters WHERE id=?", (char_id,)).fetchone()
    if not char:
        db2.close(); return

    interval, drop_min, drop_max, pool_cap = cave_pool_params(decor, bool(char['cave_advanced']))

    last = char['cave_pool_updated'] or 0
    if now_ts() - last < interval:
        db2.close(); return

    # 检查池子是否已满
    pool_count = db2.execute("SELECT SUM(quantity) s FROM cave_pool WHERE char_id=?",
                             (char_id,)).fetchone()['s'] or 0
    if pool_count >= pool_cap:
        db2.execute("UPDATE characters SET cave_pool_updated=? WHERE id=?", (now_ts(), char_id))
        db2.commit(); db2.close(); return

    # 生成掉落
    n = random.randint(drop_min, drop_max)
    n = min(n, pool_cap - pool_count)
    names  = [d[0] for d in CAVE_POOL_DROPS]
    weights= [d[1] for d in CAVE_POOL_DROPS]
    chosen = random.choices(names, weights=weights, k=n)
    for name in chosen:
        item = db2.execute("SELECT id FROM items WHERE name=?", (name,)).fetchone()
        if item:
            ex = db2.execute("SELECT id, quantity FROM cave_pool WHERE char_id=? AND item_id=?",
                             (char_id, item['id'])).fetchone()
            if ex:
                db2.execute("UPDATE cave_pool SET quantity=quantity+1 WHERE id=?", (ex['id'],))
            else:
                db2.execute("INSERT INTO cave_pool (char_id,item_id,quantity,added_at) VALUES (?,?,1,?)",
                            (char_id, item['id'], now_ts()))
    db2.execute("UPDATE characters SET cave_pool_updated=? WHERE id=?", (now_ts(), char_id))
    db2.commit()
    db2.close()

def furniture_bonus(char_id, key):
    """汇总角色已装备家具对指定属性的加成（仅 is_equipped=1）。"""
    purchases = q("SELECT item_key FROM cave_purchases WHERE char_id=? AND is_equipped=1", (char_id,))
    total = 0.0
    for p in purchases:
        f = FURNITURE_MAP.get(p['item_key'])
        if f:
            total += f.get('bonus', {}).get(key, 0.0)
    return total

def cave_level(char):
    """洞府等级 = 装饰值 // 100，每级+5%修炼产出。"""
    return (char.get('cave_decor') or 0) // CAVE_DECOR_PER_LV

def cave_slots_for(char):
    """家具装备槽位数：高级洞府 7 个，普通洞府 5 个。"""
    return CAVE_SLOTS_ADVANCED if char.get('cave_advanced') else CAVE_SLOTS

def cave_advanced_slots_left():
    """全服高级洞府剩余名额（先到先得，永久占用不释放）。"""
    used = q("SELECT COUNT(*) n FROM characters WHERE cave_advanced=1 AND is_npc=0", one=True)['n']
    return max(0, CAVE_ADVANCED_SLOTS_TOTAL - used)

def cave_advanced_price():
    """当前晋升高级洞府所需上等灵石：前 CAVE_ADVANCED_SLOTS_BASE 个名额为基础价，
    售完后剩余的加价名额（第 {BASE+1}~{TOTAL} 个）价格更高。"""
    used = q("SELECT COUNT(*) n FROM characters WHERE cave_advanced=1 AND is_npc=0", one=True)['n']
    return CAVE_ADVANCED_PRICE if used < CAVE_ADVANCED_SLOTS_BASE else CAVE_ADVANCED_PRICE_EXTRA

def get_cave_shop():
    """获取当前家具商城，过期则自动刷新3件。"""
    shop = q("SELECT * FROM cave_shop WHERE expires_at > ? ORDER BY id", (now_ts(),))
    if not shop:
        # 刷新
        run("DELETE FROM cave_shop")
        chosen = random.sample(FURNITURE_POOL, min(3, len(FURNITURE_POOL)))
        expires = now_ts() + CAVE_SHOP_INTERVAL
        for f in chosen:
            run("INSERT INTO cave_shop (item_key, listed_at, expires_at) VALUES (?,?,?)",
                (f['key'], now_ts(), expires))
        shop = q("SELECT * FROM cave_shop WHERE expires_at > ? ORDER BY id", (now_ts(),))
    return shop

def cave_price(realm_idx):
    """洞府购买价格，随境界递增。"""
    return CAVE_BASE_COST + max(0, realm_idx - CAVE_MIN_REALM) * CAVE_COST_PER_LV

def process_cave(char_id):
    """洞府每小时结算（后台线程调用，不依赖Flask上下文）。"""
    import sqlite3 as _sq3
    db2 = _sq3.connect(DB_PATH)
    db2.row_factory = _sq3.Row

    char = db2.execute("SELECT * FROM characters WHERE id=? AND status='alive' AND is_npc=0",
                       (char_id,)).fetchone()
    if not char:
        db2.close(); return
    char = dict(char)
    if is_ascended(char):  # 真仙道行圆满，洞府挂机自动停止，修为不再增长
        db2.close(); return
    mode = char.get('cave_mode')
    if not mode or mode == 'off':
        db2.close(); return

    regen = ENERGY_REGEN_PER_REALM[min(char['realm_idx'], len(ENERGY_REGEN_PER_REALM)-1)] * ENERGY_REGEN_GLOBAL_MULT

    # 洞府感悟加成（直接查db）
    def _cave_perk_bonus(key):
        row = db2.execute("SELECT SUM(value) s FROM cave_perks WHERE char_id=? AND perk_key=?",
                          (char_id, key)).fetchone()
        return float(row['s'] or 0) if row else 0.0
    cave_cult_perk  = _cave_perk_bonus('cave_cultivate_pct')
    cave_temper_perk= _cave_perk_bonus('cave_temper_pct')
    cave_regen_perk = _cave_perk_bonus('cave_regen_pct')

    def _db_bonus(key, table, col_key, col_val, where_extra=''):
        row = db2.execute(f"SELECT SUM({col_val}) s FROM {table} WHERE {col_key}=? {where_extra}",
                          (char_id,)).fetchone()
        return float(row['s'] or 0) if row else 0.0

    # 功法加成
    tech_bonus = _db_bonus('exp_bonus', 'techniques t JOIN char_techniques ct ON ct.tech_id=t.id',
                           'ct.char_id', 't.exp_bonus', "AND t.type='cultivation'")
    # 感悟加成
    perk_b = _db_bonus('value', 'char_perks', 'char_id', 'value', "AND perk_key='cultivate_pct'")
    # 家具加成
    def _furn_bonus(key):
        rows = db2.execute("SELECT item_key FROM cave_purchases WHERE char_id=? AND is_equipped=1",
                           (char_id,)).fetchall()
        return sum(FURNITURE_MAP.get(r['item_key'], {}).get('bonus', {}).get(key, 0.0) for r in rows)
    # 季节加成（直接查 site_config）
    season_row = db2.execute("SELECT value FROM site_config WHERE key='season_buff_cultivate'").fetchone()
    season_b = float(season_row['value']) if season_row else 0.0
    # 子嗣加成
    kids = db2.execute("SELECT spirit_root FROM offspring WHERE (parent_a=? OR parent_b=?) AND is_matured=1",
                       (char_id, char_id)).fetchall()
    off_b = sum(OFFSPRING_ROOT_BONUS.get(k['spirit_root'], 0) for k in kids)
    # 宗门加成
    sect_row = db2.execute("""SELECT s.level FROM sects s JOIN sect_members sm ON sm.sect_id=s.id
                               WHERE sm.char_id=?""", (char_id,)).fetchone()
    sect_b = 0.0
    if sect_row:
        slv = sect_row['level'] or 1
        sect_b = [0, 0.02, 0.05, 0.08, 0.12, 0.18][min(slv, 5)]
    # 师父加成
    shifu_row = db2.execute("""SELECT 1 FROM discipleships WHERE tudi_id=? AND status='active'""",
                            (char_id,)).fetchone()
    shifu_b = 0.15 if shifu_row else 0.0
    # 临时buff加成
    buff_row = db2.execute("""SELECT SUM(value) s FROM char_buffs
                               WHERE char_id=? AND buff_key='cultivate_pct' AND expires_at>?""",
                           (char_id, now_ts())).fetchone()
    buff_b = float(buff_row['s'] or 0) if buff_row else 0.0
    # 伙伴加成
    comp_b = 0.0
    active_companions = char.get('active_companions') or '[]'
    try:
        import json as _json
        for ck in _json.loads(active_companions):
            comp = COMPANION_MAP.get(ck)
            if comp: comp_b += comp[5].get('exp_pct', 0.0)
    except Exception:
        pass

    total_bonus = tech_bonus + perk_b + season_b + off_b + sect_b + shifu_b + buff_b + comp_b

    # 用实际能量条的值（需与 cur_energy() 保持一致，否则高级洞府的灵力恢复加成不会生效）
    energy_updated = char.get('energy_updated') or now_ts()
    elapsed_hrs_regen = (now_ts() - energy_updated) / 3600
    furn_regen = _furn_bonus('regen_pct')
    comp_regen = companion_bonus(char, 'spirit_regen_pct')
    perm_regen = _db_bonus('value', 'char_perks', 'char_id', 'value', "AND perk_key='energy_regen_pct'")
    temp_regen_row = db2.execute("""SELECT SUM(value) s FROM char_buffs
                               WHERE char_id=? AND buff_key='energy_regen_pct' AND expires_at>?""",
                           (char_id, now_ts())).fetchone()
    temp_regen = float(temp_regen_row['s'] or 0) if temp_regen_row else 0.0
    regen_mul = float(char.get('regen_mult') or 1.0)
    peak_mul  = CAVE_ADV_ENERGY_MULT if (char.get('cave_peak') or 0) in CAVE_PEAK_ADVANCED_IDS else 1.0
    eff_max   = energy_cap(char)
    current_energy = min(eff_max, char.get('energy', 0) + int(elapsed_hrs_regen * regen *
                          (1 + cave_regen_perk + furn_regen + comp_regen + perm_regen + temp_regen) *
                          regen_mul * peak_mul))
    avail = current_energy

    did_work = False

    if mode == 'cultivate':
        cost  = CULTIVATE_COST
        times = avail // cost
        if times <= 0:
            db2.execute("UPDATE characters SET cave_processed=? WHERE id=?", (now_ts(), char_id))
            db2.commit(); db2.close(); return
        did_work = True
        mult   = SPIRIT_ROOTS[char['spirit_root']]['mult']
        furn_b = _furn_bonus('cultivate_pct')
        low_exp_mult = LOW_EXP_BUFF_MULT if char['exp'] < LOW_EXP_BUFF_THRESHOLD else 1.0
        dacheng_mult = DACHENG_BUFF_MULT if char['realm_idx'] >= DACHENG_BUFF_REALM_MIN else 1.0
        # 心魔减益：洞府挂机不新增心魔，但已有心魔仍会拖累修炼所得（与手动修炼一致，惩罚随大境界递增）
        demonic_qi = char.get('demonic_qi') or 0
        dq_mult = 1.0
        if char['realm_idx'] >= 13 and demonic_qi > 0:
            m = major_idx(char['realm_idx'])
            dq_scale   = 1.0 + max(0, m - 2) * 0.5
            dq_penalty = min(0.90, demonic_qi / 100 * dq_scale)
            dq_mult = 1 - dq_penalty
        total_exp = sum(
            int(random.randint(300, 500) * mult * (1 + total_bonus) * CAVE_EFF * (1 + cave_cult_perk + furn_b) * low_exp_mult * dacheng_mult * dq_mult)
            for _ in range(min(times, 500))
        )
        remaining = current_energy - times * cost
        db2.execute("UPDATE characters SET exp=MIN(exp+?,?), energy=?, energy_updated=?, cave_processed=? WHERE id=?",
                    (total_exp, GLOBAL_EXP_CAP, max(0, remaining), now_ts(), now_ts(), char_id))
        db2.execute("INSERT INTO char_logs (char_id,type,content,created_at) VALUES (?,?,?,?)",
                    (char_id, 'cultivate',
                     f'洞府结算：自动修炼 {times} 次，修为 +{total_exp}。', now_ts()))

    elif mode == 'temper':
        lv = char.get('body_level') or 0
        if lv >= len(BODY_LEVELS) - 1:
            db2.execute("UPDATE characters SET cave_processed=? WHERE id=?", (now_ts(), char_id))
            db2.commit(); db2.close(); return
        cost  = BODY_LEVELS[lv]['cost']
        times = avail // cost
        if times <= 0:
            db2.execute("UPDATE characters SET cave_processed=? WHERE id=?", (now_ts(), char_id))
            db2.commit(); db2.close(); return
        did_work = True
        furn_tb = _furn_bonus('temper_pct')
        total_bexp = sum(
            int((random.randint(15, 35) + char['realm_idx'] // 3) * (1 + cave_temper_perk + furn_tb))
            for _ in range(min(times, 500))
        )
        new_bexp = (char.get('body_exp') or 0) + total_bexp
        new_lv   = lv
        while new_lv + 1 < len(BODY_LEVELS) and new_bexp >= BODY_LEVELS[new_lv+1]['exp'] \
              and char['realm_idx'] >= BODY_LEVELS[new_lv+1]['realm']:
            new_lv += 1
        remaining = current_energy - times * cost
        db2.execute("UPDATE characters SET body_exp=?, body_level=?, energy=?, energy_updated=?, cave_processed=? WHERE id=?",
                    (new_bexp, new_lv, max(0, remaining), now_ts(), now_ts(), char_id))
        db2.execute("INSERT INTO char_logs (char_id,type,content,created_at) VALUES (?,?,?,?)",
                    (char_id, 'cultivate',
                     f'洞府结算：自动炼体 {times} 次，炼体经验 +{total_bexp}。', now_ts()))

    # 店铺被动收入（有修炼/炼体产出才结算，灵力不足时不计）
    cave_lv = (char.get('cave_decor') or 0) // CAVE_DECOR_PER_LV
    if did_work and cave_lv >= 1:
        per_shop_income = CAVE_SHOP_INCOME_ADVANCED if char.get('cave_advanced') else CAVE_SHOP_INCOME
        shop_income = cave_lv * per_shop_income
        db2.execute("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
                    (shop_income, char_id))
        db2.execute("INSERT INTO char_logs (char_id,type,content,created_at) VALUES (?,?,?,?)",
                    (char_id, 'system',
                     f'洞府结算：{cave_lv} 家店铺营业，收入灵石 {shop_income}。', now_ts()))

    db2.commit()
    db2.close()

def cave_shops_for(char_id, cave_level):
    """返回该角色洞府固定的店铺名列表（按 char_id 确定，每次相同）。"""
    rng = random.Random(char_id ^ 0xCAFE)
    pool = CAVE_SHOP_TYPES[:]
    rng.shuffle(pool)
    return pool[:min(cave_level, len(pool))]

def advance_time(char):
    """惰性推进年龄：按真实时间结算流逝的年份与奇遇。返回是否发生了变化。
    真仙道行圆满，寿元冻结于飞升时的年岁，此后不再继续增长。"""
    if char['status'] != 'alive' or char['is_npc']:
        return False
    if REALMS[char['realm_idx']]['major'] == '真仙':
        return False
    last = char['age_updated'] or now_ts()
    age_mult = GATE_DEMONIC_AGE_MULT if char['is_demonic'] else 1.0
    age_mult *= PLAYER_AGE_RATE_MULT
    eff_year_secs = max(1, int(SECONDS_PER_YEAR / age_mult))
    elapsed_years = (now_ts() - last) // eff_year_secs
    if elapsed_years <= 0:
        if not char['age_updated']:
            run("UPDATE characters SET age_updated=? WHERE id=?", (now_ts(), char['id']))
        return False

    new_age = char['age'] + elapsed_years
    # 推进 age_updated（保留不足一年的余量）
    run("UPDATE characters SET age=?, age_updated=age_updated+? WHERE id=?",
        (new_age, elapsed_years * eff_year_secs, char['id']))

    # 结算奇遇（封顶，防止长期挂机积压过多）
    rolls = min(elapsed_years, MAX_YEARS_ROLL)
    for _ in range(rolls):
        enc_chance = min(0.95, ENCOUNTER_CHANCE + perk_total(char['id'], 'encounter_pct'))
        if random.random() < enc_chance:
            cur = q("SELECT * FROM characters WHERE id=?", (char['id'],), one=True)
            generate_encounter(cur)

    # 寿元判定：超寿则身陨
    cur = q("SELECT * FROM characters WHERE id=?", (char['id'],), one=True)
    if cur['age'] > lifespan(cur):
        run("UPDATE characters SET status='deceased' WHERE id=?", (char['id'],))
        log(char['id'], 'system', f'寿元耗尽，于 {cur["age"]} 岁坐化而逝。')
        break_daolv_on_death(char['id'], cur['name'])
    return True

# ── 战斗模拟 ───────────────────────────────────────────────────────────────────

CRIT_OVERFLOW_TO_DMG_RATIO = 0.5  # 暴击率超过 100% 时，溢出部分按此比例转为暴击伤害，避免浪费

def _apply_crit_overflow(crit_rate, crit_dmg):
    """暴击率超过 100%（必定暴击）后，多余部分不再提升命中概率，转化为暴击伤害。
    注意：crit_rate 本身原样返回（不封顶），仅用于展示真实数值；
    实战判定 random.random() < crit_rate 对任何 >=1.0 的值天然等价于必定暴击，无需再封顶。"""
    if crit_rate > 1.0:
        overflow = crit_rate - 1.0
        crit_dmg += overflow * CRIT_OVERFLOW_TO_DMG_RATIO
    return crit_rate, crit_dmg

def simulate(char, monster, equip_atk=0, equip_def=0, start_hp=None,
             char_elems=None, monster_elems=None):
    """
    返回 (won, rounds, final_char_hp)。
    rounds 每条包含 actor/dmg/m_hp/c_hp/crit/dodge/heal 字段。
    """
    max_hp, base_atk, base_def = realm_stats(char['realm_idx'])
    max_hp = int(max_hp * (1 + companion_bonus(char, 'hp_pct') + perk_total(char['id'], 'hp_pct'))) \
             + bone_hp_bonus(char['id'])

    atk_techs = q("""SELECT t.power FROM techniques t
        JOIN char_techniques ct ON ct.tech_id=t.id
        WHERE ct.char_id=? AND t.type='attack'""", (char['id'],))
    def_techs = q("""SELECT t.power FROM techniques t
        JOIN char_techniques ct ON ct.tech_id=t.id
        WHERE ct.char_id=? AND t.type='defense'""", (char['id'],))
    tech_atk = sum(r['power'] for r in atk_techs)
    tech_def = sum(r['power'] for r in def_techs)

    # 奇功效果汇总
    spec_arts = q("""SELECT t.effect_json FROM techniques t
        JOIN char_techniques ct ON ct.tech_id=t.id
        WHERE ct.char_id=? AND t.type='special'""", (char['id'],))
    crit_rate  = 0.0;  crit_dmg  = 2.0
    dodge_rate = 0.0;  lifesteal = 0.0
    atk_pct    = 0.0;  def_pct   = 0.0
    for art in spec_arts:
        eff = json.loads(art['effect_json'] or '{}')
        crit_rate  = crit_rate  + eff.get('crit_rate',  0)
        if 'crit_dmg' in eff:
            crit_dmg += eff['crit_dmg'] - 2.0   # 多门奇功的暴击伤害倍率叠加，而非取最高
        dodge_rate += eff.get('dodge_rate', 0)
        lifesteal  = lifesteal  + eff.get('lifesteal_pct', 0)
        atk_pct   +=                        eff.get('atk_pct', 0)
        def_pct   +=                        eff.get('def_pct',  0)

    # 出战宠物加成
    pb = get_pet_bonus(char)
    atk_pct    += pb["atk_pct"]
    def_pct    += pb["def_pct"]
    crit_rate   = crit_rate  + pb["crit_rate"]
    dodge_rate += pb["dodge_rate"]
    lifesteal   = lifesteal  + pb["lifesteal"]

    # 本命武器加成
    dw_bonus = get_destiny_weapon_bonus(char)
    atk_pct   += dw_bonus['atk_pct']
    def_pct   += dw_bonus['def_pct']
    crit_rate  = crit_rate + dw_bonus['crit_rate'] / 100
    crit_dmg   = max(crit_dmg, crit_dmg + dw_bonus['crit_dmg'] / 100)
    dodge_rate += dw_bonus['dodge_rate'] / 100
    lifesteal  = lifesteal + dw_bonus['lifesteal']

    # 装备武器附加战斗属性（先卫神兵及带暴击的成品武器）
    wb = get_weapon_combat_bonus(char)
    crit_rate  = crit_rate  + wb['crit_rate']
    crit_dmg   = crit_dmg   + wb['crit_dmg']
    dodge_rate += wb['dodge_rate']
    lifesteal  = lifesteal  + wb['lifesteal'] * 100

    # 感悟加成（战斗类）
    crit_rate  = crit_rate  + perk_total(char['id'], 'crit_rate')
    dodge_rate += perk_total(char['id'], 'dodge')
    lifesteal  = lifesteal  + perk_total(char['id'], 'lifesteal') * 100
    atk_pct   += perk_total(char['id'], 'atk_pct') * 100
    def_pct   += perk_total(char['id'], 'def_pct') * 100
    # 远古神话祝福强化（按当前层数 × 当前每层加成实时计算，方便后续随时调整倍率）
    atk_pct   += (char['ancient_reinforce_layers'] or 0) * ANCIENT_REINFORCE_PCT_PER_LAYER * 100
    def_pct   += (char['ancient_reinforce_layers'] or 0) * ANCIENT_REINFORCE_PCT_PER_LAYER * 100
    # 伙伴战斗加成
    atk_pct   += companion_bonus(char, 'atk_pct') * 100
    def_pct   += companion_bonus(char, 'def_pct') * 100
    crit_rate  = crit_rate  + companion_bonus(char, 'crit_rate')
    dodge_rate += companion_bonus(char, 'dodge_rate')
    # 夏季战斗加成
    atk_pct   += cur_season_buff('combat_atk') * 100

    # 法术加成
    sb = get_spell_bonuses(char['id'])
    atk_pct    += sb['atk_pct'] * 100
    def_pct    += sb['def_pct'] * 100
    crit_rate   = crit_rate  + sb['crit_rate']
    dodge_rate += sb['dodge']
    lifesteal   = lifesteal  + sb['lifesteal'] * 100
    # 招式加成
    mb = get_move_bonuses(char['id'])
    atk_pct    += mb['atk_pct'] * 100
    def_pct    += mb['def_pct'] * 100
    crit_rate   = crit_rate  + mb['crit_rate']
    dodge_rate += mb['dodge']
    lifesteal   = lifesteal  + mb['lifesteal'] * 100
    crit_dmg    = max(crit_dmg, crit_dmg + mb['crit_dmg'])

    # 本命法宝额外暴击加成
    if char['destiny_id']:
        d = q("SELECT effect_json FROM items WHERE id=?", (char['destiny_id'],), one=True)
        if d:
            crit_rate = crit_rate + json.loads(d['effect_json'] or '{}').get('crit_rate', 0)

    # 道侣同心：附加道侣攻防的一部分
    tongxin_atk = tongxin_def = 0
    if char['daolv_id']:
        dl = q("SELECT realm_idx FROM characters WHERE id=?", (char['daolv_id'],), one=True)
        if dl:
            _, dl_atk, dl_def = realm_stats(dl['realm_idx'])
            tongxin_atk = int(dl_atk * TONGXIN_PCT)
            tongxin_def = int(dl_def * TONGXIN_PCT)

    # 剑修加成
    sb_sword = get_sword_bonus(char)
    atk_pct    += sb_sword['atk_pct']
    crit_rate   = crit_rate  + sb_sword['crit_rate']
    crit_dmg    = max(crit_dmg, crit_dmg + sb_sword['crit_dmg'] / 100)
    dodge_rate += sb_sword['dodge']
    lifesteal   = lifesteal  + sb_sword['lifesteal']
    sword_pen   = sb_sword['pen_pct']         # 破甲：忽略敌方防御的百分比
    sword_qi_rate      = sb_sword['qi_rate']  # 剑气追击概率
    sword_qi_can_crit  = sb_sword['qi_can_crit']

    # 符箓临时 buff
    _cbuffs = get_char_buffs(char['id'])
    atk_pct += _cbuffs.get('atk_pct', 0) * 100
    def_pct += _cbuffs.get('def_pct', 0) * 100

    crit_rate, crit_dmg = _apply_crit_overflow(crit_rate, crit_dmg)

    c_hp  = start_hp if start_hp is not None else max_hp
    body_atk_pct, body_def_pct = get_body_bonus(char)
    ys = get_yuanshen_bonus(char)
    dmg_reduce = get_artifact_dmg_reduce(char)
    c_atk = int((base_atk + tech_atk + equip_atk + tongxin_atk + dw_bonus['base_attack'] + ys['atk'])
                * (1 + (atk_pct + body_atk_pct) / 100))
    c_def = int((base_def + tech_def + equip_def + tongxin_def + ys['def'])
                * (1 + (def_pct + body_def_pct) / 100))
    m_hp  = monster['hp']
    # 破甲：减少有效防御
    eff_def = int(monster['defense'] * (1 - sword_pen / 100))

    # 五行相克加成
    _c_elems = char_elems if char_elems is not None else char_elements(char)
    _m_elems = monster_elems if monster_elems is not None else json.loads(monster['elements'] or '[]')
    p_wx_mult, p_wx_desc = combat_wuxing(_c_elems, _m_elems)
    m_wx_mult, m_wx_desc = combat_wuxing(_m_elems, _c_elems)

    p_name = char['name']
    m_name = monster['name']
    rounds = []
    for _ in range(30):
        is_crit = crit_rate > 0 and random.random() < crit_rate
        p_dmg   = max(1, int((c_atk - eff_def + random.randint(-3, 8)) * p_wx_mult))
        if is_crit:
            p_dmg = int(p_dmg * crit_dmg)
        m_hp -= p_dmg
        heal_raw = int(p_dmg * lifesteal / 100) if lifesteal > 0 else 0
        heal = min(heal_raw, max(0, max_hp - c_hp))  # 显示实际生效的吸血量，而非被气血上限截断前的理论值
        if heal:
            c_hp += heal
        # 气血已满时，浪费掉的吸血额度转为吸血护盾：护盾值 = 吸血率(百分比) × 原始满气血，只挡本回合怪物的这一下
        overflow = heal_raw - heal
        shield = int(lifesteal / 100 * max_hp) if overflow > 0 else 0
        rd = {"actor":"p","dmg":p_dmg,"m_hp":max(0,m_hp),"c_hp":c_hp,"crit":is_crit,"dodge":False,"heal":heal,"shield_gained":shield}
        rd['desc'] = _round_desc(rd, p_name, m_name)
        rounds.append(rd)
        if m_hp <= 0: break

        # 剑气追击（玩家回合结束后额外触发）
        if sword_qi_rate > 0 and random.random() < sword_qi_rate and m_hp > 0:
            qi_base = max(1, int(c_atk * 0.60))
            qi_crit = sword_qi_can_crit and crit_rate > 0 and random.random() < crit_rate
            qi_dmg  = int(qi_base * crit_dmg) if qi_crit else qi_base
            m_hp   -= qi_dmg
            rd = {"actor":"p","dmg":qi_dmg,"m_hp":max(0,m_hp),"c_hp":c_hp,"crit":qi_crit,"dodge":False,"heal":0,"qi":True}
            rd['desc'] = _round_desc(rd, p_name, m_name)
            rounds.append(rd)
            if m_hp <= 0: break

        dodge_eff     = min(0.70, dodge_rate)
        raw_counter   = max(0.0, dodge_rate - 0.70)
        counter_rate  = min(1.0, raw_counter)
        counter_bonus = max(0.0, raw_counter - 1.0)  # 反击率超过100%的溢出部分转为反击伤害加成
        is_dodge = dodge_eff > 0 and random.random() < dodge_eff
        if is_dodge:
            rd = {"actor":"m","dmg":0,"m_hp":m_hp,"c_hp":c_hp,"crit":False,"dodge":True,"heal":0}
            rd['desc'] = _round_desc(rd, p_name, m_name)
            rounds.append(rd)
            # 溢出反击：闪避成功后有概率还手一击
            if counter_rate > 0 and random.random() < counter_rate and m_hp > 0:
                counter_dmg = max(1, int(c_atk * (0.50 + counter_bonus)))
                m_hp -= counter_dmg
                rc = {"actor":"p","dmg":counter_dmg,"m_hp":max(0,m_hp),"c_hp":c_hp,
                      "crit":False,"dodge":False,"heal":0,"counter":True}
                rc['desc'] = f'【{p_name}】借势反击，造成 {counter_dmg} 点伤害！'
                rounds.append(rc)
        else:
            m_dmg = max(1, int((monster['attack'] - c_def + random.randint(-2, 6)) * m_wx_mult))
            if dmg_reduce > 0:
                m_dmg = max(1, int(m_dmg * (1 - dmg_reduce)))
            raw_m_dmg = m_dmg
            absorbed = min(shield, m_dmg - 1) if shield > 0 else 0  # 护盾不吸满，至少留 1 点伤害
            m_dmg -= absorbed
            c_hp -= m_dmg
            rd = {"actor":"m","dmg":m_dmg,"raw_dmg":raw_m_dmg,"m_hp":m_hp,"c_hp":max(0,c_hp),"crit":False,"dodge":False,"heal":0,"shield":absorbed}
            rd['desc'] = _round_desc(rd, p_name, m_name)
            rounds.append(rd)
        if c_hp <= 0: break
        if m_hp <= 0: break
    else:
        # 30 回合耗尽双方仍未阵亡：妖兽久战暴怒，一击打飞玩家，判定战败、血条清空
        rage_dmg = max(0, c_hp)
        c_hp = 0
        rd = {"actor":"m","dmg":rage_dmg,"m_hp":max(0, m_hp),"c_hp":0,
              "crit":True,"dodge":False,"heal":0}
        rd['desc'] = f'【{m_name}】鏖战多时忽然暴怒，一记重击将【{p_name}】直接打飞，气血瞬间清空！'
        rounds.append(rd)

    return m_hp <= 0, rounds, max(0, c_hp), p_wx_desc, m_wx_desc


def _build_fighter_stats(char):
    """提取角色完整战斗属性，供 simulate_pvp 使用。"""
    max_hp, base_atk, base_def = realm_stats(char['realm_idx'])
    max_hp = int(max_hp * (1 + companion_bonus(char, 'hp_pct') + perk_total(char['id'], 'hp_pct'))) \
             + bone_hp_bonus(char['id'])
    eq_atk, eq_def = get_equip_bonuses(char)

    atk_rows = q("""SELECT t.power FROM techniques t JOIN char_techniques ct ON ct.tech_id=t.id
        WHERE ct.char_id=? AND t.type='attack'""", (char['id'],))
    def_rows = q("""SELECT t.power FROM techniques t JOIN char_techniques ct ON ct.tech_id=t.id
        WHERE ct.char_id=? AND t.type='defense'""", (char['id'],))
    tech_atk = sum(r['power'] for r in atk_rows)
    tech_def = sum(r['power'] for r in def_rows)

    spec_arts = q("""SELECT t.effect_json FROM techniques t JOIN char_techniques ct ON ct.tech_id=t.id
        WHERE ct.char_id=? AND t.type='special'""", (char['id'],))
    crit_rate = 0.0; crit_dmg = 2.0; dodge_rate = 0.0; lifesteal = 0.0
    atk_pct = 0.0; def_pct = 0.0
    for art in spec_arts:
        eff = json.loads(art['effect_json'] or '{}')
        crit_rate  = crit_rate  + eff.get('crit_rate',    0)
        if 'crit_dmg' in eff:
            crit_dmg += eff['crit_dmg'] - 2.0   # 多门奇功的暴击伤害倍率叠加，而非取最高
        dodge_rate += eff.get('dodge_rate',   0)
        lifesteal  = lifesteal  + eff.get('lifesteal_pct',0)
        atk_pct   +=                        eff.get('atk_pct',      0)
        def_pct   +=                        eff.get('def_pct',      0)

    pb = get_pet_bonus(char)
    atk_pct    += pb['atk_pct'];  def_pct    += pb['def_pct']
    crit_rate   = crit_rate  + pb['crit_rate']
    dodge_rate += pb['dodge_rate']
    lifesteal   = lifesteal  + pb['lifesteal']

    dw = get_destiny_weapon_bonus(char)
    atk_pct   += dw['atk_pct']
    def_pct   += dw['def_pct']
    crit_rate  = crit_rate  + dw['crit_rate']  / 100
    crit_dmg   = max(crit_dmg, crit_dmg + dw['crit_dmg'] / 100)
    dodge_rate += dw['dodge_rate'] / 100
    lifesteal  = lifesteal  + dw['lifesteal']

    # 装备武器附加战斗属性（先卫神兵及带暴击的成品武器）
    wb = get_weapon_combat_bonus(char)
    crit_rate  = crit_rate  + wb['crit_rate']
    crit_dmg   = crit_dmg   + wb['crit_dmg']
    dodge_rate += wb['dodge_rate']
    lifesteal  = lifesteal  + wb['lifesteal'] * 100

    crit_rate  = crit_rate  + perk_total(char['id'], 'crit_rate')
    dodge_rate += perk_total(char['id'], 'dodge')
    lifesteal  = lifesteal  + perk_total(char['id'], 'lifesteal') * 100
    atk_pct   += perk_total(char['id'], 'atk_pct') * 100
    def_pct   += perk_total(char['id'], 'def_pct') * 100
    # 远古神话祝福强化（按当前层数 × 当前每层加成实时计算，方便后续随时调整倍率）
    atk_pct   += (char['ancient_reinforce_layers'] or 0) * ANCIENT_REINFORCE_PCT_PER_LAYER * 100
    def_pct   += (char['ancient_reinforce_layers'] or 0) * ANCIENT_REINFORCE_PCT_PER_LAYER * 100

    atk_pct   += companion_bonus(char, 'atk_pct') * 100
    def_pct   += companion_bonus(char, 'def_pct') * 100
    crit_rate  = crit_rate  + companion_bonus(char, 'crit_rate')
    dodge_rate += companion_bonus(char, 'dodge_rate')
    atk_pct   += cur_season_buff('combat_atk') * 100

    sb = get_spell_bonuses(char['id'])
    atk_pct   += sb['atk_pct'] * 100;  def_pct   += sb['def_pct'] * 100
    crit_rate  = crit_rate  + sb['crit_rate']
    dodge_rate += sb['dodge']
    lifesteal  = lifesteal  + sb['lifesteal'] * 100
    mb = get_move_bonuses(char['id'])
    atk_pct   += mb['atk_pct'] * 100;  def_pct   += mb['def_pct'] * 100
    crit_rate  = crit_rate  + mb['crit_rate']
    dodge_rate += mb['dodge']
    lifesteal  = lifesteal  + mb['lifesteal'] * 100
    crit_dmg   = max(crit_dmg, crit_dmg + mb['crit_dmg'])

    if char.get('destiny_id'):
        d = q("SELECT effect_json FROM items WHERE id=?", (char['destiny_id'],), one=True)
        if d:
            crit_rate = crit_rate + json.loads(d['effect_json'] or '{}').get('crit_rate', 0)

    tongxin_atk = tongxin_def = 0
    if char.get('daolv_id'):
        dl = q("SELECT realm_idx FROM characters WHERE id=?", (char['daolv_id'],), one=True)
        if dl:
            _, dl_atk, dl_def = realm_stats(dl['realm_idx'])
            tongxin_atk = int(dl_atk * TONGXIN_PCT)
            tongxin_def = int(dl_def * TONGXIN_PCT)

    sw = get_sword_bonus(char)
    atk_pct   += sw['atk_pct']
    crit_rate  = crit_rate  + sw['crit_rate']
    crit_dmg   = max(crit_dmg, crit_dmg + sw['crit_dmg'] / 100)
    dodge_rate += sw['dodge']
    lifesteal  = lifesteal  + sw['lifesteal']

    # 符箓临时 buff
    _cbuffs2 = get_char_buffs(char['id'])
    atk_pct += _cbuffs2.get('atk_pct', 0) * 100
    def_pct += _cbuffs2.get('def_pct', 0) * 100

    crit_rate, crit_dmg = _apply_crit_overflow(crit_rate, crit_dmg)

    body_atk_pct, body_def_pct = get_body_bonus(char)
    ys = get_yuanshen_bonus(char)
    atk  = int((base_atk + tech_atk + eq_atk + tongxin_atk + dw['base_attack'] + ys['atk'])
               * (1 + (atk_pct + body_atk_pct) / 100))
    def_ = int((base_def + tech_def + eq_def  + tongxin_def + ys['def'])
               * (1 + (def_pct + body_def_pct) / 100))

    if is_ascended(char):  # 真仙攻防数值直接锁定（含后台显示），不受任何加成影响
        atk, def_ = XIAN_COMBAT_ATK, XIAN_COMBAT_DEF

    return {
        'hp': max_hp, 'max_hp': max_hp,
        'atk': atk,   'def': def_,
        'atk_pct': atk_pct, 'def_pct': def_pct,
        'crit_rate': crit_rate, 'crit_dmg': crit_dmg,
        'dodge_rate': dodge_rate, 'lifesteal': lifesteal,
        'sword_pen': sw['pen_pct'],
        'sword_qi_rate': sw['qi_rate'],
        'sword_qi_can_crit': sw['qi_can_crit'],
        'dmg_reduce': get_artifact_dmg_reduce(char),
        'elems': char_elements(char),
    }


def simulate_pvp(a, b):
    """双方均以完整角色属性对战，返回 a_won (bool)。最多 30 回合，存活血量高者胜。"""
    sa = _build_fighter_stats(a)
    sb = _build_fighter_stats(b)
    wx_ab, _ = combat_wuxing(sa['elems'], sb['elems'])
    wx_ba, _ = combat_wuxing(sb['elems'], sa['elems'])

    def _strike(attacker, defender, wx_mult):
        """攻击者打防御者一刀，原地修改 hp，返回伤害。"""
        eff_def = int(defender['def'] * (1 - attacker['sword_pen'] / 100))
        dmg = max(1, int((attacker['atk'] - eff_def + random.randint(-3, 8)) * wx_mult))
        is_crit = attacker['crit_rate'] > 0 and random.random() < attacker['crit_rate']
        if is_crit:
            dmg = int(dmg * attacker['crit_dmg'])
        if defender.get('dmg_reduce', 0) > 0:
            dmg = max(1, int(dmg * (1 - defender['dmg_reduce'])))
        defender['hp'] -= dmg
        if attacker['lifesteal'] > 0:
            attacker['hp'] = min(attacker['max_hp'], attacker['hp'] + int(dmg * attacker['lifesteal'] / 100))
        return dmg

    for _ in range(30):
        # A 出手（B 可能闪避/反击）
        b_dodge_eff     = min(0.70, sb['dodge_rate'])
        b_raw_counter   = max(0.0, sb['dodge_rate'] - 0.70)
        b_counter_rate  = min(1.0, b_raw_counter)
        b_counter_bonus = max(0.0, b_raw_counter - 1.0)
        if b_dodge_eff <= 0 or random.random() >= b_dodge_eff:
            _strike(sa, sb, wx_ab)
            if sa['sword_qi_rate'] > 0 and random.random() < sa['sword_qi_rate'] and sb['hp'] > 0:
                qi_crit = sa['sword_qi_can_crit'] and random.random() < sa['crit_rate']
                qi_dmg  = int(sa['atk'] * 0.60 * (sa['crit_dmg'] if qi_crit else 1))
                sb['hp'] -= max(1, qi_dmg)
        elif b_counter_rate > 0 and random.random() < b_counter_rate and sa['hp'] > 0:
            # B 闪避溢出反击
            counter_dmg = max(1, int(sb['atk'] * (0.50 + b_counter_bonus)))
            sa['hp'] -= counter_dmg
        if sb['hp'] <= 0:
            break

        # B 出手（A 可能闪避/反击）
        a_dodge_eff     = min(0.70, sa['dodge_rate'])
        a_raw_counter   = max(0.0, sa['dodge_rate'] - 0.70)
        a_counter_rate  = min(1.0, a_raw_counter)
        a_counter_bonus = max(0.0, a_raw_counter - 1.0)
        if a_dodge_eff <= 0 or random.random() >= a_dodge_eff:
            _strike(sb, sa, wx_ba)
            if sb['sword_qi_rate'] > 0 and random.random() < sb['sword_qi_rate'] and sa['hp'] > 0:
                qi_crit = sb['sword_qi_can_crit'] and random.random() < sb['crit_rate']
                qi_dmg  = int(sb['atk'] * 0.60 * (sb['crit_dmg'] if qi_crit else 1))
                sa['hp'] -= max(1, qi_dmg)
        elif a_counter_rate > 0 and random.random() < a_counter_rate and sb['hp'] > 0:
            # A 闪避溢出反击
            counter_dmg = max(1, int(sa['atk'] * (0.50 + a_counter_bonus)))
            sb['hp'] -= counter_dmg
        if sa['hp'] <= 0:
            break

    # 胜负：B 死 → A 胜；A 死 → B 胜；均存活 → 剩余血量高者胜
    if sb['hp'] <= 0 and sa['hp'] > 0:
        return True
    if sa['hp'] <= 0 and sb['hp'] > 0:
        return False
    return sa['hp'] >= sb['hp']


def simulate_pvp_detailed(a, b):
    """两场制PVP，返回 (a_game_wins, b_game_wins, total_dmg_a, total_dmg_b)。"""
    total_dmg_a = 0
    total_dmg_b = 0
    a_wins = 0
    b_wins = 0
    for _ in range(2):
        sa = _build_fighter_stats(a)
        sb = _build_fighter_stats(b)
        wx_ab, _ = combat_wuxing(sa['elems'], sb['elems'])
        wx_ba, _ = combat_wuxing(sb['elems'], sa['elems'])
        dmg_a = 0
        dmg_b = 0
        def _strike_d(attacker, defender, wx_mult, is_a):
            nonlocal dmg_a, dmg_b
            eff_def = int(defender['def'] * (1 - attacker['sword_pen'] / 100))
            dmg = max(1, int((attacker['atk'] - eff_def + random.randint(-3, 8)) * wx_mult))
            if attacker['crit_rate'] > 0 and random.random() < attacker['crit_rate']:
                dmg = int(dmg * attacker['crit_dmg'])
            if defender.get('dmg_reduce', 0) > 0:
                dmg = max(1, int(dmg * (1 - defender['dmg_reduce'])))
            defender['hp'] -= dmg
            if attacker['lifesteal'] > 0:
                attacker['hp'] = min(attacker['max_hp'], attacker['hp'] + int(dmg * attacker['lifesteal'] / 100))
            if is_a:
                dmg_a += dmg
            else:
                dmg_b += dmg
        for _ in range(30):
            b_dodge_eff     = min(0.70, sb['dodge_rate'])
            b_raw_counter   = max(0.0, sb['dodge_rate'] - 0.70)
            b_counter_rate  = min(1.0, b_raw_counter)
            b_counter_bonus = max(0.0, b_raw_counter - 1.0)
            if b_dodge_eff <= 0 or random.random() >= b_dodge_eff:
                _strike_d(sa, sb, wx_ab, True)
                if sa['sword_qi_rate'] > 0 and random.random() < sa['sword_qi_rate'] and sb['hp'] > 0:
                    qi = int(sa['atk'] * 0.60)
                    sb['hp'] -= max(1, qi); dmg_a += max(1, qi)
            elif b_counter_rate > 0 and random.random() < b_counter_rate and sa['hp'] > 0:
                # B 闪避溢出反击
                counter_dmg = max(1, int(sb['atk'] * (0.50 + b_counter_bonus)))
                sa['hp'] -= counter_dmg
                dmg_b += counter_dmg
            if sb['hp'] <= 0:
                break
            a_dodge_eff     = min(0.70, sa['dodge_rate'])
            a_raw_counter   = max(0.0, sa['dodge_rate'] - 0.70)
            a_counter_rate  = min(1.0, a_raw_counter)
            a_counter_bonus = max(0.0, a_raw_counter - 1.0)
            if a_dodge_eff <= 0 or random.random() >= a_dodge_eff:
                _strike_d(sb, sa, wx_ba, False)
                if sb['sword_qi_rate'] > 0 and random.random() < sb['sword_qi_rate'] and sa['hp'] > 0:
                    qi = int(sb['atk'] * 0.45)
                    sa['hp'] -= max(1, qi); dmg_b += max(1, qi)
            elif a_counter_rate > 0 and random.random() < a_counter_rate and sb['hp'] > 0:
                # A 闪避溢出反击
                counter_dmg = max(1, int(sa['atk'] * (0.50 + a_counter_bonus)))
                sb['hp'] -= counter_dmg
                dmg_a += counter_dmg
            if sa['hp'] <= 0:
                break
        a_won_game = (sb['hp'] <= 0 and sa['hp'] > 0) or (sa['hp'] > 0 and sb['hp'] > 0 and sa['hp'] >= sb['hp'])
        if a_won_game:
            a_wins += 1
        else:
            b_wins += 1
        total_dmg_a += dmg_a
        total_dmg_b += dmg_b
    return a_wins, b_wins, total_dmg_a, total_dmg_b


