@app.context_processor
def _inject_globals():
    """全局注入：待处理奇遇数、公告滚动条内容。"""
    # 公告条：最近 15 条世界事件（无需登录也显示）
    try:
        ticker_rows = q("SELECT content FROM world_log ORDER BY created_at DESC LIMIT 15")
        ticker = "　　✦　　".join(r['content'] for r in reversed(ticker_rows)) if ticker_rows else ''
    except Exception:
        ticker = ''

    if 'uid' not in S:
        return {'nav_pending_enc': 0, 'ticker': ticker}
    char = me()
    if not char:
        return {'nav_pending_enc': 0, 'ticker': ticker}
    n = q("SELECT COUNT(*) n FROM encounters WHERE char_id=? AND status='pending'",
          (char['id'],), one=True)['n']
    unread_mail = q("SELECT COUNT(*) n FROM mail WHERE to_char=? AND is_read=0",
                    (char['id'],), one=True)['n']
    now_dt = datetime.now(TZ)
    quest_date = now_dt.strftime('%Y-%m-%d')
    quest_week = f"{now_dt.year}-W{now_dt.strftime('%W')}"
    unclaimed = q("""SELECT COUNT(*) n FROM quest_progress
        WHERE char_id=? AND completed=1 AND claimed=0
        AND (period_date=? OR period_date=?)""",
        (char['id'], quest_date, quest_week), one=True)['n']
    # 仙人试炼：有阶段可操作时显示角标
    enlighten_s   = get_enlighten_session(char['id'])
    nav_enlighten = bool(enlighten_next_available(enlighten_s) is not None)
    # 开凿灵脉：活动进行中且有可用次数时显示角标
    _vein_ev    = get_vein_event()
    nav_vein    = bool(_vein_ev and vein_available_charges(_vein_ev, char['id']) > 0)
    # 每日灵力馈赠：窗口开启且未领取时显示角标
    gift_slots      = get_gift_slot_status(char)
    nav_energy_gift = any(s['open'] and not s['claimed'] for s in gift_slots)
    gift_claimed    = all(s['claimed'] for s in gift_slots if s['open'])
    # 专修路线：当前路线 + 各路名额
    nav_craft_path = current_craft_path(char['id'])
    try:
        _cap, _alch, _forge, _fulu, _beast, _heqing, _sword = craft_quota()
        nav_craft_slots = {
            'cauldron':     (_cap - _alch),
            'forge':        (_cap - _forge),
            'brush':        (_cap - _fulu),
            'beast_token':  (_cap - _beast),
            'heqing_token': (_cap - _heqing),
            'sword_token':  (_cap - _sword),
            'cap': _cap,
        }
    except Exception:
        nav_craft_slots = {}
    return {'nav_pending_enc': n, 'ticker': ticker,
            'nav_unread_mail': unread_mail, 'nav_unclaimed_quests': unclaimed,
            'nav_enlighten': nav_enlighten,
            'nav_vein': nav_vein,
            'nav_energy_gift': nav_energy_gift,
            'gift_slots': gift_slots, 'gift_claimed': gift_claimed,
            'ENERGY_GIFT_AMOUNT': ENERGY_GIFT_AMOUNT,
            'nav_craft_path': nav_craft_path,
            'nav_craft_slots': nav_craft_slots,
            'PATH_NAMES': PATH_NAMES,
            'nav_yqs': yqs_active(),
            'nav_red_packet': has_unclaimed_red_packet(char['id']),
            'gate_ev': get_gate_event(),
            'tourney_ev': get_tourney_event(),
            'nav_immortal_seat': bool(char['immortal_seat']),
            'nav_immortal_seat_pending': bool(char['immortal_seat_pending']),
            'xian_ascended': is_ascended(char),
            'nav_temple_pending': q("SELECT COUNT(*) n FROM temple_visits WHERE char_id=? AND resolved=0",
                                    (char['id'],), one=True)['n'] if is_ascended(char) else 0,
            'MAX_ENERGY': energy_cap(char)}

@app.template_filter('fromjson')
def _fromjson(s):
    try: return json.loads(s or '{}')
    except: return {}

@app.template_filter('format_number')
def _format_number(n):
    try: return f"{int(n):,}"
    except: return str(n)

@app.template_filter('fmt_exp')
def _fmt_exp_filter(n):
    return fmt_exp(n)

@app.template_filter('format_ts')
def _format_ts(ts):
    try: return datetime.fromtimestamp(int(ts), TZ).strftime('%m-%d %H:%M')
    except: return ''

@app.template_filter('rarity_label')
def _rarity_label(r):
    return {"common":"普通","uncommon":"精良","rare":"稀有","epic":"史诗","legendary":"传说"}.get(r, r)

@app.template_filter('special_effects')
def _special_effects(eff_json):
    """把奇功 effect_json 转成可读描述列表。"""
    eff = json.loads(eff_json or '{}')
    parts = []
    if eff.get('crit_rate'):     parts.append(f'暴击率 +{int(eff["crit_rate"]*100)}%')
    if eff.get('crit_dmg'):      parts.append(f'暴击伤害 ×{eff["crit_dmg"]}')
    if eff.get('dodge_rate'):    parts.append(f'闪避率 +{int(eff["dodge_rate"]*100)}%')
    if eff.get('lifesteal_pct'): parts.append(f'吸血回复 {eff["lifesteal_pct"]}%')
    if eff.get('explore_bonus'): parts.append(f'探索奖励 +{int(eff["explore_bonus"]*100)}%')
    if eff.get('atk_pct'):       parts.append(f'攻击力 +{eff["atk_pct"]}%')
    if eff.get('def_pct'):       parts.append(f'防御力 +{eff["def_pct"]}%')
    return parts

