@app.route('/admin/login', methods=['GET','POST'])
def admin_login():
    """维护模式下管理员专用登录入口，不受任何拦截。"""
    if S.get('role') == 'admin':
        return redirect(url_for('admin'))
    err = None
    if request.method == 'POST':
        uname = request.form.get('username','').strip()
        pwd   = request.form.get('password','')
        user  = q("SELECT * FROM users WHERE username=?", (uname,), one=True)
        if user and user['role'] == 'admin' and check_password_hash(user['password_hash'], pwd):
            S.permanent = True
            S['uid'] = user['id']; S['uname'] = user['username']; S['role'] = 'admin'
            run("UPDATE users SET last_login=? WHERE id=?", (now_ts(), user['id']))
            return redirect(url_for('admin'))
        err = '账号或密码错误（仅管理员可用此入口）'
    return render_template('admin_login.html', err=err)

