@app.route('/game')
@login_required
def dashboard():
    if S.get('role') == 'admin':
        return redirect(url_for('admin'))
    char = me()
    if not char: return redirect(url_for('logout'))

    energy     = cur_energy(char)
    hp_now     = cur_hp(char)
    realm      = REALMS[char['realm_idx']]
    next_r     = REALMS[char['realm_idx']+1] if char['realm_idx'] < len(REALMS)-1 else None
    exp_min    = realm['exp']
    exp_max    = next_r['exp'] if next_r else exp_min
    exp_prog   = char['exp'] - exp_min
    exp_need   = exp_max - exp_min if next_r else 1
    exp_pct    = min(100, int(exp_prog / exp_need * 100)) if exp_need else 100
    max_hp, base_atk, base_def = realm_stats(char['realm_idx'])
    max_hp += bone_hp_bonus(char['id'])
    hp_pct     = int(hp_now / max_hp * 100) if max_hp else 100
    can_bt     = next_r and char['exp'] >= next_r['exp']
    energy_regen_hour = round(energy_regen_rate(char))
    hp_regen_hour      = round(max_hp * HP_REGEN_HOUR / 100)

    equip_atk, equip_def = get_equip_bonuses(char)
    atk_techs = q("""SELECT t.power FROM techniques t
        JOIN char_techniques ct ON ct.tech_id=t.id
        WHERE ct.char_id=? AND t.type='attack'""", (char['id'],))
    tech_atk = sum(r['power'] for r in atk_techs)
    equipped_weapon   = q("SELECT * FROM items WHERE id=?", (char['equipped_weapon'],), one=True) if char['equipped_weapon'] else None
    equipped_artifact = q("SELECT * FROM items WHERE id=?", (char['equipped_artifact'],), one=True) if char['equipped_artifact'] else None
    equipped_destiny  = q("SELECT * FROM items WHERE id=?", (char['destiny_id'],), one=True) if char['destiny_id'] else None
    pet_bonus         = get_pet_bonus(char)
    dw_bonus          = get_destiny_weapon_bonus(char)
    equipped_dw       = q("SELECT * FROM destiny_weapons WHERE id=?", (char['destiny_weapon_id'],), one=True) if char['destiny_weapon_id'] else None
    body_atk_pct, body_def_pct = get_body_bonus(char)
    # 面板展示：与真实战斗完全一致的攻防数值（含奇功/符箓临时buff/道侣同心/本命武器基础攻击等全部加成）
    fighter_stats = _build_fighter_stats(char)
    real_atk = fighter_stats['atk']
    real_def = fighter_stats['def']
    panel_atk_pct = fighter_stats['atk_pct']
    panel_def_pct = fighter_stats['def_pct']

    recent   = q("SELECT * FROM char_logs WHERE char_id=? ORDER BY created_at DESC LIMIT 6", (char['id'],))
    new_char = S.pop('new_char', None)
    pending_enc = q("SELECT COUNT(*) n FROM encounters WHERE char_id=? AND status='pending'",
                    (char['id'],), one=True)['n']
    life = lifespan(char)

    today_str = datetime.now(TZ).strftime('%Y-%m-%d')
    vein_claimed   = (char.get('vein_date') or '') == today_str
    vein_amount    = min(VEIN_STONES_CAP,
                        VEIN_STONES_BASE + (char['realm_idx'] // 4) * VEIN_STONES_STEP)
    vein_ev        = get_vein_event()
    cave_result    = S.pop('cave_result', None)

    return render_template('dashboard.html',
        char=char, energy=energy, hp_now=hp_now, hp_pct=hp_pct,
        energy_regen_hour=energy_regen_hour, hp_regen_hour=hp_regen_hour,
        realm=realm, next_r=next_r,
        exp_prog=exp_prog, exp_need=exp_need, exp_pct=exp_pct, can_bt=can_bt,
        max_hp=max_hp, base_atk=base_atk, base_def=base_def,
        equip_atk=equip_atk, equip_def=equip_def, tech_atk=tech_atk,
        body_atk_pct=body_atk_pct, body_def_pct=body_def_pct,
        panel_atk_pct=panel_atk_pct, panel_def_pct=panel_def_pct,
        real_atk=real_atk, real_def=real_def,
        body_level=char['body_level'] or 0, body_level_name=BODY_LEVELS[char['body_level'] or 0]['name'],
        equipped_weapon=equipped_weapon, equipped_artifact=equipped_artifact,
        equipped_destiny=equipped_destiny, pet_bonus=pet_bonus,
        dw_bonus=dw_bonus, equipped_dw=equipped_dw,
        recent=recent, new_char=new_char, pending_enc=pending_enc,
        age=char['age'], life=life,
        elements=json.loads(char['elements']),
        vein_claimed=vein_claimed, vein_amount=vein_amount,
        vein_ev=vein_ev, VEIN_TARGET=VEIN_TARGET,
        cave_result=cave_result,
        yuanshen_bonus=get_yuanshen_bonus(char),
        patch_notes=PATCH_NOTES)

# ── 修炼 ───────────────────────────────────────────────────────────────────────

@app.route('/game/cultivate', methods=['GET','POST'])
@login_required
def cultivate():
    char   = me()
    energy = cur_energy(char)
    result = None

    if request.method == 'POST':
        action = request.form.get('action')

        if is_in_seclusion(char):
            flash('闭关中无法进行此操作', 'error')
        elif action == 'cultivate':
            if energy < CULTIVATE_COST:
                flash('灵力不足，无法打坐修炼', 'error')
            else:
                techs  = q("""SELECT t.exp_bonus FROM techniques t
                    JOIN char_techniques ct ON ct.tech_id=t.id
                    WHERE ct.char_id=? AND t.type='cultivation'""", (char['id'],))
                bonus      = sum(t['exp_bonus'] for t in techs)
                mult       = SPIRIT_ROOTS[char['spirit_root']]['mult']
                perk_b     = perk_total(char['id'], 'cultivate_pct')
                season_b   = cur_season_buff('cultivate')
                off_b      = get_offspring_cult_bonus(char['id'])
                # 宗门 + 师徒加成
                my_sect    = get_char_sect(char['id'])
                sect_b     = get_sect_buff(my_sect['id']) if my_sect else 0.0
                shifu, _   = get_shifu(char['id'])
                shifu_b    = 0.15 if shifu else 0.0
                buff_b     = get_char_buffs(char['id']).get('cultivate_pct', 0)
                comp_b     = companion_bonus(char, 'exp_pct')
                low_exp_mult = LOW_EXP_BUFF_MULT if char['exp'] < LOW_EXP_BUFF_THRESHOLD else 1.0
                dacheng_mult = DACHENG_BUFF_MULT if char['realm_idx'] >= DACHENG_BUFF_REALM_MIN else 1.0
                gained = int(random.randint(300, 500) * mult
                             * (1 + bonus + perk_b + season_b + off_b + sect_b + shifu_b + buff_b + comp_b)
                             * low_exp_mult * dacheng_mult)

                # 心魔减益（结丹以上，惩罚随大境界递增）
                demonic_qi = char['demonic_qi'] or 0
                dq_add = 0
                if char['realm_idx'] >= 13:
                    if demonic_qi > 0:
                        # 结丹=1x，元婴=1.3x，化神=1.6x，合体=1.9x，大乘+=上限90%
                        m = major_idx(char['realm_idx'])
                        dq_scale  = 1.0 + max(0, m - 2) * 0.5
                        dq_penalty = min(0.90, demonic_qi / 100 * dq_scale)
                        gained = int(gained * (1 - dq_penalty))
                    dq_add = 1
                    new_dq = min(100, demonic_qi + dq_add)
                    run("UPDATE characters SET demonic_qi=? WHERE id=?", (new_dq, char['id']))
                    if demonic_qi >= 100:
                        dq_burn = max(1, int(char['exp'] * 0.001))
                        run("UPDATE characters SET exp=MAX(0,exp-?) WHERE id=?", (dq_burn, char['id']))
                        gained -= dq_burn
                        flash(f'⚠ 心魔已满，道基受损，修为 -{dq_burn}！', 'error')
                    elif new_dq >= 90 and demonic_qi < 90:
                        flash('⚠ 心魔已达 90，再不化解将动摇道基！', 'error')
                    elif new_dq >= 80 and demonic_qi < 80:
                        flash('⚠ 心魔已达 80，须留意化解。', 'error')

                run("UPDATE characters SET exp=exp+? WHERE id=?", (gained, char['id']))
                set_energy(char['id'], energy - CULTIVATE_COST)
                energy -= CULTIVATE_COST

                next_r  = REALMS[char['realm_idx']+1] if char['realm_idx'] < len(REALMS)-1 else None
                new_exp = char['exp'] + gained
                dq_note = f'，心魔 +{dq_add}（当前 {new_dq}）' if dq_add else ''
                if next_r and new_exp >= next_r['exp']:
                    log(char['id'], 'cultivate', f'吐纳天地灵气，修为增长 {gained}{dq_note}。修为至圆满，可尝试突破！')
                else:
                    log(char['id'], 'cultivate', f'吐纳天地灵气，修为增长 {gained}{dq_note}。')
                # 概率拾获珍贵材料
                treasure_found = None
                if random.random() < TREASURE_DROP_CHANCE:
                    pool = _treasure_pool(char['realm_idx'])
                    names, weights = zip(*pool)
                    picked = random.choices(names, weights=weights, k=1)[0]
                    t_item = q("SELECT * FROM items WHERE name=? AND type='treasure'", (picked,), one=True)
                    if t_item:
                        ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?",
                               (char['id'], t_item['id']), one=True)
                        if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?",
                                   (char['id'], t_item['id']))
                        else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)",
                                   (char['id'], t_item['id']))
                        treasure_found = t_item
                        log(char['id'], 'cultivate', f'打坐时意外发现【{picked}】，收入囊中。')

                inc_quest(char['id'], 'cultivate')
                inc_sect_quest(char['id'], 'cultivate')
                result = {'type': 'cultivate', 'gained': gained, 'treasure': treasure_found,
                          'dq_add': dq_add, 'dq_now': (char['demonic_qi'] or 0) + dq_add if dq_add else (char['demonic_qi'] or 0)}
                char   = me()

        elif action == 'dispel':
            demonic_qi = char['demonic_qi'] or 0
            ri = char['realm_idx']
            dispel_cost = CULTIVATE_COST * (5 if ri >= 33 else 4 if ri >= 25 else 3 if ri >= 17 else 1)
            if char['realm_idx'] < 13:
                flash('结丹境界以上方有心魔之患', 'error')
            elif demonic_qi <= 0:
                flash('心魔已清净，无需驱散', 'error')
            elif energy < dispel_cost:
                flash(f'灵力不足（需 {dispel_cost}）', 'error')
            else:
                reduced = min(demonic_qi, 10)
                new_dq  = demonic_qi - reduced
                run("UPDATE characters SET demonic_qi=? WHERE id=?", (new_dq, char['id']))
                set_energy(char['id'], energy - dispel_cost)
                energy -= dispel_cost
                log(char['id'], 'cultivate', f'打坐入定，驱散心魔 {reduced} 点（剩余 {new_dq} 点）。')
                result = {'type': 'dispel', 'reduced': reduced, 'new_dq': new_dq}
                char   = me()

        elif action == 'breakthrough':
            cur_i  = char['realm_idx']
            next_i = cur_i + 1
            next_r = REALMS[next_i] if next_i < len(REALMS) else None
            bone_need = BONE_REALM_REQUIREMENT.get(next_i)
            bone_have = bone_owned_count(char['id']) if bone_need else 0
            if not next_r:
                flash('已至修仙巅峰', 'error')
            elif char['exp'] < next_r['exp']:
                flash('修为尚未圆满', 'error')
            elif bone_need and bone_have < bone_need:
                flash(f'突破至【{next_r["name"]}】需集齐 {bone_need} 块仙骨（当前 {bone_have}/{bone_need}），请前往「进阶→寻仙骨」', 'error')
            else:
                m_from = major_idx(cur_i)
                m_to   = major_idx(next_i)
                is_big = m_to > m_from
                # 渡劫：跨越渡劫大境界（合体→大乘以上为高危天劫）
                is_tribulation = is_big and m_from >= 6   # 大乘/渡劫为渡劫期
                if not is_big:
                    success = True
                else:
                    base_c  = BREAKTHROUGH_CHANCE.get(m_from, 0.5)
                    comp_bt = companion_bonus(char, 'breakthrough_bonus')
                    root_bt = TIANLINGGEN_BREAKTHROUGH_BONUS_PCT if char['spirit_root'] == '天灵根' else 0
                    demonic_penalty = GATE_DEMONIC_BREAKTHROUGH_PENALTY_PCT if char['is_demonic'] else 0
                    success = random.random() < max(0.0, base_c + (char['breakthrough_bonus'] + comp_bt + root_bt - demonic_penalty) / 100)

                if success:
                    new_hp, _, _ = realm_stats(next_i)
                    run("UPDATE characters SET realm_idx=?,hp=?,hp_updated=?,breakthrough_bonus=0 WHERE id=?",
                        (next_i, new_hp, now_ts(), char['id']))
                    word = '渡过天劫，' if is_tribulation else '渡过心劫，'
                    log(char['id'], 'cultivate', f'{word}成功突破至【{REALMS[next_i]["name"]}】！')
                    if next_i == DACHENG_BUFF_REALM_MIN:
                        log(char['id'], 'cultivate', f'✦ 证得大乘之境，感【{DACHENG_BUFF_NAME}】，此后修炼所得永久 ×{int(DACHENG_BUFF_MULT)}！')
                    if next_i >= 9:  # 筑基以上发世界公告
                        world_log_add('breakthrough',
                            f'【{char["name"]}】突破至{REALMS[next_i]["name"]}！')
                    # 大境界突破 → 随机3个感悟供选择
                    if is_big:
                        choices = random.sample(PERK_POOL, min(3, len(PERK_POOL)))
                        run("UPDATE characters SET perk_pending=? WHERE id=?",
                            (json.dumps(choices), char['id']))
                        # 检查是否自动出师
                        check_graduation(char['id'])
                        # 师父获得传承功德
                        shifu_ch, _ = get_shifu(char['id'])
                        if shifu_ch:
                            reward = 50 + next_i * 10
                            run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?", (reward, shifu_ch['id']))
                            log(shifu_ch['id'], 'social', f'徒弟【{char["name"]}】突破至{REALMS[next_i]["name"]}，获得传承功德 {reward} 灵石。')
                    xian_seat_pending = False
                    if next_i == len(REALMS) - 1:  # 飞升真仙：天道备下三席神位，供玩家亲择
                        candidates = immortal_seat_candidates(char, 5)
                        run("UPDATE characters SET immortal_seat_pending=?,exp_cap_reached_at=0 WHERE id=?",
                            (json.dumps(candidates, ensure_ascii=False), char['id']))
                        xian_seat_pending = True
                        dissolve_all_discipleships(char['id'], char['name'])
                    result = {'type': 'bt', 'success': True, 'realm': REALMS[next_i]['name'],
                              'tribulation': is_tribulation, 'has_perk': is_big,
                              'xian_seat_pending': xian_seat_pending}
                else:
                    # 失败惩罚随大境界递增，化神以上更重（渡劫失败不再跌小境界，只按比例扣修为）
                    penalty_rate = {0:0.10,1:0.10,2:0.10,3:0.10,4:0.10,5:0.10,6:0.10,7:0.10}.get(m_from, 0.10)
                    from_exp = REALMS[cur_i]['exp']
                    penalty  = int((char['exp'] - from_exp) * penalty_rate)
                    run("UPDATE characters SET exp=?,breakthrough_bonus=breakthrough_bonus+5 WHERE id=?",
                        (max(from_exp, char['exp'] - penalty), char['id']))
                    if is_tribulation:
                        log(char['id'], 'cultivate',
                            f'天劫加身，渡劫失败！损失修为 {penalty}（{int(penalty_rate*100)}%），道心稳固度 +5%。')
                    else:
                        log(char['id'], 'cultivate',
                            f'心劫难渡，突破失败！损失修为 {penalty}（{int(penalty_rate*100)}%），道心稳固度 +5%。')
                    result = {'type': 'bt', 'success': False, 'penalty': penalty,
                              'tribulation': is_tribulation, 'demoted': False}
                char = me()

    realm    = REALMS[char['realm_idx']]
    next_r   = REALMS[char['realm_idx']+1] if char['realm_idx'] < len(REALMS)-1 else None
    exp_min  = realm['exp']
    exp_max  = next_r['exp'] if next_r else exp_min
    exp_prog = char['exp'] - exp_min
    exp_need = exp_max - exp_min if next_r else 1
    exp_pct  = min(100, int(exp_prog / exp_need * 100)) if exp_need else 100
    can_bt   = next_r and char['exp'] >= next_r['exp']

    m_from = major_idx(char['realm_idx'])
    m_to   = major_idx(char['realm_idx']+1) if next_r else m_from
    is_big = m_to > m_from
    root_bt_disp = TIANLINGGEN_BREAKTHROUGH_BONUS_PCT if char['spirit_root'] == '天灵根' else 0
    demonic_penalty_disp = GATE_DEMONIC_BREAKTHROUGH_PENALTY_PCT if char['is_demonic'] else 0
    bt_pct = min(100, max(0, int((BREAKTHROUGH_CHANCE.get(m_from, 1.0) + (char['breakthrough_bonus'] + root_bt_disp - demonic_penalty_disp)/100) * 100))) if is_big else 100

    bone_need = BONE_REALM_REQUIREMENT.get(char['realm_idx'] + 1) if next_r else None
    bone_have = bone_owned_count(char['id']) if bone_need else 0
    bone_ok   = (not bone_need) or bone_have >= bone_need

    my_techs = q("""SELECT t.name, t.exp_bonus FROM techniques t
        JOIN char_techniques ct ON ct.tech_id=t.id
        WHERE ct.char_id=? AND t.type='cultivation'""", (char['id'],))

    ri = char['realm_idx']
    dispel_cost = CULTIVATE_COST * (5 if ri >= 33 else 4 if ri >= 25 else 3 if ri >= 17 else 1)
    # 修炼速度加成明细（用于页面展示）
    _my_sect  = get_char_sect(char['id'])
    _shifu, _ = get_shifu(char['id'])
    cult_bonuses = [
        ("灵根倍率",      f"×{SPIRIT_ROOTS[char['spirit_root']]['mult']}",  None),
        ("感悟",          perk_total(char['id'], 'cultivate_pct'),           "%"),
        ("季节",          cur_season_buff('cultivate'),                      "%"),
        ("功法",          sum(t['exp_bonus'] for t in my_techs),             "%"),
        ("子嗣",          get_offspring_cult_bonus(char['id']),              "%"),
        ("宗门",          get_sect_buff(_my_sect['id']) if _my_sect else 0,  "%"),
        ("师父",          0.15 if _shifu else 0,                             "%"),
        ("丹药/buff",     get_char_buffs(char['id']).get('cultivate_pct',0), "%"),
        ("历史伙伴",      companion_bonus(char, 'exp_pct'),                  "%"),
    ]

    return render_template('cultivate.html',
        char=char, energy=energy, realm=realm, next_r=next_r,
        exp_prog=exp_prog, exp_need=exp_need, exp_pct=exp_pct,
        can_bt=can_bt, is_big=is_big, bt_pct=bt_pct,
        bone_need=bone_need, bone_have=bone_have, bone_ok=bone_ok,
        my_techs=my_techs, result=result,
        dispel_cost=dispel_cost,
        sr=SPIRIT_ROOTS[char['spirit_root']],
        cult_bonuses=cult_bonuses)

# ── 炼体 ───────────────────────────────────────────────────────────────────────

BODY_UNLOCK_REALM = 13   # 结丹初期

@app.route('/game/temper', methods=['GET','POST'])
@login_required
def temper():
    char   = me()
    energy = cur_energy(char)
    result = None

    if char['realm_idx'] < BODY_UNLOCK_REALM:
        flash(f'需达到【{REALMS[BODY_UNLOCK_REALM]["name"]}】方可开始炼体', 'error')
        return redirect(url_for('cultivate'))

    lv    = char['body_level'] or 0
    b_exp = char['body_exp'] or 0
    cur   = BODY_LEVELS[lv]
    nxt   = BODY_LEVELS[lv + 1] if lv + 1 < len(BODY_LEVELS) else None

    if request.method == 'POST' and not is_in_seclusion(char):
        cost = cur['cost']
        if energy < cost:
            flash(f'灵力不足（需 {cost}）', 'error')
        elif nxt and char['realm_idx'] < nxt['realm']:
            flash(f'需达到【{REALMS[nxt["realm"]]["name"]}】方可继续炼体', 'error')
        elif not nxt:
            flash('炼体已至巅峰【神体成就】', 'info')
        else:
            set_energy(char['id'], energy - cost)
            gained = random.randint(15, 35) + char['realm_idx'] // 3
            new_exp = b_exp + gained
            new_lv  = lv
            while new_lv + 1 < len(BODY_LEVELS) and new_exp >= BODY_LEVELS[new_lv + 1]['exp'] \
                    and char['realm_idx'] >= BODY_LEVELS[new_lv + 1]['realm']:
                new_lv += 1
            run("UPDATE characters SET body_exp=?, body_level=? WHERE id=?",
                (new_exp, new_lv, char['id']))
            leveled_up = new_lv > lv
            if leveled_up:
                new_name = BODY_LEVELS[new_lv]['name']
                log(char['id'], 'cultivate',
                    f'炼体有成，突破至【{new_name}】！攻击+{BODY_LEVELS[new_lv]["atk_pct"]}%，防御+{BODY_LEVELS[new_lv]["def_pct"]}%。')
            inc_quest(char['id'], 'temper')
            result = {'gained': gained, 'leveled_up': leveled_up,
                      'new_lv': new_lv, 'new_lv_name': BODY_LEVELS[new_lv]['name']}
            char  = me()
            lv    = char['body_level'] or 0
            b_exp = char['body_exp'] or 0
            cur   = BODY_LEVELS[lv]
            nxt   = BODY_LEVELS[lv + 1] if lv + 1 < len(BODY_LEVELS) else None

    # 进度
    if nxt:
        span = nxt['exp'] - cur['exp']
        prog = b_exp - cur['exp']
        pct  = min(100, int(prog * 100 / span)) if span else 0
    else:
        pct  = 100

    body_atk_pct, body_def_pct = get_body_bonus(char)
    return render_template('temper.html', char=char, energy=energy,
        lv=lv, b_exp=b_exp, cur=cur, nxt=nxt, pct=pct,
        body_atk_pct=body_atk_pct, body_def_pct=body_def_pct,
        result=result, BODY_LEVELS=BODY_LEVELS, REALMS=REALMS)

# ── 探索 ───────────────────────────────────────────────────────────────────────

@app.route('/game/explore', methods=['GET','POST'])
@login_required
def explore():
    char        = me()
    energy      = cur_energy(char)
    result      = None
    all_dungeons = q("SELECT * FROM dungeons WHERE is_active=1 ORDER BY tier")

    if request.method == 'POST':
        if is_in_seclusion(char):
            flash('闭关中无法进行此操作', 'error')
        else:
            did     = int(request.form.get('dungeon_id', 0))
            dungeon = q("SELECT * FROM dungeons WHERE id=? AND is_active=1", (did,), one=True)

            hp_now_chk  = cur_hp(char)
            max_hp_chk, _, _ = realm_stats(char['realm_idx'])
            max_hp_chk += bone_hp_bonus(char['id'])
            hp_pct_chk  = hp_now_chk / max_hp_chk if max_hp_chk else 1

            if not dungeon:
                flash('请选择秘境', 'error')
            elif char['realm_idx'] < dungeon['realm_required']:
                flash(f'需达到【{REALMS[dungeon["realm_required"]]["name"]}】方可踏入{dungeon["name"]}', 'error')
            elif hp_pct_chk < 0.30:
                flash(f'气血不足（当前 {hp_now_chk}/{max_hp_chk}，低于 30% 无法探索，请先休养）', 'error')
            elif energy < dungeon['energy_cost']:
                flash(f'灵力不足（需 {dungeon["energy_cost"]}，当前 {energy}）', 'error')
            else:
                # 山河图感应奇功加成
                spec = q("""SELECT t.effect_json FROM techniques t
                    JOIN char_techniques ct ON ct.tech_id=t.id
                    WHERE ct.char_id=? AND t.type='special'""", (char['id'],))
                explore_bonus = sum(json.loads(r['effect_json'] or '{}').get('explore_bonus', 0) for r in spec) + companion_bonus(char, 'explore_bonus')

                evts = q("""SELECT * FROM explore_events
                    WHERE dungeon_min<=? AND realm_min<=? AND realm_max>=? AND is_active=1""",
                    (dungeon['tier'], char['realm_idx'], char['realm_idx']))

                if evts:
                    def _evt_w(e):
                        w = e['weight']
                        if char['realm_idx'] >= 21 and e['type'] in ('exp', 'exp_stones'):
                            w = max(1, int(w * 0.35))
                        return w
                    evt    = random.choices(evts, weights=[_evt_w(e) for e in evts], k=1)[0]
                    rwd    = json.loads(evt['rewards_json'])
                    mult   = dungeon['reward_mult'] * (1 + explore_bonus)
                    exp_g  = stone_g = 0
                    item_f = None

                    # realm 加成上限 50%，防止高境界指数膨胀
                    realm_scale = 1.0 + min(0.5, char['realm_idx'] * 0.025)
                    hp_loss = 0

                    if evt['type'] == 'exp':
                        raw_exp = int(rwd.get('exp',0) * realm_scale * mult)
                        
                        # 【核心修改：限制膨胀】根据秘境档次设置硬性上限（防止突破到120万）
                        # tier 0(普通): 最高 5,000 | tier 1: 最高 20,000 | tier 2: 最高 50,000 | tier 3(九幽): 最高 100,000
                        exp_cap = [15000, 60000, 150000, 300000][dungeon['tier']]
                        exp_g = min(raw_exp, exp_cap)

                        run("UPDATE characters SET exp=exp+? WHERE id=?", (exp_g, char['id']))
                    elif evt['type'] == 'stones':
                        stone_g = int(rwd.get('stones',0) * (1 + char['realm_idx']*0.05) * mult
                                      * (1 + perk_total(char['id'], 'explore_stone') + companion_bonus(char, 'stones_pct')))
                        run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?", (stone_g, char['id']))
                    elif evt['type'] == 'exp_stones':
                        # 2. 复合事件也同样加上上限控制
                        raw_exp = int(rwd.get('exp',0) * realm_scale * mult)
                        exp_cap = [15000, 60000, 150000, 300000][dungeon['tier']]
                        exp_g   = min(raw_exp, exp_cap)
                        
                        stone_g = int(rwd.get('stones',0) * mult)
                        run("UPDATE characters SET exp=exp+?,spirit_stones=spirit_stones+? WHERE id=?",
                            (exp_g, stone_g, char['id']))
                    elif evt['type'] == 'item':
                        iid = rwd.get('item_id')
                        if iid:
                            item_f = q("SELECT * FROM items WHERE id=?", (iid,), one=True)
                            if item_f:
                                ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?",
                                       (char['id'], iid), one=True)
                                if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?",
                                           (char['id'], iid))
                                else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)",
                                           (char['id'], iid))
                    elif evt['type'] == 'danger':
                        # 危险事件：扣HP，可附带少量修为/灵石
                        max_hp_d, _, _ = realm_stats(char['realm_idx'])
                        max_hp_d += bone_hp_bonus(char['id'])
                        hp_now_d = cur_hp(char)
                        pct      = abs(rwd.get('hp_pct', 20))
                        hp_loss  = int(max_hp_d * pct / 100)
                        new_hp   = max(1, hp_now_d - hp_loss)
                        set_hp(char['id'], new_hp)
                        if rwd.get('exp'):
                            exp_g = int(rwd['exp'] * realm_scale)
                            run("UPDATE characters SET exp=exp+? WHERE id=?", (exp_g, char['id']))
                        if rwd.get('stones'):
                            stone_g = rwd['stones']
                            run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
                                (stone_g, char['id']))

                    pet_f = None
                    if evt['type'] == 'pet':
                        ptid = rwd.get('pet_type_id')
                        if ptid:
                            pet_f = q("SELECT * FROM pet_types WHERE id=?", (ptid,), one=True)
                            if pet_f:
                                run("INSERT INTO char_pets (char_id,pet_type_id,nickname,level,obtained_at) VALUES (?,?,'',1,?)",
                                    (char['id'], ptid, now_ts()))

                    set_energy(char['id'], energy - dungeon['energy_cost'])
                    energy -= dungeon['energy_cost']

                    # 额外掉落：种子（与主事件无关的独立概率）
                    # 高阶修士采药概率递减（结丹后每升一小境界降低5%）
                    drop_mult = max(0.10, 1.0 - max(0, char['realm_idx'] - 9) * 0.05)
                    bonus_seed = None
                    tier = dungeon['tier']
                    seed_pool = []
                    if tier >= 0:
                        seed_pool += [("灵草种子",0.10),("青木叶种子",0.10),
                                      ("血参种子",0.07),("玉露草种子",0.07)]
                    if tier >= 1:
                        seed_pool += [("天门冬种子",0.06)]
                    if tier >= 2:
                        seed_pool += [("九叶草种子",0.04)]
                    if tier >= 3:
                        seed_pool += [("七彩灵芝种子",0.02)]
                    for sname, schance in seed_pool:
                        if random.random() < schance * drop_mult:
                            sitem = q("SELECT * FROM items WHERE name=?", (sname,), one=True)
                            if sitem:
                                ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?",
                                       (char['id'], sitem['id']), one=True)
                                if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?",
                                           (char['id'], sitem['id']))
                                else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)",
                                           (char['id'], sitem['id']))
                                bonus_seed = sitem
                            break  # 每次探索最多得一颗种子

                    # 探索心魔积累（结丹+，按秘境档次；化神以上额外加成）
                    dq_explore = 0
                    if char['realm_idx'] >= 13:
                        dq_explore = dungeon['tier'] + 1  # tier0→1, tier1→2, tier2→3, tier3→4
                        if char['realm_idx'] >= 21:       # 化神以上额外 +2
                            dq_explore += 2
                        if char['realm_idx'] >= 25:       # 合体以上再额外 +2
                            dq_explore += 2
                        cur_dq = char['demonic_qi'] or 0
                        new_dq_e = min(100, cur_dq + dq_explore)
                        run("UPDATE characters SET demonic_qi=? WHERE id=?", (new_dq_e, char['id']))
                        if cur_dq >= 100:
                            dq_burn = max(1, int(char['exp'] * 0.001))
                            run("UPDATE characters SET exp=MAX(0,exp-?) WHERE id=?", (dq_burn, char['id']))
                            log(char['id'], 'system', f'心魔已满，道基受损，修为 -{dq_burn}。')
                        elif new_dq_e >= 90 and cur_dq < 90:
                            log(char['id'], 'system', '⚠ 心魔已达 90，再不化解将动摇道基！')
                        elif new_dq_e >= 80 and cur_dq < 80:
                            log(char['id'], 'system', '⚠ 心魔已达 80，须留意化解。')

                    parts = [f'踏入【{dungeon["name"]}】，{evt["title"]}']
                    if hp_loss:    parts.append(f'损失气血 {hp_loss}')
                    if exp_g:      parts.append(f'获得修为 {exp_g}')
                    if stone_g:    parts.append(f'获得灵石 {stone_g}')
                    if item_f:     parts.append(f'获得【{item_f["name"]}】')
                    if pet_f:      parts.append(f'收服灵兽【{pet_f["name"]}】')
                    if bonus_seed: parts.append(f'额外发现【{bonus_seed["name"]}】')
                    if dq_explore: parts.append(f'心魔 +{dq_explore}')
                    inc_quest(char['id'], 'explore')
                    inc_sect_quest(char['id'], 'explore')
                    log(char['id'], 'explore', '；'.join(parts) + '。')

                    char   = me()
                    result = {'dungeon': dungeon, 'evt': evt,
                              'exp_g': exp_g, 'stone_g': stone_g,
                              'item_f': item_f, 'pet_f': pet_f, 'mult': mult,
                              'bonus_seed': bonus_seed, 'hp_loss': hp_loss,
                              'dq_explore': dq_explore}

    hp_now = cur_hp(char)
    max_hp, _, _ = realm_stats(char['realm_idx'])
    max_hp += bone_hp_bonus(char['id'])
    return render_template('explore.html',
        char=char, energy=energy, result=result,
        all_dungeons=all_dungeons, hp_now=hp_now, max_hp=max_hp)

# ── 战斗场 ─────────────────────────────────────────────────────────────────────

# 本命武器可无限强化后玩家整体攻击力水涨船高，合体及以上大境界的妖兽同步变强，
# 但修为/灵石奖励与掉落保持不变，只提升战斗强度。
MONSTER_HEJI_BUFF_BASE = 0.45   # 合体初期起的基础加成
MONSTER_HEJI_BUFF_STEP = 0.25   # 每高一个大境界（大乘/渡劫/真仙）再 +25%

def monster_realm_buff_mult(monster):
    """按妖兽自身所属大境界（realm_min）计算战斗强度倍率，合体以下恒为1。"""
    try:
        m = major_idx(monster['realm_min'])
    except Exception:
        return 1.0
    if m < 5:   # 5 = 合体
        return 1.0
    return 1.0 + MONSTER_HEJI_BUFF_BASE + (m - 5) * MONSTER_HEJI_BUFF_STEP

def scaled_monster_combat_stats(monster):
    """返回用于战斗展示/结算的妖兽字典副本：hp/攻/防按大境界加成放大，
    exp_reward/stone_reward/drop_json 等奖励字段保持原值不变。"""
    mult = monster_realm_buff_mult(monster)
    if mult == 1.0:
        return dict(monster)
    d = dict(monster)
    d['hp']      = int(d['hp'] * mult)
    d['attack']  = int(d['attack'] * mult)
    d['defense'] = int(d['defense'] * mult)
    return d

def get_or_refresh_combat_pool(char):
    """返回该角色当前战斗池。若不存在或已过期则重新抽取。
    返回 (pool_row_dict, monsters_list, secs_to_refresh)。"""
    cid  = char['id']
    now  = now_ts()
    pool = q("SELECT * FROM char_combat_pool WHERE char_id=?", (cid,), one=True)
    pool = dict(pool) if pool else None

    expired = (not pool) or (now - pool['generated_at'] >= COMBAT_POOL_REFRESH)
    if expired:
        # 保留上一轮未挑战的妖物（已战毕的丢弃），刷新只新增，不替换
        kept_mids = []
        if pool:
            old_mids     = json.loads(pool['monster_ids'] or '[]')
            old_defeated = set(json.loads(pool['defeated'] or '[]'))
            kept_mids    = [m for m in old_mids if m not in old_defeated]

        # 抽取与本角色境界匹配的妖物，排除已在池中的，避免重复
        candidates = q("""SELECT * FROM monsters
            WHERE realm_min <= ? AND realm_max >= ? AND is_active=1""",
            (char['realm_idx'] + 3, char['realm_idx'] - 2))
        cands = [m for m in candidates if m['id'] not in kept_mids]
        room  = max(0, COMBAT_POOL_MAX - len(kept_mids))
        add_n = min(COMBAT_POOL_SIZE, room, len(cands))
        chosen = random.sample(cands, add_n) if add_n > 0 else []
        mids   = kept_mids + [m['id'] for m in chosen]

        if pool:
            run("UPDATE char_combat_pool SET monster_ids=?, defeated='[]', generated_at=? WHERE char_id=?",
                (json.dumps(mids), now, cid))
        else:
            run("INSERT INTO char_combat_pool (char_id,monster_ids,defeated,generated_at) VALUES (?,?,?,?)",
                (cid, json.dumps(mids), '[]', now))
        pool = {'char_id': cid, 'monster_ids': json.dumps(mids), 'defeated': '[]', 'generated_at': now}

    mids     = json.loads(pool['monster_ids'])
    defeated = set(json.loads(pool['defeated']))
    monsters = []
    for mid in mids:
        m = q("SELECT * FROM monsters WHERE id=?", (mid,), one=True)
        if m:
            monsters.append({'monster': scaled_monster_combat_stats(m), 'defeated': mid in defeated})

    secs_left = max(0, COMBAT_POOL_REFRESH - (now - pool['generated_at']))
    return pool, monsters, secs_left


@app.route('/game/combat')
@login_required
def combat():
    char     = me()
    energy   = cur_energy(char)
    hp_now   = cur_hp(char)
    max_hp, _, _ = realm_stats(char['realm_idx'])
    max_hp += bone_hp_bonus(char['id'])
    hp_pct   = hp_now / max_hp if max_hp else 1
    _, pool_monsters, secs_left = get_or_refresh_combat_pool(char)

    equip_atk, equip_def = get_equip_bonuses(char)
    equipped_weapon   = q("SELECT * FROM items WHERE id=?", (char['equipped_weapon'],), one=True) if char['equipped_weapon'] else None
    equipped_artifact = q("SELECT * FROM items WHERE id=?", (char['equipped_artifact'],), one=True) if char['equipped_artifact'] else None
    pet_bonus = get_pet_bonus(char)
    body_atk_pct, body_def_pct = get_body_bonus(char)
    atk_techs = q("""SELECT t.power FROM techniques t
        JOIN char_techniques ct ON ct.tech_id=t.id
        WHERE ct.char_id=? AND t.type='attack'""", (char['id'],))
    tech_atk = sum(r['power'] for r in atk_techs)

    refresh_h = secs_left // 3600
    refresh_m = (secs_left % 3600) // 60

    fighter = _build_fighter_stats(char)
    return render_template('combat.html',
        char=char, energy=energy, pool_monsters=pool_monsters,
        hp_now=hp_now, max_hp=max_hp, hp_pct=hp_pct,
        equip_atk=equip_atk, equip_def=equip_def, tech_atk=tech_atk,
        body_atk_pct=body_atk_pct, body_def_pct=body_def_pct,
        equipped_weapon=equipped_weapon, equipped_artifact=equipped_artifact,
        pet_bonus=pet_bonus, fighter=fighter,
        refresh_h=refresh_h, refresh_m=refresh_m, secs_left=secs_left,
        COMBAT_POOL_REFRESH=COMBAT_POOL_REFRESH, COMBAT_POOL_SIZE=COMBAT_POOL_SIZE,
        COMBAT_POOL_MAX=COMBAT_POOL_MAX)

@app.route('/game/combat/<int:mid>', methods=['POST'])
@login_required
def fight(mid):
    char    = me()
    energy  = cur_energy(char)
    monster = q("SELECT * FROM monsters WHERE id=? AND is_active=1", (mid,), one=True)
    if monster:
        monster = scaled_monster_combat_stats(monster)  # 合体+妖兽战斗强度加成，奖励字段不受影响

    if is_in_seclusion(char):
        flash('闭关中无法进行此操作', 'error')
        return redirect(url_for('combat'))
    if energy < COMBAT_COST:
        flash('灵力不足，无法出战', 'error')
        return redirect(url_for('combat'))
    if not monster:
        flash('目标不存在', 'error')
        return redirect(url_for('combat'))

    # 检查妖物是否在本轮战斗池中
    pool_row = q("SELECT * FROM char_combat_pool WHERE char_id=?", (char['id'],), one=True)
    if not pool_row or mid not in json.loads(pool_row['monster_ids'] or '[]'):
        flash('此妖物不在你当前的战斗池中', 'error')
        return redirect(url_for('combat'))
    defeated_set = set(json.loads(pool_row['defeated'] or '[]'))
    if mid in defeated_set:
        flash('此妖物本轮已交手过，等待刷新', 'error')
        return redirect(url_for('combat'))

    max_hp, _, _ = realm_stats(char['realm_idx'])
    max_hp += bone_hp_bonus(char['id'])
    hp_now = cur_hp(char)

    if hp_now < int(max_hp * MIN_FIGHT_HP_PCT):
        flash(f'气血不足（{hp_now}/{max_hp}），需至少 {int(MIN_FIGHT_HP_PCT*100)}% 气血方可出战', 'error')
        return redirect(url_for('combat'))

    equip_atk, equip_def = get_equip_bonuses(char)
    won, rounds, final_hp, p_wx_desc, m_wx_desc = simulate(char, monster,
        equip_atk=equip_atk, equip_def=equip_def, start_hp=hp_now)

    # 保存战后气血（最低保留 1）
    set_hp(char['id'], max(1, final_hp))
    set_energy(char['id'], energy - COMBAT_COST)

    exp_g = stone_g = 0
    drops = []
    if won:
        exp_g   = monster['exp_reward']
        stone_g = int(monster['stone_reward'])
        run("UPDATE characters SET exp=exp+?,spirit_stones=spirit_stones+? WHERE id=?",
            (exp_g, stone_g, char['id']))
        for d in json.loads(monster['drop_json']):
            if random.random() < d['chance']:
                it = q("SELECT * FROM items WHERE id=?", (d['item_id'],), one=True)
                if it:
                    drops.append(it)
                    ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (char['id'], d['item_id']), one=True)
                    if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?", (char['id'], d['item_id']))
                    else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)", (char['id'], d['item_id']))

        inc_quest(char['id'], 'combat', 2 if char.get('sword_token_id') else 1)
        inc_sect_quest(char['id'], 'combat')
        # 剑修经验 & 专属任务
        if char.get('sword_token_id'):
            run("UPDATE characters SET sword_exp=sword_exp+? WHERE id=?",
                (SWORD_COMBAT_EXP, char['id']))
            inc_quest(char['id'], 'sword')
        msg = f'斩杀【{monster["name"]}】！获得修为 {exp_g}，灵石 {stone_g}。'
        if drops: msg += f' 掉落：{"、".join(i["name"] for i in drops)}。'
    else:
        msg = f'与【{monster["name"]}】交手，不敌败退，气血大损。'
    log(char['id'], 'combat', msg)

    # 无论胜负，将此妖物标记为本轮已交手
    defeated_set.add(mid)
    run("UPDATE char_combat_pool SET defeated=? WHERE char_id=?",
        (json.dumps(sorted(defeated_set)), char['id']))

    fresh = me()
    combat_spell = q("SELECT custom_name,element FROM char_spells WHERE char_id=? AND learned=1 ORDER BY RANDOM() LIMIT 1", (fresh['id'],), one=True)
    combat_move  = q("SELECT custom_name,move_num FROM char_spell_moves WHERE char_id=? ORDER BY RANDOM() LIMIT 1", (fresh['id'],), one=True)
    spell_label  = (combat_spell['custom_name'] or SPELL_ELEMENT_NAMES.get(combat_spell['element'], '法术')) if combat_spell else None
    move_label   = ((combat_move['custom_name'] or f'第{combat_move["move_num"]}式') if combat_move else None)
    return render_template('combat_result.html',
        char=fresh, monster=monster, won=won, rounds=rounds,
        exp_g=exp_g, stone_g=stone_g, drops=drops,
        max_hp=max_hp, final_hp=max(1, final_hp),
        energy=energy - COMBAT_COST,
        p_wx_desc=p_wx_desc, m_wx_desc=m_wx_desc,
        spell_label=spell_label, move_label=move_label)

# ── 寻仙骨 ─────────────────────────────────────────────────────────────────────

@app.route('/game/bones', methods=['GET','POST'])
@login_required
def bones():
    char   = me()
    energy = cur_energy(char)
    result = None

    if request.method == 'POST':
        action = request.form.get('action', 'search')
        if action == 'transform':
            if bone_owned_count(char['id']) < BONE_TOTAL:
                flash(f'仙骨尚未集齐（需 {BONE_TOTAL} 块）', 'error')
            elif char['bone_transformed']:
                flash('真仙蜕变已然成就，无需再次触发', 'info')
            else:
                grant_perk(char['id'], {'key': 'cultivate_pct', 'val': BONE_FULL_CULTIVATE_PCT},
                           BONE_FULL_PERK_LABEL)
                run("UPDATE characters SET bone_transformed=1 WHERE id=?", (char['id'],))
                log(char['id'], 'system',
                    f'✦ 206 块仙骨尽数归位，周身脱胎换骨，真仙蜕变已成！修炼速度永久 +{int(BONE_FULL_CULTIVATE_PCT*100)}%！')
                world_log_add('bones', f'【{char["name"]}】集齐 206 块仙骨，达成真仙蜕变！')
                result = {'transformed': True}
                flash('真仙蜕变已成就！修炼速度永久 +200%', 'success')
        elif is_in_seclusion(char):
            flash('闭关中无法进行此操作', 'error')
        elif energy < BONE_SEARCH_COST:
            flash(f'灵力不足，需 {BONE_SEARCH_COST}', 'error')
        elif bone_owned_count(char['id']) >= BONE_TOTAL:
            flash('206 块仙骨已集齐，无需再寻。', 'info')
        else:
            set_energy(char['id'], energy - BONE_SEARCH_COST)
            found, bone_name, milestone = bone_search(char['id'])
            result = {'found': found, 'name': bone_name, 'milestone': milestone}
            if found:
                log(char['id'], 'system', f'寻得一块仙骨——{bone_name}！气血上限永久 +{BONE_HP_BONUS}。')
                if milestone:
                    log(char['id'], 'system',
                        f'✦ 仙骨已凑满 {milestone} 块，忽有所悟，修炼速度永久 +{int(BONE_MILESTONE_CULTIVATE_PCT*100)}%！')

    fresh  = me()
    owned  = q("SELECT bone_id FROM char_bones WHERE char_id=? ORDER BY found_at", (fresh['id'],))
    owned_names = [XIAN_BONE_NAMES[r['bone_id']] for r in owned]
    # 按异兽归属统计已获仙骨构成占比（以「兽名之部位」的兽名前缀分类）
    beast_counts = {b: 0 for b in BONE_BEASTS}
    for name in owned_names:
        beast = name.split('之', 1)[0]
        if beast in beast_counts:
            beast_counts[beast] += 1
    owned_n = len(owned_names)
    beast_composition = [
        {'name': b, 'count': beast_counts[b],
         'pct': round(beast_counts[b] / owned_n * 100, 1) if owned_n else 0}
        for b in BONE_BEASTS
    ]
    return render_template('bones.html', char=fresh, energy=cur_energy(fresh), result=result,
        BONE_SEARCH_COST=BONE_SEARCH_COST, BONE_TOTAL=BONE_TOTAL, BONE_HP_BONUS=BONE_HP_BONUS,
        BONE_MILESTONE_CULTIVATE_PCT=BONE_MILESTONE_CULTIVATE_PCT,
        BONE_FULL_CULTIVATE_PCT=BONE_FULL_CULTIVATE_PCT,
        owned_names=owned_names, owned_count=len(owned_names),
        beast_composition=beast_composition)

# ── 背包 ───────────────────────────────────────────────────────────────────────


@app.route('/game/inventory', methods=['GET','POST'])
@login_required
def inventory():
    char = me()
    if request.method == 'POST':
        iid    = int(request.form.get('item_id', 0))
        action = request.form.get('action')
        inv    = q("SELECT * FROM inventory WHERE char_id=? AND item_id=?", (char['id'], iid), one=True)
        item   = q("SELECT * FROM items WHERE id=?", (iid,), one=True)

        if not item:
            flash('物品不存在', 'error')
        elif action == 'use':
            if item['type'] == 'pill':
                eff   = json.loads(item['effect_json'])
                parts = []
                used  = False

                if 'hp_pct' in eff:
                    # 按百分比回复气血（自动适配境界）
                    max_hp, _, _ = realm_stats(char['realm_idx'])
                    max_hp += bone_hp_bonus(char['id'])
                    heal   = int(max_hp * eff['hp_pct'] / 100)
                    hp_now = cur_hp(char)
                    set_hp(char['id'], min(max_hp, hp_now + heal))
                    parts.append(f'恢复气血 {heal}（{eff["hp_pct"]}% 上限）')
                    used = True
                if 'exp' in eff:
                    exp_gained = eff['exp']
                    demonic_qi = char['demonic_qi'] or 0
                    dm_add = 0

                    # 丹药服用次数（同种药的累计）
                    usage_row = q("SELECT count FROM pill_usage WHERE char_id=? AND item_id=?",
                                  (char['id'], iid), one=True)
                    pill_count = (usage_row['count'] if usage_row else 0) + 1  # 本次服用后的次数
                    run("""INSERT INTO pill_usage (char_id,item_id,count) VALUES (?,?,1)
                           ON CONFLICT(char_id,item_id) DO UPDATE SET count=count+1""",
                        (char['id'], iid))

                    # 滥服倍率
                    if pill_count >= 500:
                        overuse_mult = 10
                    elif pill_count >= 300:
                        overuse_mult = 6
                    elif pill_count >= 100:
                        overuse_mult = 3
                    else:
                        overuse_mult = 1

                    if char['realm_idx'] >= 13:
                        # 心魔减少丹药功效
                        if demonic_qi > 0:
                            m = major_idx(char['realm_idx'])
                            dq_scale   = 1.0 + max(0, m - 2) * 0.3
                            dq_penalty = min(0.90, demonic_qi / 100 * dq_scale)
                            exp_gained = int(exp_gained * (1 - dq_penalty))
                        # 服丹积累心魔，滥服倍率加重
                        dm_add = max(2, min(20, eff['exp'] // 1500)) * overuse_mult
                        new_dq = min(100, demonic_qi + dm_add)
                        run("UPDATE characters SET demonic_qi=? WHERE id=?", (new_dq, char['id']))
                        if demonic_qi >= 100:
                            cur_exp = q("SELECT exp FROM characters WHERE id=?", (char['id'],), one=True)['exp']
                            dq_burn = max(1, int(cur_exp * 0.001))
                            run("UPDATE characters SET exp=MAX(0,exp-?) WHERE id=?", (dq_burn, char['id']))
                            log(char['id'], 'system', f'心魔已满，道基受损，修为 -{dq_burn}。')
                        elif new_dq >= 90 and demonic_qi < 90:
                            flash('⚠ 心魔已达 90，再不化解将动摇道基！', 'error')
                        elif new_dq >= 80 and demonic_qi < 80:
                            flash('⚠ 心魔已达 80，须留意化解。', 'error')
                    else:
                        # 结丹以下无心魔：100次后药效减半
                        if pill_count >= 100:
                            exp_gained = int(exp_gained * 0.5)

                    run("UPDATE characters SET exp=exp+? WHERE id=?", (exp_gained, char['id']))
                    parts.append(f'增加修为 {exp_gained}')
                    if dm_add:
                        parts.append(f'心魔 +{dm_add}（当前 {new_dq}）')
                    # 仅在恰好跨过阈值时提示
                    if pill_count in (100, 300, 500):
                        if char['realm_idx'] >= 13:
                            mult_map = {100: 3, 300: 6, 500: 10}
                            parts.append(f'⚠ 此药已服 {pill_count} 次，心魔积累加剧（×{mult_map[pill_count]}）！')
                        else:
                            parts.append(f'⚠ 此药已服 {pill_count} 次，药效减半。')
                    used = True
                if 'energy' in eff:
                    if item['name'] == '凝气丹' and char['realm_idx'] < 17:
                        flash('凝气丹药力强横，需元婴境界方可承受。', 'error')
                    else:
                        energy_gained = eff['energy']
                        if item['name'] != '引灵丹':
                            # 非引灵丹：100次后灵力恢复减半，需记录次数
                            e_usage = q("SELECT count FROM pill_usage WHERE char_id=? AND item_id=?",
                                        (char['id'], iid), one=True)
                            e_count = (e_usage['count'] if e_usage else 0) + 1
                            if 'exp' not in eff:  # exp路径已记录，避免重复
                                run("""INSERT INTO pill_usage (char_id,item_id,count) VALUES (?,?,1)
                                       ON CONFLICT(char_id,item_id) DO UPDATE SET count=count+1""",
                                    (char['id'], iid))
                            if e_count >= 100:
                                energy_gained = energy_gained // 2
                                if e_count == 100:
                                    parts.append(f'⚠ 此药已服 {e_count} 次，灵力恢复减半。')
                        en = cur_energy(char)
                        set_energy(char['id'], min(energy_cap(char), en + energy_gained))
                        parts.append(f'恢复灵力 {energy_gained}')
                        used = True
                if 'energy_regen_pct' in eff:
                    val = eff['energy_regen_pct']
                    run("INSERT INTO char_perks (char_id,perk_key,value,realm_earned,earned_at) VALUES (?,?,?,?,?)",
                        (char['id'], 'energy_regen_pct', val, REALMS[char['realm_idx']]['name'], now_ts()))
                    parts.append(f'灵力回复速度永久 +{int(val*100)}%')
                    used = True
                if eff.get('type') == 'buff' and 'key' in eff:
                    add_char_buff(char['id'], eff['key'], eff['value'], eff['hours'], source=item['name'])
                    parts.append(f'{eff["key"]} +{int(eff["value"]*100)}%，持续 {eff["hours"]}h')
                    used = True
                if eff.get('energy_full'):
                    set_energy(char['id'], energy_cap(char))
                    parts.append('灵力全满')
                    used = True
                if 'lifespan_flat' in eff:
                    run("UPDATE characters SET lifespan_bonus=lifespan_bonus+? WHERE id=?",
                        (eff['lifespan_flat'], char['id']))
                    parts.append(f'延寿 +{eff["lifespan_flat"]} 年')
                    used = True
                if 'breakthrough_bonus' in eff:
                    bonus = eff['breakthrough_bonus']
                    run("UPDATE characters SET breakthrough_bonus=MIN(100,breakthrough_bonus+?) WHERE id=?",
                        (bonus, char['id']))
                    parts.append(f'道心稳固度 +{bonus}%')
                    used = True
                if 'demonic_qi' in eff:
                    dq_delta = eff['demonic_qi']  # 负数为驱散
                    if dq_delta < 0 and char['realm_idx'] >= HETI_REALM_MIN:
                        dq_delta = -max(1, int(abs(dq_delta) * 0.7))  # 合体+心魔道具效果打七折
                    cur_dq = char['demonic_qi'] or 0
                    new_dq = max(0, min(100, cur_dq + dq_delta))
                    run("UPDATE characters SET demonic_qi=? WHERE id=?", (new_dq, char['id']))
                    if dq_delta < 0:
                        parts.append(f'心魔 -{abs(dq_delta)}（剩余 {new_dq}）')
                    else:
                        parts.append(f'心魔 +{dq_delta}')
                    used = True
                if 'pollution' in eff:
                    poll_delta = eff['pollution']  # 负数为净化
                    cur_poll = char['pollution'] or 0
                    new_poll = max(0, cur_poll + poll_delta)
                    run("UPDATE characters SET pollution=? WHERE id=?", (new_poll, char['id']))
                    if poll_delta < 0:
                        parts.append(f'污染 -{abs(poll_delta)}（剩余 {new_poll}）')
                    else:
                        parts.append(f'污染 +{poll_delta}')
                    used = True

                if used and inv:
                    if inv['quantity'] <= 1:
                        run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], iid))
                    else:
                        run("UPDATE inventory SET quantity=quantity-1 WHERE char_id=? AND item_id=?", (char['id'], iid))
                    msg = f'服用【{item["name"]}】，{"，".join(parts)}。'
                    log(char['id'], 'system', msg)
                    flash(msg, 'success')
                elif not used:
                    if eff.get('xisui_material'):
                        flash(f'【{item["name"]}】需在洗髓伐经时使用，不可直接服用。', 'error')
                    else:
                        flash(f'【{item["name"]}】没有可发动的效果。', 'error')

            elif item['type'] == 'talisman':
                if not inv or inv['quantity'] < 1:
                    flash('没有此符', 'error')
                else:
                    eff = json.loads(item['effect_json'] or '{}')
                    etype = eff.get('type')
                    parts = []
                    if etype == 'buff':
                        add_char_buff(char['id'], eff['key'], eff['value'], eff['hours'], source=item['name'])
                        pct = int(eff['value'] * 100)
                        parts.append(f'{eff["key"]} +{pct}%，持续 {eff["hours"]}h')
                    elif etype == 'instant':
                        k, v = eff['key'], eff['value']
                        if k == 'demonic_qi':
                            if v < 0 and char['realm_idx'] >= HETI_REALM_MIN:
                                v = -max(1, int(abs(v) * 0.7))  # 合体+心魔道具效果打七折
                            cur_dq = char['demonic_qi'] or 0
                            new_dq = max(0, cur_dq + v)
                            run("UPDATE characters SET demonic_qi=? WHERE id=?", (new_dq, char['id']))
                            parts.append(f'心魔 {v}（剩余 {new_dq}）')
                        elif k == 'lifespan_flat':
                            run("UPDATE characters SET lifespan_bonus=lifespan_bonus+? WHERE id=?", (v, char['id']))
                            parts.append(f'延寿 +{v} 年')
                    if parts:
                        if inv['quantity'] <= 1:
                            run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], iid))
                        else:
                            run("UPDATE inventory SET quantity=quantity-1 WHERE char_id=? AND item_id=?", (char['id'], iid))
                        msg = f'激活【{item["name"]}】，{"，".join(parts)}。'
                        log(char['id'], 'system', msg)
                        flash(msg, 'success')

            elif item['type'] == 'technique_scroll':
                eff  = json.loads(item['effect_json'])
                tid  = eff.get('tech_id')
                tech = q("SELECT * FROM techniques WHERE id=?", (tid,), one=True) if tid else None
                if not tech:
                    flash('功法卷轴已损坏', 'error')
                elif char['realm_idx'] < tech['realm_required']:
                    flash(f'需达到【{REALMS[tech["realm_required"]]["name"]}】方可修炼', 'error')
                elif q("SELECT 1 FROM char_techniques WHERE char_id=? AND tech_id=?", (char['id'], tid), one=True):
                    flash('已习得此功法', 'error')
                else:
                    run("INSERT INTO char_techniques (char_id,tech_id,learned_at) VALUES (?,?,?)", (char['id'], tid, now_ts()))
                    if inv['quantity'] <= 1:
                        run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], iid))
                    else:
                        run("UPDATE inventory SET quantity=quantity-1 WHERE char_id=? AND item_id=?", (char['id'], iid))
                    msg = f'研习【{item["name"]}】，习得功法【{tech["name"]}】！'
                    log(char['id'], 'system', msg)
                    flash(msg, 'success')
            elif item['type'] == 'rename_card':
                new_name = request.form.get('new_name', '').strip()[:12]
                if not new_name:
                    flash('请输入新道号', 'error')
                elif q("SELECT 1 FROM characters WHERE name=? AND id!=?", (new_name, char['id']), one=True):
                    flash('该道号已被使用', 'error')
                else:
                    old_name = char['name']
                    run("UPDATE characters SET name=? WHERE id=?", (new_name, char['id']))
                    if inv['quantity'] <= 1:
                        run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], iid))
                    else:
                        run("UPDATE inventory SET quantity=quantity-1 WHERE char_id=? AND item_id=?", (char['id'], iid))
                    log(char['id'], 'system', f'使用改名卡，道号由【{old_name}】改为【{new_name}】。')
                    flash(f'道号已改为【{new_name}】！', 'success')
            else:
                flash('此物品不能直接使用', 'error')

        elif action == 'amber_boost':
            amber = q("SELECT * FROM items WHERE name='琥珀'", one=True)
            if not amber or iid != amber['id']:
                flash('此物品不是琥珀', 'error')
            elif not inv or inv['quantity'] < AMBER_ENERGY_CAP_COST:
                flash(f'琥珀不足，需 {AMBER_ENERGY_CAP_COST} 枚', 'error')
            else:
                if inv['quantity'] <= AMBER_ENERGY_CAP_COST:
                    run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], iid))
                else:
                    run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?",
                        (AMBER_ENERGY_CAP_COST, char['id'], iid))
                run("UPDATE characters SET energy_cap_bonus=energy_cap_bonus+? WHERE id=?",
                    (AMBER_ENERGY_CAP_GAIN, char['id']))
                log(char['id'], 'system', f'凝炼琥珀×{AMBER_ENERGY_CAP_COST}，灵力上限永久 +{AMBER_ENERGY_CAP_GAIN}。')
                flash(f'消耗琥珀×{AMBER_ENERGY_CAP_COST}，灵力上限永久 +{AMBER_ENERGY_CAP_GAIN}！', 'success')

        elif action == 'sell':
            qty = max(1, int(request.form.get('sell_qty', 1)))
            if not inv or inv['quantity'] < qty:
                flash('数量不足', 'error')
            elif item['market_price'] <= 0:
                flash('此物品无法出售', 'error')
            else:
                sell_price = max(1, item['market_price'] // 2)
                total      = sell_price * qty
                run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?", (total, char['id']))
                if inv['quantity'] <= qty:
                    run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], iid))
                    if item['type'] == 'cauldron':
                        run("UPDATE characters SET cauldron_id=NULL WHERE id=? AND cauldron_id=?", (char['id'], iid))
                    elif item['type'] == 'forge':
                        run("UPDATE characters SET forge_id=NULL WHERE id=? AND forge_id=?", (char['id'], iid))
                    elif item['type'] == 'brush':
                        run("UPDATE characters SET fulu_id=NULL WHERE id=? AND fulu_id=?", (char['id'], iid))
                    elif item['type'] == 'sword_token':
                        run("UPDATE characters SET sword_token_id=NULL WHERE id=? AND sword_token_id=?", (char['id'], iid))
                else:
                    run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?",
                        (qty, char['id'], iid))
                # 出售炉具：记录冷却，8小时内不能购买任何炉具
                if item['type'] in ('cauldron', 'forge', 'brush'):
                    run("INSERT OR REPLACE INTO site_config (key,value) VALUES (?,?)",
                        (f'furnace_sell_cd_{char["id"]}', str(now_ts() + 8 * 3600)))
                if item['type'] == 'beast_token':
                    run("UPDATE characters SET beast_token_id=NULL, active_pet2_id=NULL WHERE id=?", (char['id'],))
                if item['type'] == 'heqing_token':
                    run("UPDATE characters SET heqing_token_id=NULL WHERE id=?", (char['id'],))
                # 出售专修道具：损失 30% 专修经验
                _exp_penalty = {
                    'cauldron':     ('alchemy_exp',  '炼丹经验'),
                    'forge':        ('forge_exp',    '炼器经验'),
                    'brush':        ('fulu_exp',     '符修经验'),
                    'beast_token':  ('beast_exp',    '御灵经验'),
                    'heqing_token': ('heqing_exp',   '合欢经验'),
                }
                if item['type'] in _exp_penalty:
                    ecol, ename = _exp_penalty[item['type']]
                    cur_e = char.get(ecol, 0) or 0
                    loss  = int(cur_e * 0.30)
                    if loss > 0:
                        run(f"UPDATE characters SET {ecol}=? WHERE id=?", (max(0, cur_e - loss), char['id']))
                        msg_extra = f'，出售专修道具损失 30% {ename}（-{loss}）'
                    else:
                        msg_extra = ''
                else:
                    msg_extra = ''
                msg = f'出售【{item["name"]}】×{qty}，获得灵石 {total}{msg_extra}。'
                log(char['id'], 'market', msg)
                flash(msg, 'success')

        elif action == 'equip':
            # 五路互斥：入路前先检查
            if item['type'] in CRAFT_PATH_TYPES:
                existing = current_craft_path(char['id'])
                if existing and existing != item['type']:
                    flash(f'你已踏上【{PATH_NAMES[existing]}】之路，需先出售现有道具方可改修他路。', 'error')
                    return redirect(url_for('inventory'))
            if not inv:
                flash('背包中没有此物品', 'error')
            elif item['type'] == 'weapon' and gate_equip_locked(char):
                flash('异世之门活动期间攻击力已锁定，无法更换武器。', 'error')
            elif item['type'] == 'weapon':
                run("UPDATE characters SET equipped_weapon=? WHERE id=?", (iid, char['id']))
                eff = json.loads(item['effect_json'] or '{}')
                flash(f'已装备【{item["name"]}】（攻击 +{eff.get("attack",0)}）', 'success')
                log(char['id'], 'system', f'装备【{item["name"]}】。')
            elif item['type'] == 'artifact':
                run("UPDATE characters SET equipped_artifact=? WHERE id=?", (iid, char['id']))
                eff = json.loads(item['effect_json'] or '{}')
                flash(f'已装备【{item["name"]}】（防御 +{eff.get("defense",0)}）', 'success')
                log(char['id'], 'system', f'装备【{item["name"]}】。')
            elif item['type'] == 'cauldron':
                existing_path = current_craft_path(char['id'])
                if existing_path and existing_path != 'cauldron':
                    flash(f'你已踏上【{PATH_NAMES.get(existing_path, existing_path)}】之路，各修行之路互斥，无法同时持有道具。', 'error')
                    return redirect(url_for('inventory'))
                already_has_cauldron = char_has_furnace(char['id'], 'cauldron')
                if not already_has_cauldron:
                    cap, alch_count, _, _, _, _, _ = craft_quota()
                    if alch_count >= cap:
                        flash(f'全服丹修名额已满（{alch_count}/{cap}），暂无空位。', 'error')
                        return redirect(url_for('inventory'))
                eff   = json.loads(item['effect_json'] or '{}')
                bonus = int(eff.get('success_rate', 0) * 100)
                old_id = char['cauldron_id']
                refund_msg = ''
                if old_id and old_id != iid:
                    old_item = q("SELECT * FROM items WHERE id=?", (old_id,), one=True)
                    if old_item:
                        refund = old_item['market_price'] // 2
                        run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
                            (refund, char['id']))
                        run("DELETE FROM inventory WHERE char_id=? AND item_id=?",
                            (char['id'], old_id))
                        refund_msg = f'，旧丹炉【{old_item["name"]}】折价回收 {refund} 灵石'
                run("UPDATE characters SET cauldron_id=? WHERE id=?", (iid, char['id']))
                action_word = '升级至' if old_id and old_id != iid else '装备'
                flash(f'已{action_word}【{item["name"]}】（炼丹成功率 +{bonus}%）{refund_msg}', 'success')
                log(char['id'], 'system', f'{action_word}丹炉【{item["name"]}】{refund_msg}。')
            elif item['type'] == 'forge':
                existing_path = current_craft_path(char['id'])
                if existing_path and existing_path != 'forge':
                    flash(f'你已踏上【{PATH_NAMES.get(existing_path, existing_path)}】之路，各修行之路互斥，无法同时持有道具。', 'error')
                    return redirect(url_for('inventory'))
                already_has_forge = char_has_furnace(char['id'], 'forge')
                if not already_has_forge:
                    cap, _, forge_count, _, _, _, _ = craft_quota()
                    if forge_count >= cap:
                        flash(f'全服器修名额已满（{forge_count}/{cap}），暂无空位。', 'error')
                        return redirect(url_for('inventory'))
                eff   = json.loads(item['effect_json'] or '{}')
                bonus = int(eff.get('success_rate', 0) * 100)
                old_id = char['forge_id']
                refund_msg = ''
                if old_id and old_id != iid:
                    old_item = q("SELECT * FROM items WHERE id=?", (old_id,), one=True)
                    if old_item:
                        refund = old_item['market_price'] // 2
                        run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
                            (refund, char['id']))
                        run("DELETE FROM inventory WHERE char_id=? AND item_id=?",
                            (char['id'], old_id))
                        refund_msg = f'，旧炼器炉【{old_item["name"]}】折价回收 {refund} 灵石'
                run("UPDATE characters SET forge_id=? WHERE id=?", (iid, char['id']))
                action_word = '升级至' if old_id and old_id != iid else '点燃'
                flash(f'已{action_word}【{item["name"]}】（炼器成功率 +{bonus}%）{refund_msg}', 'success')
                log(char['id'], 'system', f'{action_word}炼器炉【{item["name"]}】{refund_msg}。')
            elif item['type'] == 'brush':
                existing_path = current_craft_path(char['id'])
                if existing_path and existing_path != 'brush':
                    flash(f'你已踏上【{PATH_NAMES.get(existing_path, existing_path)}】之路，各修行之路互斥，无法同时持有道具。', 'error')
                    return redirect(url_for('inventory'))
                already_has_brush = char_has_furnace(char['id'], 'brush')
                if not already_has_brush:
                    cap, _, _, fulu_count, _, _, _ = craft_quota()
                    if fulu_count >= cap:
                        flash(f'全服符修名额已满（{fulu_count}/{cap}），暂无空位。', 'error')
                        return redirect(url_for('inventory'))
                eff   = json.loads(item['effect_json'] or '{}')
                bonus = int(eff.get('success_rate', 0) * 100)
                old_id = char['fulu_id']
                refund_msg = ''
                if old_id and old_id != iid:
                    old_item = q("SELECT * FROM items WHERE id=?", (old_id,), one=True)
                    if old_item:
                        refund = old_item['market_price'] // 2
                        run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
                            (refund, char['id']))
                        run("DELETE FROM inventory WHERE char_id=? AND item_id=?",
                            (char['id'], old_id))
                        refund_msg = f'，旧毛笔【{old_item["name"]}】折价回收 {refund} 灵石'
                run("UPDATE characters SET fulu_id=? WHERE id=?", (iid, char['id']))
                action_word = '升级至' if old_id and old_id != iid else '执起'
                flash(f'已{action_word}【{item["name"]}】（画符成功率 +{bonus}%）{refund_msg}', 'success')
                log(char['id'], 'system', f'{action_word}毛笔【{item["name"]}】{refund_msg}。')
            elif item['type'] == 'destiny':
                eff      = json.loads(item['effect_json'] or '{}')
                req_elem = eff.get('element')
                if req_elem and req_elem not in [SPECIAL_ELEMENT_SOURCES.get(e, e) for e in char_elements(char)]:
                    flash(f'本命法宝需【{req_elem}】属性灵根，你的灵根不符，无法契合', 'error')
                else:
                    run("UPDATE characters SET destiny_id=? WHERE id=?", (iid, char['id']))
                    flash(f'已契合本命法宝【{item["name"]}】！', 'success')
                    log(char['id'], 'system', f'契合本命法宝【{item["name"]}】。')
            elif item['type'] == 'beast_token':
                if char.get('beast_token_id'):
                    flash('你已踏上御灵修行之路，无需重复持令。', 'error')
                else:
                    existing_path = current_craft_path(char['id'])
                    if existing_path and existing_path != 'beast_token':
                        flash(f'你已踏上【{PATH_NAMES.get(existing_path, existing_path)}】之路，各修行之路互斥，无法同时持令。', 'error')
                        return redirect(url_for('inventory'))
                    cap, _, _, _, beast_count, _, _ = craft_quota()
                    self_counted = q("""SELECT 1 FROM inventory i JOIN items it ON it.id=i.item_id
                        WHERE i.char_id=? AND it.type='beast_token' AND i.quantity>0""",
                        (char['id'],), one=True)
                    effective_count = beast_count - (1 if self_counted else 0)
                    if effective_count >= cap:
                        flash(f'全服御灵修名额已满（{beast_count}/{cap}），暂无空位。', 'error')
                    else:
                        run("UPDATE characters SET beast_token_id=? WHERE id=?", (iid, char['id']))
                        flash('已持【御灵令】，踏上御灵修行之路！可繁育灵兽、炼制御灵神牌。', 'success')
                        log(char['id'], 'system', '持御灵令，踏入御灵修行之路。')
            elif item['type'] == 'heqing_token':
                if char.get('heqing_token_id'):
                    flash('你已踏上合欢修行之路，无需重复持令。', 'error')
                else:
                    existing_path = current_craft_path(char['id'])
                    if existing_path and existing_path != 'heqing_token':
                        flash(f'你已踏上【{PATH_NAMES.get(existing_path, existing_path)}】之路，各修行之路互斥，无法同时持令。', 'error')
                        return redirect(url_for('inventory'))
                    cap, _, _, _, _, heqing_count, _ = craft_quota()
                    self_counted = q("""SELECT 1 FROM inventory i JOIN items it ON it.id=i.item_id
                        WHERE i.char_id=? AND it.type='heqing_token' AND i.quantity>0""",
                        (char['id'],), one=True)
                    effective_count = heqing_count - (1 if self_counted else 0)
                    if effective_count >= cap:
                        flash(f'全服合欢修名额已满（{heqing_count}/{cap}），暂无空位。', 'error')
                    else:
                        run("UPDATE characters SET heqing_token_id=? WHERE id=?", (iid, char['id']))
                        flash('已持【合欢令】，踏上合欢修行之路！双修收益大幅提升，4级后可强化子嗣灵根。', 'success')
                        log(char['id'], 'system', '持合欢令，踏入合欢修行之路。')
            elif item['type'] == 'sword_token':
                if char.get('sword_token_id'):
                    flash('你已踏上剑修之路，无需重复持令。', 'error')
                else:
                    existing_path = current_craft_path(char['id'])
                    if existing_path and existing_path != 'sword_token':
                        flash(f'你已踏上【{PATH_NAMES.get(existing_path, existing_path)}】之路，各修行之路互斥，无法同时持令。', 'error')
                    else:
                        cap, _, _, _, _, _, sword_count = craft_quota()
                        # 自己已在计数中（背包持有），排除自己后再判断是否超额
                        self_counted = q("""SELECT 1 FROM inventory i JOIN items it ON it.id=i.item_id
                            WHERE i.char_id=? AND it.type='sword_token' AND i.quantity>0""",
                            (char['id'],), one=True)
                        effective_count = sword_count - (1 if self_counted else 0)
                        if effective_count >= cap:
                            flash(f'全服剑修名额已满（{sword_count}/{cap}），暂无空位。', 'error')
                        else:
                            run("UPDATE characters SET sword_token_id=? WHERE id=?", (iid, char['id']))
                            flash('已持【飞剑令】，踏上剑修之路！战斗时可破甲御敌、触发剑气追击。', 'success')
                            log(char['id'], 'system', '持飞剑令，踏入剑修之路。')
            elif item['type'] == 'spirit_pass':
                if char.get('spirit_pass_id'):
                    flash('御灵神牌已激活，无需重复使用。', 'error')
                else:
                    run("UPDATE characters SET spirit_pass_id=? WHERE id=?", (iid, char['id']))
                    if inv['quantity'] <= 1:
                        run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], iid))
                    else:
                        run("UPDATE inventory SET quantity=quantity-1 WHERE char_id=? AND item_id=?", (char['id'], iid))
                    flash('御灵神牌已激活！可同时出战两只灵兽。', 'success')
                    log(char['id'], 'system', '激活御灵神牌，获得双槽出战能力。')
            else:
                flash('此物品无法装备', 'error')

        elif action == 'unequip':
            if item['type'] == 'weapon':
                run("UPDATE characters SET equipped_weapon=NULL WHERE id=?", (char['id'],))
                flash(f'已卸下【{item["name"]}】', 'success')
            elif item['type'] == 'artifact':
                run("UPDATE characters SET equipped_artifact=NULL WHERE id=?", (char['id'],))
                flash(f'已卸下【{item["name"]}】', 'success')
            elif item['type'] == 'cauldron':
                run("UPDATE characters SET cauldron_id=NULL WHERE id=?", (char['id'],))
                flash(f'已收起【{item["name"]}】', 'success')
            elif item['type'] == 'forge':
                run("UPDATE characters SET forge_id=NULL WHERE id=?", (char['id'],))
                flash(f'已熄灭【{item["name"]}】', 'success')
            elif item['type'] == 'brush':
                run("UPDATE characters SET fulu_id=NULL WHERE id=?", (char['id'],))
                flash(f'已收起毛笔【{item["name"]}】', 'success')
            elif item['type'] == 'beast_token':
                run("UPDATE characters SET beast_token_id=NULL, active_pet2_id=NULL WHERE id=?", (char['id'],))
                flash('已放弃御灵修行，第二灵兽槽已关闭。', 'success')
            elif item['type'] == 'heqing_token':
                run("UPDATE characters SET heqing_token_id=NULL WHERE id=?", (char['id'],))
                flash('已放弃合欢修行。', 'success')
            elif item['type'] == 'sword_token':
                run("UPDATE characters SET sword_token_id=NULL WHERE id=?", (char['id'],))
                flash('已放弃剑修之路，剑意归于沉寂。', 'success')
            elif item['type'] == 'destiny':
                run("UPDATE characters SET destiny_id=NULL WHERE id=?", (char['id'],))
                flash(f'已解除本命法宝【{item["name"]}】', 'success')

        char = me()

    inv_items = q("""SELECT i.*, inv.quantity, inv.gift_from FROM items i
        JOIN inventory inv ON inv.item_id=i.id
        WHERE inv.char_id=? ORDER BY i.type, i.name""", (char['id'],))
    hp_now = cur_hp(char)
    max_hp, _, _ = realm_stats(char['realm_idx'])
    max_hp += bone_hp_bonus(char['id'])
    return render_template('inventory.html', char=char, inv_items=inv_items,
        hp_now=hp_now, max_hp=max_hp,
        AMBER_ENERGY_CAP_COST=AMBER_ENERGY_CAP_COST, AMBER_ENERGY_CAP_GAIN=AMBER_ENERGY_CAP_GAIN)

# ── 邮件 ─────────────────────────────────────────────────────────────────────────

@app.route('/game/mail', methods=['GET','POST'])
@login_required
def mail():
    char = me()

    if request.method == 'POST':
        action = request.form.get('action')

        if action == 'send':
            to_name  = request.form.get('to_name','').strip()
            subject  = request.form.get('subject','').strip()[:30]
            body     = request.form.get('body','').strip()[:200]
            iid      = int(request.form.get('item_id', 0))
            iqty     = max(1, min(99, int(request.form.get('item_qty', 1) or 1)))
            stones   = max(0, min(500000, int(request.form.get('stones', 0) or 0)))
            pet_mid  = int(request.form.get('pet_id', 0))
            to_char  = q("SELECT * FROM characters WHERE name=? AND is_npc=0 AND status='alive'",
                         (to_name,), one=True)
            if not to_name or not to_char:
                flash('未找到该修士', 'error')
            elif to_char['id'] == char['id']:
                flash('不能给自己发信', 'error')
            elif daily_count(char['id'], 'mail_sent') >= 50:
                flash('今日发信已达上限（50 封）', 'error')
            else:
                # 检查物品附件
                att_iid = att_qty = 0
                if iid:
                    inv = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                            (char['id'], iid), one=True)
                    item = q("SELECT * FROM items WHERE id=?", (iid,), one=True)
                    if not inv or not item or inv['quantity'] < iqty:
                        flash('背包中物品数量不足', 'error')
                        return redirect(url_for('mail'))
                    if item['type'] in ('cauldron', 'forge', 'brush', 'beast_token', 'heqing_token', 'sword_token'):
                        flash('职业令牌属于专属道具，不可通过邮件转让。', 'error')
                        return redirect(url_for('mail'))
                    att_iid = iid
                    att_qty = iqty
                    if inv['quantity'] <= iqty:
                        run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], iid))
                    else:
                        run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?",
                            (iqty, char['id'], iid))
                # 检查宠物附件
                att_pet_type = att_pet_lv = 0
                att_pet_nick = ''
                if pet_mid:
                    pet_row = q("SELECT cp.*, pt.name as type_name FROM char_pets cp "
                                "JOIN pet_types pt ON pt.id=cp.pet_type_id "
                                "WHERE cp.id=? AND cp.char_id=?", (pet_mid, char['id']), one=True)
                    if not pet_row:
                        flash('灵兽不存在', 'error')
                        return redirect(url_for('mail'))
                    if char['active_pet_id'] == pet_mid:
                        run("UPDATE characters SET active_pet_id=NULL WHERE id=?", (char['id'],))
                    if char.get('active_pet2_id') == pet_mid:
                        run("UPDATE characters SET active_pet2_id=NULL WHERE id=?", (char['id'],))
                    att_pet_type = pet_row['pet_type_id']
                    att_pet_lv   = pet_row['level']
                    att_pet_nick = pet_row['nickname'] or ''
                    run("DELETE FROM char_pets WHERE id=?", (pet_mid,))
                if stones > 0:
                    if char['spirit_stones'] < stones:
                        flash('灵石不足', 'error')
                        return redirect(url_for('mail'))
                    run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?",
                        (stones, char['id']))
                run("""INSERT INTO mail
                    (from_char,to_char,subject,body,item_id,item_qty,stones,
                     pet_type_id,pet_level,pet_nickname,created_at)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
                    (char['id'], to_char['id'], subject, body,
                     att_iid or None, att_qty, stones,
                     att_pet_type or None, att_pet_lv, att_pet_nick, now_ts()))
                daily_inc(char['id'], 'mail_sent')
                parts = []
                if att_iid: parts.append(f'{item["name"]}×{att_qty}')
                if att_pet_type: parts.append(f'灵兽【{pet_row["type_name"]}】Lv.{att_pet_lv}')
                if stones: parts.append(f'灵石×{stones}')
                att_str = ('，附：' + '、'.join(parts)) if parts else ''
                flash(f'已发送给【{to_name}】', 'success')
                log(char['id'], 'social', f'向【{to_name}】发送了一封信件{att_str}。')

        elif action == 'claim':
            mid = int(request.form.get('mail_id', 0))
            m   = q("SELECT * FROM mail WHERE id=? AND to_char=? AND claimed=0",
                    (mid, char['id']), one=True)
            if m:
                if m['item_id'] and m['item_qty']:
                    item_info = q("SELECT name, type, effect_json, market_price FROM items WHERE id=?",
                                  (m['item_id'],), one=True)
                    if item_info and item_info['type'] == 'gift' and m['from_char']:
                        # 制作礼物：进图鉴 + 触发好感（每件计一次）
                        sender = q("SELECT name FROM characters WHERE id=?", (m['from_char'],), one=True)
                        sender_name = sender['name'] if sender else '?'
                        eff = json.loads(item_info['effect_json'] or '{}')
                        base_gain = eff.get('affinity') or max(1, (item_info['market_price'] or 50) // 100)
                        for _ in range(m['item_qty']):
                            add_affinity(char['id'], m['from_char'], base_gain)
                            run("INSERT INTO gift_log (to_char_id,from_char_id,from_name,item_id,item_name,affinity,created_at) VALUES (?,?,?,?,?,?,?)",
                                (char['id'], m['from_char'], sender_name, m['item_id'], item_info['name'], base_gain, now_ts()))
                    else:
                        ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?",
                               (char['id'], m['item_id']), one=True)
                        if ex: run("UPDATE inventory SET quantity=quantity+? WHERE char_id=? AND item_id=?",
                                   (m['item_qty'], char['id'], m['item_id']))
                        else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,?)",
                                   (char['id'], m['item_id'], m['item_qty']))
                if m['stones']:
                    run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
                        (m['stones'], char['id']))
                if m['lingfu']:
                    run("UPDATE characters SET lingfu=lingfu+? WHERE id=?",
                        (m['lingfu'], char['id']))
                try:
                    if m['exp']:
                        run("UPDATE characters SET exp=exp+? WHERE id=?",
                            (m['exp'], char['id']))
                except (IndexError, KeyError):
                    pass
                if m['pet_type_id']:
                    run("INSERT INTO char_pets (char_id,pet_type_id,nickname,level,obtained_at) VALUES (?,?,?,?,?)",
                        (char['id'], m['pet_type_id'], m['pet_nickname'] or '', m['pet_level'] or 1, now_ts()))
                run("UPDATE mail SET claimed=1, is_read=1 WHERE id=?", (mid,))
                flash('附件已领取', 'success')

        elif action == 'read':
            mid = int(request.form.get('mail_id', 0))
            run("UPDATE mail SET is_read=1 WHERE id=? AND to_char=?", (mid, char['id']))

        elif action == 'delete':
            mid = int(request.form.get('mail_id', 0))
            run("DELETE FROM mail WHERE id=? AND to_char=?", (mid, char['id']))
            flash('已删除', 'info')

        char = me()

    inbox = q("""SELECT m.*, c.name as from_name,
        i.name as item_name, i.rarity as item_rarity,
        pt.name as pet_type_name
        FROM mail m
        LEFT JOIN characters c ON c.id=m.from_char
        LEFT JOIN items i ON i.id=m.item_id
        LEFT JOIN pet_types pt ON pt.id=m.pet_type_id
        WHERE m.to_char=? ORDER BY m.created_at DESC LIMIT 50""", (char['id'],))

    outbox = q("""SELECT m.*, c.name as to_name,
        i.name as item_name, i.rarity as item_rarity,
        pt.name as pet_type_name
        FROM mail m
        LEFT JOIN characters c ON c.id=m.to_char
        LEFT JOIN items i ON i.id=m.item_id
        LEFT JOIN pet_types pt ON pt.id=m.pet_type_id
        WHERE m.from_char=? ORDER BY m.created_at DESC LIMIT 50""", (char['id'],))

    inv_items = q("""SELECT i.id, i.name, i.type, i.rarity, inv.quantity
        FROM items i JOIN inventory inv ON inv.item_id=i.id
        WHERE inv.char_id=? AND i.type NOT IN ('junk','seed') AND inv.quantity>0
        ORDER BY i.type, i.name""", (char['id'],))

    my_pets = q("""SELECT cp.id, cp.nickname, cp.level, pt.name as type_name, pt.rarity
        FROM char_pets cp JOIN pet_types pt ON pt.id=cp.pet_type_id
        WHERE cp.char_id=? ORDER BY cp.level DESC, pt.rarity DESC""", (char['id'],))

    unclaimed_dws = q("""SELECT id, weapon_type, base_attack, buffs_json
        FROM destiny_weapons WHERE char_id=? AND is_claimed=0
        ORDER BY created_at DESC""", (char['id'],))

    return render_template('mail.html', char=char, inbox=inbox, outbox=outbox,
                           inv_items=inv_items, my_pets=my_pets,
                           unclaimed_dws=unclaimed_dws)

# ── 每日/周任务 ───────────────────────────────────────────────────────────────────

@app.route('/game/quests', methods=['GET','POST'])
@login_required
def quests():
    char = me()
    now_dt = datetime.now(TZ)
    today  = now_dt.strftime('%Y-%m-%d')
    this_week = f"{now_dt.year}-W{now_dt.strftime('%W')}"

    if request.method == 'POST':
        qkey = request.form.get('quest_key','')
        qdef = next((q_ for q_ in DAILY_QUESTS + WEEKLY_QUESTS if q_['key'] == qkey), None)
        if qdef:
            pk = today if qkey.startswith('dq_') else this_week
            row = q("SELECT * FROM quest_progress WHERE char_id=? AND quest_key=? AND period_date=?",
                    (char['id'], qkey, pk), one=True)
            if row and row['completed'] and not row['claimed']:
                run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
                    (qdef['reward_stones'], char['id']))
                for iname, iqty in qdef['reward_items']:
                    it = q("SELECT id FROM items WHERE name=?", (iname,), one=True)
                    if it:
                        ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?",
                               (char['id'], it['id']), one=True)
                        if ex: run("UPDATE inventory SET quantity=quantity+? WHERE char_id=? AND item_id=?",
                                   (iqty, char['id'], it['id']))
                        else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,?)",
                                   (char['id'], it['id'], iqty))
                run("UPDATE quest_progress SET claimed=1 WHERE id=?", (row['id'],))
                parts = [f'灵石 ×{qdef["reward_stones"]}']
                for iname, iqty in qdef['reward_items']:
                    parts.append(f'【{iname}】×{iqty}')
                flash(f'任务【{qdef["name"]}】完成！获得：' + '、'.join(parts), 'success')
                log(char['id'], 'system', f'完成任务【{qdef["name"]}】。')
                char = me()

    # 组装任务状态
    def get_quest_state(qdef, pk):
        row = q("SELECT * FROM quest_progress WHERE char_id=? AND quest_key=? AND period_date=?",
                (char['id'], qdef['key'], pk), one=True)
        prog = row['progress'] if row else 0
        done = bool(row and row['completed'])
        claimed = bool(row and row['claimed'])
        pct = min(100, int(prog * 100 / qdef['target'])) if qdef['target'] else 100
        return {**qdef, 'progress': prog, 'done': done, 'claimed': claimed, 'pct': pct}

    daily  = [get_quest_state(q_, today)     for q_ in DAILY_QUESTS]
    weekly = [get_quest_state(q_, this_week) for q_ in WEEKLY_QUESTS
              if not q_.get('required_col') or char.get(q_['required_col'])]
    return render_template('quests.html', char=char, daily=daily, weekly=weekly)

# ── 礼包码兑换 ──────────────────────────────────────────────────────────────────

@app.route('/game/redeem', methods=['GET','POST'])
@login_required
def redeem():
    char   = me()
    result = None
    if request.method == 'POST':
        code_str = request.form.get('code','').strip().upper()
        if not code_str:
            flash('请输入兑换码', 'error')
        else:
            gc = q("SELECT * FROM gift_codes WHERE code=? AND is_active=1", (code_str,), one=True)
            if not gc:
                flash('兑换码无效或已停用', 'error')
            elif gc['expires_at'] and now_ts() > gc['expires_at']:
                flash('兑换码已过期', 'error')
            elif gc['used_count'] >= gc['max_uses']:
                flash('此兑换码已达最大兑换次数', 'error')
            elif q("SELECT 1 FROM gift_code_uses WHERE code_id=? AND char_id=?",
                   (gc['id'], char['id']), one=True):
                flash('你已兑换过此礼包码', 'error')
            else:
                rwd = json.loads(gc['rewards_json'] or '{}')
                gains = []
                if rwd.get('spirit_stones'):
                    run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
                        (rwd['spirit_stones'], char['id']))
                    gains.append(f'灵石 ×{rwd["spirit_stones"]}')
                if rwd.get('exp'):
                    run("UPDATE characters SET exp=exp+? WHERE id=?", (rwd['exp'], char['id']))
                    gains.append(f'修为 ×{rwd["exp"]}')
                for it in rwd.get('items', []):
                    item = q("SELECT * FROM items WHERE name=?", (it['name'],), one=True)
                    if item:
                        qty = it.get('qty', 1)
                        ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?",
                               (char['id'], item['id']), one=True)
                        if ex: run("UPDATE inventory SET quantity=quantity+? WHERE char_id=? AND item_id=?",
                                   (qty, char['id'], item['id']))
                        else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,?)",
                                   (char['id'], item['id'], qty))
                        gains.append(f'【{item["name"]}】×{qty}')
                run("INSERT INTO gift_code_uses (code_id,char_id,used_at) VALUES (?,?,?)",
                    (gc['id'], char['id'], now_ts()))
                run("UPDATE gift_codes SET used_count=used_count+1 WHERE id=?", (gc['id'],))
                msg = '兑换成功！获得：' + '、'.join(gains) if gains else '兑换成功！'
                log(char['id'], 'system', msg)
                flash(msg, 'success')
                result = {'gains': gains, 'desc': gc['description']}
                char = me()
    return render_template('redeem.html', char=char, result=result)

# ── 丹市 ───────────────────────────────────────────────────────────────────────

@app.route('/game/market', methods=['GET','POST'])
@login_required
def market():
    char = me()
    if request.method == 'POST' and request.form.get('action') == 'exchange_superior':
        try:
            ex_qty = max(1, int(request.form.get('ex_qty', 1)))
        except ValueError:
            ex_qty = 1
        cost = ex_qty * SUPERIOR_STONE_RATE
        if char['spirit_stones'] < cost:
            flash(f'灵石不足，兑换 {ex_qty} 个上等灵石需要 {cost} 灵石', 'error')
        else:
            run("UPDATE characters SET spirit_stones=spirit_stones-?, superior_stones=superior_stones+? WHERE id=?",
                (cost, ex_qty, char['id']))
            log(char['id'], 'market', f'以 {cost} 灵石兑换 {ex_qty} 个上等灵石。')
            flash(f'兑换成功！获得 {ex_qty} 个上等灵石。', 'success')
        char = me()
        _market_banned = ('洗髓丹','伐经丹','化灵丹','凝神大丹','七彩灵芝汤','造化圆满丹','太一归元丹','造化玄丹','凝气丹')
        goods = q("""SELECT * FROM items WHERE market_price>0 AND is_active=1
            AND type NOT IN ('junk','talisman','treasure')
            AND NOT (type='material' AND rarity IN ('rare','epic','legendary'))
            AND name NOT IN ({})
            ORDER BY type, market_price""".format(','.join('?'*len(_market_banned))),
            _market_banned)
        hp_now = cur_hp(char)
        max_hp, _, _ = realm_stats(char['realm_idx'])
        max_hp += bone_hp_bonus(char['id'])
        return render_template('market.html', char=char, goods=goods,
            hp_now=hp_now, max_hp=max_hp, SUPERIOR_STONE_RATE=SUPERIOR_STONE_RATE)
    if request.method == 'POST':
        iid  = int(request.form.get('item_id', 0))
        qty  = max(1, int(request.form.get('qty', 1)))
        _market_banned = ('洗髓丹','伐经丹','化灵丹','凝神大丹','七彩灵芝汤','造化圆满丹','太一归元丹','造化玄丹','凝气丹')
        item = q("""SELECT * FROM items WHERE id=? AND market_price>0 AND is_active=1
            AND type NOT IN ('junk','talisman','treasure')
            AND NOT (type='material' AND rarity IN ('rare','epic','legendary'))
            AND name NOT IN ({})""".format(','.join('?'*len(_market_banned))),
            (iid, *_market_banned), one=True)
        # 五路互斥：购买路线道具前检查
        if item and item['type'] in CRAFT_PATH_TYPES:
            existing = current_craft_path(char['id'])
            if existing and existing != item['type']:
                flash(f'你已踏上【{PATH_NAMES[existing]}】之路，需先出售现有道具方可改修他路。', 'error')
                item = None
        if not item:
            flash('商品不存在', 'error')
        elif item['type'] in ('cauldron', 'forge', 'brush') and (lambda r: r and int(r['value']) > now_ts())(
                q("SELECT value FROM site_config WHERE key=?", (f'furnace_sell_cd_{char["id"]}',), one=True)):
            cd_row = q("SELECT value FROM site_config WHERE key=?", (f'furnace_sell_cd_{char["id"]}',), one=True)
