@app.route('/game/techniques')
@login_required
def techniques():
    char = me()
    my = q("""SELECT t.*, ct.learned_at FROM techniques t
        JOIN char_techniques ct ON ct.tech_id=t.id
        WHERE ct.char_id=? ORDER BY t.type, t.realm_required""", (char['id'],))
    return render_template('techniques.html', char=char, my=my)

# ── 炼丹房 ─────────────────────────────────────────────────────────────────────

@app.route('/game/alchemy', methods=['GET','POST'])
@login_required
def alchemy():
    char   = me()
    energy = cur_energy(char)
    result = None

    if request.method == 'POST':
        rid    = int(request.form.get('recipe_id', 0))
        recipe = q("SELECT * FROM alchemy_recipes WHERE id=? AND is_active=1", (rid,), one=True)

        if not recipe:
            flash('配方不存在', 'error')
        elif recipe['requires_gate_event'] and not get_gate_event():
            flash('此配方只能在【异世之门】活动期间炼制。', 'error')
        elif energy < (recipe['energy_cost'] or ALCHEMY_ENERGY_COST):
            recipe_energy = recipe['energy_cost'] or ALCHEMY_ENERGY_COST
            flash(f'灵力不足，炼此丹需消耗 {recipe_energy} 灵力（当前 {energy}）', 'error')
        elif char_has_furnace(char['id'], 'forge'):
            flash('你持有炼器炉，无法炼丹。如需更换，请先出售炼器炉。', 'error')
        elif not char_has_furnace(char['id'], 'cauldron'):
            cap, alch_count, _, _, _, _, _ = craft_quota()
            if alch_count >= cap:
                flash(f'全服丹修名额已满（{alch_count}/{cap}），暂无空位，待有人退出后再来。', 'error')
            elif char['realm_idx'] < recipe['realm_required']:
                flash(f'需达到【{REALMS[recipe["realm_required"]]["name"]}】方可炼制', 'error')
            elif (char['alchemy_level'] or 0) < ((recipe['alchemy_level_required'] or 0)):
                need_lv = (recipe['alchemy_level_required'] or 0)
                flash(f'需达到炼丹等级【{ALCHEMY_LEVELS[need_lv]["name"]}】方可炼制此丹', 'error')
            elif not char['cauldron_id']:
                flash('需先在背包中装备丹炉', 'error')
        elif char['realm_idx'] < recipe['realm_required']:
            flash(f'需达到【{REALMS[recipe["realm_required"]]["name"]}】方可炼制', 'error')
        elif (char['alchemy_level'] or 0) < ((recipe['alchemy_level_required'] or 0)):
            need_lv = (recipe['alchemy_level_required'] or 0)
            flash(f'需达到炼丹等级【{ALCHEMY_LEVELS[need_lv]["name"]}】方可炼制此丹', 'error')
        elif not char['cauldron_id']:
            flash('需先在背包中装备丹炉', 'error')
        else:
            ings = json.loads(recipe['ingredients'])
            # 检查材料
            miss = []
            for ing in ings:
                inv = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                        (char['id'], ing['item_id']), one=True)
                have = inv['quantity'] if inv else 0
                if have < ing['qty']:
                    name = q("SELECT name FROM items WHERE id=?", (ing['item_id'],), one=True)
                    miss.append(f'{name["name"] if name else "?"} 缺 {ing["qty"]-have}')
            if miss:
                flash('材料不足：' + '，'.join(miss), 'error')
            else:
                # 消耗材料 + 灵力
                actual_energy_cost = recipe['energy_cost'] if recipe['energy_cost'] else ALCHEMY_ENERGY_COST
                set_energy(char['id'], energy - actual_energy_cost)
                for ing in ings:
                    inv = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                            (char['id'], ing['item_id']), one=True)
                    if inv['quantity'] <= ing['qty']:
                        run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], ing['item_id']))
                    else:
                        run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?",
                            (ing['qty'], char['id'], ing['item_id']))

                # 计算成功率（fixed_success_rate=1 时不叠加任何加成）
                if recipe['fixed_success_rate']:
                    final_rate = recipe['success_rate']
                else:
                    cauldron_bonus = get_cauldron_bonus(char)
                    final_rate = min(0.99, recipe['success_rate'] + cauldron_bonus + perk_total(char['id'], 'alchemy_bonus') + cur_season_buff('craft') + companion_bonus(char, 'alchemy_bonus'))
                success = random.random() < final_rate

                # 炼丹经验
                result_item_for_rarity = q("SELECT rarity FROM items WHERE id=?",
                                           (recipe['result_item_id'],), one=True)
                base_exp = ALCHEMY_RARITY_EXP.get(
                    result_item_for_rarity['rarity'] if result_item_for_rarity else 'common', 8)
                exp_gain  = base_exp if success else max(1, base_exp // 3)
                old_alch_exp = char['alchemy_exp'] or 0
                new_alch_exp = old_alch_exp + exp_gain
                old_lv = char['alchemy_level'] or 0
                new_lv = old_lv
                for i in range(len(ALCHEMY_LEVELS) - 1, -1, -1):
                    if new_alch_exp >= ALCHEMY_LEVELS[i]['exp']:
                        new_lv = i
                        break
                run("UPDATE characters SET alchemy_exp=?, alchemy_level=? WHERE id=?",
                    (new_alch_exp, new_lv, char['id']))
                leveled_up = new_lv > old_lv

                if success:
                    result_item = q("SELECT * FROM items WHERE id=?", (recipe['result_item_id'],), one=True)
                    base_qty = recipe['result_qty']
                    # 双倍/三倍产出概率
                    alch_lv_bonus = (char['alchemy_level'] or 0) * 0.014
                    cauldron_eff  = json.loads(q("SELECT effect_json FROM items WHERE id=?",
                                                 (char['cauldron_id'],), one=True)['effect_json'] or '{}') \
                                    if char['cauldron_id'] else {}
                    cauldron_dc   = cauldron_eff.get('double_chance', 0)
                    double_chance = min(0.40, 0.08 + alch_lv_bonus + cauldron_dc)
                    triple_chance = min(0.12, 0.02 + (char['alchemy_level'] or 0) * 0.005)
                    roll = random.random()
                    if roll < triple_chance:
                        qty, bonus_label = base_qty * 3, '✦ 丹成三炉！'
                    elif roll < double_chance:
                        qty, bonus_label = base_qty * 2, '✦ 丹成双炉！'
                    else:
                        qty, bonus_label = base_qty, ''
                    ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?",
                           (char['id'], recipe['result_item_id']), one=True)
                    if ex: run("UPDATE inventory SET quantity=quantity+? WHERE char_id=? AND item_id=?",
                               (qty, char['id'], recipe['result_item_id']))
                    else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,?)",
                               (char['id'], recipe['result_item_id'], qty))
                    msg = f'炼制【{recipe["name"]}】成功！{bonus_label}获得【{result_item["name"]}】×{qty}。炼丹经验 +{exp_gain}。'
                    if leveled_up:
                        msg += f' 炼丹等级提升至【{ALCHEMY_LEVELS[new_lv]["name"]}】！'
                    inc_quest(char['id'], 'alchemy')
                    inc_sect_quest(char['id'], 'alchemy')
                    log(char['id'], 'alchemy', msg)
                    result = {'success': True, 'item': result_item, 'qty': qty,
                              'bonus_label': bonus_label,
                              'rate': int(final_rate*100), 'exp_gain': exp_gain, 'leveled_up': leveled_up,
                              'new_lv_name': ALCHEMY_LEVELS[new_lv]['name']}
                else:
                    msg = f'炉火失控，【{recipe["name"]}】炼制失败，材料尽数消耗。炼丹经验 +{exp_gain}。'
                    log(char['id'], 'alchemy', msg)
                    result = {'success': False, 'rate': int(final_rate*100),
                              'exp_gain': exp_gain, 'leveled_up': leveled_up,
                              'new_lv_name': ALCHEMY_LEVELS[new_lv]['name']}
                flash(msg, 'success' if success else 'error')
                char = me()

    # 炼丹等级信息
    alch_lv, alch_lv_name, alch_next_exp, alch_exp, alch_pct = alchemy_level_info(char)

    # 配方列表 + 材料库存
    recipes = q("""SELECT r.*, i.name as result_name, i.rarity as result_rarity
        FROM alchemy_recipes r JOIN items i ON i.id=r.result_item_id
        WHERE r.is_active=1 ORDER BY r.alchemy_level_required, r.realm_required, r.success_rate DESC""")

    # 注意：配方食材不限于草药（如造化灵液方需要矿石/珍宝类材料），故不按 type 过滤
    ing_stock = {r['item_id']: r['quantity']
        for r in q("SELECT item_id, quantity FROM inventory WHERE char_id=?", (char['id'],))}

    # 当前丹炉
    cauldron = q("SELECT * FROM items WHERE id=?", (char['cauldron_id'],), one=True) \
        if char['cauldron_id'] else None
    cauldron_bonus = get_cauldron_bonus(char)

    # 草药库存（显示用）
    herbs = q("""SELECT i.*, inv.quantity FROM items i
        JOIN inventory inv ON inv.item_id=i.id
        WHERE inv.char_id=? AND i.type='herb' ORDER BY i.rarity, i.name""", (char['id'],))

    # 每个配方解析食材名称
    recipe_details = []
    for r in recipes:
        ings_raw = json.loads(r['ingredients'])
        ings = []
        for ing in ings_raw:
            item = q("SELECT name FROM items WHERE id=?", (ing['item_id'],), one=True)
            have = ing_stock.get(ing['item_id'], 0)
            ings.append({'name': item['name'] if item else '?',
                         'item_id': ing['item_id'],
                         'qty': ing['qty'], 'have': have,
                         'enough': have >= ing['qty']})
        can_brew = all(i['enough'] for i in ings)
        recipe_details.append({'r': r, 'ings': ings, 'can_brew': can_brew})

    _liquid_gift_row = q("SELECT count FROM daily_counters WHERE char_id=? AND key=? AND day='total'",
        (char['id'], ALCHEMY_LIQUID_GIFT_TOTAL_KEY), one=True)
    liquid_gift_total = _liquid_gift_row['count'] if _liquid_gift_row else 0

    return render_template('alchemy.html',
        char=char, cauldron=cauldron, cauldron_bonus=cauldron_bonus,
        recipe_details=recipe_details, herbs=herbs, result=result,
        alch_lv=alch_lv, alch_lv_name=alch_lv_name,
        alch_next_exp=alch_next_exp, alch_exp=alch_exp, alch_pct=alch_pct,
        liquid_gift_total=liquid_gift_total,
        ALCHEMY_LEVELS=ALCHEMY_LEVELS)

