# ── 剑修 ───────────────────────────────────────────────────────────────────────

@app.route('/game/sword', methods=['GET','POST'])
@login_required
def sword():
    char = me()
    if not char.get('sword_token_id'):
        flash('你尚未踏上剑修之路，请先在丹市购买飞剑令并于背包持令。', 'error')
        return redirect(url_for('market'))

    if request.method == 'POST':
        action = request.form.get('action')

        if action == 'create_art':
            art_name = request.form.get('art_name', '').strip()
            slv, _, _, _, _ = sword_level_info(char)
            if slv < 4:
                flash('需达到剑道传人（Lv5）方可创立剑法。', 'error')
            elif not art_name:
                flash('剑法名称不可为空。', 'error')
            elif len(art_name) > 20:
                flash('剑法名称最多20字。', 'error')
            elif q("SELECT 1 FROM sword_arts WHERE creator_id=?", (char['id'],), one=True):
                flash('已有一门自创剑法，不可再立新法。', 'error')
            else:
                run("INSERT INTO sword_arts (creator_id,name,stances_json,created_at) VALUES (?,?,'[]',?)",
                    (char['id'], art_name, now_ts()))
                flash(f'剑法【{art_name}】已立！可继续添加剑式（最多{SWORD_MAX_STANCES}式）。', 'success')
                log(char['id'], 'system', f'自创剑法【{art_name}】。')

        elif action == 'add_stance':
            art = q("SELECT * FROM sword_arts WHERE creator_id=?", (char['id'],), one=True)
            stance_type = request.form.get('stance_type', '')
            if not art:
                flash('你尚无自创剑法。', 'error')
            elif stance_type not in SWORD_STANCE_TYPES:
                flash('无效的剑式类型。', 'error')
            else:
                stances = json.loads(art['stances_json'] or '[]')
                if len(stances) >= SWORD_MAX_STANCES:
                    flash(f'剑法已达{SWORD_MAX_STANCES}式上限，无法继续添加。', 'error')
                else:
                    st = SWORD_STANCE_TYPES[stance_type]
                    val = random.randint(st['range'][0], st['range'][1])
                    stances.append({"name": stance_type, "key": st['key'],
                                    "label": st['label'], "value": val, "unit": st['unit']})
                    run("UPDATE sword_arts SET stances_json=? WHERE id=?",
                        (json.dumps(stances, ensure_ascii=False), art['id']))
                    flash(f'已添加【{stance_type}】：{st["label"]} +{val}{st["unit"]}', 'success')
                    log(char['id'], 'system', f'剑法添加{stance_type}（{st["label"]}+{val}{st["unit"]}）。')

        elif action == 'teach':
            target_name = request.form.get('target_name', '').strip()
            art = q("SELECT * FROM sword_arts WHERE creator_id=?", (char['id'],), one=True)
            if not art:
                flash('你尚无自创剑法，无法传授。', 'error')
            elif not target_name:
                flash('请输入传授对象的角色名。', 'error')
            else:
                disciple_count = q("SELECT COUNT(*) n FROM sword_art_disciples WHERE art_id=?",
                                   (art['id'],), one=True)['n']
                if disciple_count >= SWORD_MAX_DISCIPLES:
                    flash(f'此剑法已传授{SWORD_MAX_DISCIPLES}人，名额已满。', 'error')
                else:
                    target = q("SELECT * FROM characters WHERE name=? AND status='alive' AND is_npc=0",
                               (target_name,), one=True)
                    if not target:
                        flash(f'未找到修士【{target_name}】。', 'error')
                    elif target['id'] == char['id']:
                        flash('不可传授给自己。', 'error')
                    elif q("SELECT 1 FROM sword_art_disciples WHERE art_id=? AND disciple_id=?",
                           (art['id'], target['id']), one=True):
                        flash(f'【{target_name}】已是此法传人，无需重复传授。', 'error')
                    elif q("SELECT 1 FROM sword_art_disciples WHERE disciple_id=?",
                           (target['id'],), one=True) or \
                         q("SELECT 1 FROM sword_arts WHERE creator_id=?", (target['id'],), one=True):
                        flash(f'【{target_name}】已有剑法传承，一人只可习一门剑法。', 'error')
                    else:
                        run("INSERT OR IGNORE INTO sword_art_disciples (art_id,disciple_id,learned_at) VALUES (?,?,?)",
                            (art['id'], target['id'], now_ts()))
                        flash(f'已将剑法【{art["name"]}】传授给【{target_name}】。', 'success')
                        log(char['id'], 'system', f'将剑法【{art["name"]}】传授给【{target_name}】。')
                        log(target['id'], 'social', f'【{char["name"]}】将剑法【{art["name"]}】传授给你，剑意入体！')

    slv, slv_name, slv_next_exp, slv_exp, slv_pct = sword_level_info(char)
    my_art = q("SELECT * FROM sword_arts WHERE creator_id=?", (char['id'],), one=True)
    learned_art = None
    if not my_art:
        learned_art = q("""SELECT sa.*, c.name as creator_name
                           FROM sword_arts sa
                           JOIN sword_art_disciples sad ON sad.art_id=sa.id
                           JOIN characters c ON c.id=sa.creator_id
                           WHERE sad.disciple_id=?""", (char['id'],), one=True)
    disciples = []
    if my_art:
        disciples = q("""SELECT c.name, sad.learned_at
                         FROM sword_art_disciples sad
                         JOIN characters c ON c.id=sad.disciple_id
                         WHERE sad.art_id=?""", (my_art['id'],))

    sword_bonus = get_sword_bonus(char)

    return render_template('sword.html',
        char=char,
        slv=slv, slv_name=slv_name, slv_next_exp=slv_next_exp,
        slv_exp=slv_exp, slv_pct=slv_pct,
        SWORD_LEVELS=SWORD_LEVELS,
        SWORD_COMBAT_EXP=SWORD_COMBAT_EXP, SWORD_PVP_EXP=SWORD_PVP_EXP,
        SWORD_MAX_STANCES=SWORD_MAX_STANCES, SWORD_MAX_DISCIPLES=SWORD_MAX_DISCIPLES,
        SWORD_STANCE_TYPES=SWORD_STANCE_TYPES,
        my_art=my_art, learned_art=learned_art, disciples=disciples,
        sword_bonus=sword_bonus)


@app.route('/game/pets', methods=['GET','POST'])
@login_required
def pets():
    char = me()

    if request.method == 'POST':
        action = request.form.get('action')
        pid    = int(request.form.get('pet_id', 0))
        pet    = q("SELECT * FROM char_pets WHERE id=? AND char_id=?", (pid, char['id']), one=True)

        if action == 'activate':
            if not pet:
                flash('灵兽不存在', 'error')
            else:
                run("UPDATE characters SET active_pet_id=? WHERE id=?", (pid, char['id']))
                flash('已设为出战灵兽', 'success')
        elif action == 'deactivate':
            run("UPDATE characters SET active_pet_id=NULL WHERE id=?", (char['id'],))
            flash('已收回灵兽', 'success')
        elif action == 'rename':
            nick = request.form.get('nickname', '').strip()[:12]
            if pet and nick:
                run("UPDATE char_pets SET nickname=? WHERE id=?", (nick, pid))
                flash('已改名', 'success')
        elif action == 'release':
            if pet:
                if char['active_pet_id'] == pid:
                    run("UPDATE characters SET active_pet_id=NULL WHERE id=?", (char['id'],))
                pt = q("SELECT name, rarity FROM pet_types WHERE id=?", (pet['pet_type_id'],), one=True)
                run("""INSERT INTO pet_release_pool
                       (pet_name,rarity,nickname,level,owner_id,owner_name,released_at)
                       VALUES (?,?,?,?,?,?,?)""",
                    (pt['name'] if pt else '未知灵兽', pt['rarity'] if pt else 'common',
                     pet['nickname'], pet['level'], char['id'], char['name'], now_ts()))
                run("DELETE FROM char_pets WHERE id=?", (pid,))
                flash('已放生灵兽，它已进入放生池', 'success')

        elif action == 'breed_start':
            if not char.get('beast_token_id'):
                flash('需持御灵令方可繁育灵兽', 'error')
            else:
                p1 = int(request.form.get('pet1_id', 0))
                p2 = int(request.form.get('pet2_id', 0))
                if p1 == p2 or not p1 or not p2:
                    flash('请选择两只不同的灵兽进行繁育', 'error')
                elif q("SELECT 1 FROM pet_breeding WHERE char_id=? AND collected=0", (char['id'],), one=True):
                    flash('已有一对灵兽正在繁育中，请先收取', 'error')
                else:
                    pet1 = q("SELECT * FROM char_pets WHERE id=? AND char_id=?", (p1, char['id']), one=True)
                    pet2 = q("SELECT * FROM char_pets WHERE id=? AND char_id=?", (p2, char['id']), one=True)
                    if not pet1 or not pet2:
                        flash('灵兽不存在', 'error')
                    else:
                        finish = now_ts() + BEAST_BREED_SECS
                        # 只从繁育专属池中随机选结果
                        bred_types = q(
                            "SELECT * FROM pet_types WHERE name IN ({}) AND is_active=1".format(
                                ','.join('?' * len(BREED_ONLY_PETS))),
                            tuple(BREED_ONLY_PETS))
                        if not bred_types:
                            flash('繁育数据未初始化，请联系管理员', 'error')
                        else:
                            result = random.choice(bred_types)['name']
                            run("INSERT INTO pet_breeding (char_id,pet1_id,pet2_id,result_type,started_at,finish_at) VALUES (?,?,?,?,?,?)",
                                (char['id'], p1, p2, result, now_ts(), finish))
                            log(char['id'], 'system', f'灵兽【{pet1["nickname"] or q("SELECT name FROM pet_types WHERE id=?", (pet1["pet_type_id"],), one=True)["name"]}】与【{pet2["nickname"] or q("SELECT name FROM pet_types WHERE id=?", (pet2["pet_type_id"],), one=True)["name"]}】开始繁育，8小时后可收取。')
                            flash('繁育已开始，8小时后来收取幼兽！', 'success')

        elif action == 'breed_collect':
            breed = q("SELECT * FROM pet_breeding WHERE char_id=? AND collected=0", (char['id'],), one=True)
            if not breed:
                flash('没有待收取的繁育结果', 'error')
            elif now_ts() < breed['finish_at']:
                remain = breed['finish_at'] - now_ts()
                flash(f'幼兽还需 {remain//3600}h{(remain%3600)//60}m 才能出生', 'error')
            else:
                pt = q("SELECT * FROM pet_types WHERE name=?", (breed['result_type'],), one=True)
                if pt:
                    run("INSERT INTO char_pets (char_id,pet_type_id,nickname,level,obtained_at) VALUES (?,?,'',1,?)",
                        (char['id'], pt['id'], now_ts()))
                    run("UPDATE pet_breeding SET collected=1 WHERE id=?", (breed['id'],))
                    log(char['id'], 'system', f'繁育成功，获得灵兽【{pt["name"]}】！')
                    flash(f'繁育成功！获得【{pt["name"]}】！可在坊市出售。', 'success')
                else:
                    flash('繁育数据异常', 'error')

        elif action == 'craft_spirit_pass':
            if not char.get('beast_token_id'):
                flash('需持御灵令方可炼制御灵神牌', 'error')
            else:
                blv, _, _, _, _ = beast_level_info(char)
                if blv < 3:
                    flash(f'需御灵等级【{BEAST_LEVELS[3]["name"]}】才可炼制御灵神牌（当前 {BEAST_LEVELS[blv]["name"]}）', 'error')
                else:
                    cost = 5000
                    mats = [('龙晶', 1), ('夜明珠', 1)]
                    missing = []
                    for mat_name, qty in mats:
                        mat = q("SELECT id FROM items WHERE name=?", (mat_name,), one=True)
                        have = 0
                        if mat:
                            inv_r = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?", (char['id'], mat['id']), one=True)
                            have = inv_r['quantity'] if inv_r else 0
                        if have < qty:
                            missing.append(f'{mat_name}（需{qty}有{have}）')
                    if char['spirit_stones'] < cost:
                        missing.append(f'灵石（需{cost}）')
                    if missing:
                        flash('材料不足：' + '、'.join(missing), 'error')
                    else:
                        for mat_name, qty in mats:
                            mat = q("SELECT id FROM items WHERE name=?", (mat_name,), one=True)
                            if mat:
                                inv_r = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?", (char['id'], mat['id']), one=True)
                                if inv_r and inv_r['quantity'] <= qty:
                                    run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], mat['id']))
                                else:
                                    run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?", (qty, char['id'], mat['id']))
                        run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?", (cost, char['id']))
                        sp = q("SELECT id FROM items WHERE name='御灵神牌'", one=True)
                        if sp:
                            ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (char['id'], sp['id']), one=True)
                            if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?", (char['id'], sp['id']))
                            else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)", (char['id'], sp['id']))
                        run("UPDATE characters SET beast_exp=beast_exp+50 WHERE id=?", (char['id'],))
                        log(char['id'], 'system', '炼制御灵神牌，消耗龙晶×1、夜明珠×1、灵石5000，御灵经验+50。')
                        flash('御灵神牌炼制成功！可在坊市出售，让他人获得双槽出战能力。', 'success')

        elif action == 'activate2':
            if not char.get('beast_token_id') and not char.get('spirit_pass_id'):
                flash('需持御灵令或激活御灵神牌方可使用第二灵兽槽', 'error')
            elif not pet:
                flash('灵兽不存在', 'error')
            elif pet['id'] == char.get('active_pet_id'):
                flash('此灵兽已在第一槽出战', 'error')
            else:
                run("UPDATE characters SET active_pet2_id=? WHERE id=?", (pid, char['id']))
                flash('已设为第二出战灵兽', 'success')

        elif action == 'deactivate2':
            run("UPDATE characters SET active_pet2_id=NULL WHERE id=?", (char['id'],))
            flash('已收回第二灵兽', 'success')

        elif action == 'feed':
            if not pet:
                flash('灵兽不存在', 'error')
            elif pet['level'] >= 20:
                flash('灵兽已达最高等级 Lv.20', 'error')
            else:
                is_beast = bool(char.get('beast_token_id'))
                cost = pet['level'] * (150 if is_beast else 300)
                if char['spirit_stones'] < cost:
                    flash(f'灵石不足，升至 Lv.{pet["level"]+1} 需 {cost} 灵石', 'error')
                else:
                    run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?", (cost, char['id']))
                    if is_beast:
                        run("UPDATE characters SET beast_exp=beast_exp+? WHERE id=?", (BEAST_FEED_EXP, char['id']))
                    run("UPDATE char_pets SET level=level+1 WHERE id=?", (pid,))
                    new_lv = pet['level'] + 1
                    beast_note = f'，御灵经验 +{BEAST_FEED_EXP}' if is_beast else ''
                    log(char['id'], 'system', f'灵兽升至 Lv.{new_lv}，消耗灵石 {cost}{beast_note}。')
                    flash(f'喂养成功，灵兽升至 Lv.{new_lv}！{beast_note}', 'success')
                    if char.get('beast_token_id'):
                        inc_quest(char['id'], 'beast')

        elif action in ('evolve', 'evolve_special'):
            if not pet:
                flash('灵兽不存在', 'error')
            else:
                pt   = q("SELECT * FROM pet_types WHERE id=?", (pet['pet_type_id'],), one=True)
                evo  = (PET_SPECIAL_EVOLUTION if action == 'evolve_special' else PET_EVOLUTION).get(pt['name'] if pt else '')
                if not evo:
                    flash('此灵兽无对应进化路线', 'error')
                else:
                    miss = []
                    for mat_name, qty in evo['mats']:
                        mat = q("SELECT id FROM items WHERE name=?", (mat_name,), one=True)
                        have = 0
                        if mat:
                            inv_r = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                                      (char['id'], mat['id']), one=True)
                            have = inv_r['quantity'] if inv_r else 0
                        if have < qty:
                            miss.append(f'{mat_name}（需{qty}，有{have}）')
                    if miss:
                        flash('材料不足：' + '、'.join(miss), 'error')
                    else:
                        new_pt = q("SELECT * FROM pet_types WHERE name=?", (evo['to'],), one=True)
                        if not new_pt:
                            flash('进化目标数据缺失', 'error')
                        else:
                            for mat_name, qty in evo['mats']:
                                mat = q("SELECT id FROM items WHERE name=?", (mat_name,), one=True)
                                if mat:
                                    inv_r = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                                              (char['id'], mat['id']), one=True)
                                    if inv_r and inv_r['quantity'] <= qty:
                                        run("DELETE FROM inventory WHERE char_id=? AND item_id=?",
                                            (char['id'], mat['id']))
                                    elif inv_r:
                                        run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?",
                                            (qty, char['id'], mat['id']))
                            run("UPDATE char_pets SET pet_type_id=? WHERE id=?", (new_pt['id'], pid))
                            tag = '【特殊进化】' if action == 'evolve_special' else ''
                            log(char['id'], 'system', f'{tag}灵兽【{pt["name"]}】进化为【{new_pt["name"]}】！')
                            flash(f'{"✦ 特殊进化" if action=="evolve_special" else "进化"}成功！【{pt["name"]}】→【{new_pt["name"]}】', 'success')

        elif action == 'evolve_super':
            if not pet:
                flash('灵兽不存在', 'error')
            elif not char.get('beast_token_id'):
                flash('超进化为御灵修专属，请先踏上御灵之路', 'error')
            elif pet['level'] < 20:
                flash(f'超进化需要灵兽达到 Lv.20 满级（当前 Lv.{pet["level"]}）', 'error')
            else:
                pt  = q("SELECT * FROM pet_types WHERE id=?", (pet['pet_type_id'],), one=True)
                evo = PET_SUPER_EVOLUTION.get(pt['name'] if pt else '')
                if not evo:
                    flash('此灵兽无超进化路线（需先进化至二段）', 'error')
                else:
                    miss = []
                    for mat_name, qty in evo['mats']:
                        mat = q("SELECT id FROM items WHERE name=?", (mat_name,), one=True)
                        have = 0
                        if mat:
                            inv_r = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                                      (char['id'], mat['id']), one=True)
                            have = inv_r['quantity'] if inv_r else 0
                        if have < qty:
                            miss.append(f'{mat_name}（需{qty}，有{have}）')
                    if miss:
                        flash('材料不足：' + '、'.join(miss), 'error')
                    else:
                        new_pt = q("SELECT * FROM pet_types WHERE name=?", (evo['to'],), one=True)
                        if not new_pt:
                            flash('超进化目标数据缺失，请联系管理员', 'error')
                        else:
                            for mat_name, qty in evo['mats']:
                                mat = q("SELECT id FROM items WHERE name=?", (mat_name,), one=True)
                                if mat:
                                    inv_r = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                                              (char['id'], mat['id']), one=True)
                                    if inv_r and inv_r['quantity'] <= qty:
                                        run("DELETE FROM inventory WHERE char_id=? AND item_id=?",
                                            (char['id'], mat['id']))
                                    elif inv_r:
                                        run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?",
                                            (qty, char['id'], mat['id']))
                            run("UPDATE char_pets SET pet_type_id=? WHERE id=?", (new_pt['id'], pid))
                            log(char['id'], 'system',
                                f'【御灵超进化】灵兽【{pt["name"]}】超进化为【{new_pt["name"]}】！')
                            flash(f'✦✦ 御灵超进化成功！【{pt["name"]}】→【{new_pt["name"]}】', 'success')

        elif action == 'maxlevel':
            blv, blv_name, _, _, _ = beast_level_info(char)
            if blv < BEAST_BRAND_MIN_LEVEL:
                flash(f'需御灵等级【{BEAST_LEVELS[BEAST_BRAND_MIN_LEVEL]["name"]}】才可一键满级（当前 {blv_name}）', 'error')
            elif not pet:
                flash('灵兽不存在', 'error')
            elif pet['level'] >= 20:
                flash('灵兽已达最高等级 Lv.20', 'error')
            else:
                run("UPDATE char_pets SET level=20 WHERE id=?", (pid,))
                log(char['id'], 'system', '御灵威能加身，灵兽一键满级至 Lv.20！')
                flash('一键满级成功，灵兽已至 Lv.20！', 'success')

        elif action == 'brand':
            blv, blv_name, _, _, _ = beast_level_info(char)
            if blv < BEAST_BRAND_MIN_LEVEL:
                flash(f'需御灵等级【{BEAST_LEVELS[BEAST_BRAND_MIN_LEVEL]["name"]}】才可神兽烙印（当前 {blv_name}）', 'error')
            elif not pet:
                flash('灵兽不存在', 'error')
            elif pet['is_branded']:
                flash('此灵兽已完成神兽烙印', 'error')
            elif pet['level'] < 20:
                flash(f'神兽烙印需灵兽达到 Lv.20 满级（当前 Lv.{pet["level"]}）', 'error')
            elif cur_energy(char) < BEAST_BRAND_ENERGY_COST:
                flash(f'灵力不足，神兽烙印需 {BEAST_BRAND_ENERGY_COST} 灵力（当前 {cur_energy(char)}）', 'error')
            else:
                mat = q("SELECT * FROM items WHERE name=?", (BEAST_BRAND_MAT_NAME,), one=True)
                mat_inv = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                            (char['id'], mat['id']), one=True) if mat else None
                mat_have = mat_inv['quantity'] if mat_inv else 0
                if not mat or mat_have < BEAST_BRAND_MAT_QTY:
                    flash(f'材料不足，神兽烙印需 {BEAST_BRAND_MAT_NAME}×{BEAST_BRAND_MAT_QTY}（持有 {mat_have}）', 'error')
                else:
                    pt   = q("SELECT * FROM pet_types WHERE id=?", (pet['pet_type_id'],), one=True)
                    brand = BEAST_BRAND.get(pt['name'] if pt else '')
                    if not brand:
                        flash('此灵兽已是终极形态或无烙印路线', 'error')
                    else:
                        brand_name, _ = brand
                        new_pt = q("SELECT * FROM pet_types WHERE name=?", (brand_name,), one=True)
                        if not new_pt:
                            flash('烙印目标数据缺失，请联系管理员', 'error')
                        else:
                            if mat_have <= BEAST_BRAND_MAT_QTY:
                                run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], mat['id']))
                            else:
                                run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?",
                                    (BEAST_BRAND_MAT_QTY, char['id'], mat['id']))
                            set_energy(char['id'], cur_energy(char) - BEAST_BRAND_ENERGY_COST)
                            buff_key = random.choice(BEAST_BRAND_BUFF_KEYS)
                            run("UPDATE char_pets SET pet_type_id=?, is_branded=1, brand_buff_key=? WHERE id=?",
                                (new_pt['id'], buff_key, pid))
                            buff_label = {'atk_pct':'攻击', 'def_pct':'防御', 'crit_rate':'暴击率', 'lifesteal':'吸血'}[buff_key]
                            log(char['id'], 'system',
                                f'【神兽烙印】灵兽【{pt["name"]}】烙印蜕变为【{new_pt["name"]}】！额外觉醒{buff_label}+20%之力，'
                                f'消耗灵力 {BEAST_BRAND_ENERGY_COST}、{BEAST_BRAND_MAT_NAME}×{BEAST_BRAND_MAT_QTY}。')
                            flash(f'✦✦✦ 神兽烙印成功！【{pt["name"]}】→【{new_pt["name"]}】，额外获得{buff_label}+20%！'
                                  f'（消耗灵力{BEAST_BRAND_ENERGY_COST}、{BEAST_BRAND_MAT_NAME}×{BEAST_BRAND_MAT_QTY}）', 'success')

        elif action == 'list_pet':
            if not pet:
                flash('灵兽不存在', 'error')
            elif q("SELECT 1 FROM pet_listings WHERE pet_id=? AND is_active=1", (pid,), one=True):
                flash('此灵兽已在坊市挂售', 'error')
            elif pet['id'] == char.get('active_pet_id') or pet['id'] == char.get('active_pet2_id'):
                flash('请先收回出战灵兽再挂售', 'error')
            else:
                try:
                    price = max(1, int(request.form.get('pet_price', 1000)))
                except Exception:
                    price = 1000
                active_cnt = q("SELECT COUNT(*) n FROM pet_listings WHERE seller_id=? AND is_active=1",
                               (char['id'],), one=True)['n']
                if active_cnt >= 5:
                    flash('灵兽挂单上限为 5 只', 'error')
                else:
                    expires = now_ts() + 7 * 86400
                    run("INSERT INTO pet_listings (seller_id,pet_id,price,listed_at,expires_at,is_active) VALUES (?,?,?,?,?,1)",
                        (char['id'], pid, price, now_ts(), expires))
                    pt_name = q("SELECT name FROM pet_types WHERE id=?", (pet['pet_type_id'],), one=True)['name']
                    log(char['id'], 'market', f'灵兽【{pt_name}】以 {price} 灵石挂售于坊市。')
                    flash(f'灵兽已挂售，价格 {price} 灵石，7天内有效。', 'success')

        elif action == 'cancel_pet_listing':
            listing_id = int(request.form.get('listing_id', 0))
            lst = q("SELECT * FROM pet_listings WHERE id=? AND seller_id=? AND is_active=1",
                    (listing_id, char['id']), one=True)
            if not lst:
                flash('挂单不存在', 'error')
            else:
                run("UPDATE pet_listings SET is_active=0 WHERE id=?", (lst['id'],))
                flash('已撤回灵兽挂单。', 'success')

        char = me()

    my_pets = q("""SELECT p.*, pt.name as type_name, pt.description, pt.effect_json,
        pt.rarity FROM char_pets p JOIN pet_types pt ON pt.id=p.pet_type_id
        WHERE p.char_id=? ORDER BY p.obtained_at DESC""", (char['id'],))

    # 丹市可购买的低阶灵兽
    shop_pets = q("SELECT * FROM pet_types WHERE market_price>0 AND is_active=1 ORDER BY market_price")

    is_beast     = bool(char.get('beast_token_id'))
    has_slot2    = is_beast or bool(char.get('spirit_pass_id'))
    blv, blv_name, blv_next, blv_exp, blv_pct = beast_level_info(char) if is_beast else (0,'',None,0,0)
    breeding     = q("SELECT * FROM pet_breeding WHERE char_id=? AND collected=0 ORDER BY id DESC LIMIT 1", (char['id'],), one=True)

    # 过期灵兽挂单退还
    expired_pet_lst = q("SELECT * FROM pet_listings WHERE is_active=1 AND expires_at>0 AND expires_at<=?", (now_ts(),))
    for el in expired_pet_lst:
        run("UPDATE pet_listings SET is_active=0 WHERE id=?", (el['id'],))
        ep = q("SELECT pt.name FROM char_pets cp JOIN pet_types pt ON pt.id=cp.pet_type_id WHERE cp.id=?", (el['pet_id'],), one=True)
        log(el['seller_id'], 'market', f'灵兽【{ep["name"] if ep else "未知"}】挂单已到期，灵兽退还。')

    # 我的灵兽挂单
    my_pet_listings = q("""SELECT pl.*, pt.name as type_name, pt.rarity
        FROM pet_listings pl JOIN char_pets cp ON cp.id=pl.pet_id
        JOIN pet_types pt ON pt.id=cp.pet_type_id
        WHERE pl.seller_id=? AND pl.is_active=1""", (char['id'],))
    listed_pet_ids = {pl['pet_id'] for pl in my_pet_listings}

    return render_template('pets.html', char=char, my_pets=my_pets, shop_pets=shop_pets,
                           PET_EVOLUTION=PET_EVOLUTION,
                           PET_SPECIAL_EVOLUTION=PET_SPECIAL_EVOLUTION,
                           PET_SUPER_EVOLUTION=PET_SUPER_EVOLUTION,
                           is_beast=is_beast, has_slot2=has_slot2,
                           beast_lv=blv, beast_lv_name=blv_name,
                           beast_lv_next=blv_next, beast_lv_exp=blv_exp, beast_lv_pct=blv_pct,
                           BEAST_LEVELS=BEAST_LEVELS, BEAST_FEED_EXP=BEAST_FEED_EXP,
                           BEAST_BRAND=BEAST_BRAND, BEAST_BRAND_MIN_LEVEL=BEAST_BRAND_MIN_LEVEL,
                           BEAST_BRAND_ENERGY_COST=BEAST_BRAND_ENERGY_COST,
                           BEAST_BRAND_MAT_NAME=BEAST_BRAND_MAT_NAME, BEAST_BRAND_MAT_QTY=BEAST_BRAND_MAT_QTY,
                           breeding=breeding, now_ts=now_ts(),
                           my_pet_listings=my_pet_listings,
                           listed_pet_ids=listed_pet_ids)

@app.route('/game/pets/buy', methods=['POST'])
@login_required
def buy_pet():
    char = me()
    ptid = int(request.form.get('pet_type_id', 0))
    pt   = q("SELECT * FROM pet_types WHERE id=? AND market_price>0 AND is_active=1", (ptid,), one=True)
    if not pt:
        flash('灵兽不存在', 'error')
    elif char['spirit_stones'] < pt['market_price']:
        flash(f'灵石不足，需 {pt["market_price"]}', 'error')
    else:
        run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?", (pt['market_price'], char['id']))
        run("INSERT INTO char_pets (char_id,pet_type_id,nickname,level,obtained_at) VALUES (?,?,'',1,?)",
            (char['id'], ptid, now_ts()))
        log(char['id'], 'system', f'于灵兽阁购入【{pt["name"]}】。')
        flash(f'已购入【{pt["name"]}】！', 'success')
    return redirect(url_for('pets'))

# ── 洗髓伐经 ───────────────────────────────────────────────────────────────────

@app.route('/game/xisui', methods=['GET','POST'])
@login_required
def xisui():
    char    = me()
    cur_root = char['spirit_root']
    result  = None

    # 当前灵根是否可继续提升
    can_upgrade = cur_root in XISUI_STEPS
    step = XISUI_STEPS.get(cur_root)
    next_root = None
    if can_upgrade:
        idx = SPIRIT_ROOT_CHAIN.index(cur_root)
        next_root = SPIRIT_ROOT_CHAIN[idx + 1]

    # 材料库存（若该档有 material_alt，优先选持有量充足的一种）
    mat_name = mat_have = 0
    mat_item = None
    if step:
        mat_name, mat_item, mat_have = xisui_resolve_material(step, char['id'])

    if request.method == 'POST' and can_upgrade:
        if mat_have < step['mat_qty']:
            need_desc = step['material']
            if step.get('material_alt'):
                need_desc += f'/{step["material_alt"]}'
            flash(f'材料不足：需 {need_desc} ×{step["mat_qty"]}（当前 {mat_have}）', 'error')
        elif char['spirit_stones'] < step['stones']:
            flash(f'灵石不足：需 {step["stones"]}', 'error')
        else:
            # 扣材料与灵石
            if mat_have <= step['mat_qty']:
                run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], mat_item['id']))
            else:
                run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?",
                    (step['mat_qty'], char['id'], mat_item['id']))
            run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?", (step['stones'], char['id']))

            success = random.random() < step['rate']
            if success:
                # 保存洗髓前的元素，用于变体判定
                old_elems = json.loads(char.get('elements', '') or '[]')
                # 灵根升级：变异/天灵根为单元素，从旧元素中保留一个，避免丢失亲和属性
                if next_root in ('变异灵根', '天灵根') and old_elems:
                    new_elems = [random.choice(old_elems)]
                else:
                    new_elems = rand_elements(next_root)
                run("UPDATE characters SET spirit_root=?, elements=? WHERE id=?",
                    (next_root, json.dumps(new_elems), char['id']))
                # 检查并处理失效法术
                check_spells_on_xisui(char['id'], new_elems)
                # 变异/天灵根：按洗髓前的元素判定变体，有该元素就有机会
                special_unlock = []
                if next_root in ('变异灵根', '天灵根'):
                    chance = 0.40 if next_root == '变异灵根' else 0.60
                    for base_e, spec_e in [('水','冰'),('金','雷'),('火','炎'),('木','风'),('土','岩')]:
                        if base_e in old_elems and random.random() < chance:
                            cur_spec = json.loads(char.get('special_elements','') or '[]')
                            if spec_e not in cur_spec:
                                cur_spec.append(spec_e)
                                run("UPDATE characters SET special_elements=? WHERE id=?",
                                    (json.dumps(cur_spec), char['id']))
                                special_unlock.append(spec_e)
                msg = f'洗髓伐经成功！灵根由【{cur_root}】蜕变为【{next_root}】，脱胎换骨！'
                if special_unlock:
                    msg += f' 感应到特殊灵根变体：{"、".join(special_unlock)}！'
                log(char['id'], 'system', msg)
                result = {'success': True, 'old': cur_root, 'new': next_root,
                          'elems': new_elems, 'special_unlock': special_unlock}
            else:
                msg = f'洗髓伐经失败，经脉剧痛，材料与灵石尽失，灵根未能蜕变。'
                log(char['id'], 'system', msg)
                result = {'success': False}
            flash(msg, 'success' if success else 'error')
            char = me()
            cur_root = char['spirit_root']
            can_upgrade = cur_root in XISUI_STEPS
            step = XISUI_STEPS.get(cur_root)
            next_root = None
            if can_upgrade:
                idx = SPIRIT_ROOT_CHAIN.index(cur_root)
                next_root = SPIRIT_ROOT_CHAIN[idx + 1]
                mat_name, mat_item, mat_have = xisui_resolve_material(step, char['id'])

    return render_template('xisui.html',
        char=char, cur_root=cur_root, next_root=next_root,
        can_upgrade=can_upgrade, step=step, mat_have=mat_have, mat_name=mat_name,
        result=result,
        cur_mult=SPIRIT_ROOTS[cur_root]['mult'],
        next_mult=SPIRIT_ROOTS[next_root]['mult'] if next_root else None)

# ── 寿元典当 ──────────────────────────────────────────────────────────────────────

@app.route('/game/cave', methods=['GET','POST'])
@login_required
def cave():
    char      = me()
    purchased = bool(char.get('cave_mode') is not None)
    price     = cave_price(char['realm_idx'])
    # 确保串门记录表存在（新功能兼容旧数据库）
    try:
        get_db().execute("""CREATE TABLE IF NOT EXISTS cave_visits (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            visitor_id INTEGER NOT NULL, owner_id INTEGER NOT NULL,
            visited_at INTEGER NOT NULL, UNIQUE(visitor_id,owner_id))""")
        get_db().commit()
    except Exception:
        pass

    if request.method == 'POST':
        action = request.form.get('action')
        if action == 'buy':
            if purchased:
                flash('你已拥有洞府', 'error')
            elif char['realm_idx'] < CAVE_MIN_REALM:
                flash(f'需达到【{REALMS[CAVE_MIN_REALM]["name"]}】方可购置洞府', 'error')
            elif char['spirit_stones'] < price:
                flash(f'灵石不足，需 {price}', 'error')
            else:
                peak_id = random.randint(1, 9)
                run("UPDATE characters SET spirit_stones=spirit_stones-?, cave_mode='off', cave_processed=?, cave_peak=? WHERE id=?",
                    (price, now_ts(), peak_id, char['id']))
                log(char['id'], 'system', f'花费 {price} 灵石购置洞府，获得【{CAVE_PEAK_MAP[peak_id]["name"]}】。')
                flash('洞府已购置！可选择修炼或炼体模式。', 'success')
                char = me()
                purchased = True
        elif action == 'set_mode' and purchased:
            mode = request.form.get('mode', 'off')
            if mode not in ('off', 'cultivate', 'temper'):
                mode = 'off'
            if mode == 'temper' and char['realm_idx'] < BODY_UNLOCK_REALM:
                flash(f'需达到【{REALMS[BODY_UNLOCK_REALM]["name"]}】才能开启炼体模式', 'error')
            else:
                run("UPDATE characters SET cave_mode=?, cave_processed=? WHERE id=?", (mode, now_ts(), char['id']))
                labels = {'off':'关闭', 'cultivate':'自动修炼', 'temper':'自动炼体'}
                flash(f'洞府模式已设为：{labels[mode]}', 'success')
                char = me()

        elif action == 'buy_furniture' and purchased:
            fkey = request.form.get('item_key', '')
            f    = FURNITURE_MAP.get(fkey)
            shop = get_cave_shop()
            shop_keys = [s['item_key'] for s in shop]
            already   = q("SELECT 1 FROM cave_purchases WHERE char_id=? AND item_key=?",
                          (char['id'], fkey), one=True)
            if not f:
                flash('家具不存在', 'error')
            elif fkey not in shop_keys:
                flash('该家具当前未上架', 'error')
            elif already:
                flash('你已购买过此家具', 'error')
            elif char['spirit_stones'] < f['price']:
                flash(f'灵石不足，需 {f["price"]}', 'error')
            else:
                equipped_count = q("SELECT COUNT(*) n FROM cave_purchases WHERE char_id=? AND is_equipped=1",
                                   (char['id'],), one=True)['n']
                auto_equip = 1 if equipped_count < cave_slots_for(char) else 0
                run("UPDATE characters SET spirit_stones=spirit_stones-?, cave_decor=cave_decor+10 WHERE id=?",
                    (f['price'], char['id']))
                run("INSERT INTO cave_purchases (char_id, item_key, slot, is_equipped, bought_at) VALUES (?,?,?,?,?)",
                    (char['id'], fkey, 0, auto_equip, now_ts()))
                log(char['id'], 'system', f'购置洞府家具【{f["name"]}】，装饰值 +10。')
                # 检查是否升级并给感悟
                old_lv = (char.get('cave_decor') or 0) // CAVE_DECOR_PER_LV
                new_lv = ((char.get('cave_decor') or 0) + 10) // CAVE_DECOR_PER_LV
                if new_lv > old_lv:
                    perk = random.choice(CAVE_PERK_POOL)
                    run("INSERT INTO cave_perks (char_id,perk_key,perk_name,value,earned_at) VALUES (?,?,?,?,?)",
                        (char['id'], perk['key'], perk['name'], perk['val'], now_ts()))
                    send_system_mail(char['id'], f'🏔 洞府感悟·{perk["name"]}',
                        f'{perk["narrative"]}\n\n'
                        f'【{perk["name"]}】已永久刻入你的洞府修炼之道。')
                    flash(f'已购置【{f["name"]}】，装饰值 +10！洞府升级，习得感悟【{perk["name"]}】！', 'success')
                else:
                    flash(f'已购置【{f["name"]}】，洞府装饰值 +10！', 'success')
                char = me()

        elif action == 'collect_pool' and purchased:
            pool_items = q("""SELECT cp.id, cp.quantity, i.name, i.id as item_id
                FROM cave_pool cp JOIN items i ON i.id=cp.item_id
                WHERE cp.char_id=?""", (char['id'],))
            total = 0
            for p in pool_items:
                ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?",
                       (char['id'], p['item_id']), one=True)
                if ex: run("UPDATE inventory SET quantity=quantity+? WHERE char_id=? AND item_id=?",
                           (p['quantity'], char['id'], p['item_id']))
                else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,?)",
                           (char['id'], p['item_id'], p['quantity']))
                total += p['quantity']
            run("DELETE FROM cave_pool WHERE char_id=?", (char['id'],))
            log(char['id'], 'system', f'从珍宝池领取 {total} 件物品。')
            flash(f'已从珍宝池领取 {total} 件物品！', 'success')
            char = me()

        elif action == 'rename_cave' and purchased:
            new_name = request.form.get('cave_name', '').strip()[:12]
            run("UPDATE characters SET cave_name=? WHERE id=?", (new_name, char['id']))
            flash(f'洞府已命名为【{new_name}】' if new_name else '洞府名称已清除', 'success')
            char = me()

        elif action == 'buy_luxury' and purchased:
            lkey = request.form.get('item_key', '')
            is_adv_lux = lkey in ADV_LUXURY_MAP
            lx   = ADV_LUXURY_MAP.get(lkey) or LUXURY_MAP.get(lkey)
            already = q("SELECT 1 FROM cave_luxury WHERE char_id=? AND item_key=?",
                        (char['id'], lkey), one=True)
            if not lx:
                flash('装饰品不存在', 'error')
            elif is_adv_lux and not char.get('cave_advanced'):
                flash('该装饰品需先晋升高级洞府', 'error')
            elif already:
                flash('已购置此装饰', 'error')
            elif char['spirit_stones'] < lx['price']:
                flash(f'灵石不足，需 {lx["price"]}', 'error')
            else:
                old_lv = (char.get('cave_decor') or 0) // CAVE_DECOR_PER_LV
                new_decor = (char.get('cave_decor') or 0) + lx['decor']
                new_lv = new_decor // CAVE_DECOR_PER_LV
                run("UPDATE characters SET spirit_stones=spirit_stones-?, cave_decor=? WHERE id=?",
                    (lx['price'], new_decor, char['id']))
                run("INSERT INTO cave_luxury (char_id,item_key,bought_at) VALUES (?,?,?)",
                    (char['id'], lkey, now_ts()))
                # 升级感悟
                for _ in range(new_lv - old_lv):
                    perk = random.choice(CAVE_PERK_POOL)
                    run("INSERT INTO cave_perks (char_id,perk_key,perk_name,value,earned_at) VALUES (?,?,?,?,?)",
                        (char['id'], perk['key'], perk['name'], perk['val'], now_ts()))
                    send_system_mail(char['id'], f'🏔 洞府感悟·{perk["name"]}',
                        f'{perk["narrative"]}\n\n【{perk["name"]}】已永久刻入你的洞府修炼之道。')
                log(char['id'], 'system', f'购置洞府装饰【{lx["name"]}】，装饰值 +{lx["decor"]}。')
                flash(f'已购置【{lx["name"]}】，装饰值 +{lx["decor"]}！', 'success')
                char = me()

        elif action == 'toggle_equip' and purchased:
            fkey = request.form.get('item_key', '')
            row  = q("SELECT * FROM cave_purchases WHERE char_id=? AND item_key=?",
                     (char['id'], fkey), one=True)
            if row:
                if row['is_equipped']:
                    run("UPDATE cave_purchases SET is_equipped=0 WHERE char_id=? AND item_key=?",
                        (char['id'], fkey))
                    flash(f'已卸下【{FURNITURE_MAP[fkey]["name"]}】', 'info')
                else:
                    eq_count = q("SELECT COUNT(*) n FROM cave_purchases WHERE char_id=? AND is_equipped=1",
                                 (char['id'],), one=True)['n']
                    my_slots = cave_slots_for(char)
                    if eq_count >= my_slots:
                        flash(f'已装备 {my_slots} 件，请先卸下一件', 'error')
                    else:
                        run("UPDATE cave_purchases SET is_equipped=1 WHERE char_id=? AND item_key=?",
                            (char['id'], fkey))
                        flash(f'已装备【{FURNITURE_MAP[fkey]["name"]}】', 'success')
            char = me()

        elif action == 'buy_advanced' and purchased:
            adv_price = cave_advanced_price()
            if char.get('cave_advanced'):
                flash('已是高级洞府', 'error')
            elif cave_level(char) < CAVE_ADVANCED_UNLOCK_LV:
                flash(f'洞府需达到 Lv{CAVE_ADVANCED_UNLOCK_LV} 才能升级为高级洞府', 'error')
            elif cave_advanced_slots_left() <= 0:
                flash(f'全服高级洞府名额（{CAVE_ADVANCED_SLOTS_TOTAL}个）已满', 'error')
            elif (char['superior_stones'] or 0) < adv_price:
                flash(f'上等灵石不足，需 {adv_price}（当前 {char["superior_stones"] or 0}）', 'error')
            else:
                run("UPDATE characters SET superior_stones=superior_stones-?, cave_advanced=1 WHERE id=?",
                    (adv_price, char['id']))
                log(char['id'], 'system', f'花费 {adv_price} 上等灵石，洞府晋升为高级洞府。')
                flash('洞府已晋升为高级洞府！可迁往高级山峰。', 'success')
                char = me()

        elif action == 'move_peak' and purchased:
            try:
                peak_id = int(request.form.get('peak_id', 0))
            except ValueError:
                peak_id = 0
            if not char.get('cave_advanced'):
                flash('需先将洞府升级为高级洞府', 'error')
            elif peak_id not in CAVE_PEAK_ADVANCED_IDS:
                flash('目标山峰不存在', 'error')
            elif char.get('cave_peak') == peak_id:
                flash('已定居此峰', 'error')
            else:
                run("UPDATE characters SET cave_peak=? WHERE id=?", (peak_id, char['id']))
                log(char['id'], 'system', f'迁居至高级山峰【{CAVE_PEAK_MAP[peak_id]["name"]}】。')
                flash(f'已迁居至【{CAVE_PEAK_MAP[peak_id]["name"]}】！灵力恢复速度翻倍，元神系统已开启。', 'success')
                char = me()

    shop = get_cave_shop() if purchased else []
    my_purchase_rows = q("SELECT item_key, is_equipped FROM cave_purchases WHERE char_id=? ORDER BY bought_at",
                         (char['id'],)) if purchased else []
    my_purchase_keys = {r['item_key'] for r in my_purchase_rows}
    # 已拥有家具列表（含装备状态）
    owned_items = [
        {**FURNITURE_MAP[r['item_key']], 'is_equipped': r['is_equipped']}
        for r in my_purchase_rows if r['item_key'] in FURNITURE_MAP
    ]
    # 装备槽展示（普通5个，高级洞府7个）
    my_slots = cave_slots_for(char)
    slot_list = [f for f in owned_items if f['is_equipped']][:my_slots]
    while len(slot_list) < my_slots:
        slot_list.append(None)

    shop_items = [
        {**FURNITURE_MAP[s['item_key']], 'expires_at': s['expires_at'],
         'bought': s['item_key'] in my_purchase_keys,
         'can_buy': len(my_purchase_keys) < len(FURNITURE_POOL)}
        for s in shop if s['item_key'] in FURNITURE_MAP
    ]
    clv  = cave_level(char)
    peak = CAVE_PEAK_MAP.get(char.get('cave_peak') or 0)
    my_cave_perks = q("SELECT perk_name, value, perk_key FROM cave_perks WHERE char_id=? ORDER BY earned_at",
                      (char['id'],)) if purchased else []
    my_luxury_keys = {r['item_key'] for r in q(
        "SELECT item_key FROM cave_luxury WHERE char_id=?", (char['id'],))} if purchased else set()
    luxury_items = [{**lx, 'bought': lx['key'] in my_luxury_keys} for lx in LUXURY_POOL]
    adv_luxury_items = [{**lx, 'bought': lx['key'] in my_luxury_keys} for lx in ADV_LUXURY_POOL]
    if purchased and (char.get('cave_decor') or 0) >= CAVE_POOL_UNLOCK:
        generate_cave_pool(char['id'], char.get('cave_decor') or 0)
    cave_pool_items = q("""SELECT cp.quantity, i.name FROM cave_pool cp JOIN items i ON i.id=cp.item_id
        WHERE cp.char_id=? ORDER BY cp.added_at""", (char['id'],)) if purchased else []
    pool_unlocked = purchased and (char.get('cave_decor') or 0) >= CAVE_POOL_UNLOCK
    _cur_pool_params = cave_pool_params(char.get('cave_decor') or 0, bool(char.get('cave_advanced')))

    return render_template('cave.html', char=char,
        purchased=purchased, price=price,
        CAVE_MIN_REALM=CAVE_MIN_REALM,
        BODY_UNLOCK_REALM=BODY_UNLOCK_REALM, REALMS=REALMS,
        cave_eff=int(CAVE_EFF*100),
        shop_items=shop_items, cave_lv=clv, peak=peak,
        CAVE_ADVANCED_UNLOCK_LV=CAVE_ADVANCED_UNLOCK_LV,
        CAVE_ADVANCED_PRICE=cave_advanced_price(),
        CAVE_PEAKS_ADVANCED=CAVE_PEAKS_ADVANCED,
        CAVE_ADV_ENERGY_MULT=CAVE_ADV_ENERGY_MULT,
        CAVE_ADVANCED_SLOTS_TOTAL=CAVE_ADVANCED_SLOTS_TOTAL,
        CAVE_SLOTS_ADVANCED=CAVE_SLOTS_ADVANCED,
        adv_slots_left=cave_advanced_slots_left(),
        is_advanced_peak=yuanshen_unlocked(char),
        slot_list=slot_list, owned_items=owned_items, CAVE_SLOTS=my_slots,
        CAVE_DECOR_PER_LV=CAVE_DECOR_PER_LV, my_cave_perks=my_cave_perks,
        luxury_items=luxury_items, adv_luxury_items=adv_luxury_items, cave_pool_items=cave_pool_items,
        pool_unlocked=pool_unlocked, CAVE_POOL_UNLOCK=CAVE_POOL_UNLOCK,
        CAVE_POOL_LIMIT=CAVE_POOL_LIMIT,
        pool_interval=_cur_pool_params[0], pool_drop_min=_cur_pool_params[1],
        pool_drop_max=_cur_pool_params[2], cave_pool_cap=_cur_pool_params[3],
        cave_shops=cave_shops_for(char['id'], clv),
        CAVE_SHOP_INCOME=(CAVE_SHOP_INCOME_ADVANCED if char.get('cave_advanced') else CAVE_SHOP_INCOME),
        cave_others=q("""SELECT c.id, c.name, c.cave_decor, c.cave_name, c.realm_idx
            FROM characters c WHERE c.is_npc=0 AND c.status='alive'
            AND c.cave_mode IS NOT NULL AND c.id != ? ORDER BY c.cave_decor DESC LIMIT 20""",
            (char['id'],)),
        visit_cooldowns={
            r['owner_id']: r['visited_at'] for r in
            q("SELECT owner_id, visited_at FROM cave_visits WHERE visitor_id=?", (char['id'],))
        },
        cave_affinity=_char_affinity_map(char['id']),
        now_ts=now_ts(),
        CAVE_VISIT_COOLDOWN=CAVE_VISIT_COOLDOWN)

@app.route('/game/cave/visit/<int:owner_cid>', methods=['POST'])
@login_required
def cave_visit(owner_cid):
    char = me()
    try:
        get_db().execute("""CREATE TABLE IF NOT EXISTS cave_visits (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            visitor_id INTEGER NOT NULL, owner_id INTEGER NOT NULL,
            visited_at INTEGER NOT NULL, UNIQUE(visitor_id,owner_id))""")
        get_db().commit()
    except Exception:
        pass
    if char['id'] == owner_cid:
        flash('不能串自己的洞府', 'error')
        return redirect(url_for('cave'))

    owner = q("SELECT * FROM characters WHERE id=? AND status='alive' AND is_npc=0 AND cave_mode IS NOT NULL",
              (owner_cid,), one=True)
    if not owner:
        flash('对方没有洞府或角色不存在', 'error')
        return redirect(url_for('cave'))

    # 冷却检查
    visit_row = q("SELECT visited_at FROM cave_visits WHERE visitor_id=? AND owner_id=?",
                  (char['id'], owner_cid), one=True)
    if visit_row and now_ts() - visit_row['visited_at'] < CAVE_VISIT_COOLDOWN:
        remain = CAVE_VISIT_COOLDOWN - (now_ts() - visit_row['visited_at'])
        flash(f'今日已串过此洞府，还需等待 {remain//3600} 时 {(remain%3600)//60} 分', 'error')
        return redirect(url_for('cave'))

    # 随机种子
    names, weights = zip(*CAVE_VISIT_SEED_POOL)
    seed_name = random.choices(names, weights=weights, k=1)[0]
    seed_item = q("SELECT id FROM items WHERE name=?", (seed_name,), one=True)
    if seed_item:
        ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (char['id'], seed_item['id']), one=True)
        if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?", (char['id'], seed_item['id']))
        else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)", (char['id'], seed_item['id']))

    # 好感（双向）
    add_affinity(char['id'], owner_cid, CAVE_VISIT_AFFINITY)

    # 记录
    run("INSERT INTO cave_visits (visitor_id,owner_id,visited_at) VALUES (?,?,?) ON CONFLICT(visitor_id,owner_id) DO UPDATE SET visited_at=?",
        (char['id'], owner_cid, now_ts(), now_ts()))
    log(char['id'], 'social', f'串门拜访【{owner["name"]}】的洞府，获得【{seed_name}】×1，好感 +{CAVE_VISIT_AFFINITY}。')
    log(owner_cid, 'social', f'【{char["name"]}】前来串门，给你带来了一些人气。')

    flash(f'成功串门【{owner["name"]}】的洞府！获得【{seed_name}】×1，好感 +{CAVE_VISIT_AFFINITY}。', 'success')
    return redirect(url_for('cave'))

@app.route('/game/cave/visit_all', methods=['POST'])
@login_required
def cave_visit_all():
    char = me()
    others = q("""SELECT c.id FROM characters c WHERE c.is_npc=0 AND c.status='alive'
        AND c.cave_mode IS NOT NULL AND c.id != ? ORDER BY c.cave_decor DESC LIMIT 20""",
        (char['id'],))
    cooldowns = {r['owner_id']: r['visited_at'] for r in
        q("SELECT owner_id, visited_at FROM cave_visits WHERE visitor_id=?", (char['id'],))}
    names_w, weights_w = zip(*CAVE_VISIT_SEED_POOL)
    visited, skipped, seeds_got = [], 0, []
    for row in others:
        oid = row['id']
        last = cooldowns.get(oid, 0)
        if now_ts() - last < CAVE_VISIT_COOLDOWN:
            skipped += 1
            continue
        owner = q("SELECT * FROM characters WHERE id=?", (oid,), one=True)
        if not owner:
            continue
        seed_name = random.choices(names_w, weights=weights_w, k=1)[0]
        seed_item = q("SELECT id FROM items WHERE name=?", (seed_name,), one=True)
        if seed_item:
            ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (char['id'], seed_item['id']), one=True)
            if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?", (char['id'], seed_item['id']))
            else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)", (char['id'], seed_item['id']))
        add_affinity(char['id'], oid, CAVE_VISIT_AFFINITY)
        run("INSERT INTO cave_visits (visitor_id,owner_id,visited_at) VALUES (?,?,?) ON CONFLICT(visitor_id,owner_id) DO UPDATE SET visited_at=?",
            (char['id'], oid, now_ts(), now_ts()))
        log(char['id'], 'social', f'串门拜访【{owner["name"]}】的洞府，获得【{seed_name}】×1，好感 +{CAVE_VISIT_AFFINITY}。')
        log(oid, 'social', f'【{char["name"]}】前来串门，给你带来了一些人气。')
        visited.append(owner['name'])
        seeds_got.append(seed_name)
    if visited:
        from collections import Counter
        seed_summary = '、'.join(f'{n}×{c}' for n, c in Counter(seeds_got).items())
        flash(f'一键串门完成！拜访了 {len(visited)} 位道友，获得种子：{seed_summary}，各获好感 +{CAVE_VISIT_AFFINITY}。', 'success')
    else:
        flash('当前没有可串门的洞府（全部冷却中）。', 'info')
    return redirect(url_for('cave'))

