@app.route('/game/peaks')
@login_required
def peaks():
    char = me()
    # 每座峰的居民
    residents = q("""SELECT c.name, c.realm_idx, c.spirit_root, c.cave_peak,
        c.cave_decor, c.cave_mode
        FROM characters c
        WHERE c.is_npc=0 AND c.status='alive'
        AND c.cave_mode IS NOT NULL AND c.cave_peak > 0
        ORDER BY c.cave_peak, c.realm_idx DESC""")
    peak_map = {}
    for r in residents:
        pid = r['cave_peak']
        if pid not in peak_map:
            peak_map[pid] = []
        peak_map[pid].append(r)
    return render_template('peaks.html', char=char,
        CAVE_PEAKS=CAVE_PEAKS + CAVE_PEAKS_ADVANCED, peak_map=peak_map, REALMS=REALMS,
        CAVE_PEAK_ADVANCED_IDS=CAVE_PEAK_ADVANCED_IDS)

@app.route('/game/yuanshen', methods=['GET', 'POST'])
@login_required
def yuanshen():
    char = me()
    unlocked = yuanshen_unlocked(char)
    level    = char['yuanshen_level'] or 0
    stones_cost, energy_cost, mats_needed = yuanshen_next_cost(level)

    if request.method == 'POST' and request.form.get('action') == 'nourish':
        if not unlocked:
            flash('需迁居至高级山峰方可温养元神', 'error')
        elif char['realm_idx'] < YUANSHEN_REALM_MIN:
            flash(f'需达到【{REALMS[YUANSHEN_REALM_MIN]["name"]}】才能温养元神', 'error')
        elif cur_energy(char) < energy_cost:
            flash(f'灵力不足，需 {energy_cost}', 'error')
        elif char['spirit_stones'] < stones_cost:
            flash(f'灵石不足，需 {stones_cost}', 'error')
        else:
            have_all = True
            for mname, mqty in mats_needed:
                row = q("""SELECT inv.quantity FROM inventory inv JOIN items i ON i.id=inv.item_id
                           WHERE inv.char_id=? AND i.name=?""", (char['id'], mname), one=True)
                if not row or row['quantity'] < mqty:
                    have_all = False
                    break
            if not have_all:
                flash('材料不足：' + '、'.join(f'{n}×{q_}' for n, q_ in mats_needed), 'error')
            else:
                set_energy(char['id'], cur_energy(char) - energy_cost)
                run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?",
                    (stones_cost, char['id']))
                for mname, mqty in mats_needed:
                    item = q("SELECT id FROM items WHERE name=?", (mname,), one=True)
                    run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?",
                        (mqty, char['id'], item['id']))
                run("DELETE FROM inventory WHERE char_id=? AND quantity<=0", (char['id'],))
                new_level = level + 1
                run("UPDATE characters SET yuanshen_level=? WHERE id=?", (new_level, char['id']))
                log(char['id'], 'system',
                    f'温养元神成功，元神境界提升至第 {new_level} 层，基础攻防各 +{YUANSHEN_ATK_PER_LV}。')
                flash(f'温养成功！元神提升至第 {new_level} 层。', 'success')
                char  = me()
                level = new_level
                stones_cost, energy_cost, mats_needed = yuanshen_next_cost(level)

    mats_display = []
    mats_ok = True
    for mname, mqty in mats_needed:
        row = q("""SELECT inv.quantity FROM inventory inv JOIN items i ON i.id=inv.item_id
                   WHERE inv.char_id=? AND i.name=?""", (char['id'], mname), one=True)
        have = row['quantity'] if row else 0
        mats_display.append({'name': mname, 'need': mqty, 'have': have})
        if have < mqty:
            mats_ok = False

    cur_en = cur_energy(char)
    can_nourish = (unlocked and char['realm_idx'] >= YUANSHEN_REALM_MIN
                   and cur_en >= energy_cost and char['spirit_stones'] >= stones_cost and mats_ok)

    return render_template('yuanshen.html', char=char,
        unlocked=unlocked, level=level, energy=cur_en,
        stones_cost=stones_cost, energy_cost=energy_cost, mats_display=mats_display,
        can_nourish=can_nourish,
        bonus=get_yuanshen_bonus(char), next_bonus=get_yuanshen_bonus({'yuanshen_level': level + 1}),
        YUANSHEN_REALM_MIN=YUANSHEN_REALM_MIN, REALMS=REALMS,
        YUANSHEN_ATK_PER_LV=YUANSHEN_ATK_PER_LV, YUANSHEN_DEF_PER_LV=YUANSHEN_DEF_PER_LV)

@app.route('/game/awakening', methods=['GET', 'POST'])
@login_required
def awakening():
    char     = me()
    eligible = ancient_awakening_eligible(char)
    awakened = bool(char.get('ancient_awakened'))
    blessing = ANCIENT_BLESSING_MAP.get(char.get('ancient_blessing_id')) if awakened else None
    reinforce_layers   = char.get('ancient_reinforce_layers') or 0
    reinforce_eligible = awakened and char['realm_idx'] >= ANCIENT_REINFORCE_REALM_MIN \
                         and reinforce_layers < ANCIENT_REINFORCE_MAX_LAYERS
    mat_name, mat_item, mat_have = (None, None, 0)
    if eligible and not awakened:
        mat_name, mat_item, mat_have = ancient_awaken_resolve_material(char['id'])
    reinforce_mat_name, reinforce_mat_item, reinforce_mat_have, reinforce_mat_need = (None, None, 0, 1)
    if reinforce_eligible:
        reinforce_mat_name, reinforce_mat_item, reinforce_mat_have, reinforce_mat_need = \
            ancient_reinforce_resolve_material(char['id'], reinforce_layers)

    result = None
    if request.method == 'POST' and request.form.get('action') == 'reinforce':
        if not awakened:
            flash('尚未觉醒远古意识，无法强化祝福', 'error')
        elif char['realm_idx'] < ANCIENT_REINFORCE_REALM_MIN:
            flash(f'需达到【{REALMS[ANCIENT_REINFORCE_REALM_MIN]["name"]}】方可强化祝福', 'error')
        elif reinforce_layers >= ANCIENT_REINFORCE_MAX_LAYERS:
            flash(f'祝福强化已达最高 {ANCIENT_REINFORCE_MAX_LAYERS} 层', 'error')
        elif reinforce_mat_have < reinforce_mat_need:
            flash(f'材料不足：需【{reinforce_mat_name}】×{reinforce_mat_need}', 'error')
        else:
            if reinforce_mat_have <= reinforce_mat_need:
                run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], reinforce_mat_item['id']))
            else:
                run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?",
                    (reinforce_mat_need, char['id'], reinforce_mat_item['id']))
            new_layers = reinforce_layers + 1
            run("UPDATE characters SET ancient_reinforce_layers=? WHERE id=?", (new_layers, char['id']))
            log(char['id'], 'system',
                f'以【{reinforce_mat_name}】×{reinforce_mat_need} 强化远古神话祝福，攻击、防御各再 +{int(ANCIENT_REINFORCE_PCT_PER_LAYER*100)}%'
                f'（第 {new_layers}/{ANCIENT_REINFORCE_MAX_LAYERS} 层）。')
            flash(f'强化成功！第 {new_layers}/{ANCIENT_REINFORCE_MAX_LAYERS} 层，攻击、防御各再 +{int(ANCIENT_REINFORCE_PCT_PER_LAYER*100)}%！', 'success')
            char = me()
            reinforce_layers   = char.get('ancient_reinforce_layers') or 0
            reinforce_eligible = awakened and char['realm_idx'] >= ANCIENT_REINFORCE_REALM_MIN \
                                 and reinforce_layers < ANCIENT_REINFORCE_MAX_LAYERS
            reinforce_mat_name, reinforce_mat_item, reinforce_mat_have, reinforce_mat_need = (None, None, 0, 1)
            if reinforce_eligible:
                reinforce_mat_name, reinforce_mat_item, reinforce_mat_have, reinforce_mat_need = \
                    ancient_reinforce_resolve_material(char['id'], reinforce_layers)

    if request.method == 'POST' and request.form.get('action') == 'attempt':
        if not eligible:
            flash('尚未在任一本领达到觉醒门槛', 'error')
        elif awakened:
            flash('已然觉醒远古意识，无需重复尝试', 'error')
        elif mat_have < 1:
            flash(f'材料不足：需 {"或".join(ANCIENT_AWAKEN_MATERIALS)} 至少 1 份', 'error')
        else:
            if mat_have <= 1:
                run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], mat_item['id']))
            else:
                run("UPDATE inventory SET quantity=quantity-1 WHERE char_id=? AND item_id=?",
                    (char['id'], mat_item['id']))
            success = random.random() < ANCIENT_AWAKEN_RATE
            if success:
                taken_ids = {r['ancient_blessing_id'] for r in q(
                    "SELECT DISTINCT ancient_blessing_id FROM characters WHERE ancient_blessing_id!='' AND ancient_blessing_id IS NOT NULL")}
                available = [b for b in ANCIENT_BLESSING_POOL if b['id'] not in taken_ids]
                # 祝福池共20种，已被他人选走的不再重复；若20种已被瓜分殆尽，则允许重复
                picked = random.choice(available) if available else random.choice(ANCIENT_BLESSING_POOL)
                # 无论抽到哪位神话人物，效果统一为攻击、防御各 +100%
                grant_perk(char['id'], {'key': 'atk_pct', 'val': ANCIENT_BLESSING_ATK_PCT}, '远古意识觉醒')
                grant_perk(char['id'], {'key': 'def_pct', 'val': ANCIENT_BLESSING_DEF_PCT}, '远古意识觉醒')
                # 无论抽到哪种祝福，觉醒本身额外附赠修炼速度加成（普通修炼、洞府挂机通用）
                grant_perk(char['id'], {'key': 'cultivate_pct', 'val': ANCIENT_AWAKEN_CULTIVATE_BONUS},
                           '远古意识觉醒·道基')
                run("UPDATE characters SET ancient_awakened=1, ancient_blessing_id=? WHERE id=?",
                    (picked['id'], char['id']))
                log(char['id'], 'system',
                    f'远古意识觉醒成功！感应到【{picked["name"]}】的祝福：{picked["desc"]}；'
                    f'道基本源觉醒，修炼速度额外 +{int(ANCIENT_AWAKEN_CULTIVATE_BONUS*100)}%（打坐、洞府均生效）。')
                flash(f'觉醒成功！获得远古神话祝福【{picked["name"]}】，并附赠修炼速度 +{int(ANCIENT_AWAKEN_CULTIVATE_BONUS*100)}%！', 'success')
                result = {'success': True, 'blessing': picked}
            else:
                log(char['id'], 'system', '远古意识觉醒失败，本领灵光一闪即逝，材料尽毁。')
                flash('觉醒失败，材料尽毁，可再次尝试。', 'error')
                result = {'success': False}
            char     = me()
            awakened = bool(char.get('ancient_awakened'))
            blessing = ANCIENT_BLESSING_MAP.get(char.get('ancient_blessing_id')) if awakened else None
            reinforce_layers   = char.get('ancient_reinforce_layers') or 0
            reinforce_eligible = awakened and char['realm_idx'] >= ANCIENT_REINFORCE_REALM_MIN \
                                 and reinforce_layers < ANCIENT_REINFORCE_MAX_LAYERS
            mat_name, mat_item, mat_have = (None, None, 0)
            if eligible and not awakened:
                mat_name, mat_item, mat_have = ancient_awaken_resolve_material(char['id'])
            reinforce_mat_name, reinforce_mat_item, reinforce_mat_have, reinforce_mat_need = (None, None, 0, 1)
            if reinforce_eligible:
                reinforce_mat_name, reinforce_mat_item, reinforce_mat_have, reinforce_mat_need = \
                    ancient_reinforce_resolve_material(char['id'], reinforce_layers)

    return render_template('awakening.html', char=char, eligible=eligible, awakened=awakened,
        blessing=blessing, mat_name=mat_name, mat_have=mat_have, result=result,
        ANCIENT_AWAKEN_RATE=ANCIENT_AWAKEN_RATE, ANCIENT_AWAKEN_EXP_REQ=ANCIENT_AWAKEN_EXP_REQ,
        ANCIENT_AWAKEN_MATERIALS=ANCIENT_AWAKEN_MATERIALS,
        ANCIENT_AWAKEN_CULTIVATE_BONUS=ANCIENT_AWAKEN_CULTIVATE_BONUS,
        ANCIENT_BLESSING_POOL=ANCIENT_BLESSING_POOL,
        reinforce_layers=reinforce_layers, reinforce_eligible=reinforce_eligible,
        reinforce_mat_name=reinforce_mat_name, reinforce_mat_have=reinforce_mat_have,
        reinforce_mat_need=reinforce_mat_need,
        ANCIENT_REINFORCE_REALM_MIN=ANCIENT_REINFORCE_REALM_MIN,
        ANCIENT_REINFORCE_PCT_PER_LAYER=ANCIENT_REINFORCE_PCT_PER_LAYER,
        ANCIENT_REINFORCE_MAX_LAYERS=ANCIENT_REINFORCE_MAX_LAYERS,
        ANCIENT_REINFORCE_TIER2_LAYER=ANCIENT_REINFORCE_TIER2_LAYER,
        ANCIENT_REINFORCE_TIER2_QTY=ANCIENT_REINFORCE_TIER2_QTY)

@app.route('/game/lifespan_pawn', methods=['GET', 'POST'])
@login_required
def lifespan_pawn():
    char     = me()
    today    = datetime.now(TZ).strftime('%Y-%m-%d')
    major    = REALMS[char['realm_idx']]['major']
    rate     = LIFESPAN_PAWN_RATE.get(major, 1)          # 石/年
    max_life  = lifespan(char)
    daily_cap = max(1, int(max_life * LIFESPAN_PAWN_DAILY_PCT))
    min_left  = max(1, int(max_life * LIFESPAN_PAWN_MIN_PCT))   # 不可典当的保留底线

    # 每日重置
    if (char.get('life_sold_date') or '') != today:
        run("UPDATE characters SET life_sold_today=0, life_sold_date=? WHERE id=?",
            (today, char['id']))
        char = me()

    sold_today   = char.get('life_sold_today') or 0
    remain_quota = daily_cap - sold_today
    cur_age      = char['age']
    life_left    = max_life - cur_age

    result = None
    if request.method == 'POST':
        try:
            years = int(request.form.get('years', 0))
        except (ValueError, TypeError):
            years = 0

        if years <= 0:
            flash('请输入有效年数', 'error')
        elif years > remain_quota:
            flash(f'今日剩余配额不足（剩余 {remain_quota} 年）', 'error')
        elif life_left - years < min_left:
            flash(f'寿元不足，剩余寿命低于上限 10%（{min_left} 年）时无法典当', 'error')
        else:
            stones = years * rate
            run("""UPDATE characters
                   SET spirit_stones   = spirit_stones + ?,
                       life_sold_today = life_sold_today + ?,
                       life_sold_date  = ?,
                       life_sold_total = life_sold_total + ?
                   WHERE id=?""",
                (stones, years, today, years, char['id']))
            log(char['id'], 'system',
                f'寿元典当：以 {years} 年寿命换得灵石 {stones}（汇率 {rate} 石/年）。')
            result = {'years': years, 'stones': stones}
            flash(f'典当 {years} 年寿命，换得灵石 {stones}', 'success')
            char = me()
            sold_today   = char.get('life_sold_today') or 0
            remain_quota = daily_cap - sold_today
            life_left    = lifespan(char) - char['age']

    return render_template('lifespan_pawn.html',
        char=char, major=major, rate=rate,
        max_life=max_life, daily_cap=daily_cap, min_left=min_left,
        sold_today=sold_today, remain_quota=remain_quota,
        life_left=life_left, result=result,
        LIFESPAN_PAWN_RATE=LIFESPAN_PAWN_RATE)

# ── 药田 ─────────────────────────────────────────────────────────────────────────

@app.route('/game/herb_garden', methods=['GET','POST'])
@login_required
def herb_garden():
    char = me()
    realm_cap = max_herb_plots(char['realm_idx'])
    purchased = char['herb_plots_unlocked'] or 1
    max_plots = min(purchased, realm_cap)
    next_unlock_cost = PLOT_UNLOCK_COSTS[purchased - 1] if purchased < 5 else None
    realm_unlock_reqs = [0, 3, 9, 13, 17]
    can_unlock = (next_unlock_cost is not None
                  and purchased < len(realm_unlock_reqs)
                  and char['realm_idx'] >= realm_unlock_reqs[purchased]
                  and char['spirit_stones'] >= next_unlock_cost)

    if request.method == 'POST':
        action = request.form.get('action')

        if action == 'unlock_plot':
            purchased2 = char['herb_plots_unlocked'] or 1
            if purchased2 >= 5:
                flash('地块已全部解锁', 'error')
            else:
                cost = PLOT_UNLOCK_COSTS[purchased2 - 1]
                realm_needed = realm_unlock_reqs[purchased2]
                if char['realm_idx'] < realm_needed:
                    flash(f'需达到【{REALMS[realm_needed]["name"]}】境界', 'error')
                elif char['spirit_stones'] < cost:
                    flash(f'灵石不足，需要 {cost} 灵石', 'error')
                else:
                    run("UPDATE characters SET herb_plots_unlocked=herb_plots_unlocked+1, spirit_stones=spirit_stones-? WHERE id=?", (cost, char['id']))
                    flash(f'成功解锁第 {purchased2+1} 块药田！', 'success')
                    char = me()
                    purchased = char['herb_plots_unlocked'] or 1
                    max_plots = min(purchased, realm_cap)
                    next_unlock_cost = PLOT_UNLOCK_COSTS[purchased - 1] if purchased < 5 else None
                    can_unlock = (next_unlock_cost is not None
                                  and purchased < len(realm_unlock_reqs)
                                  and char['realm_idx'] >= realm_unlock_reqs[purchased]
                                  and char['spirit_stones'] >= next_unlock_cost)
        elif action == 'plant':
            seed_id = int(request.form.get('seed_id', 0))
            seed = q("SELECT * FROM items WHERE id=? AND type='seed'", (seed_id,), one=True)
            inv  = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                     (char['id'], seed_id), one=True)
            active = q("SELECT COUNT(*) n FROM herb_plots WHERE char_id=? AND harvested=0",
                       (char['id'],), one=True)['n']
            if not seed or not inv or inv['quantity'] < 1:
                flash('没有此种子', 'error')
            elif active >= max_plots:
                flash(f'药田已满（最多 {max_plots} 块，提升境界可解锁更多）', 'error')
            else:
                eff = json.loads(seed['effect_json'] or '{}')
                grow_secs = eff.get('grow_secs', 3600)
                matures_at = now_ts() + grow_secs
                run("INSERT INTO herb_plots (char_id,seed_item_id,planted_at,matures_at,harvested) VALUES (?,?,?,?,0)",
                    (char['id'], seed_id, now_ts(), matures_at))
                if inv['quantity'] <= 1:
                    run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], seed_id))
                else:
                    run("UPDATE inventory SET quantity=quantity-1 WHERE char_id=? AND item_id=?",
                        (char['id'], seed_id))
                flash(f'已将【{seed["name"]}】种入药田，耐心等待成熟。', 'success')
                log(char['id'], 'system', f'将【{seed["name"]}】种入药田。')

        elif action == 'harvest':
            plot_id = int(request.form.get('plot_id', 0))
            plot = q("SELECT * FROM herb_plots WHERE id=? AND char_id=? AND harvested=0",
                     (plot_id, char['id']), one=True)
            if not plot:
                flash('地块不存在', 'error')
            elif now_ts() < plot['matures_at']:
                flash('尚未成熟，请耐心等待', 'error')
            else:
                seed = q("SELECT * FROM items WHERE id=?", (plot['seed_item_id'],), one=True)
                if seed:
                    eff = json.loads(seed['effect_json'] or '{}')
                    herb_name = eff.get('herb_name', '')
                    ymin = eff.get('yield_min', 1)
                    ymax = eff.get('yield_max', 1)
                    qty  = random.randint(ymin, ymax)
                    herb = q("SELECT * FROM items WHERE name=?", (herb_name,), one=True)
                    if herb:
                        ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?",
                               (char['id'], herb['id']), one=True)
                        if ex: run("UPDATE inventory SET quantity=quantity+? WHERE char_id=? AND item_id=?",
                                   (qty, char['id'], herb['id']))
                        else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,?)",
                                   (char['id'], herb['id'], qty))
                        run("UPDATE herb_plots SET harvested=1 WHERE id=?", (plot['id'],))

                        # 收获减少心魔（结丹+才有心魔；合体+田间劳作渐渐压不住心魔，有一定概率无效）
                        char = me()
                        dq_now = char['demonic_qi'] or 0
                        dq_reduce = 0
                        if dq_now > 0:
                            m = major_idx(char['realm_idx'])
                            dq_fail_prob = min(0.95, max(0, m - 4) * 0.45)  # 合体45%/大乘90%/渡劫+95%
                            if random.random() >= dq_fail_prob:
                                dq_reduce = min(dq_now, random.randint(1, 3))
                                run("UPDATE characters SET demonic_qi=demonic_qi-? WHERE id=?",
                                    (dq_reduce, char['id']))

                        # 5% 概率触发感悟，获得修为
                        insight_exp = 0
                        cd_now = char['herb_insight_cd'] or 0
                        if cd_now > 0:
                            run("UPDATE characters SET herb_insight_cd=herb_insight_cd-1 WHERE id=?", (char['id'],))
                        elif random.random() < 0.05:
                            base   = REALMS[char['realm_idx']]['exp']
                            nxt_r  = REALMS[char['realm_idx']+1] if char['realm_idx'] < len(REALMS)-1 else None
                            gap    = (nxt_r['exp'] - base) if nxt_r else base
                            insight_exp = min(100000, max(50, gap // 20))
                            run("UPDATE characters SET exp=exp+?, herb_insight_cd=? WHERE id=?",
                                (insight_exp, random.randint(8, 15), char['id']))

                        msg = f'收获【{herb_name}】×{qty}'
                        if dq_reduce:   msg += f'，田间劳作令心神宁静，心魔 -{dq_reduce}'
                        if insight_exp: msg += f'，忽有所悟，获得感悟 +{insight_exp} 修为'
                        msg += '！'
                        flash(msg, 'success')
                        log(char['id'], 'system', msg)
                    else:
                        flash('草药数据异常', 'error')

    # 活跃地块
    plots_raw = q("""SELECT hp.*, i.name as seed_name, i.effect_json as seed_eff
        FROM herb_plots hp JOIN items i ON i.id=hp.seed_item_id
        WHERE hp.char_id=? AND hp.harvested=0 ORDER BY hp.matures_at""", (char['id'],))
    plots = []
    now = now_ts()
    for p in plots_raw:
        eff = json.loads(p['seed_eff'] or '{}')
        mature = now >= p['matures_at']
        remain_secs = max(0, p['matures_at'] - now)
        remain_h = remain_secs // 3600
        remain_m = (remain_secs % 3600) // 60
        plots.append({**dict(p), 'mature': mature, 'herb_name': eff.get('herb_name',''),
                      'remain_h': remain_h, 'remain_m': remain_m,
                      'yield_min': eff.get('yield_min',1), 'yield_max': eff.get('yield_max',1)})

    # 背包中的种子
    seeds_inv = q("""SELECT i.*, inv.quantity FROM items i
        JOIN inventory inv ON inv.item_id=i.id
        WHERE inv.char_id=? AND i.type='seed'
        ORDER BY i.rarity, i.name""", (char['id'],))

    return render_template('herb_garden.html',
        char=char, plots=plots, seeds_inv=seeds_inv,
        max_plots=max_plots, active_count=len(plots),
        next_unlock_cost=next_unlock_cost, can_unlock=can_unlock, purchased=purchased,
        PLOT_UNLOCK_COSTS=PLOT_UNLOCK_COSTS, REALMS=REALMS)

# ── 打工系统 ───────────────────────────────────────────────────────────────────

@app.route('/game/work', methods=['GET', 'POST'])
@login_required
def work():
    char   = me()
    energy = cur_energy(char)
    now    = now_ts()

    alch_lv   = char['alchemy_level'] or 0
    forge_lv  = char['forge_level']   or 0
    fulu_lv_w, _, _, _, _ = fulu_level_info(char)
    beast_lv_w,  _, _, _, _ = beast_level_info(char)  if (char['beast_token_id'] or None)  else (0,'',None,0,0)
    heqing_lv_w, _, _, _, _ = heqing_level_info(char) if (char['heqing_token_id'] or None) else (0,'',None,0,0)
    sword_lv_w,  _, _, _, _ = sword_level_info(char)  if (char['sword_token_id'] or None)  else (0,'',None,0,0)

    def _job_block_reason(job):
        """返回 (status, reason_str) 或 None 表示可接单。"""
        if char['realm_idx'] < job['min_realm']:
            return 'locked',    f'需达到【{REALMS[job["min_realm"]]["name"]}】'
        if char['realm_idx'] > job['max_realm']:
            return 'prestige',  '有损形象'
        if 'min_alchemy_level' in job:
            if not char_has_furnace(char['id'], 'cauldron'):
                return 'locked', '需持有丹炉'
            if alch_lv < job['min_alchemy_level']:
                return 'locked', f'需炼丹等级【{ALCHEMY_LEVELS[job["min_alchemy_level"]]["name"]}】'
        if 'min_forge_level' in job:
            if not char_has_furnace(char['id'], 'forge'):
                return 'locked', '需持有炼器炉'
            if forge_lv < job['min_forge_level']:
                return 'locked', f'需炼器等级【{FORGE_LEVELS[job["min_forge_level"]]["name"]}】'
        if 'min_fulu_level' in job:
            if not char_has_furnace(char['id'], 'brush'):
                return 'locked', '需持有毛笔'
            if fulu_lv_w < job['min_fulu_level']:
                return 'locked', f'需符修等级【{FULU_LEVELS[job["min_fulu_level"]]["name"]}】'
        if 'min_beast_level' in job:
            if not char.get('beast_token_id'):
                return 'locked', '需持有御灵令'
            if beast_lv_w < job['min_beast_level']:
                return 'locked', f'需御灵等级【{BEAST_LEVELS[job["min_beast_level"]]["name"]}】'
        if 'min_heqing_level' in job:
            if not char.get('heqing_token_id'):
                return 'locked', '需持有合欢令'
            if heqing_lv_w < job['min_heqing_level']:
                return 'locked', f'需合欢等级【{HEQING_LEVELS[job["min_heqing_level"]]["name"]}】'
        if 'min_sword_level' in job:
            if not char.get('sword_token_id'):
                return 'locked', '需持有飞剑令'
            req_lv = job['min_sword_level']
            if sword_lv_w < req_lv:
                lv_name = SWORD_LEVELS[req_lv]['name'] if req_lv < len(SWORD_LEVELS) else SWORD_LEVELS[-1]['name']
                return 'locked', f'需剑修等级【{lv_name}】'
        return None

    if request.method == 'POST':
        key = request.form.get('job_key', '')
        job = WORK_JOBS_MAP.get(key)
        if not job:
            flash('未知任务', 'error')
        else:
            block = _job_block_reason(job)
            if block:
                flash(f'无法接受此差事：{block[1]}', 'error')
            elif energy < job['energy']:
                flash(f'灵力不足（需 {job["energy"]}，当前 {energy}）', 'error')
            else:
                cd_row = q("SELECT last_ts FROM work_cooldowns WHERE char_id=? AND job_key=?",
                           (char['id'], key), one=True)
                last   = cd_row['last_ts'] if cd_row else 0
                remain = last + job['cooldown'] - now
                if remain > 0:
                    h, m = divmod(remain // 60, 60)
                    flash(f'此差事仍在冷却中，还需等待 {h} 小时 {m} 分钟', 'error')
                else:
                    earned = random.randint(job['stones_min'], job['stones_max'])
                    run("UPDATE characters SET spirit_stones=spirit_stones+?, exp=exp+? WHERE id=?",
                        (earned, job['exp'], char['id']))
                    set_energy(char['id'], energy - job['energy'])
                    run("""INSERT INTO work_cooldowns (char_id, job_key, last_ts) VALUES (?,?,?)
                           ON CONFLICT(char_id, job_key) DO UPDATE SET last_ts=excluded.last_ts""",
                        (char['id'], key, now))
                    msg = f'完成【{job["name"]}】，获得灵石 {earned}、修为 {job["exp"]}。'
                    log(char['id'], 'system', msg)
                    flash(msg, 'success')
                    char     = me()
                    energy   = cur_energy(char)
                    alch_lv  = char['alchemy_level'] or 0
                    forge_lv = char['forge_level']   or 0

    # 构建展示列表，附带每个任务的当前状态
    cd_rows = {r['job_key']: r['last_ts']
               for r in q("SELECT job_key, last_ts FROM work_cooldowns WHERE char_id=?", (char['id'],))}
    jobs_view = []
    for job in WORK_JOBS:
        last   = cd_rows.get(job['key'], 0)
        remain = last + job['cooldown'] - now
        on_cd  = remain > 0
        cd_h, cd_m = divmod(max(0, remain) // 60, 60) if on_cd else (0, 0)

        block     = _job_block_reason(job)
        no_energy = energy < job['energy']

        if block:
            status, reason = block
        elif on_cd:
            status = 'cooldown'
            reason = f'冷却中 {cd_h}h{cd_m:02d}m'
        elif no_energy:
            status = 'no_energy'
            reason = f'灵力不足（需 {job["energy"]}）'
        else:
            status = 'available'
            reason = ''

        # 需求标签，供模板展示
        req_label = ''
        if 'min_alchemy_level' in job:
            req_label = f'炼丹：{ALCHEMY_LEVELS[job["min_alchemy_level"]]["name"]}'
        elif 'min_forge_level' in job:
            req_label = f'炼器：{FORGE_LEVELS[job["min_forge_level"]]["name"]}'
        elif 'min_fulu_level' in job:
            req_label = f'符修：{FULU_LEVELS[job["min_fulu_level"]]["name"]}'
        elif 'min_beast_level' in job:
            req_label = f'御灵：{BEAST_LEVELS[job["min_beast_level"]]["name"]}'
        elif 'min_heqing_level' in job:
            req_label = f'合欢：{HEQING_LEVELS[job["min_heqing_level"]]["name"]}'
        elif 'min_sword_level' in job:
            _slv_idx = job['min_sword_level']
            _slv_name = SWORD_LEVELS[_slv_idx]['name'] if _slv_idx < len(SWORD_LEVELS) else SWORD_LEVELS[-1]['name']
            req_label = f'剑修：{_slv_name}'
        elif job['min_realm'] > 0:
            req_label = f'境界：{REALMS[job["min_realm"]]["name"]}'

        cd_total_h = job['cooldown'] // 3600
        jobs_view.append({**job, 'status': status, 'reason': reason,
                          'cd_h': cd_total_h, 'req_label': req_label})

    general_jobs = [j for j in jobs_view if j['category'] == 'general']
    farm_jobs    = [j for j in jobs_view if j['category'] == 'farm']
    alchemy_jobs = [j for j in jobs_view if j['category'] == 'alchemy']
    forge_jobs   = [j for j in jobs_view if j['category'] == 'forge']
    fulu_jobs    = [j for j in jobs_view if j['category'] == 'fulu']
    beast_jobs   = [j for j in jobs_view if j['category'] == 'beast']
    heqing_jobs  = [j for j in jobs_view if j['category'] == 'heqing']
    sword_jobs   = [j for j in jobs_view if j['category'] == 'sword']

    return render_template('work.html',
        char=char, energy=energy, MAX_ENERGY=energy_cap(char),
        general_jobs=general_jobs, farm_jobs=farm_jobs,
        alchemy_jobs=alchemy_jobs, forge_jobs=forge_jobs, fulu_jobs=fulu_jobs,
        beast_jobs=beast_jobs, heqing_jobs=heqing_jobs, sword_jobs=sword_jobs,
        alch_lv=alch_lv, forge_lv=forge_lv, fulu_lv=fulu_lv_w,
        beast_lv=beast_lv_w, heqing_lv=heqing_lv_w, sword_lv=sword_lv_w,
        ALCHEMY_LEVELS=ALCHEMY_LEVELS, FORGE_LEVELS=FORGE_LEVELS,
        FULU_LEVELS=FULU_LEVELS, BEAST_LEVELS=BEAST_LEVELS,
        HEQING_LEVELS=HEQING_LEVELS, SWORD_LEVELS=SWORD_LEVELS, REALMS=REALMS)

# ── 灵矿（器修专属）─────────────────────────────────────────────────────────────

@app.route('/game/mine', methods=['GET','POST'])
@login_required
def mine():
    char   = me()
    energy = cur_energy(char)

    if not char_has_furnace(char['id'], 'forge'):
        flash('此处仅供器修进入，需先持有炼器炉。', 'error')
        return redirect(url_for('inventory'))

    forge_lv = char['forge_level'] or 0
    result   = None

    if request.method == 'POST':
        key  = request.form.get('mine_key', '')
        spot = MINE_SPOTS_MAP.get(key)
        if not spot:
            flash('矿脉不存在', 'error')
        elif forge_lv < spot['min_forge_level']:
            flash(f'需达到炼器等级【{FORGE_LEVELS[spot["min_forge_level"]]["name"]}】方可开采此矿。', 'error')
        elif energy < spot['energy']:
            flash(f'灵力不足，需 {spot["energy"]}（当前 {energy}）', 'error')
        else:
            now_t   = now_ts()
            cd_row  = q("SELECT last_ts FROM work_cooldowns WHERE char_id=? AND job_key=?",
                        (char['id'], key), one=True)
            on_cd   = cd_row and (now_t - cd_row['last_ts']) < spot['cooldown']
            if on_cd:
                remain = spot['cooldown'] - (now_t - cd_row['last_ts'])
                flash(f'矿脉尚未恢复，剩余 {remain//3600}h{(remain%3600)//60}m', 'error')
            else:
                # 随机抽掉落
                weights = [d['weight'] for d in spot['drops']]
                drop    = random.choices(spot['drops'], weights=weights, k=1)[0]
                qty     = random.randint(drop['qty_min'], drop['qty_max'])
                item    = q("SELECT * FROM items WHERE name=?", (drop['item'],), one=True)
                if item:
                    ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?",
                           (char['id'], item['id']), one=True)
                    if ex: run("UPDATE inventory SET quantity=quantity+? WHERE char_id=? AND item_id=?",
                               (qty, char['id'], item['id']))
                    else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,?)",
                               (char['id'], item['id'], qty))
                set_energy(char['id'], energy - spot['energy'])
                run("""INSERT INTO work_cooldowns (char_id,job_key,last_ts) VALUES (?,?,?)
                       ON CONFLICT(char_id,job_key) DO UPDATE SET last_ts=excluded.last_ts""",
                    (char['id'], key, now_t))
                inc_quest(char['id'], 'mine')
                log(char['id'], 'mine', f'于【{spot["name"]}】开采，获得【{drop["item"]}】×{qty}。')
                result = {'spot': spot['name'], 'item': drop['item'], 'qty': qty}
                energy -= spot['energy']
                char = me()

    now_t   = now_ts()
    cd_rows = {r['job_key']: r['last_ts']
               for r in q("SELECT job_key,last_ts FROM work_cooldowns WHERE char_id=?", (char['id'],))}
    spots_view = []
    for spot in MINE_SPOTS:
        last   = cd_rows.get(spot['key'], 0)
        remain = max(0, last + spot['cooldown'] - now_t)
        spots_view.append({**spot,
            'locked':    forge_lv < spot['min_forge_level'],
            'on_cd':     remain > 0,
            'cd_h':      remain // 3600,
            'cd_m':      (remain % 3600) // 60,
            'no_energy': energy < spot['energy'],
        })
    return render_template('mine.html', char=char, energy=energy,
                           MAX_ENERGY=energy_cap(char), spots=spots_view,
                           forge_lv=forge_lv, FORGE_LEVELS=FORGE_LEVELS,
                           result=result)

# ── 秘矿（符修专属，大乘及以上开启）────────────────────────────────────────────

