# ── 本命武器管理 ────────────────────────────────────────────────────────────────

@app.route('/game/forge/destiny_weapons', methods=['GET','POST'])
@login_required
def forge_destiny_weapons():
    char = me()
    if request.method == 'POST':
        action = request.form.get('action')
        dw_id  = int(request.form.get('dw_id', 0))
        dw     = q("SELECT * FROM destiny_weapons WHERE id=? AND char_id=?",
                   (dw_id, char['id']), one=True)
        if not dw:
            flash('本命武器不存在', 'error')
        elif action in ('equip', 'unequip') and gate_equip_locked(char):
            flash('异世之门活动期间攻击力已锁定，无法更换本命武器。', 'error')
        elif action == 'equip':
            run("UPDATE characters SET destiny_weapon_id=? WHERE id=?", (dw_id, char['id']))
            flash(f'已契合【{dw["custom_name"] or dw["weapon_type"]}】', 'success')
        elif action == 'unequip':
            run("UPDATE characters SET destiny_weapon_id=NULL WHERE id=?", (char['id'],))
            flash('已解除本命武器契合', 'success')
        elif action == 'enhance':
            star_mat = q("SELECT * FROM items WHERE name='星陨铁'", one=True)
            star_inv = q("SELECT * FROM inventory WHERE char_id=? AND item_id=?",
                         (char['id'], star_mat['id']), one=True) if star_mat else None
            star_need = destiny_enhance_star_iron_cost(dw['enhance_level'])
            extra_name = dw['enhance_next_mat']
            if not extra_name:
                extra_name = destiny_enhance_pick_extra_mat(char['realm_idx'])
                run("UPDATE destiny_weapons SET enhance_next_mat=? WHERE id=?", (extra_name, dw_id))
            extra_mat = q("SELECT * FROM items WHERE name=?", (extra_name,), one=True)
            extra_inv = q("SELECT * FROM inventory WHERE char_id=? AND item_id=?",
                          (char['id'], extra_mat['id']), one=True) if extra_mat else None
            if not star_mat or not star_inv or star_inv['quantity'] < star_need:
                flash(f'材料不足（需 星陨铁 ×{star_need}）', 'error')
            elif not extra_mat or not extra_inv or extra_inv['quantity'] < 1:
                flash(f'材料不足（还需 {extra_name} ×1）', 'error')
            else:
                # 消耗材料（无论成功失败）
                if star_inv['quantity'] <= star_need:
                    run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], star_mat['id']))
                else:
                    run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?",
                        (star_need, char['id'], star_mat['id']))
                if extra_inv['quantity'] <= 1:
                    run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], extra_mat['id']))
                else:
                    run("UPDATE inventory SET quantity=quantity-1 WHERE char_id=? AND item_id=?",
                        (char['id'], extra_mat['id']))

                success_rate = destiny_enhance_success_rate(dw['enhance_level'])
                if random.random() < success_rate:
                    bk  = random.choice(DESTINY_ENHANCE_BUFF_POOL)
                    val = DESTINY_ENHANCE_BUFF_VALUE
                    enh = json.loads(dw['enhance_json'] or '{}')
                    enh[bk] = enh.get(bk, 0) + val
                    new_level = dw['enhance_level'] + 1
                    next_mat = destiny_enhance_pick_extra_mat(char['realm_idx'])
                    milestone_msg = ''
                    if new_level % DESTINY_ENHANCE_MILESTONE_LEVEL == 0:
                        run("""UPDATE destiny_weapons SET enhance_json=?, enhance_level=?,
                               enhance_next_mat=?, base_attack=base_attack+? WHERE id=?""",
                            (json.dumps(enh), new_level, next_mat, DESTINY_ENHANCE_MILESTONE_ATK, dw_id))
                        milestone_msg = f'，达到 +{new_level} 级里程碑，基础攻击额外 +{DESTINY_ENHANCE_MILESTONE_ATK}！'
                    else:
                        run("""UPDATE destiny_weapons SET enhance_json=?, enhance_level=?,
                               enhance_next_mat=? WHERE id=?""",
                            (json.dumps(enh), new_level, next_mat, dw_id))
                    bk_label = {'atk_pct':'攻击%','def_pct':'防御%','lifesteal':'吸血'}.get(bk, bk)
                    flash(f'强化成功！【{bk_label}】 +{val}%，当前 +{new_level} 级{milestone_msg}', 'success')
                else:
                    flash(f'强化失败，材料尽毁！（本次成功率 {int(success_rate*100)}%）', 'error')
        char = me()

    my_dws = q("SELECT * FROM destiny_weapons WHERE char_id=? ORDER BY is_claimed, created_at DESC", (char['id'],))
    equipped_id = char['destiny_weapon_id']
    buff_labels = {'atk_pct':'攻击%','def_pct':'防御%','crit_rate':'暴击率','crit_dmg':'暴击伤害',
                   'dodge_rate':'闪避率','lifesteal':'吸血'}
    dw_list = []
    for dw in my_dws:
        forge_buffs = json.loads(dw['buffs_json'] or '{}')
        claim_buffs = json.loads(dw['claim_buffs_json'] or '{}') if dw['is_claimed'] else {}
        enh         = json.loads(dw['enhance_json'] or '{}')
        # 合并三组buff
        merged = {}
        for src in (forge_buffs, claim_buffs, enh):
            for k, v in src.items():
                merged[k] = merged.get(k, 0) + v
        buff_disp = []
        for k, v in merged.items():
            label = buff_labels.get(k, k)
            buff_disp.append(f'{label} +{v}%')
        winfo = DESTINY_WEAPON_TYPES.get(dw['weapon_type'], {})
        row = {**dict(dw), 'buff_disp': buff_disp,
               'forge_buffs': {buff_labels.get(k,k): f'+{v}%' for k,v in forge_buffs.items()},
               'claim_buffs': {buff_labels.get(k,k): f'+{v}%' for k,v in claim_buffs.items()},
               'enh_buffs': {buff_labels.get(k,k): f'+{v}%' for k,v in enh.items()},
               'winfo': winfo,
               'is_equipped': dw['id'] == equipped_id,
               'display_name': dw['custom_name'] or dw['weapon_type']}
        if dw['is_claimed']:
            extra_name = dw['enhance_next_mat']
            if not extra_name:
                extra_name = destiny_enhance_pick_extra_mat(char['realm_idx'])
                run("UPDATE destiny_weapons SET enhance_next_mat=? WHERE id=?", (extra_name, dw['id']))
            extra_owned = q("""SELECT inv.quantity FROM inventory inv JOIN items i ON i.id=inv.item_id
                WHERE inv.char_id=? AND i.name=?""", (char['id'], extra_name), one=True)
            row['enhance_star_need']  = destiny_enhance_star_iron_cost(dw['enhance_level'])
            row['enhance_extra_name'] = extra_name
            row['enhance_extra_qty']  = extra_owned['quantity'] if extra_owned else 0
            row['enhance_rate_pct']   = int(destiny_enhance_success_rate(dw['enhance_level']) * 100)
        dw_list.append(row)

    # 星陨铁库存（强化材料）
    star_iron = q("""SELECT inv.quantity FROM inventory inv JOIN items i ON i.id=inv.item_id
        WHERE inv.char_id=? AND i.name='星陨铁'""", (char['id'],), one=True)
    star_iron_qty = star_iron['quantity'] if star_iron else 0

    return render_template('forge_destiny_weapons.html',
        char=char, dw_list=dw_list, star_iron_qty=star_iron_qty,
        DESTINY_WEAPON_TYPES=DESTINY_WEAPON_TYPES)

