@app.route('/game/auction', methods=['GET','POST'])
@login_required
def auction():
    char    = me()
    my_elems = [SPECIAL_ELEMENT_SOURCES.get(e, e) for e in char_elements(char)]

    if request.method == 'POST':
        aid = int(request.form.get('auction_id', 0))
        a   = q("""SELECT au.*, i.name, i.effect_json, i.rarity, i.type, i.description
            FROM auctions au JOIN items i ON i.id=au.item_id
            WHERE au.id=? AND au.is_active=1""", (aid,), one=True)
        if not a:
            flash('拍品不存在', 'error')
        else:
            req_elem = json.loads(a['effect_json'] or '{}').get('element')
            if req_elem and req_elem not in my_elems:
                flash(f'此本命法宝需【{req_elem}】属性灵根方可拍下，你的灵根不符', 'error')
            elif char['spirit_stones'] < a['price']:
                flash(f'灵石不足，需 {a["price"]}', 'error')
            else:
                run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?", (a['price'], char['id']))
                ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (char['id'], a['item_id']), one=True)
                if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?", (char['id'], a['item_id']))
                else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)", (char['id'], a['item_id']))
                log(char['id'], 'market', f'于拍卖行以 {a["price"]} 灵石拍下【{a["name"]}】。')
                flash(f'成功拍下【{a["name"]}】！前往背包装备。', 'success')
                char = me()

    lots = q("""SELECT au.id as auction_id, au.price, i.*
        FROM auctions au JOIN items i ON i.id=au.item_id
        WHERE au.is_active=1 ORDER BY au.price""")
    return render_template('auction.html', char=char, lots=lots, my_elems=my_elems)

# ── 上等灵石拍卖行（造化灵液，每日竞拍）──────────────────────────────────────────

@app.route('/game/superior_auction', methods=['GET', 'POST'])
@login_required
def superior_auction():
    char = me()
    today = time.strftime('%Y-%m-%d', time.localtime())

    # 兜底：若后台线程尚未补齐今日拍卖位（如刚重启、线程未及时触发），此处直接补上
    existing_slots = {r['slot'] for r in q("SELECT slot FROM superior_auctions WHERE day=?", (today,))}
    for slot in range(1, superior_auction_slots() + 1):
        if slot not in existing_slots:
            run("""INSERT OR IGNORE INTO superior_auctions
                (day,slot,item_name,start_price,settled,created_at) VALUES (?,?,?,?,0,?)""",
                (today, slot, SUPERIOR_AUCTION_ITEM, SUPERIOR_AUCTION_START, now_ts()))

    if request.method == 'POST' and request.form.get('action') == 'buy_direct':
        try:
            buy_qty = max(1, int(request.form.get('qty', 1)))
        except ValueError:
            buy_qty = 1
        cost = buy_qty * SUPERIOR_LIQUID_DIRECT_PRICE
        if (char['superior_stones'] or 0) < cost:
            flash(f'上等灵石不足，购买 {buy_qty} 份造化灵液需 {cost}（当前持有 {char["superior_stones"] or 0}）', 'error')
        else:
            liquid = q("SELECT id FROM items WHERE name=?", (SUPERIOR_AUCTION_ITEM,), one=True)
            if not liquid:
                flash('造化灵液尚未初始化，请联系管理员', 'error')
            else:
                run("UPDATE characters SET superior_stones=superior_stones-? WHERE id=?", (cost, char['id']))
                ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (char['id'], liquid['id']), one=True)
                if ex: run("UPDATE inventory SET quantity=quantity+? WHERE char_id=? AND item_id=?",
                           (buy_qty, char['id'], liquid['id']))
                else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,?)",
                           (char['id'], liquid['id'], buy_qty))
                log(char['id'], 'market', f'直接购买【{SUPERIOR_AUCTION_ITEM}】×{buy_qty}，花费 {cost} 上等灵石。')
                flash(f'购买成功！获得【{SUPERIOR_AUCTION_ITEM}】×{buy_qty}，花费 {cost} 上等灵石。', 'success')
                char = me()

    if request.method == 'POST' and request.form.get('action') == 'bid':
        try:
            aid = int(request.form.get('auction_id', 0))
            amount = int(request.form.get('amount', 0))
        except ValueError:
            aid, amount = 0, 0
        a = q("SELECT * FROM superior_auctions WHERE id=? AND day=? AND settled=0", (aid, today), one=True)
        if not a:
            flash('该拍品不存在或已结算', 'error')
        else:
            min_bid = superior_auction_min_bid(aid, a['start_price'])
            if amount < min_bid:
                flash(f'出价过低，至少需 {min_bid} 上等灵石', 'error')
            else:
                existing = q("SELECT amount FROM superior_auction_bids WHERE auction_id=? AND char_id=?",
                             (aid, char['id']), one=True)
                old_amount = existing['amount'] if existing else 0
                delta = amount - old_amount
                if (char['superior_stones'] or 0) < delta:
                    flash(f'上等灵石不足，需追加 {delta}（当前持有 {char["superior_stones"] or 0}）', 'error')
                else:
                    run("UPDATE characters SET superior_stones=superior_stones-? WHERE id=?", (delta, char['id']))
                    run("""INSERT INTO superior_auction_bids (auction_id,char_id,amount,bid_at) VALUES (?,?,?,?)
                           ON CONFLICT(auction_id,char_id) DO UPDATE SET amount=excluded.amount, bid_at=excluded.bid_at""",
                        (aid, char['id'], amount, now_ts()))
                    log(char['id'], 'market', f'于拍卖行【{a["item_name"]}】出价 {amount} 上等灵石。')
                    flash(f'出价成功！当前出价 {amount} 上等灵石。', 'success')
                    char = me()

    auctions = q("SELECT * FROM superior_auctions WHERE day=? ORDER BY slot", (today,))
    lots = []
    for a in auctions:
        bids = superior_auction_bids(a['id'])
        my_bid = next((b['amount'] for b in bids if b['char_id'] == char['id']), 0)
        lots.append({
            'auction': a,
            'top3': bids[:3],
            'min_bid': superior_auction_min_bid(a['id'], a['start_price']),
            'my_bid': my_bid,
        })

    now_lt = time.localtime()
    settle_ts = time.mktime((now_lt.tm_year, now_lt.tm_mon, now_lt.tm_mday,
                              SUPERIOR_AUCTION_SETTLE_HOUR, SUPERIOR_AUCTION_SETTLE_MINUTE, 0, 0, 0, -1))
    if (now_lt.tm_hour, now_lt.tm_min) >= (SUPERIOR_AUCTION_SETTLE_HOUR, SUPERIOR_AUCTION_SETTLE_MINUTE):
        settle_ts += 86400

    return render_template('superior_auction.html', char=char, lots=lots,
        SUPERIOR_AUCTION_SETTLE_HOUR=SUPERIOR_AUCTION_SETTLE_HOUR,
        settle_ts=int(settle_ts), now_ts=now_ts(),
        SUPERIOR_AUCTION_SLOTS_CUR=len(auctions),
        SUPERIOR_LIQUID_DIRECT_PRICE=SUPERIOR_LIQUID_DIRECT_PRICE,
        SUPERIOR_AUCTION_ITEM=SUPERIOR_AUCTION_ITEM)

# ── 道友（玩家交互） ───────────────────────────────────────────────────────────

def _rel_view(me_char, other_id):
    """组装一对关系的展示数据。"""
    other = q("SELECT * FROM characters WHERE id=?", (other_id,), one=True)
    if not other:
        return None
    rel    = get_relationship(me_char['id'], other_id)
    factor, desc, is_ke = wuxing_factor(char_elements(me_char), char_elements(other))
    cd_left = max(0, (rel['last_shuangxiu'] + SHUANGXIU_COOLDOWN) - now_ts())
    return {
        'other': other,
        'affinity': rel['affinity'],
        'level': affinity_label(rel['affinity']),
        'is_partner': rel['is_partner'],
        'is_daolv': bool(rel['is_daolv']),
        'is_npc': bool(other['is_npc']),
        'can_propose': rel['affinity'] >= DAOLV_AFFINITY,
        'wx_factor': factor, 'wx_desc': desc, 'wx_ke': is_ke,
        'cd_left': cd_left,
        'other_realm': REALMS[other['realm_idx']]['name'],
        'other_elems': char_elements(other),
    }

@app.route('/game/gift_craft', methods=['GET','POST'])
@login_required
def gift_craft():
    char   = me()
    result = None

    if request.method == 'POST':
        recipe_name = request.form.get('recipe_name','')
        recipe = next((r for r in GIFT_RECIPES if r[0] == recipe_name), None)
        if not recipe:
            flash('配方不存在', 'error')
        else:
            _, gift_name, ings_raw, affinity, rarity = recipe
            # 检查材料
            miss = []
            for mat_name, qty in ings_raw:
                mat = q("SELECT id FROM items WHERE name=? AND type='treasure'", (mat_name,), one=True)
                if not mat:
                    miss.append(mat_name)
                    continue
                inv = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                        (char['id'], mat['id']), one=True)
                have = inv['quantity'] if inv else 0
                if have < qty:
                    miss.append(f'{mat_name}（缺{qty-have}）')
            if miss:
                flash('材料不足：' + '、'.join(miss), 'error')
            else:
                # 扣材料
                for mat_name, qty in ings_raw:
                    mat = q("SELECT id FROM items WHERE name=?", (mat_name,), one=True)
                    inv = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                            (char['id'], mat['id']), one=True)
                    if inv['quantity'] <= qty:
                        run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], mat['id']))
                    else:
                        run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?",
                            (qty, char['id'], mat['id']))
                # 产出礼物
                gift_item = q("SELECT * FROM items WHERE name=? AND type='gift'", (gift_name,), one=True)
                if gift_item:
                    ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?",
                           (char['id'], gift_item['id']), one=True)
                    if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?",
                               (char['id'], gift_item['id']))
                    else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)",
                               (char['id'], gift_item['id']))
                    log(char['id'], 'system', f'亲手制作了礼物【{gift_name}】（好感 +{affinity}）。')
                    flash(f'制作成功！【{gift_name}】已放入背包，赠予道友可获好感 +{affinity}。', 'success')
                    result = {'gift_name': gift_name, 'affinity': affinity}
                else:
                    flash('礼物物品数据异常', 'error')
                char = me()

    # 整理材料库存
    treasure_inv = {r['name']: r['quantity']
        for r in q("""SELECT i.name, inv.quantity FROM items i
            JOIN inventory inv ON inv.item_id=i.id
            WHERE inv.char_id=? AND i.type='treasure'""", (char['id'],))}

    # 每个配方的材料详情
    recipe_details = []
    for recipe in GIFT_RECIPES:
        rname, gift_name, ings_raw, affinity, rarity = recipe
        ings = []
        for mat_name, qty in ings_raw:
            have = treasure_inv.get(mat_name, 0)
            ings.append({'name': mat_name, 'qty': qty, 'have': have, 'enough': have >= qty})
        can = all(i['enough'] for i in ings)
        recipe_details.append({'name': rname, 'gift_name': gift_name,
                                'ings': ings, 'affinity': affinity,
                                'rarity': rarity, 'can': can})

    return render_template('gift_craft.html', char=char, result=result,
        recipe_details=recipe_details, treasure_inv=treasure_inv,
        TREASURE_POOLS=TREASURE_POOLS)

# ── 论道坛 ─────────────────────────────────────────────────────────────────────

FORUM_POST_CD   = 5 * 60   # 发帖冷却 5 分钟
FORUM_REPLY_CD  = 60        # 回复冷却 1 分钟
FORUM_TITLE_MAX = 40
FORUM_CONTENT_MAX = 600
FORUM_REPLY_MAX   = 300
FORUM_PAGE_SIZE   = 20

# ── 拼手气红包 ─────────────────────────────────────────────────────────────────
RED_PACKET_MIN_STONES  = 100        # 最少发 100 灵石
RED_PACKET_MAX_STONES  = 1_000_000  # 最多发 100 万灵石
RED_PACKET_EXPIRE_SECS = 86400      # 一天后未领完自动退回

def _split_red_packet(total, count):
    """拼手气红包经典算法：随机拆成 count 份，每份至少1，总和等于 total，再打乱顺序。"""
    shares = []
    remaining_total = total
    remaining_count = count
    for _ in range(count - 1):
        avg = remaining_total / remaining_count
        amt = random.randint(1, max(1, int(avg * 2)))
        amt = min(amt, remaining_total - (remaining_count - 1))
        shares.append(amt)
        remaining_total -= amt
        remaining_count -= 1
    shares.append(remaining_total)
    random.shuffle(shares)
    return shares

def get_active_red_packets(char_id):
    """返回论道坛当前可见的红包列表（未过期），附带我是否已抢过、抢到多少。"""
    now = now_ts()
    rows = q("""SELECT rp.*, c.name as sender_name FROM red_packets rp
        JOIN characters c ON c.id=rp.sender_id
        WHERE rp.status='active' AND rp.expires_at>?
        ORDER BY rp.created_at DESC""", (now,))
    my_claims = {r['packet_id']: r['amount'] for r in q(
        "SELECT packet_id, amount FROM red_packet_claims WHERE char_id=?", (char_id,))}
    packets = []
    for r in rows:
        d = dict(r)
        d['my_amount'] = my_claims.get(r['id'])
        d['full'] = d['claimed_count'] >= d['share_count']
        packets.append(d)
    return packets

def has_unclaimed_red_packet(char_id):
    """用于导航栏红点：是否存在我还没抢过、且还有余量的红包。"""
    now = now_ts()
    rows = q("""SELECT rp.id FROM red_packets rp
        WHERE rp.status='active' AND rp.expires_at>? AND rp.claimed_count<rp.share_count
        AND rp.id NOT IN (SELECT packet_id FROM red_packet_claims WHERE char_id=?)""",
        (now, char_id))
    return len(rows) > 0

@app.route('/game/red_packet/send', methods=['POST'])
@login_required
def red_packet_send():
    char = me()
    try:
        total = int(request.form.get('total', 0))
        count = int(request.form.get('count', 0))
    except ValueError:
        total, count = 0, 0
    message = request.form.get('message', '').strip()[:40]
    alive_cnt = q("SELECT COUNT(*) n FROM characters WHERE status='alive' AND is_npc=0", one=True)['n']

    if total < RED_PACKET_MIN_STONES:
        flash(f'红包总额至少 {RED_PACKET_MIN_STONES} 灵石', 'error')
    elif total > RED_PACKET_MAX_STONES:
        flash(f'红包总额最多 {RED_PACKET_MAX_STONES} 灵石', 'error')
    elif count < 1:
        flash('红包个数至少为 1', 'error')
    elif count > alive_cnt:
        flash(f'红包个数不能超过存活玩家人数（{alive_cnt}）', 'error')
    elif count > total:
        flash('红包个数不能超过总灵石数（每份至少 1 灵石）', 'error')
    elif char['spirit_stones'] < total:
        flash(f'灵石不足，需要 {total}', 'error')
    else:
        run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?", (total, char['id']))
        shares = _split_red_packet(total, count)
        now = now_ts()
        run("""INSERT INTO red_packets
               (sender_id,total_stones,share_count,shares_json,claimed_count,message,status,created_at,expires_at)
               VALUES (?,?,?,?,0,?,'active',?,?)""",
            (char['id'], total, count, json.dumps(shares), message, now, now + RED_PACKET_EXPIRE_SECS))
        log(char['id'], 'system', f'在论道坛发出一个 {total} 灵石的拼手气红包，共 {count} 个。')
        flash('红包发送成功！', 'success')
    return redirect(url_for('forum'))

@app.route('/game/red_packet/claim/<int:pid>', methods=['POST'])
@login_required
def red_packet_claim(pid):
    char = me()
    packet = q("SELECT * FROM red_packets WHERE id=?", (pid,), one=True)
    if not packet or packet['status'] != 'active' or packet['expires_at'] <= now_ts():
        flash('红包不存在或已失效', 'error')
        return redirect(url_for('forum'))
    already = q("SELECT 1 FROM red_packet_claims WHERE packet_id=? AND char_id=?",
                (pid, char['id']), one=True)
    if already:
        flash('你已经抢过这个红包了', 'error')
        return redirect(url_for('forum'))

    cur = run("""UPDATE red_packets SET claimed_count=claimed_count+1
                 WHERE id=? AND status='active' AND claimed_count<share_count""", (pid,))
    if cur.rowcount == 0:
        flash('手慢了，红包已被抢完', 'error')
        return redirect(url_for('forum'))

    packet = q("SELECT * FROM red_packets WHERE id=?", (pid,), one=True)
    shares = json.loads(packet['shares_json'])
    amount = shares[packet['claimed_count'] - 1]
    try:
        run("INSERT INTO red_packet_claims (packet_id,char_id,amount,claimed_at) VALUES (?,?,?,?)",
            (pid, char['id'], amount, now_ts()))
    except Exception:
        run("UPDATE red_packets SET claimed_count=claimed_count-1 WHERE id=?", (pid,))
        flash('你已经抢过这个红包了', 'error')
        return redirect(url_for('forum'))
    run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?", (amount, char['id']))
    sender = q("SELECT name FROM characters WHERE id=?", (packet['sender_id'],), one=True)
    sender_name = sender['name'] if sender else '神秘人'
    log(char['id'], 'system', f'抢到【{sender_name}】的红包，获得 {amount} 灵石！')
    flash(f'手气不错！抢到 {amount} 灵石！', 'success')
    return redirect(url_for('forum'))

@app.route('/game/forum', methods=['GET', 'POST'])
@login_required
def forum():
    char = me()
    if request.method == 'POST':
        title   = request.form.get('title', '').strip()
        content = request.form.get('content', '').strip()
        if not title or not content:
            flash('标题和内容不能为空', 'error')
        elif len(title) > FORUM_TITLE_MAX:
            flash(f'标题最多 {FORUM_TITLE_MAX} 字', 'error')
        elif len(content) > FORUM_CONTENT_MAX:
            flash(f'内容最多 {FORUM_CONTENT_MAX} 字', 'error')
        else:
            last = q("SELECT created_at FROM forum_posts WHERE char_id=? AND is_deleted=0 ORDER BY created_at DESC LIMIT 1",
                     (char['id'],), one=True)
            if last and now_ts() - last['created_at'] < FORUM_POST_CD:
                wait = FORUM_POST_CD - (now_ts() - last['created_at'])
                flash(f'发帖冷却中，还需等待 {wait//60} 分 {wait%60} 秒', 'error')
            else:
                run("INSERT INTO forum_posts (char_id, title, content, created_at) VALUES (?,?,?,?)",
                    (char['id'], title, content, now_ts()))
                flash('帖子已发布', 'success')
        return redirect(url_for('forum'))

    page = max(1, int(request.args.get('page', 1)))
    offset = (page - 1) * FORUM_PAGE_SIZE
    total = q("SELECT COUNT(*) n FROM forum_posts WHERE is_deleted=0", one=True)['n']
    posts = q("""
        SELECT p.*, c.name as author_name, c.realm_idx as author_realm, c.spirit_root as author_root,
               (SELECT COUNT(*) FROM forum_likes WHERE target_type='post' AND target_id=p.id) as like_count
        FROM forum_posts p JOIN characters c ON c.id=p.char_id
        WHERE p.is_deleted=0
        ORDER BY p.is_pinned DESC, p.created_at DESC
        LIMIT ? OFFSET ?
    """, (FORUM_PAGE_SIZE, offset))
    total_pages = max(1, (total + FORUM_PAGE_SIZE - 1) // FORUM_PAGE_SIZE)
    my_liked_posts = {r['target_id'] for r in q(
        "SELECT target_id FROM forum_likes WHERE char_id=? AND target_type='post'", (char['id'],))}
    alive_cnt = q("SELECT COUNT(*) n FROM characters WHERE status='alive' AND is_npc=0", one=True)['n']
    return render_template('forum.html', char=char, posts=posts,
                           page=page, total_pages=total_pages, total=total,
                           my_liked_posts=my_liked_posts,
                           red_packets=get_active_red_packets(char['id']), alive_cnt=alive_cnt,
                           RED_PACKET_MIN_STONES=RED_PACKET_MIN_STONES,
                           RED_PACKET_MAX_STONES=RED_PACKET_MAX_STONES)

@app.route('/game/forum/<int:pid>', methods=['GET', 'POST'])
@login_required
def forum_post(pid):
    char = me()
    post = q("""SELECT p.*, c.name as author_name, c.realm_idx as author_realm, c.spirit_root as author_root
                FROM forum_posts p JOIN characters c ON c.id=p.char_id
                WHERE p.id=? AND p.is_deleted=0""", (pid,), one=True)
    if not post:
        flash('帖子不存在或已删除', 'error')
        return redirect(url_for('forum'))

    if request.method == 'POST':
        act = request.form.get('action', '')

        if act == 'reply':
            content = request.form.get('content', '').strip()
            if not content:
                flash('回复不能为空', 'error')
            elif len(content) > FORUM_REPLY_MAX:
                flash(f'回复最多 {FORUM_REPLY_MAX} 字', 'error')
            else:
                last = q("SELECT created_at FROM forum_replies WHERE char_id=? ORDER BY created_at DESC LIMIT 1",
                         (char['id'],), one=True)
                if last and now_ts() - last['created_at'] < FORUM_REPLY_CD:
                    flash('回复太频繁，请稍后再试', 'error')
                else:
                    run("INSERT INTO forum_replies (post_id, char_id, content, created_at) VALUES (?,?,?,?)",
                        (pid, char['id'], content, now_ts()))
                    run("UPDATE forum_posts SET reply_count=reply_count+1 WHERE id=?", (pid,))
                    flash('回复成功', 'success')

        elif act == 'delete_post' and (char['id'] == post['char_id'] or S.get('role') == 'admin'):
            run("UPDATE forum_posts SET is_deleted=1 WHERE id=?", (pid,))
            flash('帖子已删除', 'success')
            return redirect(url_for('forum'))

        elif act == 'delete_reply' and S.get('role') == 'admin':
            rid = int(request.form.get('reply_id', 0))
            run("UPDATE forum_replies SET is_deleted=1 WHERE id=?", (rid,))
            run("UPDATE forum_posts SET reply_count=MAX(0,reply_count-1) WHERE id=?", (pid,))
            flash('回复已删除', 'success')

        elif act == 'pin' and S.get('role') == 'admin':
            new_pin = 0 if post['is_pinned'] else 1
            run("UPDATE forum_posts SET is_pinned=? WHERE id=?", (new_pin, pid))
            flash('置顶状态已切换', 'success')

        return redirect(url_for('forum_post', pid=pid))

    replies = q("""SELECT r.*, c.name as author_name, c.realm_idx as author_realm, c.spirit_root as author_root,
                          (SELECT COUNT(*) FROM forum_likes WHERE target_type='reply' AND target_id=r.id) as like_count
                   FROM forum_replies r JOIN characters c ON c.id=r.char_id
                   WHERE r.post_id=? AND r.is_deleted=0
                   ORDER BY r.created_at ASC""", (pid,))
    post_likes = q("SELECT COUNT(*) n FROM forum_likes WHERE target_type='post' AND target_id=?",
                   (pid,), one=True)['n']
    my_liked_replies = {r['target_id'] for r in q(
        "SELECT target_id FROM forum_likes WHERE char_id=? AND target_type='reply'", (char['id'],))}
    i_liked_post = bool(q("SELECT 1 FROM forum_likes WHERE char_id=? AND target_type='post' AND target_id=?",
                          (char['id'], pid), one=True))
    is_admin = S.get('role') == 'admin'
    return render_template('forum_post.html', char=char, post=post, replies=replies,
                           post_likes=post_likes, my_liked_replies=my_liked_replies,
                           i_liked_post=i_liked_post, is_admin=is_admin)

@app.route('/game/forum/like', methods=['POST'])
@login_required
def forum_like():
    char        = me()
    target_type = request.form.get('target_type', '')
    target_id   = int(request.form.get('target_id', 0))
    back        = request.form.get('back', url_for('forum'))
    if target_type not in ('post', 'reply') or not target_id:
        return redirect(back)
    existing = q("SELECT id FROM forum_likes WHERE char_id=? AND target_type=? AND target_id=?",
                 (char['id'], target_type, target_id), one=True)
    if existing:
        run("DELETE FROM forum_likes WHERE id=?", (existing['id'],))
    else:
        run("INSERT INTO forum_likes (char_id, target_type, target_id, created_at) VALUES (?,?,?,?)",
            (char['id'], target_type, target_id, now_ts()))
    return redirect(back)

# ── 合欢修专页 ────────────────────────────────────────────────────────────────────

@app.route('/game/heqing', methods=['GET','POST'])
@login_required
def heqing():
    char = me()
    if not char.get('heqing_token_id'):
        flash('此处仅供合欢修进入，需先在丹市购买合欢令。', 'error')
        return redirect(url_for('market'))

    energy = cur_energy(char)
    result = None

    YINGLUO_MATS = [("血玉",1),("东珠",1),("玄银",1),("红宝石",1),("蓝宝石",1)]

    if request.method == 'POST' and request.form.get('action') == 'craft_yingluo':
        hq_lv_check, _, _, _, _ = heqing_level_info(char)
        if hq_lv_check < 4:
            flash('需合欢修【天人双修】（4级）方可炼制七彩璎珞', 'error')
        else:
            miss = []
            for mat_name, qty in YINGLUO_MATS:
                mat = q("SELECT id FROM items WHERE name=?", (mat_name,), one=True)
                inv = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                        (char['id'], mat['id'] if mat else -1), one=True) if mat else None
                have = inv['quantity'] if inv else 0
                if have < qty:
                    miss.append(f'{mat_name}（缺{qty-have}）')
            if miss:
                flash('材料不足：' + '、'.join(miss), 'error')
            else:
                for mat_name, qty in YINGLUO_MATS:
                    mat = q("SELECT id FROM items WHERE name=?", (mat_name,), one=True)
                    inv = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                            (char['id'], mat['id']), one=True)
                    if inv['quantity'] <= qty:
                        run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], mat['id']))
                    else:
                        run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?",
                            (qty, char['id'], mat['id']))
                yl = q("SELECT id FROM items WHERE name='七彩璎珞'", one=True)
                if yl:
                    ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (char['id'], yl['id']), one=True)
                    if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?", (char['id'], yl['id']))
                    else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)", (char['id'], yl['id']))
                log(char['id'], 'system', '以珍稀宝材炼制【七彩璎珞】×1。')
                flash('成功炼制【七彩璎珞】！已放入背包，可赠予道友或自用于子嗣强化。', 'success')
                char = me()

    if request.method == 'POST' and request.form.get('action') == 'meditate':
        if energy < HEQING_MEDITATION_COST:
            flash(f'灵力不足（需 {HEQING_MEDITATION_COST}，当前 {energy}）', 'error')
        else:
            set_energy(char['id'], energy - HEQING_MEDITATION_COST)
            new_exp = (char.get('heqing_exp') or 0) + HEQING_MEDITATION_EXP
            new_lv  = 0
            for i, lvl in enumerate(HEQING_LEVELS):
                if new_exp >= lvl['exp']: new_lv = i
            leveled_up = new_lv > (char.get('heqing_level') or 0)
            run("UPDATE characters SET heqing_exp=?, heqing_level=? WHERE id=?",
                (new_exp, new_lv, char['id']))
            log(char['id'], 'cultivate', f'情缘冥思，合欢经验 +{HEQING_MEDITATION_EXP}。')
            result = {'exp': HEQING_MEDITATION_EXP, 'leveled_up': leveled_up,
                      'new_lv_name': HEQING_LEVELS[new_lv]['name'] if leveled_up else ''}
            flash(f'情缘冥思，合欢经验 +{HEQING_MEDITATION_EXP}{"，境界精进：" + HEQING_LEVELS[new_lv]["name"] if leveled_up else ""}', 'success')
            char = me()

    hq_lv, hq_lv_name, next_exp, hq_exp_val, hq_pct = heqing_level_info(char)
    daolv_list = get_daolv(char)
    daolv_list = [daolv_list] if daolv_list else []
    # 道侣名单（最多3位）
    all_daolv = q("""SELECT c.id, c.name, c.realm_idx, c.spirit_root
        FROM relationships r
        JOIN characters c ON c.id = CASE WHEN r.char_a=? THEN r.char_b ELSE r.char_a END
        WHERE (r.char_a=? OR r.char_b=?) AND r.is_daolv=1""",
        (char['id'], char['id'], char['id']))

    treasure_inv = {r['name']: r['quantity']
        for r in q("""SELECT i.name, inv.quantity FROM items i
            JOIN inventory inv ON inv.item_id=i.id
            WHERE inv.char_id=? AND i.type IN ('treasure','ore')""", (char['id'],))}
    return render_template('heqing.html',
        char=char, energy=energy, MAX_ENERGY=energy_cap(char),
        hq_lv=hq_lv, hq_lv_name=hq_lv_name,
        hq_exp=hq_exp_val, next_exp=next_exp, hq_pct=hq_pct,
        result=result, HEQING_LEVELS=HEQING_LEVELS,
        HEQING_MEDITATION_COST=HEQING_MEDITATION_COST,
        all_daolv=all_daolv, REALMS=REALMS,
        YINGLUO_MATS=YINGLUO_MATS, treasure_inv=treasure_inv)

@app.route('/game/social')
@login_required
def social():
    char = me()

    # 已有关系列表
    rels = q("""SELECT * FROM relationships
        WHERE (char_a=? OR char_b=?) ORDER BY affinity DESC""", (char['id'], char['id']))
    rel_views = []
    for r in rels:
        other_id = r['char_b'] if r['char_a'] == char['id'] else r['char_a']
        rv = _rel_view(char, other_id)
        if rv: rel_views.append(rv)

    # 待处理的邀请（双修 + 结亲）
    pending = q("""SELECT i.*, c.name as from_name, c.realm_idx as from_realm, c.spirit_root as from_root
        FROM interactions i JOIN characters c ON c.id=i.from_char
        WHERE i.to_char=? AND i.status='pending' ORDER BY i.created_at DESC""", (char['id'],))

    # 我发出的待回应邀请
    sent = q("""SELECT i.*, c.name as to_name FROM interactions i
        JOIN characters c ON c.id=i.to_char
        WHERE i.from_char=? AND i.status='pending'""", (char['id'],))

    # 搜索（不含 NPC，NPC 单列）
    kw = request.args.get('q', '').strip()
    search_results = []
    if kw:
        rows = q("""SELECT id,name,zi,realm_idx,spirit_root FROM characters
            WHERE name LIKE ? AND id!=? AND is_npc=0 AND status='alive' LIMIT 10""", (f'%{kw}%', char['id']))
        search_results = [dict(r) for r in rows]

    # 我的道侣
    daolv = get_daolv(char)
    daolv_rv = _rel_view(char, daolv['id']) if daolv else None
    daolv_count = sum(1 for f in ['daolv_id','daolv2_id','daolv3_id'] if char.get(f))
    daolv_max   = 3 if char.get('heqing_token_id') else 1

    # 可结缘的 NPC
    npcs = q("SELECT * FROM characters WHERE is_npc=1 ORDER BY realm_idx")
    npc_views = [_rel_view(char, n['id']) for n in npcs]

    energy = cur_energy(char)
    gift_items = q("""SELECT i.id, i.name, inv.quantity FROM items i
        JOIN inventory inv ON inv.item_id=i.id
        WHERE inv.char_id=? ORDER BY i.type, i.name""", (char['id'],))
    # 最近收到的礼物图鉴（最新5条预览）
    recent_gifts = q("""SELECT * FROM gift_log WHERE to_char_id=?
        ORDER BY created_at DESC LIMIT 5""", (char['id'],))
    gift_log_count = q("SELECT COUNT(*) n FROM gift_log WHERE to_char_id=?",
                       (char['id'],), one=True)['n']
    return render_template('social.html', char=char, energy=energy,
        rel_views=rel_views, pending=pending, sent=sent,
        search_results=search_results, kw=kw, gift_items=gift_items,
        daolv=daolv, daolv_rv=daolv_rv, npc_views=npc_views,
        daolv_count=daolv_count, daolv_max=daolv_max,
        DAOLV_AFFINITY=DAOLV_AFFINITY,
        recent_gifts=recent_gifts, gift_log_count=gift_log_count)

GIFT_MAT_CD = 2 * 3600  # 材料赠送冷却 2 小时

@app.route('/game/social/gift', methods=['POST'])
@login_required
def social_gift():
    char     = me()
    other_id = int(request.form.get('target_id', 0))
    iid      = int(request.form.get('item_id', 0))
    other    = q("SELECT * FROM characters WHERE id=?", (other_id,), one=True)
    inv      = q("SELECT * FROM inventory WHERE char_id=? AND item_id=?", (char['id'], iid), one=True)
    item     = q("SELECT * FROM items WHERE id=?", (iid,), one=True)

    cd_key  = f'gift_{other_id}'
    cd_row  = q("SELECT last_ts FROM work_cooldowns WHERE char_id=? AND job_key=?",
                (char['id'], cd_key), one=True)
    cd_left = max(0, (cd_row['last_ts'] + GIFT_MAT_CD) - now_ts()) if cd_row else 0

    if not other or other_id == char['id']:
        flash('对象不存在', 'error')
    elif not inv or not item:
        flash('物品不存在', 'error')
    elif item['type'] in ('cauldron', 'forge', 'brush', 'beast_token', 'heqing_token', 'sword_token', 'spirit_pass'):
        flash('职业令牌及炉具不可赠送。', 'error')
    elif cd_left > 0:
        h, m = divmod(cd_left // 60, 60)
        flash(f'赠予此道友的冷却未结束，还需等待 {h} 小时 {m} 分钟。', 'error')
    else:
        eff = json.loads(item['effect_json'] or '{}')
        is_crafted_gift = item['type'] == 'gift'
        base_gain = eff.get('affinity') or max(1, (item['market_price'] or 50) // 100)
        gain = int(base_gain * (1 + companion_bonus(char, 'affinity_pct'))) if is_crafted_gift else 0
        # 减少发送方库存
        if inv['quantity'] <= 1:
            run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], iid))
        else:
            run("UPDATE inventory SET quantity=quantity-1 WHERE char_id=? AND item_id=?", (char['id'], iid))
        # 礼物直接进接收方图鉴，其他物品正常入背包
        if is_crafted_gift:
            run("INSERT INTO gift_log (to_char_id,from_char_id,from_name,item_id,item_name,affinity,created_at) VALUES (?,?,?,?,?,?,?)",
                (other_id, char['id'], char['name'], iid, item['name'], gain, now_ts()))
            add_affinity(char['id'], other_id, gain)
            log(char['id'], 'social', f'赠予【{other["name"]}】一件【{item["name"]}】，好感 +{gain}。')
            log(other_id, 'social', f'收到【{char["name"]}】赠予的【{item["name"]}】，好感 +{gain}，已入图鉴。')
            flash(f'已赠予【{item["name"]}】，好感 +{gain}', 'success')
        else:
            ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (other_id, iid), one=True)
            if ex:
                run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?", (other_id, iid))
            else:
                run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)", (other_id, iid))
            log(char['id'], 'social', f'赠予【{other["name"]}】一件【{item["name"]}】。')
            log(other_id, 'social', f'收到【{char["name"]}】赠予的【{item["name"]}】，已入背包。')
            flash(f'已赠予【{item["name"]}】', 'success')
        # 更新冷却时间戳
        run("""INSERT INTO work_cooldowns (char_id,job_key,last_ts) VALUES (?,?,?)
               ON CONFLICT(char_id,job_key) DO UPDATE SET last_ts=?""",
            (char['id'], cd_key, now_ts(), now_ts()))
    return redirect(url_for('social'))

