def build_pvp_monster(other):
    """把另一个玩家的数据构造成兼容 simulate() 的 monster 结构。"""
    if not isinstance(other, dict):
        other = dict(other)
    max_hp, base_atk, base_def = realm_stats(other['realm_idx'])
    max_hp  = int(max_hp * (1 + companion_bonus(other, 'hp_pct'))) + bone_hp_bonus(other['id'])
    eq_atk, eq_def = get_equip_bonuses(other)
    atk_rows = q("""SELECT t.power FROM techniques t
        JOIN char_techniques ct ON ct.tech_id=t.id
        WHERE ct.char_id=? AND t.type='attack'""", (other['id'],))
    def_rows = q("""SELECT t.power FROM techniques t
        JOIN char_techniques ct ON ct.tech_id=t.id
        WHERE ct.char_id=? AND t.type='defense'""", (other['id'],))
    tech_atk = sum(r['power'] for r in atk_rows)
    tech_def = sum(r['power'] for r in def_rows)
    dw       = get_destiny_weapon_bonus(other)
    b_atk_pct, b_def_pct = get_body_bonus(other)
    pb       = get_pet_bonus(other)
    sb       = get_spell_bonuses(other['id'])
    smb      = get_move_bonuses(other['id'])
    comp_atk = companion_bonus(other, 'atk_pct') * 100
    comp_def = companion_bonus(other, 'def_pct') * 100
    ys = get_yuanshen_bonus(other)
    total_atk = int((base_atk + tech_atk + eq_atk + dw['base_attack'] + ys['atk'])
                    * (1 + (dw['atk_pct'] + b_atk_pct + pb['atk_pct'] + sb['atk_pct'] * 100 + smb['atk_pct'] * 100 + comp_atk) / 100))
    total_def = int((base_def + tech_def + eq_def + ys['def'])
                    * (1 + (b_def_pct + pb['def_pct'] + sb['def_pct'] * 100 + smb['def_pct'] * 100 + comp_def) / 100))
    return {'hp': max_hp, 'attack': total_atk, 'defense': total_def,
            'name': other['name'], 'drop_json': '[]',
            'exp_reward': 0, 'stone_reward': 0}

@app.route('/game/pvp', methods=['GET','POST'])
@login_required
def pvp():
    char   = me()
    result = None
    other  = None

    if request.method == 'POST':
        target_name = request.form.get('target_name', '').strip()
        other = q("SELECT * FROM characters WHERE name=? AND is_npc=0 AND status='alive'",
                  (target_name,), one=True)
        energy = cur_energy(char)

        if not other:
            flash('未找到该修士，请确认道号', 'error')
        elif other['id'] == char['id']:
            flash('不能与自己切磋', 'error')
        elif energy < PVP_ENERGY_COST:
            flash(f'灵力不足（需 {PVP_ENERGY_COST}）', 'error')
            other = None
        elif abs(major_idx(char['realm_idx']) - major_idx(other['realm_idx'])) > PVP_MAX_MAJOR_DIFF:
            flash(f'境界差距过大（最多相差 {PVP_MAX_MAJOR_DIFF} 个大境界），切磋无意义', 'error')
            other = None
        elif daily_count(char['id'], 'pvp_total') >= PVP_DAILY_TOTAL:
            flash(f'今日切磋次数已达上限（每天最多 {PVP_DAILY_TOTAL} 次）', 'error')
            other = None
        elif daily_count(char['id'], f'pvp_{other["id"]}') >= PVP_DAILY_LIMIT:
            flash(f'今日与【{other["name"]}】切磋次数已达上限（每人最多 {PVP_DAILY_LIMIT} 次）', 'error')
            other = None
        else:
            set_energy(char['id'], energy - PVP_ENERGY_COST)
            daily_inc(char['id'], f'pvp_{other["id"]}')
            daily_inc(char['id'], 'pvp_total')
            inc_quest(char['id'], 'pvp')
            add_affinity(char['id'], other['id'], 2)

            # ── 每周重置检查 ──
            now_dt   = datetime.now(TZ)
            week_key = f"{now_dt.year}-W{now_dt.strftime('%W')}"
            if not q("SELECT 1 FROM pvp_weekly_reset WHERE week_key=?", (week_key,), one=True):
                run("UPDATE characters SET pvp_score=0, pvp_wins=0, pvp_losses=0, pvp_streak=0 WHERE is_npc=0")
                run("INSERT OR REPLACE INTO pvp_weekly_reset (week_key,reset_at) VALUES (?,?)",
                    (week_key, now_ts()))

            equip_atk, equip_def = get_equip_bonuses(char)
            c_elems = char_elements(char)
            o_elems = char_elements(other)
            dummy   = build_pvp_monster(other)
            won, rounds, final_hp, p_wx_desc, m_wx_desc = simulate(
                char, dummy, equip_atk=equip_atk, equip_def=equip_def,
                char_elems=c_elems, monster_elems=o_elems)

            # ── 30% 运气翻转（天命难测）──
            luck_flip = random.random() < 0.30
            if luck_flip:
                won = not won

            # ── 切磋奖励 ──
            other_realm = other['realm_idx']
            realm_bonus = major_idx(other_realm) > major_idx(char['realm_idx'])  # 以弱胜强
            stones_mult = 1 + companion_bonus(char, 'stones_pct')
            if won:
                base   = 100 + other_realm * 10
                stones = base + random.randint(-20, 60)
                if realm_bonus:
                    stones = int(stones * 2.0)
                stones = int(stones * stones_mult)
                exp_gain = 30 + other_realm * 2
            else:
                stones   = int(random.randint(20, 60) * stones_mult)
                exp_gain = 10 + other_realm
            run("UPDATE characters SET spirit_stones=spirit_stones+?, exp=exp+? WHERE id=?",
                (stones, exp_gain, char['id']))
            # 小概率掉落珍宝（胜者15%，败者5%）
            drop_item = None
            drop_chance = 0.15 if won else 0.05
            if random.random() < drop_chance:
                pool = q("""SELECT id, name FROM items
                    WHERE type='treasure' AND rarity='common' AND is_active=1
                    ORDER BY RANDOM() LIMIT 1""", one=True)
                if pool:
                    ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?",
                           (char['id'], pool['id']), one=True)
                    if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?",
                               (char['id'], pool['id']))
                    else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)",
                               (char['id'], pool['id']))
                    drop_item = pool['name']

            # ── 积分更新 ──
            if won:
                # 剑修PvP经验
                if char.get('sword_token_id'):
                    run("UPDATE characters SET sword_exp=sword_exp+? WHERE id=?",
                        (SWORD_PVP_EXP, char['id']))
                score_delta = 20 if realm_bonus else 10
                run("""UPDATE characters SET
                    pvp_score=MAX(0,pvp_score+?), pvp_wins=pvp_wins+1,
                    pvp_streak=pvp_streak+1 WHERE id=?""", (score_delta, char['id']))
                run("UPDATE characters SET pvp_losses=pvp_losses+1, pvp_streak=0 WHERE id=?",
                    (other['id'],))
            else:
                run("""UPDATE characters SET
                    pvp_score=MAX(0,pvp_score-2), pvp_losses=pvp_losses+1,
                    pvp_streak=0 WHERE id=?""", (char['id'],))
                run("UPDATE characters SET pvp_wins=pvp_wins+1, pvp_streak=pvp_streak+1 WHERE id=?",
                    (other['id'],))
            char_pvp = q("SELECT pvp_score,pvp_wins,pvp_losses,pvp_streak FROM characters WHERE id=?",
                         (char['id'],), one=True)

            verdict   = '获胜' if won else '落败'
            drop_note = f'，获得【{drop_item}】' if drop_item else ''
            luck_note = '（天命翻转）' if luck_flip else ''
            msg = f'与【{other["name"]}】切磋，{verdict}{luck_note}！积分 {"+" if won else "-"}{"20" if (won and realm_bonus) else "10" if won else "2"}，灵石 +{stones}，修为 +{exp_gain}{drop_note}。'
            log(char['id'],  'social', msg)
            log(other['id'], 'social', f'【{char["name"]}】向你发起切磋，{"你落败了" if won else "你赢了"}{luck_note}。')
            pvp_spell = q("SELECT custom_name,element FROM char_spells WHERE char_id=? AND learned=1 ORDER BY RANDOM() LIMIT 1", (char['id'],), one=True)
            pvp_move  = q("SELECT custom_name,move_num FROM char_spell_moves WHERE char_id=? ORDER BY RANDOM() LIMIT 1", (char['id'],), one=True)
            result = {'won': won, 'rounds': rounds, 'other': dict(other),
                      'char_max_hp': realm_stats(char['realm_idx'])[0],
                      'other_max_hp': dummy['hp'],
                      'stones': stones, 'exp_gain': exp_gain,
                      'drop_item': drop_item, 'realm_bonus': realm_bonus,
                      'luck_flip': luck_flip,
                      'score_delta': (20 if realm_bonus else 10) if won else -2,
                      'pvp': dict(char_pvp),
                      'p_wx_desc': p_wx_desc, 'm_wx_desc': m_wx_desc,
                      'char_elems': c_elems, 'other_elems': o_elems,
                      'spell_label': (pvp_spell['custom_name'] or SPELL_ELEMENT_NAMES.get(pvp_spell['element'], '法术')) if pvp_spell else None,
                      'move_label': ((pvp_move['custom_name'] or f'第{pvp_move["move_num"]}式') if pvp_move else None)}

    # 可切磋的道友列表（同境界附近）
    candidates = q("""SELECT c.id, c.name, c.spirit_root, c.realm_idx,
            c.pvp_score, c.pvp_wins, c.pvp_losses
        FROM characters c WHERE c.is_npc=0 AND c.status='alive' AND c.id != ?
        ORDER BY ABS(c.realm_idx - ?) LIMIT 20""", (char['id'], char['realm_idx']))
    # 本周积分榜（Top 10）
    pvp_rank = q("""SELECT c.name, c.realm_idx, c.pvp_score, c.pvp_wins, c.pvp_losses, c.pvp_streak
        FROM characters c WHERE c.is_npc=0 AND c.status='alive' AND c.pvp_score > 0
        ORDER BY c.pvp_score DESC LIMIT 10""")
    my_pvp = q("SELECT pvp_score,pvp_wins,pvp_losses,pvp_streak FROM characters WHERE id=?",
               (char['id'],), one=True)
    energy = cur_energy(char)
    return render_template('pvp.html', char=char, result=result, other=other,
        candidates=candidates, energy=energy, pvp_rank=pvp_rank, my_pvp=my_pvp,
        PVP_ENERGY_COST=PVP_ENERGY_COST, PVP_MAX_MAJOR_DIFF=PVP_MAX_MAJOR_DIFF,
        PVP_DAILY_LIMIT=PVP_DAILY_LIMIT, PVP_DAILY_TOTAL=PVP_DAILY_TOTAL,
        pvp_today=daily_count(char['id'], 'pvp_total'))

@app.route('/game/social/spar', methods=['POST'])
@login_required
def social_spar():
    char     = me()
    other_id = int(request.form.get('target_id', 0))
    other    = q("SELECT * FROM characters WHERE id=?", (other_id,), one=True)
    energy   = cur_energy(char)

    if not other or other_id == char['id']:
        flash('对象不存在', 'error')
    elif energy < 5:
        flash('灵力不足（需 5）', 'error')
    elif daily_count(char['id'], f'spar_{other_id}') >= 3:
        flash('今日与此道友切磋次数已达上限（3 次）', 'error')
    else:
        set_energy(char['id'], energy - 5)
        add_affinity(char['id'], other_id, 2)
        daily_inc(char['id'], f'spar_{other_id}')
        _, my_atk, my_def = realm_stats(char['realm_idx'])
        ea = get_equip_bonuses(char)
        my_power = (my_atk + ea[0]) + (my_def + ea[1])
        oe = get_equip_bonuses(other)
        _, ot_atk, ot_def = realm_stats(other['realm_idx'])
        ot_power = (ot_atk + oe[0]) + (ot_def + oe[1])
        if my_power > ot_power * 1.1:   verdict = '你略胜一筹，点到为止。'
        elif ot_power > my_power * 1.1: verdict = f'{other["name"]} 技高一筹，你心悦诚服。'
        else:                            verdict = '势均力敌，惺惺相惜。'
        log(char['id'], 'social', f'与【{other["name"]}】友好切磋，{verdict}好感 +2。')
        flash(f'切磋完毕——{verdict}好感 +2', 'success')
    return redirect(url_for('social'))

def do_shuangxiu(char, other):
    """执行一次双修，返回 (category, message)。preconditions 内部检查。"""
    if not isinstance(other, dict): other = dict(other)
    rel = get_relationship(char['id'], other['id'])
    is_heqing = bool(char.get('heqing_token_id')) or bool(other.get('heqing_token_id'))
    if char.get('heqing_token_id'):
        _hqlv_cd, _, _, _, _ = heqing_level_info(char)
        if _hqlv_cd >= 3: effective_cd = int(1.5 * 3600)
        else:             effective_cd = HEQING_SHUANGXIU_COOLDOWN
    elif is_heqing:
        effective_cd = HEQING_SHUANGXIU_COOLDOWN
    else:
        effective_cd = SHUANGXIU_COOLDOWN
    effective_cost = HEQING_SHUANGXIU_COST     if is_heqing else SHUANGXIU_COST
    cd_left = (rel['last_shuangxiu'] + effective_cd) - now_ts()
    if cd_left > 0:
        return ('error', f'双修冷却中，还需 {cd_left//3600} 时 {(cd_left%3600)//60} 分')
    my_energy = cur_energy(char)
    if my_energy < effective_cost:
        return ('error', f'你的灵力不足（需 {effective_cost}）')
    is_npc = bool(other['is_npc'])
    ot_energy = cur_energy(other) if not is_npc else 999
    if not is_npc and ot_energy < effective_cost:
        return ('error', '对方灵力不足，双修未能进行')

    factor, desc, is_ke = wuxing_factor(char_elements(char), char_elements(other))
    daolv_bonus    = DAOLV_SHUANGXIU_BONUS if is_daolv_pair(char['id'], other['id']) else 0
    shuangxiu_pct  = perk_total(char['id'], 'shuangxiu_pct')
    winter_bonus   = cur_season_buff('shuangxiu')
    if char.get('heqing_token_id'):
        _hqlv, _, _, _, _ = heqing_level_info(char)
        if _hqlv >= 5:   heqing_mult = 4.0
        elif _hqlv >= 4: heqing_mult = 3.0
        else:            heqing_mult = HEQING_SHUANGXIU_MULT
    else:
        heqing_mult = 1.0
    # 师父加成：徒弟与师父双修收益 ×2
    shifu_char, _ = get_shifu(char['id'])
    shifu_mult     = SHIFU_SHUANGXIU_MULT if (shifu_char and shifu_char['id'] == other['id']) else 1.0
    total_bonus    = daolv_bonus + shuangxiu_pct + winter_bonus
    zouhuo = is_ke and random.random() < 0.15

    set_energy(char['id'], my_energy - effective_cost)
    if not is_npc:
        set_energy(other['id'], ot_energy - effective_cost)
    ca, cb = _pair(char['id'], other['id'])
    run("UPDATE relationships SET last_shuangxiu=? WHERE char_a=? AND char_b=?", (now_ts(), ca, cb))
    add_affinity(char['id'], other['id'], SHUANGXIU_AFFINITY)

    participants = [(char, other)] + ([] if is_npc else [(other, char)])
    my_gain = 0
    for p, partner in participants:
        mult  = SPIRIT_ROOTS[p['spirit_root']]['mult']
        gap   = max(0, partner['realm_idx'] - p['realm_idx'])
        carry = 1 + min(0.5, gap * 0.05)
        if zouhuo:
            from_exp = REALMS[p['realm_idx']]['exp']
            loss = int((p['exp'] - from_exp) * ZOUHUO_PENALTY)
            run("UPDATE characters SET exp=? WHERE id=?", (max(from_exp, p['exp'] - loss), p['id']))
            log(p['id'], 'cultivate', f'与【{partner["name"]}】双修，灵根相克走火入魔，损失修为 {loss}！')
            if p['id'] == char['id']: my_gain = -loss
        else:
            base   = random.randint(120, 200)
            # 合欢修倍率按各自是否持令计算，不依赖谁发起
            if p.get('heqing_token_id'):
                _hqlv_p, _, _, _, _ = heqing_level_info(p)
                if _hqlv_p >= 5:   p_heqing_mult = 4.0
                elif _hqlv_p >= 4: p_heqing_mult = 3.0
                else:              p_heqing_mult = float(HEQING_SHUANGXIU_MULT)
            else:
                p_heqing_mult = 1.0
            p_mult = p_heqing_mult
            p_mult *= shifu_mult if p['id'] == char['id'] else 1.0
            gained = int(base * mult * factor * carry * (1 + total_bonus) * p_mult)
            run("UPDATE characters SET exp=exp+? WHERE id=?", (gained, p['id']))
            tag = '·道侣' if daolv_bonus else ''
            hq_tag = f'·合欢×{int(p_heqing_mult)}' if p_heqing_mult > 1 else ''
            sf_tag = '·师父×2' if (p['id'] == char['id'] and shifu_mult > 1) else ''
            # 合欢修本人：心魔 + 合欢经验 + 各级加成；被合欢修带着双修的对方：仅积累心魔
            if p.get('heqing_token_id'):
                cur_p_dq = p.get('demonic_qi') or 0
                new_dq = min(100, cur_p_dq + HEQING_DQ_PER_SHUANGXIU)
                if cur_p_dq >= 100:
                    dq_burn = max(1, int(p['exp'] * 0.001))
                    run("UPDATE characters SET exp=MAX(0,exp-?) WHERE id=?", (dq_burn, p['id']))
                    log(p['id'], 'system', f'心魔已满，道基受损，修为 -{dq_burn}。')
                new_hq_exp = (p.get('heqing_exp') or 0) + HEQING_SHUANGXIU_EXP
                new_hq_lv  = 0
                for _i, _lvl in enumerate(HEQING_LEVELS):
                    if new_hq_exp >= _lvl['exp']: new_hq_lv = _i
                run("UPDATE characters SET demonic_qi=?, heqing_exp=?, heqing_level=? WHERE id=?",
                    (new_dq, new_hq_exp, new_hq_lv, p['id']))
                hqlv = new_hq_lv
                extra_notes = []
                # Lv1：额外50灵石
                if hqlv >= 1:
                    run("UPDATE characters SET spirit_stones=spirit_stones+50 WHERE id=?", (p['id'],))
                    extra_notes.append('灵石+50')
                # Lv2：35%几率掉落礼物材料
                if hqlv >= 2 and random.random() < HEQING_DROP_CHANCE:
                    drop = random.choices(HEQING_TREASURE_DROPS,
                                         weights=[d['weight'] for d in HEQING_TREASURE_DROPS], k=1)[0]
                    drop_item = q("SELECT id FROM items WHERE name=?", (drop['name'],), one=True)
                    if drop_item:
                        ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (p['id'], drop_item['id']), one=True)
                        if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?", (p['id'], drop_item['id']))
                        else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)", (p['id'], drop_item['id']))
                        extra_notes.append(f'获得【{drop["name"]}】')
                extra_str = '，' + '、'.join(extra_notes) if extra_notes else ''
            elif is_heqing:
                cur_p_dq2 = p.get('demonic_qi') or 0
                new_dq = min(100, cur_p_dq2 + HEQING_DQ_PER_SHUANGXIU)
                run("UPDATE characters SET demonic_qi=? WHERE id=?", (new_dq, p['id']))
                if cur_p_dq2 >= 100:
                    dq_burn = max(1, int(p['exp'] * 0.001))
                    run("UPDATE characters SET exp=MAX(0,exp-?) WHERE id=?", (dq_burn, p['id']))
                    log(p['id'], 'system', f'心魔已满，道基受损，修为 -{dq_burn}。')
                extra_str = ''
            else:
                extra_str = ''
            log(p['id'], 'cultivate', f'与【{partner["name"]}】双修（{desc}×{factor}{tag}{hq_tag}{sf_tag}），修为 +{gained}{extra_str}。')
            if p['id'] == char['id']: my_gain = gained

    if zouhuo:
        return ('error', f'双修遭遇灵根相克，走火入魔，损修为！（{desc}）')
    bonus_txt = '·道侣+30%' if daolv_bonus else ''
    shifu_txt = '·师父×2' if shifu_mult > 1 else ''
    return ('success', f'双修圆满（五行{desc} ×{factor}{bonus_txt}{shifu_txt}）！你修为 +{my_gain}')

@app.route('/game/social/invite', methods=['POST'])
@login_required
def social_invite():
    char     = me()
    other_id = int(request.form.get('target_id', 0))
    _other   = q("SELECT * FROM characters WHERE id=?", (other_id,), one=True)
    other    = dict(_other) if _other else None

    if not other or other_id == char['id']:
        flash('对象不存在', 'error')
    elif other['is_npc']:
        # NPC 即时双修，无需等待
        cat, msg = do_shuangxiu(char, other)
        if cat == 'success' and char.get('heqing_token_id'):
            inc_quest(char['id'], 'heqing')
        flash(msg, cat)
    elif q("""SELECT 1 FROM interactions WHERE from_char=? AND to_char=?
              AND type='shuangxiu' AND status='pending'""", (char['id'], other_id), one=True):
        flash('已有一份双修邀请待对方回应', 'error')
    else:
        rel = get_relationship(char['id'], other_id)
        inv_cd = HEQING_SHUANGXIU_COOLDOWN if (char.get('heqing_token_id') or other.get('heqing_token_id')) else SHUANGXIU_COOLDOWN
        cd_left = (rel['last_shuangxiu'] + inv_cd) - now_ts()
        if cd_left > 0:
            flash(f'双修冷却中，还需 {cd_left//3600} 时 {(cd_left%3600)//60} 分', 'error')
        else:
            run("""INSERT INTO interactions (from_char,to_char,type,status,created_at)
                VALUES (?,?,'shuangxiu','pending',?)""", (char['id'], other_id, now_ts()))
            log(other_id, 'social', f'【{char["name"]}】向你发出双修邀请。')
            flash(f'已向【{other["name"]}】发出双修邀请，待对方接受', 'success')
    return redirect(url_for('social'))

@app.route('/game/social/respond', methods=['POST'])
@login_required
def social_respond():
    char    = me()
    inter_id = int(request.form.get('interaction_id', 0))
    decision = request.form.get('decision')
    inter   = q("SELECT * FROM interactions WHERE id=? AND to_char=? AND status='pending'",
                (inter_id, char['id']), one=True)
    if not inter:
        flash('邀请不存在或已处理', 'error')
        return redirect(url_for('social'))

    other = dict(q("SELECT * FROM characters WHERE id=?", (inter['from_char'],), one=True) or {})

    if decision == 'decline':
        run("UPDATE interactions SET status='declined' WHERE id=?", (inter_id,))
        verb = '双修' if inter['type'] == 'shuangxiu' else '结道侣'
        log(inter['from_char'], 'social', f'【{char["name"]}】婉拒了你的{verb}邀请。')
        flash('已婉拒邀请', 'info')
        return redirect(url_for('social'))

    if inter['type'] == 'marriage':
        char_cnt  = sum(1 for f in ['daolv_id','daolv2_id','daolv3_id'] if char.get(f))
        other_cnt = sum(1 for f in ['daolv_id','daolv2_id','daolv3_id'] if other.get(f))
        char_max  = 3 if char.get('heqing_token_id') else 1
        other_max = 3 if other.get('heqing_token_id') else 1
        if char_cnt >= char_max or other_cnt >= other_max:
            run("UPDATE interactions SET status='expired' WHERE id=?", (inter_id,))
            flash('一方道侣名额已满，无法结亲', 'error')
        else:
            run("UPDATE interactions SET status='accepted' WHERE id=?", (inter_id,))
            ca, cb = _pair(char['id'], other['id'])
            run("UPDATE relationships SET is_daolv=1 WHERE char_a=? AND char_b=?", (ca, cb))
            c_slot = 'daolv_id' if not char.get('daolv_id') else ('daolv2_id' if not char.get('daolv2_id') else 'daolv3_id')
            o_slot = 'daolv_id' if not other.get('daolv_id') else ('daolv2_id' if not other.get('daolv2_id') else 'daolv3_id')
            run(f"UPDATE characters SET {c_slot}=? WHERE id=?", (other['id'], char['id']))
            run(f"UPDATE characters SET {o_slot}=? WHERE id=?", (char['id'], other['id']))
            log(char['id'], 'social', f'与【{other["name"]}】结为道侣，从此双修同心！')
            log(other['id'], 'social', f'与【{char["name"]}】结为道侣，从此双修同心！')
            flash(f'喜结道侣！你与【{other["name"]}】永结同心。', 'success')
        return redirect(url_for('social'))

    # 接受双修
    run("UPDATE interactions SET status='accepted' WHERE id=?", (inter_id,))
    cat, msg = do_shuangxiu(char, other)
    if cat == 'success':
        if char.get('heqing_token_id'):
            inc_quest(char['id'], 'heqing')
        if other.get('heqing_token_id'):
            inc_quest(other['id'], 'heqing')
    flash(msg, cat)
    return redirect(url_for('social'))

@app.route('/game/social/propose', methods=['POST'])
@login_required
def social_propose():
    char     = me()
    other_id = int(request.form.get('target_id', 0))
    _other   = q("SELECT * FROM characters WHERE id=?", (other_id,), one=True)
    other    = dict(_other) if _other else None
    rel      = get_relationship(char['id'], other_id)

    # 计算当前道侣数 / 上限（合欢修最多3个，普通修士1个）
    max_daolv = 3 if char.get('heqing_token_id') else 1
    cur_daolv_count = sum(1 for f in ['daolv_id','daolv2_id','daolv3_id'] if char.get(f))

    if not other or other_id == char['id']:
        flash('对象不存在', 'error')
    elif cur_daolv_count >= max_daolv:
        flash(f'你的道侣名额已满（{cur_daolv_count}/{max_daolv}）', 'error')
    elif rel['affinity'] < DAOLV_AFFINITY:
        flash(f'好感需达「情投意合」（{DAOLV_AFFINITY}）方可求亲，当前 {rel["affinity"]}', 'error')
    elif other['is_npc']:
        # NPC 好感足够即应允
        oth_daolv = sum(1 for f in ['daolv_id','daolv2_id','daolv3_id'] if other.get(f))
        oth_max_daolv = 3 if other.get('heqing_token_id') else 1
        if oth_daolv >= oth_max_daolv:
            flash(f'【{other["name"]}】道侣名额已满', 'error')
        else:
            ca, cb = _pair(char['id'], other_id)
            run("UPDATE relationships SET is_daolv=1 WHERE char_a=? AND char_b=?", (ca, cb))
            # 写入发起方第一个空闲槽
            slot = 'daolv_id' if not char.get('daolv_id') else ('daolv2_id' if not char.get('daolv2_id') else 'daolv3_id')
            run(f"UPDATE characters SET {slot}=? WHERE id=?", (other_id, char['id']))
            # 写入NPC第一个空闲槽
            oth_slot = 'daolv_id' if not other.get('daolv_id') else ('daolv2_id' if not other.get('daolv2_id') else 'daolv3_id')
            run(f"UPDATE characters SET {oth_slot}=? WHERE id=?", (char['id'], other_id))
            log(char['id'], 'social', f'与【{other["name"]}】结为道侣！')
            flash(f'【{other["name"]}】含羞应允，你们结为道侣！', 'success')
    elif sum(1 for f in ['daolv_id','daolv2_id','daolv3_id'] if other.get(f)) >= (3 if other.get('heqing_token_id') else 1):
        flash(f'【{other["name"]}】道侣名额已满', 'error')
    elif q("""SELECT 1 FROM interactions WHERE from_char=? AND to_char=?
              AND type='marriage' AND status='pending'""", (char['id'], other_id), one=True):
        flash('已有一份结亲请求待对方回应', 'error')
    else:
        run("""INSERT INTO interactions (from_char,to_char,type,status,created_at)
            VALUES (?,?,'marriage','pending',?)""", (char['id'], other_id, now_ts()))
        log(other_id, 'social', f'【{char["name"]}】向你提出结为道侣！')
        flash(f'已向【{other["name"]}】提出结亲，待对方回应', 'success')
    return redirect(url_for('social'))

@app.route('/game/social/divorce', methods=['POST'])
@login_required
def social_divorce():
    char = me()
    if not char['daolv_id']:
        flash('你尚无道侣', 'error')
        return redirect(url_for('social'))
    other = q("SELECT * FROM characters WHERE id=?", (char['daolv_id'],), one=True)
    ca, cb = _pair(char['id'], char['daolv_id'])
    run("UPDATE relationships SET is_daolv=0 WHERE char_a=? AND char_b=?", (ca, cb))
    run("UPDATE characters SET daolv_id=NULL WHERE id=?", (char['id'],))
    if other:
        run("UPDATE characters SET daolv_id=NULL WHERE id=?", (other['id'],))
        log(other['id'], 'social', f'【{char["name"]}】与你和离。')
    log(char['id'], 'social', f'与【{other["name"] if other else "道侣"}】和离。')
    flash('已和离，缘尽于此。', 'info')
    return redirect(url_for('social'))

