@app.route('/game/encounters')
@login_required
def encounters():
    char    = me()
    pending = q("""SELECT * FROM encounters WHERE char_id=? AND status='pending'
        ORDER BY created_at ASC""", (char['id'],))
    history = q("""SELECT * FROM encounters WHERE char_id=? AND status!='pending'
        ORDER BY created_at DESC LIMIT 30""", (char['id'],))
    pending_list = []
    for p in pending:
        pending_list.append({'row': p, 'options': json.loads(p['options_json'] or '[]')})
