# ── 闭关 ───────────────────────────────────────────────────────────────────────

@app.route('/game/seclusion', methods=['GET','POST'])
@login_required
def seclusion():
    flash('闭关功能已关闭。', 'info')
    return redirect(url_for('cultivate'))
    char   = me()
    energy = cur_energy(char)
    in_sec = is_in_seclusion(char)

    if request.method == 'POST':
        action = request.form.get('action')
        if action == 'start' and not in_sec:
            hours = int(request.form.get('hours', 4))
            hours = max(2, min(24, hours))
            cost_mult = 4 if char['realm_idx'] >= 17 else 1
            cost  = hours * SECLUSION_COST_PER_HOUR * cost_mult
            energy_cost = 20  # 开始闭关消耗灵力
            if char['spirit_stones'] < cost:
                flash(f'灵石不足，需 {cost}', 'error')
            elif energy < energy_cost:
                flash(f'灵力不足，需 {energy_cost}', 'error')
            else:
                run("UPDATE characters SET spirit_stones=spirit_stones-?,seclusion_start=?,seclusion_end=? WHERE id=?",
                    (cost, now_ts(), now_ts()+hours*3600, char['id']))
                set_energy(char['id'], energy - energy_cost)
                log(char['id'], 'cultivate', f'开始闭关修炼，预计 {hours} 时。')
                flash(f'已进入闭关，将修炼 {hours} 小时，花费 {cost} 灵石和 {energy_cost} 灵力', 'success')
                char = me()
                in_sec = True
        elif action == 'cancel' and in_sec:
            # 提前结束：按实际已过时间结算，不受 seclusion_end 限制
            elapsed  = max(0, now_ts() - char['seclusion_start'])
            hours    = elapsed / 3600
            mult     = SPIRIT_ROOTS[char['spirit_root']]['mult']
            cult_pct = perk_total(char['id'], 'cultivate_pct')
            season_b = cur_season_buff('cultivate')
            gained   = int(SECLUSION_ACTIVE_RATE * mult * SECLUSION_EFFICIENCY
                           * (1 + cult_pct + season_b) * hours)
            run("UPDATE characters SET seclusion_start=0, seclusion_end=0, exp=exp+? WHERE id=?",
                (gained, char['id']))
            log(char['id'], 'cultivate',
                f'提前结束闭关（历时 {int(hours)}h {(elapsed%3600)//60}m），修为增长 {gained}。')
            flash(f'闭关提前结束，已修炼 {int(hours)}时{(elapsed%3600)//60}分，获得修为 {gained}。', 'info')
            char = me(); in_sec = False

    # 预估收益
    cost_mult = 4 if char['realm_idx'] >= 17 else 1
    previews = {}
    for h in [2, 4, 8, 12, 24]:
        mult   = SPIRIT_ROOTS[char['spirit_root']]['mult']
        perk_b = perk_total(char['id'], 'cultivate_pct')
        off_b  = get_offspring_cult_bonus(char['id'])
        st_b   = cur_season_buff('cultivate')
        est    = int(SECLUSION_ACTIVE_RATE * mult * SECLUSION_EFFICIENCY
                     * (1+perk_b+off_b+st_b) * h)
        previews[h] = {'exp': est, 'cost': h * SECLUSION_COST_PER_HOUR * cost_mult}

    secs_left = max(0, (char['seclusion_end'] or 0) - now_ts()) if in_sec else 0
    cost_per_hour = SECLUSION_COST_PER_HOUR * cost_mult
    return render_template('seclusion.html', char=char, in_sec=in_sec,
        previews=previews, secs_left=secs_left,
        SECLUSION_COST_PER_HOUR=cost_per_hour,
        seclusion_cost_mult=cost_mult)

# ── 法术领悟 ────────────────────────────────────────────────────────────────────

@app.route('/game/spells', methods=['GET','POST'])
@login_required
def spells_page():
    char   = me()
    energy = cur_energy(char)

    elems         = char_elements(char)
    special_elems = json.loads(char.get('special_elements', '') or '[]')
    all_elems     = elems + [e for e in special_elems if e not in elems]

    my_spells = q("SELECT * FROM char_spells WHERE char_id=? ORDER BY created_at", (char['id'],))
    max_sp    = spell_max(char['realm_idx'])

    if request.method == 'POST':
        action = request.form.get('action')

        if action == 'start':
            in_prog = [s for s in my_spells if not s['learned']]
            if len(my_spells) >= max_sp:
                flash(f'当前境界最多领悟 {max_sp} 门法术', 'error')
            elif in_prog:
                flash('已有法术正在领悟中，请先完成或放弃', 'error')
            elif char['spirit_stones'] < SPELL_START_COST:
                flash(f'灵石不足，开始领悟需 {SPELL_START_COST} 灵石', 'error')
            elif energy < 20:
                flash('灵力不足（需 20）', 'error')
            elif not all_elems:
                flash('暂无可领悟的属性', 'error')
            else:
                elem = random.choice(all_elems)
                run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?",
                    (SPELL_START_COST, char['id']))
                set_energy(char['id'], energy - 20)
                run("INSERT INTO char_spells (char_id,element,custom_name,mastery,comprehend_progress,learned,created_at) VALUES (?,?,?,0,0,0,?)",
                    (char['id'], elem, '', now_ts()))
                log(char['id'], 'cultivate',
                    f'开始感应{SPELL_ELEMENT_NAMES.get(elem,"法术")}，心随灵动，万象归一。')
                flash(f'感应到了【{SPELL_ELEMENT_NAMES.get(elem, elem)}】！开始领悟之路。', 'success')
            return redirect(url_for('spells_page'))

        elif action == 'practice':
            spell_id = int(request.form.get('spell_id', 0))
            sp = q("SELECT * FROM char_spells WHERE id=? AND char_id=?", (spell_id, char['id']), one=True)
            if not sp:
                flash('法术不存在', 'error')
            elif energy < SPELL_ENERGY_COST:
                flash(f'灵力不足（需 {SPELL_ENERGY_COST}）', 'error')
            elif sp['learned']:
                if sp['mastery'] >= 100:
                    flash('此法术熟练度已达满级', 'info')
                else:
                    gain = random.randint(3, 7)
                    new_m = min(100, (sp['mastery'] or 0) + gain)
                    run("UPDATE char_spells SET mastery=? WHERE id=?", (new_m, spell_id))
                    set_energy(char['id'], energy - SPELL_ENERGY_COST)
                    name = sp['custom_name'] or SPELL_ELEMENT_NAMES.get(sp['element'], '法术')
                    log(char['id'], 'cultivate', f'修炼【{name}】，熟练度 +{gain}（{new_m}/100）。')
                    flash(f'修炼有成，熟练度 +{gain}！当前 {new_m}/100', 'success')
            else:
                rate = SPELL_PROGRESS_RATE.get(char['spirit_root'], 7)
                gain = max(1, rate + random.randint(-2, 3))
                new_p = min(100, (sp['comprehend_progress'] or 0) + gain)
                set_energy(char['id'], energy - SPELL_ENERGY_COST)
                if new_p >= 100:
                    run("UPDATE char_spells SET comprehend_progress=100, learned=1, mastery=10 WHERE id=?",
                        (spell_id,))
                    ename = SPELL_ELEMENT_NAMES.get(sp['element'], '法术')
                    log(char['id'], 'cultivate', f'成功领悟{ename}！可为其命名。')
                    flash(f'🎉 {ename}领悟完成！请为它取一个属于自己的名字。', 'success')
                else:
                    run("UPDATE char_spells SET comprehend_progress=? WHERE id=?", (new_p, spell_id))
                    log(char['id'], 'cultivate', f'法术感应加深，进度 +{gain}（{new_p}/100）。')
                    flash(f'感应加深，进度 {new_p}/100。', 'info')
            return redirect(url_for('spells_page'))

        elif action == 'rename':
            spell_id = int(request.form.get('spell_id', 0))
            new_name = request.form.get('name', '').strip()[:16]
            sp = q("SELECT * FROM char_spells WHERE id=? AND char_id=? AND learned=1",
                   (spell_id, char['id']), one=True)
            if not sp:
                flash('法术不存在或尚未领悟', 'error')
            elif not new_name:
                flash('名称不能为空', 'error')
            else:
                run("UPDATE char_spells SET custom_name=? WHERE id=?", (new_name, spell_id))
                log(char['id'], 'system', f'将法术命名为【{new_name}】。')
                flash(f'已将法术命名为【{new_name}】', 'success')
            return redirect(url_for('spells_page'))

        elif action == 'forge_move':
            spell_id  = int(request.form.get('spell_id', 0))
            sp_target = q("SELECT * FROM char_spells WHERE id=? AND char_id=? AND learned=1",
                          (spell_id, char['id']), one=True)
            my_moves  = q("SELECT id FROM char_spell_moves WHERE char_id=? AND spell_id=?", (char['id'], spell_id))
            if char['realm_idx'] < MOVE_MIN_REALM:
                flash('需达化神境界方可研制法术招式', 'error')
            elif not sp_target:
                flash('法术不存在', 'error')
            elif (sp_target['mastery'] or 0) < 100:
                flash('法术熟练度需达满级（100）方可研制招式', 'error')
            elif len(my_moves) >= MOVE_MAX:
                flash(f'该法术招式已达上限（{MOVE_MAX}式）', 'error')
            else:
                move_num   = len(my_moves) + 1
                stone_cost = move_num * 2000
                move_rate  = max(0.05, MOVE_SUCCESS_RATE - (move_num - 1) * 0.06)
                if char['spirit_stones'] < stone_cost:
                    flash(f'灵石不足（需 {stone_cost} 灵石）', 'error')
                elif energy < MOVE_ENERGY_COST:
                    flash(f'灵力不足（需 {MOVE_ENERGY_COST}）', 'error')
                else:
                    run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?", (stone_cost, char['id']))
                    set_energy(char['id'], energy - MOVE_ENERGY_COST)
                    sp_name = sp_target['custom_name'] or SPELL_ELEMENT_NAMES.get(sp_target['element'], '法术')
                    if random.random() < move_rate:
                        pool = list(MOVE_BUFF_POOL)
                        b1 = random.choice(pool)
                        pool2 = [b for b in pool if b[0] != b1[0]]
                        b2 = random.choice(pool2)
                        run("INSERT INTO char_spell_moves (char_id,move_num,spell_id,custom_name,buff1_key,buff1_val,buff2_key,buff2_val,created_at) VALUES (?,?,?,?,?,?,?,?,?)",
                            (char['id'], move_num, spell_id, '', b1[0], b1[1], b2[0], b2[1], now_ts()))
                        l1 = MOVE_BUFF_LABELS.get(b1[0], b1[0])
                        l2 = MOVE_BUFF_LABELS.get(b2[0], b2[0])
                        log(char['id'], 'cultivate',
                            f'为法术【{sp_name}】研制招式成功，解锁：{l1}+{round(b1[1]*100,1)}% 与 {l2}+{round(b2[1]*100,1)}%。')
                        flash(f'招式研制成功！{l1}+{round(b1[1]*100,1)}%，{l2}+{round(b2[1]*100,1)}%', 'success')
                    else:
                        refund = stone_cost // 2
                        run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?", (refund, char['id']))
                        log(char['id'], 'cultivate',
                            f'为法术【{sp_name}】研制招式失败，退还 {refund} 灵石。')
                        flash(f'研制失败，灵力损耗殆尽，退还 {refund} 灵石。', 'error')
            return redirect(url_for('spells_page'))

        elif action == 'rename_move':
            move_id  = int(request.form.get('move_id', 0))
            new_name = request.form.get('name', '').strip()[:16]
            mv = q("SELECT id FROM char_spell_moves WHERE id=? AND char_id=?", (move_id, char['id']), one=True)
            if not mv:
                flash('招式不存在', 'error')
            elif not new_name:
                flash('名称不能为空', 'error')
            else:
                run("UPDATE char_spell_moves SET custom_name=? WHERE id=?", (new_name, move_id))
                flash(f'已命名为【{new_name}】', 'success')
            return redirect(url_for('spells_page'))

        elif action == 'abandon':
            spell_id = int(request.form.get('spell_id', 0))
            sp = q("SELECT * FROM char_spells WHERE id=? AND char_id=?", (spell_id, char['id']), one=True)
            if not sp:
                flash('法术不存在', 'error')
            elif sp['learned']:
                flash('已领悟的法术无法放弃', 'error')
            else:
                refund = SPELL_START_COST // 2
                run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?", (refund, char['id']))
                run("DELETE FROM char_spells WHERE id=?", (spell_id,))
                log(char['id'], 'system',
                    f'放弃领悟{SPELL_ELEMENT_NAMES.get(sp["element"],"法术")}，退还 {refund} 灵石。')
                flash(f'已放弃，退还 {refund} 灵石。', 'info')
            return redirect(url_for('spells_page'))

    # 招式数据：按 spell_id 建索引，旧数据（无spell_id）单独收集
    my_moves_raw = q("SELECT * FROM char_spell_moves WHERE char_id=? ORDER BY move_num", (char['id'],))
    moves_by_spell = {}
    orphan_moves   = []
    for mv in my_moves_raw:
        mv_view = {
            **dict(mv),
            'display_name': mv['custom_name'] or f'第{mv["move_num"]}式',
            'buff1_label':  MOVE_BUFF_LABELS.get(mv['buff1_key'], mv['buff1_key']),
            'buff1_pct':    round(mv['buff1_val'] * 100, 1),
            'buff2_label':  MOVE_BUFF_LABELS.get(mv['buff2_key'], mv['buff2_key']),
            'buff2_pct':    round(mv['buff2_val'] * 100, 1),
        }
        if mv['spell_id']:
            moves_by_spell.setdefault(mv['spell_id'], []).append(mv_view)
        else:
            orphan_moves.append(mv_view)
    # 构建展示数据，将招式附加到对应法术；研制进度（第几式/花费/成功率）按各法术单独计算
    spells_view = []
    for sp in my_spells:
        eff = SPELL_ELEMENT_EFFECTS.get(sp['element'], {})
        m   = (sp['mastery'] or 0) / 100
        sp_moves      = moves_by_spell.get(sp['id'], [])
        sp_move_count = len(sp_moves)
        spells_view.append({
            **dict(sp),
            'display_name': sp['custom_name'] or SPELL_ELEMENT_NAMES.get(sp['element'], '法术'),
            'elem_name':    SPELL_ELEMENT_NAMES.get(sp['element'], sp['element']),
            'elem_color':   SPELL_ELEMENT_COLORS.get(sp['element'], '#888'),
            'is_special':   sp['element'] in SPECIAL_ELEMENT_SOURCES,
            'effects_now':  {k: round(v * m * 100, 1) for k, v in eff.items()},
            'effects_max':  {k: round(v * 100, 1) for k, v in eff.items()},
            'moves':        sp_moves,
            'move_count':   sp_move_count,
            'next_move_num':  sp_move_count + 1,
            'next_move_cost': (sp_move_count + 1) * 2000,
            'next_move_rate': max(5, int(round(max(0.05, MOVE_SUCCESS_RATE - sp_move_count * 0.06) * 100))),
        })

    return render_template('spells.html',
        char=char, energy=energy,
        my_spells=spells_view, max_sp=max_sp,
        all_elems=all_elems, special_elems=special_elems,
        SPELL_START_COST=SPELL_START_COST,
        SPELL_ENERGY_COST=SPELL_ENERGY_COST,
        SPELL_ELEMENT_NAMES=SPELL_ELEMENT_NAMES,
        SPELL_ELEMENT_COLORS=SPELL_ELEMENT_COLORS,
        MAX_ENERGY=energy_cap(char),
        orphan_moves=orphan_moves,
        MOVE_MIN_REALM=MOVE_MIN_REALM, MOVE_MAX=MOVE_MAX,
        MOVE_ENERGY_COST=MOVE_ENERGY_COST)

# ── 仙人试炼 玩家端 ─────────────────────────────────────────────────────────────

@app.route('/game/enlighten', methods=['GET','POST'])
@login_required
def enlighten():
    char    = me()
    energy  = cur_energy(char)
    esess = get_enlighten_session(char['id'])
    event_on = enlighten_event_active()
    result_flash = None

    if request.method == 'POST':
        action = request.form.get('action')

        # ── 开启试炼 ──
        if action == 'start':
            if esess and not esess['resolved']:
                flash('你已有进行中的试炼', 'error')
            elif not event_on and not (esess and not esess['resolved']):
                flash('当前没有开放的仙人试炼活动', 'error')
            elif char['spirit_stones'] < ENLIGHTEN_COST_STONES:
                flash(f'灵石不足，需 {ENLIGHTEN_COST_STONES}', 'error')
            elif energy < ENLIGHTEN_COST_ENERGY:
                flash(f'灵力不足，需 {ENLIGHTEN_COST_ENERGY}', 'error')
            else:
                seed = {
                    's1': random.randrange(len(ENLIGHTEN_ELEMENT_TRIALS)),
                    's2': random.randrange(len(ENLIGHTEN_MORAL_TRIALS)),
                    's4': random.randrange(len(ENLIGHTEN_WISDOM_TRIALS)),
                }
                run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?",
                    (ENLIGHTEN_COST_STONES, char['id']))
                set_energy(char['id'], energy - ENLIGHTEN_COST_ENERGY)
                run("""INSERT OR REPLACE INTO enlighten_sessions
                    (char_id, started_at, seed_json, stages_done, scores_json, resolved, result)
                    VALUES (?,?,?,0,'[]',0,'')""",
                    (char['id'], now_ts(), json.dumps(seed)))
                log(char['id'], 'cultivate', '踏入仙人试炼，36小时顿悟之路就此开启。')
                flash('试炼开始！36小时内共五关，每关适时解锁，请留意。', 'success')
                return redirect(url_for('enlighten'))

        # ── 提交阶段答案 ──
        elif action == 'submit_stage' and esess and not esess['resolved']:
            stage_idx = int(request.form.get('stage_idx', -1))
            if stage_idx < 0 or stage_idx > 4:
                flash('无效阶段', 'error')
            elif not enlighten_stage_unlocked(esess, stage_idx):
                flash('此阶段尚未解锁', 'error')
            elif enlighten_stage_done(esess, stage_idx):
                flash('此阶段已完成', 'error')
            else:
                seed = json.loads(esess['seed_json'] or '{}')
                scores = json.loads(esess['scores_json'] or '[]')
                while len(scores) < 5:
                    scores.append(None)
                score = 0
                narrative = ''

                if stage_idx == 0:  # 五行感应
                    trial   = ENLIGHTEN_ELEMENT_TRIALS[seed.get('s1', 0)]
                    choice  = request.form.get('choice', '')
                    correct = (choice == trial['answer'])
                    score   = 100 if correct else 25
                    narrative = (f'你感应到的是【{choice}】——' +
                                 ('仙人微微点头，目光中现出一丝欣慰。' if correct
                                  else f'仙人沉默片刻。{trial["answer"]}行之力尚待体会。'))

                elif stage_idx == 1:  # 道心抉择
                    trial  = ENLIGHTEN_MORAL_TRIALS[seed.get('s2', 0)]
                    try:
                        cidx = int(request.form.get('choice_idx', 0))
                    except Exception:
                        cidx = 0
                    cidx  = max(0, min(cidx, len(trial['choices']) - 1))
                    ch    = trial['choices'][cidx]
                    score = ch['score']
                    narrative = ch['after']

                elif stage_idx == 2:  # 时机把握（JS端算分，服务端接收并校验）
                    try:
                        raw = int(request.form.get('timing_score', 0))
                    except Exception:
                        raw = 0
                    score     = max(0, min(100, raw))
                    if score >= 80:
                        narrative = '灵气如约归位，仙人赞许道：「把握精准，此子有慧根。」'
                    elif score >= 50:
                        narrative = '灵气勉强入窍，仙人颔首：「尚可，继续磨练。」'
                    else:
                        narrative = '灵气散逸大半，仙人叹道：「心神未静，时机难握。」'

                elif stage_idx == 3:  # 道理辨析
                    trial  = ENLIGHTEN_WISDOM_TRIALS[seed.get('s4', 0)]
                    try:
                        cidx = int(request.form.get('choice_idx', 0))
                    except Exception:
                        cidx = 0
                    cidx  = max(0, min(cidx, len(trial['choices']) - 1))
                    ch    = trial['choices'][cidx]
                    score = ch['score']
                    narrative = ('仙人微笑点头：「正是此理。」' if ch['correct']
                                 else '仙人轻轻摇头：「再细细品味。」')

                elif stage_idx == 4:  # 感悟传承（文字反思）
                    text  = (request.form.get('reflection') or '').strip()
                    score = min(100, 55 + min(45, len(text) // 2))
                    if len(text) >= 60:
                        narrative = '仙人凝视着你留下的感悟，久久无言，最终点了点头。'
                    elif len(text) >= 20:
                        narrative = '仙人扫了一眼，道：「心有所感，继续深思。」'
                    else:
                        narrative = '仙人静默片刻，未置可否。'

                scores[stage_idx]        = score
                new_done = esess['stages_done'] | (1 << stage_idx)
                run("UPDATE enlighten_sessions SET stages_done=?, scores_json=? WHERE char_id=?",
                    (new_done, json.dumps(scores), char['id']))
                log(char['id'], 'cultivate',
                    f'仙人试炼第{stage_idx+1}关【{ENLIGHTEN_STAGE_NAMES[stage_idx]}】完成，得分 {score}。{narrative}')
                result_flash = {'score': score, 'narrative': narrative,
                                'stage_name': ENLIGHTEN_STAGE_NAMES[stage_idx]}
                esess = get_enlighten_session(char['id'])

        # 检查是否到结算时间
        if esess and not esess['resolved'] and now_ts() >= esess['started_at'] + ENLIGHTEN_DURATION_SECS:
            resolve_enlighten(char['id'])
            esess = get_enlighten_session(char['id'])

    # ── GET 渲染 ──
    char = me()
    esess = get_enlighten_session(char['id'])

    # 构建阶段展示数据
    stage_data = []
    seed   = json.loads(esess['seed_json'] if esess else '{}')
    scores = json.loads(esess['scores_json'] if esess else '[]')
    while len(scores) < 5:
        scores.append(None)

    for i in range(5):
        unlocked = enlighten_stage_unlocked(esess, i) if esess else False
        done     = enlighten_stage_done(esess, i) if esess else False
        unlock_ts = (esess['started_at'] + ENLIGHTEN_STAGE_HOURS[i] * 3600) if esess else 0
        stage_data.append({
            'idx': i, 'name': ENLIGHTEN_STAGE_NAMES[i],
            'unlocked': unlocked, 'done': done,
            'score': scores[i], 'unlock_ts': unlock_ts,
        })

    # 当前可操作的关卡内容
    active_idx = enlighten_next_available(esess)
    active_content = None
    if active_idx == 0:
        active_content = ENLIGHTEN_ELEMENT_TRIALS[seed.get('s1', 0)]
    elif active_idx == 1:
        active_content = ENLIGHTEN_MORAL_TRIALS[seed.get('s2', 0)]
    elif active_idx == 3:
        active_content = ENLIGHTEN_WISDOM_TRIALS[seed.get('s4', 0)]

    immortal_line = random.choice(ENLIGHTEN_IMMORTAL_LINES)
    total_score   = sum(s for s in scores if isinstance(s, (int, float)))
    secs_left     = max(0, (esess['started_at'] + ENLIGHTEN_DURATION_SECS - now_ts())) if esess else 0

    return render_template('enlighten.html',
        char=char, esess=esess, event_on=event_on,
        stage_data=stage_data, active_idx=active_idx, active_content=active_content,
        immortal_line=immortal_line, total_score=total_score, secs_left=secs_left,
        result_flash=result_flash,
        ENLIGHTEN_COST_STONES=ENLIGHTEN_COST_STONES,
        ENLIGHTEN_COST_ENERGY=ENLIGHTEN_COST_ENERGY,
        ENLIGHTEN_STAGE_NAMES=ENLIGHTEN_STAGE_NAMES,
    )

# ── 开凿灵脉 ────────────────────────────────────────────────────────────────────

@app.route('/game/vein', methods=['GET','POST'])
@login_required
def vein():
    char = me()
    ev   = get_vein_event()
    msg  = None

    if request.method == 'POST' and ev:
        if request.form.get('action') == 'dig':
            charges = vein_available_charges(ev, char['id'])
            if charges <= 0:
                flash('当前没有可用开凿次数，每小时累积一次', 'error')
            else:
                dug    = random.randint(VEIN_DIG_MIN, VEIN_DIG_MAX)
                stones = random.randint(VEIN_STONE_MIN, VEIN_STONE_MAX)
                # 记录开凿前状态（用于公告判断）
                old_progress = ev['total_progress']
                is_first_dig = not q("SELECT 1 FROM vein_contributions WHERE event_id=? AND char_id=?",
                                     (ev['id'], char['id']), one=True)
                # 更新个人贡献
                run("""INSERT INTO vein_contributions (event_id, char_id, contribution, excavations, last_excavate_at)
                       VALUES (?,?,?,1,?)
                       ON CONFLICT(event_id, char_id) DO UPDATE SET
                           contribution=contribution+?,
                           excavations=excavations+1,
                           last_excavate_at=?""",
                    (ev['id'], char['id'], dug, now_ts(), dug, now_ts()))
                # 更新全服进度
                run("UPDATE vein_event SET total_progress=total_progress+? WHERE id=?",
                    (dug, ev['id']))
                # 发放灵石
                run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
                    (stones, char['id']))
                log(char['id'], 'cultivate',
                    f'参与开凿上古灵脉，本次开凿 {dug} 点，获得灵石 {stones}。')
                ev = get_vein_event()
                contrib = q("SELECT * FROM vein_contributions WHERE event_id=? AND char_id=?",
                            (ev['id'] if ev else 0, char['id']), one=True)
                msg = {'dug': dug, 'stones': stones,
                       'total': contrib['contribution'] if contrib else dug}
                # 公告：首次参与
                if is_first_dig:
                    world_log_add('system', f'🪨 【{char["name"]}】响应天地召唤，参与上古灵脉开凿！')
                # 公告：全服进度里程碑（25% / 50% / 75%）
                if ev:
                    new_progress = ev['total_progress']
                    for pct, label in ((75, '四分之三'), (50, '过半'), (25, '四分之一')):
                        milestone = VEIN_TARGET * pct // 100
                        if old_progress < milestone <= new_progress and \
                           not q("SELECT 1 FROM world_log WHERE content LIKE ?",
                                 (f'%灵脉开凿进度已达{label}%',), one=True):
                            world_log_add('system',
                                f'⛏ 上古灵脉开凿进度已达{label}！修士们再接再厉，灵脉在望！')
                            break
                # 进度到顶：立即结算发奖
                if ev and ev['total_progress'] >= VEIN_TARGET:
                    world_log_add('system', '🌟 上古灵脉全面贯通！修士们的齐心开凿终见成效，感悟即将降临！')
                    _close_vein_event(ev)
                    ev = None
                flash(f'开凿成功！贡献 {dug} 点，获得灵石 {stones}。', 'success')

    # 读取最新数据
    ev = get_vein_event()
    contrib = None
    charges = 0
    if ev:
        contrib = q("SELECT * FROM vein_contributions WHERE event_id=? AND char_id=?",
                    (ev['id'], char['id']), one=True)
        charges = vein_available_charges(ev, char['id'])

    # 贡献榜（前20名）
    leaderboard = []
    if ev:
        leaderboard = q("""SELECT vc.contribution, vc.excavations, c.name, c.realm_idx
            FROM vein_contributions vc JOIN characters c ON c.id=vc.char_id
            WHERE vc.event_id=? ORDER BY vc.contribution DESC LIMIT 20""", (ev['id'],))

    return render_template('vein.html',
        char=char, ev=ev, contrib=contrib, charges=charges,
        leaderboard=leaderboard, msg=msg,
        VEIN_TARGET=VEIN_TARGET, VEIN_THRESHOLD=VEIN_THRESHOLD,
        VEIN_MAX_CHARGES=VEIN_MAX_CHARGES, REALMS=REALMS)

# ── 异世之门 ────────────────────────────────────────────────────────────────────

@app.route('/game/gate', methods=['GET', 'POST'])
@login_required
def gate():
    char = me()
    ev   = get_gate_event()
    if not ev:
        flash('异世之门活动当前未开启。', 'info')
        return redirect(url_for('dashboard'))

    ghosts, defeated_ids = get_or_create_gate_pool(char, ev)
    defeated_set = set(defeated_ids)
    # 首次进入异世之门，初始化积攒计时器
    if not (char['ghost_atk_ts'] or 0):
        run("UPDATE characters SET ghost_atk_ts=?, ghost_atk_charges=0 WHERE id=?",
            (now_ts(), char['id']))
        char = me()
    can_atk, atk_cd = gate_has_atk_chance(char)
    can_help, _     = gate_has_help_chance(char)

    if request.method == 'POST':
        action = request.form.get('action')

        # ── 攻击鬼魔 ──
        if action == 'attack':
            ghost_idx = int(request.form.get('ghost_idx', -1))
            hp_now = cur_hp(char)
            if hp_now <= 0:
                flash('气血耗尽，无法战斗！', 'error')
                return redirect(url_for('gate'))
            if not can_atk:
                flash(f'攻击机会冷却中，请稍后再试。', 'error')
                return redirect(url_for('gate'))
            ghost = next((g for g in ghosts if g['idx'] == ghost_idx), None)
            if not ghost:
                flash('无效的目标。', 'error')
                return redirect(url_for('gate'))
            if ghost_idx in defeated_set:
                flash('此鬼魔已被击败。', 'info')
                return redirect(url_for('gate'))

            # 使用攻击机会（累计制：扣1次，同步基准时间）
            charges_now, _, new_base = gate_calc_atk_charges(char)
            run("UPDATE characters SET ghost_atk_ts=?, ghost_atk_charges=? WHERE id=?",
                (new_base, max(0, charges_now - 1), char['id']))

            # 战斗模拟（含全部加成：历史伙伴/符咒/法术/剑修/暴击/闪避等）
            char_wins, c_hp, ghost_hp_left = _gate_fight(char, ghost, hp_now)
            today_str = time.strftime('%Y-%m-%d', time.localtime())

            if char_wins:
                # 更新鬼魔血量为0、记录击败
                new_defeated = list(defeated_set | {ghost_idx})
                for g in ghosts:
                    if g['idx'] == ghost_idx:
                        g['hp'] = 0
                        g['defeated'] = True
                run("""UPDATE gate_ghost_pool SET ghosts_json=?, defeated_ids=?
                       WHERE char_id=? AND event_id=? AND day=?""",
                    (json.dumps(ghosts), json.dumps(new_defeated),
                     char['id'], ev['id'], today_str))
                # 更新战斗后气血
                set_hp(char['id'], max(1, c_hp))
                # 奖励：灵石 + 随机碎片
                run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
                    (ghost['stones'], char['id']))
                shard_got = 0
                if random.random() < ghost.get('shard_chance', 0.30):
                    shard_got = random.randint(1, ghost.get('shard_max', 1))
                    _gate_give_shard(char['id'], ghost['law'], shard_got)
                shard_txt = f'、{ghost["law"]}法则碎片 {shard_got} 片' if shard_got else ''
                bonus_txt = _gate_daily_clear_bonus(char['id'], len(defeated_set), len(new_defeated), len(ghosts))
                # 更新求救帖（如有）
                run("""UPDATE gate_help_board SET is_resolved=1, helper_id=?, resolved_at=?
                       WHERE requester_id=? AND ghost_idx=? AND event_id=? AND is_resolved=0""",
                    (char['id'], now_ts(), char['id'], ghost_idx, ev['id']))
                log(char['id'], 'combat',
                    f'击败【{ghost["icon"]}{ghost["name"]}】，获得灵石 {ghost["stones"]} 枚{shard_txt}。')
                flash(f'击败【{ghost["icon"]}{ghost["name"]}】！获得灵石 {ghost["stones"]} 枚{shard_txt or "，未掉落碎片"}{bonus_txt}。', 'success')
            else:
                # 战斗失败：保存鬼魔剩余血量（累计伤害），更新玩家气血
                for g in ghosts:
                    if g['idx'] == ghost_idx:
                        g['hp'] = ghost_hp_left
                run("""UPDATE gate_ghost_pool SET ghosts_json=?
                       WHERE char_id=? AND event_id=? AND day=?""",
                    (json.dumps(ghosts), char['id'], ev['id'], today_str))
                set_hp(char['id'], max(0, c_hp))
                hp_pct_lost = int((ghost['max_hp'] - ghost_hp_left) / max(1, ghost['max_hp']) * 100)
                log(char['id'], 'combat',
                    f'与【{ghost["icon"]}{ghost["name"]}】交手，力竭而退，气血大损。'
                    f'（鬼魔已损耗 {hp_pct_lost}% 气血，下次攻击可继续削减）')
                flash(f'战斗失败！鬼魔已损耗 {hp_pct_lost}% 气血，下次获得攻击机会后可继续打击。', 'error')
            return redirect(url_for('gate'))

        # ── 打天魔（今日6只鬼魔全部击败后才能挑战，可反复挑战直到次数耗尽；
        #    尽歼补发加派的【天魔分身】不计入此判定，天魔分身在场也不影响挑战天魔本体）──
        elif action == 'attack_tianmo':
            core_ghosts = [g for g in ghosts if g.get('name') != '天魔分身']
            if len(defeated_set & {g['idx'] for g in core_ghosts}) < len(core_ghosts):
                flash(f'尚未击败今日全部 {len(core_ghosts)} 只鬼魔，无法挑战天魔。', 'error')
                return redirect(url_for('gate'))
            today_str = time.strftime('%Y-%m-%d', time.localtime())
            attempt_row = q("SELECT attempts FROM gate_tianmo_attempts WHERE char_id=? AND day=?",
                            (char['id'], today_str), one=True)
            attempts_used = attempt_row['attempts'] if attempt_row else 0
            if attempts_used >= GATE_TIANMO_DAILY_LIMIT:
                flash(f'今日挑战天魔次数已用完（{GATE_TIANMO_DAILY_LIMIT}/{GATE_TIANMO_DAILY_LIMIT}），明天再来。', 'error')
                return redirect(url_for('gate'))
            hp_now = cur_hp(char)
            if hp_now <= 0:
                flash('气血耗尽，无法战斗！', 'error')
                return redirect(url_for('gate'))
            if not can_atk:
                flash('攻击机会冷却中，请稍后再试。', 'error')
                return redirect(url_for('gate'))
            charges_now, _, new_base = gate_calc_atk_charges(char)
            run("UPDATE characters SET ghost_atk_ts=?, ghost_atk_charges=? WHERE id=?",
                (new_base, max(0, charges_now - 1), char['id']))
            run("""INSERT INTO gate_tianmo_attempts (char_id,day,attempts) VALUES (?,?,1)
                   ON CONFLICT(char_id,day) DO UPDATE SET attempts=attempts+1""",
                (char['id'], today_str))

            row = q("SELECT day_number FROM gate_ghost_pool WHERE char_id=? AND event_id=? AND day=?",
                    (char['id'], ev['id'], today_str), one=True)
            day_number = row['day_number'] if row else 1
            tianmo = _gate_gen_tianmo(char, day_number)
            char_wins, c_hp, _ = _gate_fight(char, tianmo, hp_now)
            set_hp(char['id'], max(0 if not char_wins else 1, c_hp))
            attempts_left = GATE_TIANMO_DAILY_LIMIT - (attempts_used + 1)

            if char_wins:
                run("UPDATE characters SET spirit_stones=spirit_stones+?, exp=exp+? WHERE id=?",
                    (tianmo['stones'], tianmo['exp'], char['id']))
                shard_got = random.randint(1, tianmo['shard_max'])
                _gate_give_shard(char['id'], tianmo['law'], shard_got)
                shard_txt = f'、{tianmo["law"]}法则碎片 {shard_got} 片'
                log(char['id'], 'combat',
                    f'击败【👹天魔】，获得灵石 {tianmo["stones"]} 枚、修为 {tianmo["exp"]}{shard_txt}。')
                flash(f'击败【👹天魔】！获得灵石 {tianmo["stones"]} 枚、修为 {tianmo["exp"]}'
                      f'{shard_txt or "，未掉落碎片"}。今日剩余挑战次数 {attempts_left}。', 'success')
            else:
                log(char['id'], 'combat', '与【👹天魔】交手，力竭而退，未能讨得便宜。')
                flash(f'天魔过于强大，挑战失败！今日剩余挑战次数 {attempts_left}。', 'error')
            return redirect(url_for('gate'))

        # ── 发求救 ──
        elif action == 'help_request':
            ghost_idx = int(request.form.get('ghost_idx', -1))
            if not can_help:
                flash('求救冷却中，请稍后再发。', 'error')
                return redirect(url_for('gate'))
            ghost = next((g for g in ghosts if g['idx'] == ghost_idx), None)
            if not ghost or ghost_idx in defeated_set:
                flash('无效目标或已击败。', 'error')
                return redirect(url_for('gate'))
            # 检查是否已有未解决的求救
            existing = q("""SELECT 1 FROM gate_help_board
                WHERE requester_id=? AND event_id=? AND ghost_idx=? AND is_resolved=0""",
                (char['id'], ev['id'], ghost_idx), one=True)
            if existing:
                flash('已有一条未解决的求救，无法重复发送。', 'info')
                return redirect(url_for('gate'))
            run("""INSERT INTO gate_help_board (requester_id,event_id,ghost_idx,posted_at)
                   VALUES (?,?,?,?)""",
                (char['id'], ev['id'], ghost_idx, now_ts()))
            run("UPDATE characters SET ghost_help_ts=? WHERE id=?", (now_ts(), char['id']))
            flash('已在求救板发出求援信号！', 'success')
            return redirect(url_for('gate'))

        # ── 与天相争 ──
        elif action == 'contend':
            slot = _heaven_hour_slot()
            heaven_num = gate_heaven_current(ev['id'])
            already, _ = gate_player_rolled_this_hour(char['id'], ev['id'])
            if heaven_num is None:
                flash('天尚未投掷本小时数字，请稍后再试。', 'error')
            elif already:
                flash('本小时已投掷过，下小时再来。', 'error')
            else:
                player_num = random.randint(0, 100)
                run("INSERT OR IGNORE INTO gate_player_rolls (event_id,char_id,hour_slot,player_num,rolled_at) VALUES (?,?,?,?,?)",
                    (ev['id'], char['id'], slot, player_num, now_ts()))
                # 检查本小时是否已达到5人胜天
                winners_now = q("""SELECT COUNT(*) cnt FROM gate_player_rolls
                                   WHERE event_id=? AND hour_slot=? AND player_num>?""",
                                (ev['id'], slot, heaven_num), one=True)['cnt']
                beat = player_num > heaven_num
                msg = f'你投出【{player_num}】，天出【{heaven_num}】，{"胜！" if beat else "败。"}'
                if beat and winners_now == HEAVEN_CONTEND_WIN_THRESHOLD:
                    # 全员+1攻击机会
                    all_chars = q("SELECT id,ghost_atk_ts,ghost_atk_charges FROM characters WHERE is_npc=0 AND status='alive'")
                    for c in all_chars:
                        charges_now, _, new_base = gate_calc_atk_charges(c)
                        new_charges = min(charges_now + 1, GATE_ATK_MAX_CHARGES)
                        run("UPDATE characters SET ghost_atk_ts=?,ghost_atk_charges=? WHERE id=?",
                            (new_base, new_charges, c['id']))
                    world_log_add('system',
                        f'⚔️【与天相争】本小时天出【{heaven_num}】，{winners_now}名修士胜天！全服修士各获+1攻击机会！')
                    msg += f' 本小时已有{winners_now}人胜天，全服+1攻击机会！'
                    flash(msg, 'success')
                elif beat:
                    msg += f' 本小时共{winners_now}人胜天（满5人可触发全服奖励）。'
                    flash(msg, 'success')
                else:
                    flash(msg, 'info')
            return redirect(url_for('gate'))

        # ── 参悟法则 ──
        elif action == 'insight':
            law_type = request.form.get('law_type', '')
            ok, msg  = gate_do_insight(char['id'], law_type)
            flash(msg, 'success' if ok else 'error')
            return redirect(url_for('gate_laws'))

    # ── 计算每种法则碎片数量 ──
    shard_counts = {lt: _gate_count_shards(char['id'], lt) for lt in GATE_LAW_TYPES}
    my_insight   = q("SELECT law_type FROM gate_law_insights WHERE char_id=?",
                     (char['id'],), one=True)
    fighter      = _build_fighter_stats(char)
    heaven_num   = gate_heaven_current(ev['id'])
    contend_rolled, contend_my_num = gate_player_rolled_this_hour(char['id'], ev['id'])
    contend_slot = _heaven_hour_slot()
    contend_winners = 0
    if heaven_num is not None:
        row = q("""SELECT COUNT(*) cnt FROM gate_player_rolls
                   WHERE event_id=? AND hour_slot=? AND player_num>?""",
                (ev['id'], contend_slot, heaven_num), one=True)
        contend_winners = row['cnt'] if row else 0
    contend_history  = gate_heaven_history(ev['id'])
    today_str_disp = time.strftime('%Y-%m-%d', time.localtime())
    tianmo_row = q("SELECT attempts FROM gate_tianmo_attempts WHERE char_id=? AND day=?",
                   (char['id'], today_str_disp), one=True)
    tianmo_attempts_left = GATE_TIANMO_DAILY_LIMIT - (tianmo_row['attempts'] if tianmo_row else 0)
    core_ghosts_disp = [g for g in ghosts if g.get('name') != '天魔分身']
    tianmo_unlocked = len(defeated_set & {g['idx'] for g in core_ghosts_disp}) >= len(core_ghosts_disp)
    return render_template('gate.html',
        char=char, ev=ev, ghosts=ghosts, defeated_set=defeated_set,
        can_atk=can_atk, atk_cd_min=atk_cd // 60,
        atk_charges=gate_calc_atk_charges(char)[0], GATE_ATK_MAX_CHARGES=GATE_ATK_MAX_CHARGES,
        can_help=can_help,
        shard_counts=shard_counts, my_insight=my_insight,
        fighter=fighter,
        GATE_LAW_TYPES=GATE_LAW_TYPES, GATE_LAW_SHARDS_NEEDED=GATE_LAW_SHARDS_NEEDED,
        GATE_POLLUTION_CAP=GATE_POLLUTION_CAP,
        heaven_num=heaven_num, contend_rolled=contend_rolled, contend_my_num=contend_my_num,
        contend_winners=contend_winners, contend_history=contend_history,
        HEAVEN_CONTEND_WIN_THRESHOLD=HEAVEN_CONTEND_WIN_THRESHOLD,
        tianmo_unlocked=tianmo_unlocked, core_ghost_count=len(core_ghosts_disp),
        tianmo_attempts_left=tianmo_attempts_left, GATE_TIANMO_DAILY_LIMIT=GATE_TIANMO_DAILY_LIMIT,
        now_ts=now_ts, REALMS=REALMS)


@app.route('/game/gate/board', methods=['GET', 'POST'])
@login_required
def gate_board():
    char = me()
    ev   = get_gate_event()
    if not ev:
        flash('异世之门活动未开启。', 'info')
        return redirect(url_for('dashboard'))

    if request.method == 'POST':
        req_id = int(request.form.get('req_id', 0))
        req = q("SELECT * FROM gate_help_board WHERE id=? AND is_resolved=0", (req_id,), one=True)
        if not req:
            flash('该求援已被解决或不存在。', 'error')
            return redirect(url_for('gate_board'))
        if req['requester_id'] == char['id']:
            flash('不能帮助自己。', 'error')
            return redirect(url_for('gate_board'))
        can_atk, _ = gate_has_atk_chance(char)
        if not can_atk:
            flash('你的攻击机会已用尽，请等待冷却。', 'error')
            return redirect(url_for('gate_board'))

        # 拉取求救方的鬼魔池
        today_str = time.strftime('%Y-%m-%d', time.localtime())
        pool = q("""SELECT * FROM gate_ghost_pool
            WHERE char_id=? AND event_id=? AND day=?""",
            (req['requester_id'], ev['id'], today_str), one=True)
        if not pool:
            flash('对方今日尚无鬼魔记录。', 'error')
            return redirect(url_for('gate_board'))

        ghosts   = json.loads(pool['ghosts_json'] or '[]')
        defeated = set(json.loads(pool['defeated_ids'] or '[]'))
        ghost    = next((g for g in ghosts if g['idx'] == req['ghost_idx']), None)
        if not ghost or req['ghost_idx'] in defeated:
            run("UPDATE gate_help_board SET is_resolved=1 WHERE id=?", (req_id,))
            flash('该鬼魔已被击败。', 'info')
            return redirect(url_for('gate_board'))

        # 消耗帮助者的攻击机会（累计制）
        charges_now, _, new_base = gate_calc_atk_charges(char)
        run("UPDATE characters SET ghost_atk_ts=?, ghost_atk_charges=? WHERE id=?",
            (new_base, max(0, charges_now - 1), char['id']))

        # 战斗模拟（含全部加成）
        helper_wins, _, ghost_hp_left = _gate_fight(char, ghost, _build_fighter_stats(char)['hp'])

        requester = q("SELECT name FROM characters WHERE id=?",
                      (req['requester_id'],), one=True)
        req_name  = requester['name'] if requester else '道友'

        if helper_wins:
            ghost['hp'] = 0
            ghost['defeated'] = True
            new_defeated = list(defeated | {req['ghost_idx']})
            for g in ghosts:
                if g['idx'] == req['ghost_idx']:
                    g['hp'] = 0
                    g['defeated'] = True
            run("""UPDATE gate_ghost_pool SET ghosts_json=?, defeated_ids=?
                   WHERE char_id=? AND event_id=? AND day=?""",
                (json.dumps(ghosts), json.dumps(new_defeated),
                 req['requester_id'], ev['id'], today_str))
            run("UPDATE gate_help_board SET is_resolved=1, helper_id=?, resolved_at=? WHERE id=?",
                (char['id'], now_ts(), req_id))
            # 奖励给被救者（灵石 + 随机碎片）
            run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
                (ghost['stones'], req['requester_id']))
            shard_got = 0
            if random.random() < ghost.get('shard_chance', 0.30):
                shard_got = random.randint(1, ghost.get('shard_max', 1))
                _gate_give_shard(req['requester_id'], ghost['law'], shard_got)
            shard_mail = f'、{ghost["law"]}法则碎片 {shard_got} 片' if shard_got else ''
            bonus_mail = _gate_daily_clear_bonus(req['requester_id'], len(defeated), len(new_defeated), len(ghosts))
            send_system_mail(req['requester_id'], '⚔ 道友援手',
                f'【{char["name"]}】为你击退了【{ghost["icon"]}{ghost["name"]}】！\n'
                f'已为你结算奖励：灵石 {ghost["stones"]} 枚{shard_mail}{bonus_mail}。',
                stones=0)
            log(char['id'], 'combat',
                f'援助【{req_name}】，击退【{ghost["icon"]}{ghost["name"]}】。')
            flash(f'成功援助【{req_name}】！击退了【{ghost["icon"]}{ghost["name"]}】。', 'success')
        else:
            # 援助失败：保存对鬼造成的伤害
            for g in ghosts:
                if g['idx'] == req['ghost_idx']:
                    g['hp'] = ghost_hp_left
            run("""UPDATE gate_ghost_pool SET ghosts_json=?
                   WHERE char_id=? AND event_id=? AND day=?""",
                (json.dumps(ghosts), req['requester_id'], ev['id'], today_str))
            flash(f'援助失败，未能击退【{ghost["icon"]}{ghost["name"]}】，但已造成一定伤害。', 'error')
        return redirect(url_for('gate_board'))

    # ── GET：展示全服求援板 ──
    requests = q("""SELECT ghb.*, c.name as req_name, c.realm_idx as req_realm
        FROM gate_help_board ghb
        JOIN characters c ON c.id=ghb.requester_id
        WHERE ghb.event_id=? AND ghb.is_resolved=0
        ORDER BY ghb.posted_at DESC LIMIT 50""", (ev['id'],))
    can_atk, atk_cd = gate_has_atk_chance(char)
    return render_template('gate_board.html',
        char=char, ev=ev, requests=requests,
        can_atk=can_atk, atk_cd_min=atk_cd // 60, REALMS=REALMS)


