# ── 子嗣 ───────────────────────────────────────────────────────────────────────

def _calc_boost_charges(char, boost_limit):
    """计算当前可用强化次数（累计制：每过一个冷却周期自动叠加，上限 7*limit）。"""
    stored   = char.get('offspring_boost_used') or 0  # 字段复用：存剩余次数
    boost_at = char.get('offspring_boost_at') or 0
    if boost_at == 0:
        # 首次：初始化为满额
        return boost_limit, now_ts()
    elapsed  = now_ts() - boost_at
    periods  = int(elapsed // OFFSPRING_BOOST_COOLDOWN)
    new_at   = boost_at + periods * OFFSPRING_BOOST_COOLDOWN
    charges  = min(stored + periods * boost_limit, 7 * boost_limit)
    return charges, new_at


def _do_offspring_boost(char, kids):
    """强化子嗣灵根：合欢修4级解锁，次数累计，需与父母一方好感≥300。"""
    kid_id = int(request.form.get('boost_kid_id', 0))
    kid    = next((k for k in kids if k['id'] == kid_id), None)
    if not kid:
        flash('无效的子嗣', 'error'); return

    # 合欢修等级检查
    if not char.get('heqing_token_id'):
        flash('此功能仅限合欢修使用', 'error'); return
    hq_lv, _, _, _, _ = heqing_level_info(char)
    if hq_lv < 4:
        flash('需合欢修等级【天人双修】（4级）方可强化子嗣', 'error'); return

    # 累计次数检查
    boost_limit = 10 if hq_lv >= 5 else 5
    charges, new_at = _calc_boost_charges(char, boost_limit)
    if charges <= 0:
        next_tick = new_at + OFFSPRING_BOOST_COOLDOWN
        secs_left = max(0, next_tick - now_ts())
        h, m = secs_left // 3600, (secs_left % 3600) // 60
        flash(f'强化次数已耗尽，还需 {h}h{m}m 积累下一次', 'error'); return

    # 灵根上限检查
    cur_root = kid['spirit_root']
    if cur_root not in OFFSPRING_BOOST_RATE:
        flash('此子嗣灵根已是天灵根，无法再强化', 'error'); return

    # 好感检查（与父母一方≥300，自己是父母之一则自动满足）
    pa, pb = kid['parent_a'], kid['parent_b']
    if char['id'] in (pa, pb):
        af_ok = True
        af_desc = '（你是该子嗣的父母）'
    else:
        def _affinity(a, b):
            lo, hi = min(a, b), max(a, b)
            row = q("SELECT affinity FROM relationships WHERE char_a=? AND char_b=?", (lo, hi), one=True)
            return row['affinity'] if row else 0
        af_a = _affinity(char['id'], pa)
        af_b = _affinity(char['id'], pb)
        af_ok = af_a >= OFFSPRING_BOOST_AFFINITY or af_b >= OFFSPRING_BOOST_AFFINITY
        af_desc = f'当前分别为 {af_a} / {af_b}'
    if not af_ok:
        flash(f'需与子嗣的父母一方好感度≥{OFFSPRING_BOOST_AFFINITY}，{af_desc}', 'error'); return

    # 灵力检查
    energy = cur_energy(char)
    if energy < OFFSPRING_BOOST_ENERGY:
        flash(f'灵力不足（需 {OFFSPRING_BOOST_ENERGY}，当前 {energy}）', 'error'); return

    # 扣灵力、扣次数
    set_energy(char['id'], energy - OFFSPRING_BOOST_ENERGY)
    run("UPDATE characters SET offspring_boost_at=?, offspring_boost_used=? WHERE id=?",
        (new_at, charges - 1, char['id']))

    # 判定成功
    rate     = OFFSPRING_BOOST_RATE[cur_root]
    success  = random.random() < rate
    idx      = SPIRIT_ROOT_CHAIN.index(cur_root)
    next_root = SPIRIT_ROOT_CHAIN[idx + 1]

    # 合欢经验
    new_hq_exp = (char.get('heqing_exp') or 0) + OFFSPRING_BOOST_EXP
    new_hq_lv  = 0
    for i, lvl in enumerate(HEQING_LEVELS):
        if new_hq_exp >= lvl['exp']: new_hq_lv = i
    run("UPDATE characters SET heqing_exp=?, heqing_level=? WHERE id=?",
        (new_hq_exp, new_hq_lv, char['id']))

    if success:
        run("UPDATE offspring SET spirit_root=?, boost_at=? WHERE id=?",
            (next_root, now_ts(), kid_id))
        log(char['id'], 'social',
            f'强化子嗣【{kid["name"]}】灵根成功：{cur_root}→{next_root}，获合欢经验 {OFFSPRING_BOOST_EXP}。')
        flash(f'✨ 强化成功！【{kid["name"]}】灵根由 {cur_root} 晋升为 {next_root}！获合欢经验 +{OFFSPRING_BOOST_EXP}', 'success')
    else:
        log(char['id'], 'social',
            f'强化子嗣【{kid["name"]}】灵根失败（{cur_root}），获合欢经验 {OFFSPRING_BOOST_EXP}。')
        flash(f'强化失败，【{kid["name"]}】灵根仍为 {cur_root}。获合欢经验 +{OFFSPRING_BOOST_EXP}', 'warning')


@app.route('/game/offspring', methods=['GET','POST'])
@login_required
def offspring():
    char   = me()
    # 收集所有道侣
    all_daolv_ids = [char.get(f) for f in ('daolv_id','daolv2_id','daolv3_id') if char.get(f)]
    all_daolvs = []
    for did in all_daolv_ids:
        row = q("SELECT * FROM characters WHERE id=?", (did,), one=True)
        if row:
            all_daolvs.append(dict(row))
    daolv = all_daolvs[0] if all_daolvs else None  # 向后兼容

    kids   = q("""SELECT * FROM offspring
        WHERE (parent_a=? OR parent_b=?) ORDER BY conceived_at""",
        (char['id'], char['id']))
    mature_kids = [k for k in kids if k['is_matured']]
    growing_kids = [k for k in kids if not k['is_matured']]

    if request.method == 'POST':
        action = request.form.get('action')
        if action == 'conceive':
            # 确定目标道侣
            target_id = int(request.form.get('target_daolv_id', 0))
            if target_id and target_id in all_daolv_ids:
                target_daolv = next((d for d in all_daolvs if d['id'] == target_id), None)
            else:
                target_daolv = daolv  # 默认第一个
            if not target_daolv:
                flash('需有道侣方可孕育子嗣', 'error')
            elif char['realm_idx'] < 9 or target_daolv['realm_idx'] < 9:
                flash('双方需至少达到筑基方可孕育子嗣', 'error')
            elif len(kids) >= MAX_OFFSPRING:
                flash(f'子嗣已达上限（{MAX_OFFSPRING}），无法再孕育', 'error')
            else:
                has_perk = perk_total(char['id'], 'offspring_bonus') > 0
                new_root  = inherit_spirit_root(char['spirit_root'], target_daolv['spirit_root'], has_perk)
                # 五行：各取一个父母的属性组合
                pa_elem = random.choice(char_elements(char) or ['木'])
                pb_elem = random.choice(char_elements(target_daolv) or ['火'])
                elems   = list({pa_elem, pb_elem})
                mature_ts = now_ts() + OFFSPRING_MATURE_SECS
                run("""INSERT INTO offspring (parent_a,parent_b,name,spirit_root,elements,conceived_at,matures_at)
                    VALUES (?,?,?,?,?,?,?)""",
                    (char['id'], target_daolv['id'], '无名', new_root, json.dumps(elems),
                     now_ts(), mature_ts))
                bonus = int(OFFSPRING_ROOT_BONUS.get(new_root, 0.03) * 100)
                log(char['id'], 'social',
                    f'与【{target_daolv["name"]}】孕育子嗣，灵根{new_root}，1天后成人，届时修炼 +{bonus}%。')
                world_log_add('offspring', f'【{char["name"]}】与【{target_daolv["name"]}】喜得子嗣！')
                flash(f'子嗣即将诞生！灵根：{new_root}（{bonus}% 修炼加成），1天后成人。', 'success')
                kids = q("SELECT * FROM offspring WHERE (parent_a=? OR parent_b=?) ORDER BY conceived_at",
                         (char['id'], char['id']))
                growing_kids = [k for k in kids if not k['is_matured']]
        elif action == 'rename':
            kid_id = int(request.form.get('kid_id', 0))
            name   = request.form.get('name', '').strip()[:8]
            if name and any(k['id'] == kid_id for k in kids):
                run("UPDATE offspring SET name=? WHERE id=?", (name, kid_id))
                flash(f'已命名为【{name}】', 'success')
                kids = q("SELECT * FROM offspring WHERE (parent_a=? OR parent_b=?) ORDER BY conceived_at",
                         (char['id'], char['id']))
                mature_kids = [k for k in kids if k['is_matured']]
                growing_kids = [k for k in kids if not k['is_matured']]
        elif action == 'boost_offspring':
            _do_offspring_boost(char, kids)
            char = me()
            kids = q("SELECT * FROM offspring WHERE (parent_a=? OR parent_b=?) ORDER BY conceived_at",
                     (char['id'], char['id']))
            mature_kids  = [k for k in kids if k['is_matured']]
            growing_kids = [k for k in kids if not k['is_matured']]
        elif action == 'use_yingluo':
            kid_id = int(request.form.get('boost_kid_id', 0))
            kid = next((k for k in kids if k['id'] == kid_id), None)
            if not kid:
                flash('无效的子嗣', 'error')
            else:
                cur_root = kid['spirit_root']
                if cur_root not in OFFSPRING_BOOST_RATE:
                    flash('此子嗣灵根已是混元灵根，无法再强化', 'error')
                else:
                    yl_item = q("SELECT id FROM items WHERE name='七彩璎珞'", one=True)
                    yl_inv  = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                                (char['id'], yl_item['id'] if yl_item else -1), one=True) if yl_item else None
                    if not yl_inv or yl_inv['quantity'] < 1:
                        flash('背包中没有七彩璎珞', 'error')
                    else:
                        energy_now = cur_energy(char)
                        if energy_now < OFFSPRING_BOOST_ENERGY:
                            flash(f'灵力不足（需 {OFFSPRING_BOOST_ENERGY}，当前 {energy_now}）', 'error')
                        else:
                            # 消耗璎珞
                            if yl_inv['quantity'] <= 1:
                                run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], yl_item['id']))
                            else:
                                run("UPDATE inventory SET quantity=quantity-1 WHERE char_id=? AND item_id=?",
                                    (char['id'], yl_item['id']))
                            set_energy(char['id'], energy_now - OFFSPRING_BOOST_ENERGY)
                            rate = OFFSPRING_BOOST_RATE[cur_root]
                            success = random.random() < rate
                            new_exp = (char.get('heqing_exp') or 0) + OFFSPRING_BOOST_EXP
                            new_lv  = max(i for i, lvl in enumerate(HEQING_LEVELS) if new_exp >= lvl['exp']) if char.get('heqing_token_id') else 0
                            if char.get('heqing_token_id'):
                                run("UPDATE characters SET heqing_exp=?, heqing_level=? WHERE id=?",
                                    (new_exp, new_lv, char['id']))
                            if success:
                                idx = SPIRIT_ROOT_CHAIN.index(cur_root)
                                new_root = SPIRIT_ROOT_CHAIN[idx + 1]
                                run("UPDATE offspring SET spirit_root=? WHERE id=?", (new_root, kid_id))
                                log(char['id'], 'social',
                                    f'使用七彩璎珞强化子嗣【{kid["name"]}】灵根，{cur_root}→{new_root}！')
                                flash(f'七彩璎珞光芒大盛！【{kid["name"]}】灵根由{cur_root}晋升为{new_root}！', 'success')
                            else:
                                log(char['id'], 'social',
                                    f'使用七彩璎珞强化子嗣【{kid["name"]}】失败，灵根仍为{cur_root}。')
                                flash(f'七彩璎珞光芒散去，【{kid["name"]}】灵根未有变化（{cur_root}），璎珞已消耗。', 'error')
                            char = me()
                            kids = q("SELECT * FROM offspring WHERE (parent_a=? OR parent_b=?) ORDER BY conceived_at",
                                     (char['id'], char['id']))
                            mature_kids  = [k for k in kids if k['is_matured']]
                            growing_kids = [k for k in kids if not k['is_matured']]

    # 计算合欢修等级与子嗣强化额度
    hq_lv = 0
    boost_limit = 0
    if char.get('heqing_token_id'):
        hq_lv, _, _, _, _ = heqing_level_info(char)
        if hq_lv >= 5:
            boost_limit = 10
        elif hq_lv >= 4:
            boost_limit = 5
    # 累计次数计算
    boost_at = 0
    if boost_limit > 0:
        boost_remain, boost_at = _calc_boost_charges(char, boost_limit)
    else:
        boost_remain = 0
    # 七彩璎珞库存
    yl_item = q("SELECT id FROM items WHERE name='七彩璎珞'", one=True)
    yl_count = 0
    if yl_item:
        yl_inv = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                   (char['id'], yl_item['id']), one=True)
        yl_count = yl_inv['quantity'] if yl_inv else 0

    return render_template('offspring.html', char=char, daolv=daolv,
        all_daolvs=all_daolvs,
        mature_kids=mature_kids, growing_kids=growing_kids,
        total=len(kids), MAX_OFFSPRING=MAX_OFFSPRING,
        OFFSPRING_ROOT_BONUS=OFFSPRING_ROOT_BONUS,
        hq_lv=hq_lv, boost_limit=boost_limit, boost_remain=boost_remain,
        boost_at=boost_at, OFFSPRING_BOOST_COOLDOWN=OFFSPRING_BOOST_COOLDOWN,
        OFFSPRING_BOOST_ENERGY=OFFSPRING_BOOST_ENERGY,
        OFFSPRING_BOOST_EXP=OFFSPRING_BOOST_EXP,
        OFFSPRING_BOOST_AFFINITY=OFFSPRING_BOOST_AFFINITY,
        OFFSPRING_BOOST_RATE=OFFSPRING_BOOST_RATE,
        SPIRIT_ROOT_CHAIN=SPIRIT_ROOT_CHAIN,
        yl_count=yl_count)

# ── 宗门 ───────────────────────────────────────────────────────────────────────

def send_system_mail(to_char_id, subject, body, item_id=None, item_qty=0, stones=0, lingfu=0, exp=0):
    run("""INSERT INTO mail (from_char,to_char,subject,body,item_id,item_qty,stones,lingfu,exp,created_at)
           VALUES (0,?,?,?,?,?,?,?,?,?)""",
        (to_char_id, subject, body, item_id, item_qty, stones, lingfu, exp, now_ts()))


def _tournament_sect_name(tid):
    t = q("SELECT sect_id FROM sect_tournaments WHERE id=?", (tid,), one=True)
    if not t:
        return '未知宗门'
    row = q("SELECT name FROM sects WHERE id=?", (t['sect_id'],), one=True)
    return row['name'] if row else '未知宗门'


def _generate_round(tid, char_ids, round_num):
    """随机配对本轮选手，奇数末位轮空直接晋级。"""
    players = list(char_ids)
    random.shuffle(players)
    expires_at = now_ts() + TOURNAMENT_MATCH_TIMEOUT_SECS
    for i in range(0, len(players), 2):
        a = players[i]
        if i + 1 < len(players):
            b = players[i + 1]
            run("""INSERT INTO sect_tournament_matches
                   (tournament_id,round_num,match_num,char_a,char_b,status,expires_at,created_at)
                   VALUES (?,?,?,?,?,'pending',?,?)""",
                (tid, round_num, i // 2 + 1, a, b, expires_at, now_ts()))
        else:
            run("""INSERT INTO sect_tournament_matches
                   (tournament_id,round_num,match_num,char_a,char_b,overall_winner,status,expires_at,created_at)
                   VALUES (?,?,?,?,0,?,'done',?,?)""",
                (tid, round_num, i // 2 + 1, a, a, expires_at, now_ts()))
            send_system_mail(a, '宗门大比·轮空', f'第 {round_num} 轮你获得轮空，直接晋级下一轮！')


def _execute_match(match_id):
    """执行比赛（两局制），更新结果，返回 overall_winner char_id。"""
    m = q("SELECT * FROM sect_tournament_matches WHERE id=?", (match_id,), one=True)
    if not m or m['status'] != 'pending':
        return None
    _ca = q("SELECT * FROM characters WHERE id=?", (m['char_a'],), one=True)
    _cb = q("SELECT * FROM characters WHERE id=?", (m['char_b'],), one=True)
    if not _ca or not _cb:
        return None
    ca = dict(_ca)
    cb = dict(_cb)

    a_wins, b_wins, dmg_a, dmg_b = simulate_pvp_detailed(ca, cb)
    g1_a = 1 if a_wins >= 1 else 0
    g2_a = 1 if a_wins == 2 else 0

    if a_wins > b_wins:
        winner = m['char_a']
    elif b_wins > a_wins:
        winner = m['char_b']
    else:
        winner = m['char_a'] if dmg_a >= dmg_b else m['char_b']

    run("""UPDATE sect_tournament_matches
           SET game1_a_won=?, game1_dmg_a=?, game1_dmg_b=?,
               game2_a_won=?, game2_dmg_a=?, game2_dmg_b=?,
               overall_winner=?, status='done'
           WHERE id=?""",
        (g1_a, dmg_a // 2, dmg_b // 2,
         g2_a, dmg_a - dmg_a // 2, dmg_b - dmg_b // 2,
         winner, match_id))
    return winner


def _advance_tournament(tid, round_num):
    """本轮全部结束后推进下一轮或结算。"""
    pending = q("""SELECT COUNT(*) n FROM sect_tournament_matches
                   WHERE tournament_id=? AND round_num=? AND status='pending'""",
                (tid, round_num), one=True)['n']
    if pending > 0:
        return

    winners = [r['overall_winner'] for r in
               q("SELECT overall_winner FROM sect_tournament_matches WHERE tournament_id=? AND round_num=?",
                 (tid, round_num))]
    sect_name = _tournament_sect_name(tid)

    if len(winners) <= 1:
        _finish_knockout(tid, winners, round_num, sect_name)
    else:
        next_round = round_num + 1
        run("UPDATE sect_tournaments SET current_round=? WHERE id=?", (next_round, tid))
        _generate_round(tid, winners, next_round)
        world_log_add('sect', f'「{sect_name}」宗门大比第 {round_num} 轮结束，第 {next_round} 轮对阵已公布！')


def _finish_knockout(tid, final_winners, total_rounds, sect_name):
    """颁奖并关闭大比。"""
    pool = list(TOURNAMENT_PRIZE_POOL)
    random.shuffle(pool)
    drawn = sorted(pool[:3], key=lambda x: x['weight'], reverse=True)

    # 按被淘汰轮次排名，晚出局排名靠前
    eliminated_in = {}
    for r in q("""SELECT round_num, char_a, char_b, overall_winner
                  FROM sect_tournament_matches WHERE tournament_id=? ORDER BY round_num""", (tid,)):
        if r['char_b'] == 0:
            continue
        loser = r['char_a'] if r['overall_winner'] == r['char_b'] else r['char_b']
        eliminated_in[loser] = r['round_num']
    if final_winners:
        eliminated_in[final_winners[0]] = total_rounds + 1

    sorted_chars = sorted(eliminated_in.keys(), key=lambda c: -eliminated_in[c])
    result = []
    for rank, char_id in enumerate(sorted_chars, 1):
        c = q("SELECT name FROM characters WHERE id=?", (char_id,), one=True)
        result.append({'rank': rank, 'char_id': char_id, 'name': c['name'] if c else '?'})

    rank_labels      = {1: '🥇 魁首', 2: '🥈 亚军', 3: '🥉 季军'}
    rank_base_stones = {1: 5000, 2: 3000, 3: 1500, 4: 800, 5: 400}

    for entry in result:
        rank    = entry['rank']
        char_id = entry['char_id']
        if rank <= 3:
            prize    = drawn[rank - 1]
            stones   = rank_base_stones.get(rank, 200)
            item_row = q("SELECT id FROM items WHERE name=?", (prize['name'],), one=True)
            item_id  = item_row['id'] if item_row else None
            send_system_mail(char_id, f'宗门大比·{rank_labels[rank]}',
                f'恭喜你在「{sect_name}」宗门大比中荣获{rank_labels[rank]}！\n奖励：【{prize["name"]}】×1、{stones} 灵石。',
                item_id=item_id, item_qty=1, stones=stones)
        else:
            stones = rank_base_stones.get(rank, 200)
            send_system_mail(char_id, f'宗门大比·第 {rank} 名',
                f'你在「{sect_name}」宗门大比中位列第 {rank} 名，获得 {stones} 灵石。',
                stones=stones)

    run("UPDATE sect_tournaments SET status='done', result_json=?, prizes_json=? WHERE id=?",
        (json.dumps(result, ensure_ascii=False),
         json.dumps([p['name'] for p in drawn], ensure_ascii=False), tid))
    winner_name = result[0]['name'] if result else '无'
    world_log_add('sect', f'「{sect_name}」宗门大比落幕，【{winner_name}】荣获魁首！')


def resolve_tournament(tid):
    """报名期结束后启动淘汰赛。"""
    t = q("SELECT * FROM sect_tournaments WHERE id=?", (tid,), one=True)
    if not t or t['status'] != 'signup':
        return
    entries = q("""SELECT c.id FROM sect_tournament_entries te
                   JOIN characters c ON c.id=te.char_id
                   WHERE te.tournament_id=?""", (tid,))
    char_ids = [r['id'] for r in entries]
    sect_name = _tournament_sect_name(tid)

    if len(char_ids) < TOURNAMENT_MIN_PLAYERS:
        run("UPDATE sect_tournaments SET status='cancelled' WHERE id=?", (tid,))
        run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
            (TOURNAMENT_COST, t['started_by']))
        send_system_mail(t['started_by'], '宗门大比流局',
            f'「{sect_name}」大比报名人数不足（至少需要 {TOURNAMENT_MIN_PLAYERS} 人），已流局，退还 {TOURNAMENT_COST} 灵石。',
            stones=TOURNAMENT_COST)
        world_log_add('sect', f'「{sect_name}」宗门大比因人数不足流局。')
        return

    run("UPDATE sect_tournaments SET status='group', current_round=1 WHERE id=?", (tid,))
    _generate_round(tid, char_ids, 1)
    world_log_add('sect', f'「{sect_name}」宗门大比正式开始！第一轮对阵已公布，请参赛者前往宗门页出战。')


@app.route('/game/sect', methods=['GET','POST'])
@login_required
def sect():
    char     = me()
    my_sect  = get_char_sect(char['id'])
    # 收到的邀请（type='invite'，to_char=自己）
    pending_invites = q("""SELECT si.*, s.name as sect_name, c.name as from_name
        FROM sect_invites si
        JOIN sects s ON s.id=si.sect_id
        JOIN characters c ON c.id=si.from_char
        WHERE si.to_char=? AND si.status='pending' AND (si.type='invite' OR si.type IS NULL)""",
        (char['id'],))
    # 宗门内：待审核的申请（type='apply'，sect_id=我的宗门）
    pending_applications = []
    if my_sect and my_sect['rank'] in ('leader','elder'):
        pending_applications = q("""SELECT si.*, c.name as applicant_name,
            c.realm_idx as applicant_realm, c.spirit_root as applicant_root
            FROM sect_invites si JOIN characters c ON c.id=si.from_char
            WHERE si.sect_id=? AND si.status='pending' AND si.type='apply'
            ORDER BY si.created_at""", (my_sect['id'],))

    if request.method == 'POST':
        action = request.form.get('action')

        if action == 'create' and not my_sect:
            name = request.form.get('name','').strip()[:20]
            desc = request.form.get('description','').strip()[:100]
            emblem = request.form.get('emblem','🏯').strip()[:2]
            if not name:
                flash('宗门名不能为空', 'error')
            elif q("SELECT 1 FROM sects WHERE name=?", (name,), one=True):
                flash('宗门名已被使用', 'error')
            elif char['spirit_stones'] < SECT_CREATE_COST:
                flash(f'灵石不足，创建宗门需 {SECT_CREATE_COST} 灵石', 'error')
            else:
                run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?", (SECT_CREATE_COST, char['id']))
                db = get_db()
                cur = db.execute("INSERT INTO sects (name,description,emblem,leader_id,created_at) VALUES (?,?,?,?,?)",
                    (name, desc, emblem or '🏯', char['id'], now_ts()))
                sid = cur.lastrowid
                db.execute("INSERT INTO sect_members (sect_id,char_id,rank,joined_at) VALUES (?,?,'leader',?)",
                    (sid, char['id'], now_ts()))
                db.commit()
                world_log_add('sect', f'【{char["name"]}】创立宗门「{name}」！')
                log(char['id'], 'social', f'创立宗门「{name}」，招募道友共修大道。')
                flash(f'宗门「{name}」创立成功！', 'success')
                my_sect = get_char_sect(char['id'])

        elif action == 'apply' and not my_sect:
            # 主动申请加入某宗门
            sect_id = int(request.form.get('sect_id', 0))
            target_sect = q("SELECT * FROM sects WHERE id=?", (sect_id,), one=True)
            if not target_sect:
                flash('宗门不存在', 'error')
            elif q("SELECT COUNT(*) n FROM sect_members WHERE sect_id=?", (sect_id,), one=True)['n'] >= sect_capacity(sect_id):
                flash('该宗门已满员', 'error')
            elif q("SELECT 1 FROM sect_invites WHERE sect_id=? AND from_char=? AND status='pending' AND type='apply'",
                   (sect_id, char['id']), one=True):
                flash('已提交申请，请等待审核', 'error')
            else:
                run("""INSERT INTO sect_invites (sect_id,from_char,to_char,type,created_at)
                    VALUES (?,?,?,?,?)""", (sect_id, char['id'], target_sect['leader_id'], 'apply', now_ts()))
                leader = q("SELECT name FROM characters WHERE id=?", (target_sect['leader_id'],), one=True)
                log(char['id'], 'social', f'向宗门「{target_sect["name"]}」提交了入宗申请。')
                log(target_sect['leader_id'], 'social',
                    f'【{char["name"]}】申请加入「{target_sect["name"]}」，请前往宗门页面审核。')
                flash(f'已向「{target_sect["name"]}」提交申请，等待宗主/长老审核', 'success')

        elif action == 'approve_apply' and my_sect and my_sect['rank'] in ('leader','elder'):
            inv_id = int(request.form.get('inv_id', 0))
            inv = q("SELECT * FROM sect_invites WHERE id=? AND sect_id=? AND status='pending' AND type='apply'",
                    (inv_id, my_sect['id']), one=True)
            if not inv:
                flash('申请不存在', 'error')
            elif q("SELECT COUNT(*) n FROM sect_members WHERE sect_id=?", (my_sect['id'],), one=True)['n'] >= sect_capacity(my_sect['id']):
                flash(f'宗门已满员（当前上限 {sect_capacity(my_sect["id"])} 人）', 'error')
            elif get_char_sect(inv['from_char']):
                run("UPDATE sect_invites SET status='declined' WHERE id=?", (inv_id,))
                flash('该修士已加入其他宗门', 'error')
            else:
                run("UPDATE sect_invites SET status='accepted' WHERE id=?", (inv_id,))
                run("INSERT OR IGNORE INTO sect_members (sect_id,char_id,rank,joined_at) VALUES (?,?,'member',?)",
                    (my_sect['id'], inv['from_char'], now_ts()))
                applicant = q("SELECT name FROM characters WHERE id=?", (inv['from_char'],), one=True)
                log(inv['from_char'], 'social', f'申请通过！已加入宗门「{my_sect["name"]}」。')
                world_log_add('sect', f'【{applicant["name"]}】加入宗门「{my_sect["name"]}」。')
                flash(f'已批准【{applicant["name"]}】的入宗申请', 'success')

        elif action == 'reject_apply' and my_sect and my_sect['rank'] in ('leader','elder'):
            inv_id = int(request.form.get('inv_id', 0))
            run("UPDATE sect_invites SET status='declined' WHERE id=? AND sect_id=? AND type='apply'",
                (inv_id, my_sect['id']))
            flash('已拒绝该申请', 'info')

        elif action == 'invite' and my_sect and my_sect['rank'] in ('leader','elder'):
            target_name = request.form.get('target_name','').strip()
            target = q("SELECT id FROM characters WHERE name=? AND is_npc=0 AND status='alive'", (target_name,), one=True)
            if not target:
                flash('未找到该修士', 'error')
            elif get_char_sect(target['id']):
                flash('对方已有宗门', 'error')
            elif q("SELECT COUNT(*) n FROM sect_members WHERE sect_id=?", (my_sect['id'],), one=True)['n'] >= sect_capacity(my_sect['id']):
                flash(f'宗门已满员（当前上限 {sect_capacity(my_sect["id"])} 人）', 'error')
            else:
                run("""INSERT INTO sect_invites (sect_id,from_char,to_char,created_at)
                    VALUES (?,?,?,?)""", (my_sect['id'], char['id'], target['id'], now_ts()))
                log(target['id'], 'social', f'「{my_sect["name"]}」宗门邀请你加入！')
                flash(f'已向【{target_name}】发出入宗邀请', 'success')

        elif action == 'accept_invite':
            inv_id = int(request.form.get('inv_id', 0))
            inv = q("SELECT * FROM sect_invites WHERE id=? AND to_char=? AND status='pending'", (inv_id, char['id']), one=True)
            if inv:
                # 检查是否被该宗门冷却禁止
                ban = q("SELECT ban_until FROM sect_join_cooldowns WHERE char_id=? AND sect_id=? AND ban_until>?",
                        (char['id'], inv['sect_id'], now_ts()), one=True)
                if ban:
                    secs = ban['ban_until'] - now_ts()
                    flash(f'你被此宗门遣返过，需冷却 {secs//3600}h{(secs%3600)//60}m 才可重新加入。', 'error')
                else:
                    run("UPDATE sect_invites SET status='accepted' WHERE id=?", (inv_id,))
                    run("INSERT OR IGNORE INTO sect_members (sect_id,char_id,rank,joined_at) VALUES (?,?,'member',?)",
                        (inv['sect_id'], char['id'], now_ts()))
                    s = q("SELECT name FROM sects WHERE id=?", (inv['sect_id'],), one=True)
                    log(char['id'], 'social', f'加入宗门「{s["name"]}」。')
                    world_log_add('sect', f'【{char["name"]}】加入宗门「{s["name"]}」。')
                    flash(f'已加入宗门「{s["name"]}」！', 'success')
                    my_sect = get_char_sect(char['id'])

        elif action == 'decline_invite':
            inv_id = int(request.form.get('inv_id', 0))
            run("UPDATE sect_invites SET status='declined' WHERE id=? AND to_char=?", (inv_id, char['id']))
            flash('已婉拒入宗邀请', 'info')

        elif action == 'post' and my_sect:
            content = request.form.get('content','').strip()[:200]
            if content:
                run("INSERT INTO sect_posts (sect_id,char_id,content,created_at) VALUES (?,?,?,?)",
                    (my_sect['id'], char['id'], content, now_ts()))
                flash('留言成功', 'success')

        elif action == 'leave' and my_sect:
            if my_sect['rank'] == 'leader':
                flash('宗主不可离宗。请先转让宗主身份，或解散宗门。', 'error')
            else:
                run("DELETE FROM sect_members WHERE char_id=?", (char['id'],))
                # 退宗自动解除师徒关系
                active_ds = q("SELECT * FROM discipleships WHERE (shifu_id=? OR tudi_id=?) AND status='active'",
                               (char['id'], char['id']))
                for ds in active_ds:
                    other_id = ds['tudi_id'] if ds['shifu_id'] == char['id'] else ds['shifu_id']
                    run("UPDATE discipleships SET status='dismissed', graduated_at=? WHERE id=?",
                        (now_ts(), ds['id']))
                    log(other_id, 'social', f'【{char["name"]}】退出宗门，师徒缘分就此了结。')
                if active_ds:
                    log(char['id'], 'social', f'退出宗门「{my_sect["name"]}」，师徒关系同步解除。')
                else:
                    log(char['id'], 'social', f'退出宗门「{my_sect["name"]}」。')
                flash('已退出宗门', 'info')
                my_sect = None

        elif action == 'promote' and my_sect and my_sect['rank'] == 'leader':
            tid = int(request.form.get('target_id', 0))
            new_rank = request.form.get('new_rank', 'member')
            if new_rank in ('elder','member'):
                run("UPDATE sect_members SET rank=? WHERE sect_id=? AND char_id=?", (new_rank, my_sect['id'], tid))
                flash('成员身份已更新', 'success')

        elif action == 'kick' and my_sect and my_sect['rank'] == 'leader':
            tid = int(request.form.get('target_id', 0))
            target = q("SELECT c.name FROM sect_members sm JOIN characters c ON c.id=sm.char_id WHERE sm.sect_id=? AND sm.char_id=? AND sm.char_id!=? AND sm.rank!='leader'",
                       (my_sect['id'], tid, char['id']), one=True)
            if not target:
                flash('无法驱逐该成员', 'error')
            else:
                run("DELETE FROM sect_members WHERE sect_id=? AND char_id=?", (my_sect['id'], tid))
                for ds in q("SELECT * FROM discipleships WHERE (shifu_id=? OR tudi_id=?) AND status='active'", (tid, tid)):
                    other_id = ds['tudi_id'] if ds['shifu_id'] == tid else ds['shifu_id']
                    run("UPDATE discipleships SET status='dismissed', graduated_at=? WHERE id=?", (now_ts(), ds['id']))
                    log(other_id, 'social', f'宗门变故，与【{target["name"] if other_id != tid else char["name"]}】师徒缘分就此了结。')
                log(char['id'], 'social', f'将【{target["name"]}】逐出宗门「{my_sect["name"]}」。')
                log(tid, 'social', f'你被宗主【{char["name"]}】逐出宗门「{my_sect["name"]}」。')
                flash(f'已将【{target["name"]}】逐出宗门', 'info')

        elif action == 'transfer_leader' and my_sect and my_sect['rank'] == 'leader':
            tid = int(request.form.get('target_id', 0))
            target_member = q("SELECT 1 FROM sect_members WHERE sect_id=? AND char_id=? AND char_id!=?",
                              (my_sect['id'], tid, char['id']), one=True)
            if not target_member:
                flash('成员不存在', 'error')
            else:
                run("UPDATE sect_members SET rank='leader' WHERE sect_id=? AND char_id=?", (my_sect['id'], tid))
                run("UPDATE sects SET leader_id=? WHERE id=?", (tid, my_sect['id']))
                run("UPDATE sect_members SET rank='member' WHERE sect_id=? AND char_id=?", (my_sect['id'], char['id']))
                new_leader = q("SELECT name FROM characters WHERE id=?", (tid,), one=True)
                log(char['id'], 'social', f'将「{my_sect["name"]}」宗主之位传予【{new_leader["name"]}】。')
                log(tid, 'social', f'【{char["name"]}】将宗主之位传予你，你现在是「{my_sect["name"]}」的新宗主！')
                world_log_add('sect', f'「{my_sect["name"]}」宗主易主，【{new_leader["name"]}】接任宗主。')
                flash(f'已将宗主之位传予【{new_leader["name"]}】，你现在是普通门人', 'success')

        elif action == 'dissolve' and my_sect and my_sect['rank'] == 'leader':
            sid = my_sect['id']
            sname = my_sect['name']
            # 解散时所有成员的师徒关系也解除
            member_ids = [r['char_id'] for r in
                          q("SELECT char_id FROM sect_members WHERE sect_id=?", (sid,))]
            for mid in member_ids:
                ds_rows = q("SELECT * FROM discipleships WHERE (shifu_id=? OR tudi_id=?) AND status='active'",
                            (mid, mid))
                for ds in ds_rows:
                    run("UPDATE discipleships SET status='dismissed', graduated_at=? WHERE id=?",
                        (now_ts(), ds['id']))
            run("DELETE FROM sect_members WHERE sect_id=?", (sid,))
            run("DELETE FROM sect_posts WHERE sect_id=?", (sid,))
            run("DELETE FROM sect_invites WHERE sect_id=?", (sid,))
            run("DELETE FROM sects WHERE id=?", (sid,))
            world_log_add('sect', f'宗门「{sname}」宣告解散。')
            log(char['id'], 'social', f'解散宗门「{sname}」。')
            flash(f'宗门「{sname}」已解散', 'info')
            my_sect = None

        elif action in ('claim_sq', 'submit_sq', 'donate_sq'):
            qkey = request.form.get('quest_key', '')
            qdef = next((q_ for q_ in SECT_QUESTS if q_['key'] == qkey), None)
            if qdef and my_sect:
                now_dt    = datetime.now(TZ)
                this_week = f"{now_dt.year}-W{now_dt.strftime('%W')}"
                # 当前贡献品阶 → 可完成次数
                my_mem_row = q("SELECT cult_rank FROM sect_members WHERE char_id=? AND sect_id=?",
                               (char['id'], my_sect['id']), one=True)
                my_cr = my_mem_row['cult_rank'] if my_mem_row else 0
                quest_max = CULT_RANKS[my_cr]['quest_max']
                row = q("SELECT * FROM sect_quest_progress WHERE char_id=? AND quest_key=? AND period_date=?",
                        (char['id'], qkey, this_week), one=True)

                if action in ('submit_sq', 'donate_sq'):
                    # 材料/灵石上交：推进进度
                    is_unlimited = qdef.get('unlimited', False)
                    already_done = not is_unlimited and row and row['claimed'] and (row['claim_count'] >= quest_max)
                    if already_done:
                        flash('本周此任务已完成上限', 'error')
                    elif action == 'submit_sq' and qdef['type'] == 'submit':
                        iname = qdef['item']
                        it = q("SELECT * FROM items WHERE name=?", (iname,), one=True)
                        inv = q("SELECT quantity FROM inventory WHERE char_id=? AND item_id=?",
                                (char['id'], it['id']), one=True) if it else None
                        cur_prog = row['progress'] if row else 0
                        need = qdef['target'] - cur_prog
                        have = inv['quantity'] if inv else 0
                        give = min(have, need)
                        if give <= 0:
                            flash(f'没有可上交的{iname}', 'error')
                        else:
                            if inv['quantity'] <= give:
                                run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (char['id'], it['id']))
                            else:
                                run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?",
                                    (give, char['id'], it['id']))
                            new_prog = cur_prog + give
                            done = 1 if new_prog >= qdef['target'] else 0
                            if row:
                                run("UPDATE sect_quest_progress SET progress=?,completed=? WHERE id=?",
                                    (new_prog, done, row['id']))
                            else:
                                run("""INSERT INTO sect_quest_progress (char_id,quest_key,period_date,progress,completed,claimed,claim_count)
                                    VALUES (?,?,?,?,?,0,0)""", (char['id'], qkey, this_week, new_prog, done))
                            flash(f'上交{iname} ×{give}，进度 {new_prog}/{qdef["target"]}', 'success')
                    elif action == 'donate_sq' and qdef['type'] == 'donate':
                        cur_prog = row['progress'] if row else 0
                        need = qdef['target'] - cur_prog
                        give = min(char['spirit_stones'], need)
                        if give <= 0:
                            flash('灵石不足', 'error')
                        else:
                            run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?", (give, char['id']))
                            new_prog = cur_prog + give
                            done = 1 if new_prog >= qdef['target'] else 0
                            if row:
                                run("UPDATE sect_quest_progress SET progress=?,completed=? WHERE id=?",
                                    (new_prog, done, row['id']))
                            else:
                                run("""INSERT INTO sect_quest_progress (char_id,quest_key,period_date,progress,completed,claimed,claim_count)
                                    VALUES (?,?,?,?,?,0,0)""", (char['id'], qkey, this_week, new_prog, done))
                            flash(f'捐献灵石 {give}，进度 {new_prog}/{qdef["target"]}', 'success')
                    # 领取任务奖励
                elif action == 'claim_sq':
                    if not (row and row['completed'] and not row['claimed']):
                        flash('任务未完成或已领取', 'error')
                    else:
                        new_cnt = (row['claim_count'] or 0) + 1
                        is_unlimited = qdef.get('unlimited', False)
                        if is_unlimited or new_cnt < quest_max:
                            # 重置进度，允许再做
                            run("UPDATE sect_quest_progress SET claimed=0,completed=0,progress=0,claim_count=? WHERE id=?",
                                (new_cnt, row['id']))
                        else:
                            run("UPDATE sect_quest_progress SET claimed=1,claim_count=? WHERE id=?",
                                (new_cnt, row['id']))
                        run("UPDATE sect_members SET contribution=contribution+?, total_contribution=total_contribution+? WHERE char_id=? AND sect_id=?",
                            (qdef['reward_contrib'], qdef['reward_contrib'], char['id'], my_sect['id']))
                        if qdef['reward_stones'] > 0:
                            run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
                                (qdef['reward_stones'], char['id']))
                        # 累计宗门总贡献并检查升级
                        run("UPDATE sects SET total_contribution=total_contribution+? WHERE id=?",
                            (qdef['reward_contrib'], my_sect['id']))
                        _check_sect_level_up(my_sect['id'])
                        repeat_note = '（可继续捐献）' if is_unlimited else (f'（本周还可完成 {quest_max - new_cnt} 次）' if new_cnt < quest_max else '（本周已达上限）')
                        flash(f'宗门任务【{qdef["name"]}】完成！+{qdef["reward_contrib"]} 贡献 +{qdef["reward_stones"]} 灵石 {repeat_note}', 'success')
                        log(char['id'], 'social', f'完成宗门任务【{qdef["name"]}】，获得贡献 {qdef["reward_contrib"]} 点。')

        elif action == 'sect_exam':
            # 宗门修炼考核
            if my_sect:
                my_mem_row = q("SELECT cult_rank, exam_cooldown, total_contribution FROM sect_members WHERE char_id=? AND sect_id=?",
                               (char['id'], my_sect['id']), one=True)
                my_cr        = (my_mem_row['cult_rank'] or 0) if my_mem_row else 0
                cd_raw       = (my_mem_row['exam_cooldown'] or '') if my_mem_row else ''
                total_contrib = (my_mem_row['total_contribution'] or 0) if my_mem_row else 0
                today   = datetime.now(TZ).strftime('%Y-%m-%d')
                # cd_raw 格式：'YYYY-MM-DD:count'
                if ':' in cd_raw:
                    cd_date, cd_count = cd_raw.split(':', 1)
                    cd_count = int(cd_count) if cd_count.isdigit() else 0
                else:
                    cd_date, cd_count = cd_raw, 0
                today_count = cd_count if cd_date == today else 0
                next_cr = my_cr + 1
                if next_cr >= len(CULT_RANKS):
                    flash('已达最高品阶', 'error')
                elif today_count >= 2:
                    flash(f'今日考核次数已用完（每天2次），明日再来', 'error')
                else:
                    cr_def = CULT_RANKS[next_cr]
                    sect_lv = q("SELECT level FROM sects WHERE id=?", (my_sect['id'],), one=True)['level'] or 1
                    if sect_lv < cr_def['sect_lv_req']:
                        flash(f'宗门需达 {cr_def["sect_lv_req"]} 级方可考核【{cr_def["name"]}】', 'error')
                    elif char['realm_idx'] < cr_def['realm_req']:
                        flash(f'需达到【{REALMS[cr_def["realm_req"]]["name"]}】方可考核', 'error')
                    elif total_contrib < cr_def['contrib_req']:
                        flash(f'历史贡献不足（需 {cr_def["contrib_req"]}，当前 {total_contrib}），需继续为宗门效力', 'error')
                    elif random.random() < cr_def['exam_rate']:
                        new_cd = f'{today}:{today_count+1}'
                        run("UPDATE sect_members SET cult_rank=?, exam_cooldown=? WHERE char_id=? AND sect_id=?",
                            (next_cr, new_cd, char['id'], my_sect['id']))
                        flash(f'考核通过！晋升为【{cr_def["name"]}】！每日俸禄 +{cr_def["salary"]} 灵石', 'success')
                        log(char['id'], 'social', f'通过宗门考核，晋升【{cr_def["name"]}】。')
                    else:
                        new_cd = f'{today}:{today_count+1}'
                        run("UPDATE sect_members SET exam_cooldown=? WHERE char_id=? AND sect_id=?",
                            (new_cd, char['id'], my_sect['id']))
                        remain = 2 - (today_count + 1)
                        flash(f'考核失败！今日剩余 {remain} 次机会（成功率 {int(cr_def["exam_rate"]*100)}%）', 'error')

        elif action == 'set_peak':
            # 长老命名/修改自己的峰
            if my_sect:
                my_mem_row = q("SELECT cult_rank FROM sect_members WHERE char_id=? AND sect_id=?",
                               (char['id'], my_sect['id']), one=True)
                my_cr = (my_mem_row['cult_rank'] or 0) if my_mem_row else 0
                if my_cr < 3:
                    flash('需晋升为长老方可开峰', 'error')
                else:
                    pname = request.form.get('peak_name', '').strip()[:10]
                    if not pname:
                        flash('峰名不能为空', 'error')
                    else:
                        run("UPDATE sect_members SET peak_name=? WHERE char_id=? AND sect_id=?",
                            (pname, char['id'], my_sect['id']))
                        flash(f'【{pname}】已开设，弟子将归属此峰', 'success')
                        log(char['id'], 'social', f'开设宗门峰头【{pname}】。')

        elif action == 'claim_salary':
            # 领取每日俸禄
            if my_sect:
                my_mem_row = q("SELECT cult_rank, salary_claimed FROM sect_members WHERE char_id=? AND sect_id=?",
                               (char['id'], my_sect['id']), one=True)
                my_cr   = my_mem_row['cult_rank'] if my_mem_row else 0
                claimed = my_mem_row['salary_claimed'] if my_mem_row else ''
                today   = datetime.now(TZ).strftime('%Y-%m-%d')
                salary  = CULT_RANKS[my_cr]['salary']
                if salary <= 0:
                    flash('外门弟子无俸禄', 'error')
                elif claimed == today:
                    flash('今日俸禄已领取', 'error')
                else:
                    parts = []
                    if salary > 0:
                        run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?", (salary, char['id']))
                        parts.append(f'灵石 ×{salary}')
                    lf = CULT_RANKS[my_cr].get('salary_lingfu', 0)
                    if lf > 0:
                        run("UPDATE characters SET lingfu=lingfu+? WHERE id=?", (lf, char['id']))
                        parts.append(f'灵符 ×{lf}')
                    for iname, iqty in CULT_RANKS[my_cr]['salary_items']:
                        it = q("SELECT id FROM items WHERE name=?", (iname,), one=True)
                        if it:
                            ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?",
                                   (char['id'], it['id']), one=True)
                            if ex: run("UPDATE inventory SET quantity=quantity+? WHERE char_id=? AND item_id=?",
                                       (iqty, char['id'], it['id']))
                            else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,?)",
                                       (char['id'], it['id'], iqty))
                            parts.append(f'{iname} ×{iqty}')
                    run("UPDATE sect_members SET salary_claimed=? WHERE char_id=? AND sect_id=?",
                        (today, char['id'], my_sect['id']))
                    flash(f'领取今日俸禄：{"、".join(parts)}！', 'success')
                    log(char['id'], 'social', f'领取宗门俸禄：{"、".join(parts)}。')

        elif action == 'start_tournament' and my_sect and my_sect['rank'] == 'leader':
            last = q("SELECT started_at FROM sect_tournaments WHERE sect_id=? ORDER BY started_at DESC LIMIT 1",
                     (my_sect['id'],), one=True)
            active = q("SELECT 1 FROM sect_tournaments WHERE sect_id=? AND status='signup'",
                       (my_sect['id'],), one=True)
            if active:
                flash('当前已有进行中的大比报名', 'error')
            elif last and now_ts() - last['started_at'] < TOURNAMENT_COOLDOWN_SECS:
                days_left = int((TOURNAMENT_COOLDOWN_SECS - (now_ts() - last['started_at'])) / 86400) + 1
                flash(f'宗门大比冷却中，还需 {days_left} 天才可再次举办', 'error')
            elif char['spirit_stones'] < TOURNAMENT_COST:
                flash(f'灵石不足（需要 {TOURNAMENT_COST} 灵石）', 'error')
            else:
                run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?",
                    (TOURNAMENT_COST, char['id']))
                signup_ends = now_ts() + TOURNAMENT_SIGNUP_SECS
                run("""INSERT INTO sect_tournaments (sect_id,started_by,status,signup_ends,started_at)
                       VALUES (?,?,'signup',?,?)""",
                    (my_sect['id'], char['id'], signup_ends, now_ts()))
                flash(f'宗门大比已开启！报名期 24 小时，消耗 {TOURNAMENT_COST} 灵石', 'success')
                world_log_add('sect', f'「{my_sect["name"]}」宗主开启宗门大比，报名进行中！')
                log(char['id'], 'social', f'开启宗门大比，消耗 {TOURNAMENT_COST} 灵石。')

        elif action == 'force_start_tournament' and my_sect and my_sect['rank'] == 'leader':
            active_t = q("SELECT * FROM sect_tournaments WHERE sect_id=? AND status='signup'",
                         (my_sect['id'],), one=True)
            if not active_t:
                flash('当前没有进行中的大比报名', 'error')
            else:
                entry_count = q("SELECT COUNT(*) as cnt FROM sect_tournament_entries WHERE tournament_id=?",
                                (active_t['id'],), one=True)['cnt']
                if entry_count < TOURNAMENT_MIN_PLAYERS:
                    flash(f'报名人数不足，至少需要 {TOURNAMENT_MIN_PLAYERS} 人才可提前开始（当前 {entry_count} 人）', 'error')
                else:
                    run("UPDATE sect_tournaments SET signup_ends=? WHERE id=?", (now_ts(), active_t['id']))
                    resolve_tournament(active_t['id'])
                    flash('宗门大比报名截止，淘汰赛对阵已公布！', 'success')

        elif action == 'concede_match' and my_sect:
            match_id = int(request.form.get('match_id', 0))
            mt = q("SELECT * FROM sect_tournament_matches WHERE id=?", (match_id,), one=True)
            if not mt or mt['status'] != 'pending':
                flash('比赛不存在或已结束', 'error')
            elif char['id'] not in (mt['char_a'], mt['char_b']):
                flash('你不是本场参赛选手', 'error')
            else:
                winner_id = mt['char_b'] if char['id'] == mt['char_a'] else mt['char_a']
                run("""UPDATE sect_tournament_matches
                       SET overall_winner=?, status='done'
                       WHERE id=?""", (winner_id, match_id))
                wname = q("SELECT name FROM characters WHERE id=?", (winner_id,), one=True)
                flash(f'你已认输，【{wname["name"] if wname else "?"}】晋级。', 'info')
                log(char['id'], 'social', f'宗门大比认输，对手晋级。')
                _advance_tournament(mt['tournament_id'], mt['round_num'])

        elif action == 'fight_match' and my_sect:
            match_id = int(request.form.get('match_id', 0))
            mt = q("SELECT * FROM sect_tournament_matches WHERE id=?", (match_id,), one=True)
            if not mt or mt['status'] != 'pending':
                flash('比赛不存在或已结束', 'error')
            elif char['id'] not in (mt['char_a'], mt['char_b']):
                flash('你不是本场参赛选手', 'error')
            else:
                winner_id = _execute_match(match_id)
                if winner_id:
                    wname = q("SELECT name FROM characters WHERE id=?", (winner_id,), one=True)
                    flash(f'比赛结束！胜者：【{wname["name"] if wname else "?"}】', 'success')
                    _advance_tournament(mt['tournament_id'], mt['round_num'])
                else:
                    flash('比赛执行失败', 'error')

        elif action == 'join_tournament' and my_sect:
            active_t = q("SELECT * FROM sect_tournaments WHERE sect_id=? AND status='signup'",
                         (my_sect['id'],), one=True)
            if not active_t:
                flash('当前没有进行中的大比报名', 'error')
            elif now_ts() > active_t['signup_ends']:
                flash('报名已截止', 'error')
            elif q("SELECT 1 FROM sect_tournament_entries WHERE tournament_id=? AND char_id=?",
                   (active_t['id'], char['id']), one=True):
                flash('你已报名', 'error')
            elif daily_count(char['id'], 'tournament_join') >= 3:
                flash('今日报名次数已达上限（每天最多 3 次）', 'error')
            else:
                run("INSERT OR IGNORE INTO sect_tournament_entries (tournament_id,char_id,joined_at) VALUES (?,?,?)",
                    (active_t['id'], char['id'], now_ts()))
                daily_inc(char['id'], 'tournament_join')
                flash('报名成功！大比期待你的精彩表现', 'success')
                log(char['id'], 'social', '报名参加宗门大比。')

        my_sect = get_char_sect(char['id'])

    # 触发超时未结算的大比（报名期）
    if my_sect:
        expired_t = q("SELECT * FROM sect_tournaments WHERE sect_id=? AND status='signup'",
                      (my_sect['id'],), one=True)
        if expired_t and now_ts() >= expired_t['signup_ends']:
            resolve_tournament(expired_t['id'])

    # 触发超时未打的淘汰赛场次（比赛期）
    if my_sect:
        active_kt = q("SELECT * FROM sect_tournaments WHERE sect_id=? AND status='group'",
                      (my_sect['id'],), one=True)
        if active_kt:
            expired_matches = q("""SELECT id, round_num FROM sect_tournament_matches
                                   WHERE tournament_id=? AND status='pending' AND expires_at<=?""",
                                (active_kt['id'], now_ts()))
            rounds_to_check = set()
            for em in expired_matches:
                _execute_match(em['id'])
                rounds_to_check.add(em['round_num'])
            for rn in rounds_to_check:
                _advance_tournament(active_kt['id'], rn)

    members = []
    posts   = []
    my_contribution    = 0
    my_contrib_balance = 0
    my_cult_rank       = 0
    my_peak_name       = ''
    my_salary          = 0
    salary_available   = False
    sect_quests        = []
    sect_lv            = 1
    sect_lv_info       = SECT_LEVELS[0]
    sect_disciples     = {}
    shifu_peak_name    = ''
    my_contribution    = 0
    my_contrib_balance = 0
    my_cult_rank       = 0
    my_salary          = 0
    salary_available   = False
    peak_map           = {}
    my_joined_at       = 0
    if my_sect:
        members = q("""SELECT sm.rank, sm.contribution, sm.total_contribution, sm.cult_rank, sm.peak_name, sm.joined_at, c.name, c.zi, c.realm_idx, c.spirit_root, c.id as char_id
            FROM sect_members sm JOIN characters c ON c.id=sm.char_id
            WHERE sm.sect_id=? ORDER BY sm.cult_rank DESC, c.realm_idx DESC""", (my_sect['id'],))
        # 同宗门内师徒关系：shifu_id -> [tudi_char_id, ...]
        sect_char_ids = [m['char_id'] for m in members]
        sect_disciples = {}
        if sect_char_ids:
            ds_rows = q("""SELECT ds.shifu_id, ds.tudi_id FROM discipleships ds
                WHERE ds.status='active' AND ds.shifu_id IN ({})""".format(
                ','.join('?' * len(sect_char_ids))), sect_char_ids)
            for ds in ds_rows:
                sect_disciples.setdefault(ds['shifu_id'], []).append(ds['tudi_id'])
        # 建立每个成员的所属峰映射：本人有峰用本人的，否则用师父的
        peak_map = {}  # char_id -> peak_name
        for m in members:
            if m['peak_name']:
                peak_map[m['char_id']] = m['peak_name']
        # 弟子继承师父的峰
        for shifu_id, tudi_ids in sect_disciples.items():
            shifu_peak = peak_map.get(shifu_id, '')
            if shifu_peak:
                for tid in tudi_ids:
                    if tid not in peak_map:
                        peak_map[tid] = shifu_peak
        posts   = q("""SELECT sp.content, sp.created_at, c.name as char_name
            FROM sect_posts sp JOIN characters c ON c.id=sp.char_id
            WHERE sp.sect_id=? ORDER BY sp.created_at DESC LIMIT 30""", (my_sect['id'],))
        my_mem = q("SELECT contribution, total_contribution, cult_rank, salary_claimed, exam_cooldown, peak_name, joined_at FROM sect_members WHERE char_id=? AND sect_id=?",
                   (char['id'], my_sect['id']), one=True)
        my_peak_name = ''
        my_joined_at = 0
        if my_mem:
            my_contribution    = my_mem['total_contribution'] or 0
            my_contrib_balance = my_mem['contribution'] or 0
            my_cult_rank       = my_mem['cult_rank'] or 0
            my_peak_name       = my_mem['peak_name'] or ''
            my_joined_at       = my_mem['joined_at'] or 0
            my_salary          = CULT_RANKS[my_cult_rank]['salary']
            today              = datetime.now(TZ).strftime('%Y-%m-%d')
            salary_available   = my_salary > 0 and my_mem['salary_claimed'] != today
        # 如果自己没有峰，查师父是否有峰头（徒弟归属师父的峰）
        shifu_peak_name = ''
        if not my_peak_name:
            shifu, _ = get_shifu(char['id'])
            if shifu:
                shifu_mem = q("SELECT peak_name FROM sect_members WHERE char_id=? AND sect_id=?",
                              (shifu['id'], my_sect['id']), one=True)
                if shifu_mem and shifu_mem['peak_name']:
                    shifu_peak_name = shifu_mem['peak_name']
        # 宗门等级
        s_row    = q("SELECT level, total_contribution FROM sects WHERE id=?", (my_sect['id'],), one=True)
        sect_lv  = s_row['level'] if s_row else 1
        sect_lv_info = SECT_LEVELS[sect_lv - 1]
        # 宗门任务进度
        now_dt    = datetime.now(TZ)
        this_week = f"{now_dt.year}-W{now_dt.strftime('%W')}"
        quest_max = CULT_RANKS[my_cult_rank]['quest_max']
        def get_sq_state(qdef):
            row = q("SELECT * FROM sect_quest_progress WHERE char_id=? AND quest_key=? AND period_date=?",
                    (char['id'], qdef['key'], this_week), one=True)
            # unlimited 任务若被旧逻辑标记为 claimed=1，自动重置
            if qdef.get('unlimited') and row and row['claimed']:
                run("UPDATE sect_quest_progress SET claimed=0,completed=0,progress=0 WHERE id=?", (row['id'],))
                row = None
            prog       = row['progress'] if row else 0
            done       = bool(row and row['completed'])
            claim_cnt  = row['claim_count'] if row else 0
            exhausted  = not qdef.get('unlimited') and bool(row and row['claimed'] and claim_cnt >= quest_max)
            can_claim  = done and not (row and row['claimed'])
            pct        = min(100, int(prog * 100 / qdef['target'])) if qdef['target'] else 100
            return {**qdef, 'progress': prog, 'done': done, 'can_claim': can_claim,
                    'exhausted': exhausted, 'claim_cnt': claim_cnt, 'pct': pct}
        sect_quests = [get_sq_state(q_) for q_ in SECT_QUESTS]

    # 宗门列表（申请用 + 排行）
    all_sects_raw = q("""SELECT s.*, COUNT(sm.char_id) as member_count,
        SUM(c.realm_idx) as total_realm,
        (SELECT c2.name FROM characters c2 WHERE c2.id=s.leader_id) as leader_name
        FROM sects s
        LEFT JOIN sect_members sm ON sm.sect_id=s.id
        LEFT JOIN characters c ON c.id=sm.char_id
        GROUP BY s.id ORDER BY total_realm DESC""")
    all_sects = [dict(s) | {'cap': sect_capacity(s['id'])} for s in all_sects_raw]

    if my_sect and not pending_applications:
        pending_applications = []

    # 大比数据
    active_tournament   = None
    last_tournament     = None
    my_in_tournament    = False
    tournament_entries  = 0
    tournament_cooldown = 0
    knockout_tournament = None   # 淘汰赛进行中
    my_kt_match         = None   # 我本轮的对局
    kt_round_matches    = []     # 本轮所有对局（含对手姓名）
    if my_sect:
        active_tournament = q("SELECT * FROM sect_tournaments WHERE sect_id=? AND status='signup'",
                              (my_sect['id'],), one=True)
        if active_tournament:
            tournament_entries = q("SELECT COUNT(*) n FROM sect_tournament_entries WHERE tournament_id=?",
                                   (active_tournament['id'],), one=True)['n']
            my_in_tournament   = bool(q("SELECT 1 FROM sect_tournament_entries WHERE tournament_id=? AND char_id=?",
                                        (active_tournament['id'], char['id']), one=True))
        knockout_tournament = q("SELECT * FROM sect_tournaments WHERE sect_id=? AND status='group'",
                                (my_sect['id'],), one=True)
        if knockout_tournament:
            rn = knockout_tournament['current_round']
            raw_matches = q("""SELECT stm.*,
                ca.name as name_a, cb.name as name_b,
                wc.name as name_winner
                FROM sect_tournament_matches stm
                LEFT JOIN characters ca ON ca.id=stm.char_a
                LEFT JOIN characters cb ON cb.id=stm.char_b
                LEFT JOIN characters wc ON wc.id=stm.overall_winner
                WHERE stm.tournament_id=? AND stm.round_num=?
                ORDER BY stm.match_num""", (knockout_tournament['id'], rn))
            kt_round_matches = [dict(r) for r in raw_matches]
            for m in kt_round_matches:
                if char['id'] in (m['char_a'], m['char_b']) and m['char_b'] != 0:
                    my_kt_match = m
                    break
        last_tournament = q("SELECT * FROM sect_tournaments WHERE sect_id=? AND status='done' ORDER BY started_at DESC LIMIT 1",
                            (my_sect['id'],), one=True)
        last_t_any = q("SELECT started_at FROM sect_tournaments WHERE sect_id=? ORDER BY started_at DESC LIMIT 1",
                       (my_sect['id'],), one=True)
        if last_t_any:
            remaining = TOURNAMENT_COOLDOWN_SECS - (now_ts() - last_t_any['started_at'])
            tournament_cooldown = max(0, int(remaining / 86400))

    return render_template('sect.html', char=char, my_sect=my_sect,
        members=members, posts=posts, pending_invites=pending_invites,
        pending_applications=pending_applications,
        all_sects=all_sects, sect_quests=sect_quests,
        my_contribution=my_contribution, my_contrib_balance=my_contrib_balance,
        my_cult_rank=my_cult_rank, my_peak_name=my_peak_name, shifu_peak_name=shifu_peak_name,
        my_salary=my_salary, salary_available=salary_available,
        sect_lv=sect_lv, sect_lv_info=sect_lv_info,
        CULT_RANKS=CULT_RANKS, SECT_LEVELS=SECT_LEVELS,
        sect_disciples=sect_disciples, peak_map=peak_map,
        sect_buff=get_sect_buff(my_sect['id']) if my_sect else 0,
        SECT_CREATE_COST=SECT_CREATE_COST, SECT_MAX_MEMBERS=SECT_MAX_MEMBERS,
        sect_cap=sect_capacity(my_sect['id']) if my_sect else SECT_MAX_MEMBERS,
        cur_ts=now_ts(), my_joined_at=my_joined_at,
        active_tournament=active_tournament, last_tournament=last_tournament,
        my_in_tournament=my_in_tournament, tournament_entries=tournament_entries,
        tournament_cooldown=tournament_cooldown,
        knockout_tournament=knockout_tournament, my_kt_match=my_kt_match,
        kt_round_matches=kt_round_matches,
        TOURNAMENT_COST=TOURNAMENT_COST, TOURNAMENT_MIN_PLAYERS=TOURNAMENT_MIN_PLAYERS,
        TOURNAMENT_MATCH_TIMEOUT_SECS=TOURNAMENT_MATCH_TIMEOUT_SECS)

# ── 宗门积分商店 ───────────────────────────────────────────────────────────────

@app.route('/game/sect/shop', methods=['GET','POST'])
@login_required
def sect_shop():
    char    = me()
    my_sect = get_char_sect(char['id'])
    if not my_sect:
        flash('需先加入宗门方可使用宗门商店', 'error')
        return redirect(url_for('sect'))

    my_mem  = q("SELECT contribution FROM sect_members WHERE char_id=? AND sect_id=?",
                (char['id'], my_sect['id']), one=True)
    my_contrib = my_mem['contribution'] if my_mem else 0

    now_dt   = datetime.now(TZ)
    week_key = f"{now_dt.year}-W{now_dt.strftime('%W')}"
    SECT_SHOP_WEEKLY_LIMIT = 10

    def _week_bought(cid, iname):
        r = q("SELECT value FROM site_config WHERE key=?",
              (f'ss_wk_{cid}_{iname}_{week_key}',), one=True)
        return int(r['value']) if r else 0

    def _week_bought_inc(cid, iname):
        k = f'ss_wk_{cid}_{iname}_{week_key}'
        cur = _week_bought(cid, iname)
        run("INSERT OR REPLACE INTO site_config (key,value) VALUES (?,?)", (k, str(cur + 1)))

    if request.method == 'POST':
        iname = request.form.get('item_name', '')
        entry = next((e for e in SECT_SHOP_ITEMS if e[0] == iname), None)
        if not entry:
            flash('商品不存在', 'error')
        elif my_contrib < entry[1]:
            flash(f'贡献不足（需 {entry[1]}，当前 {my_contrib}）', 'error')
        elif _week_bought(char['id'], iname) >= SECT_SHOP_WEEKLY_LIMIT:
            flash(f'【{iname}】本周兑换已达上限（{SECT_SHOP_WEEKLY_LIMIT} 次）', 'error')
        else:
            it = q("SELECT * FROM items WHERE name=?", (iname,), one=True)
            if not it:
                flash('物品数据缺失', 'error')
            else:
                run("UPDATE sect_members SET contribution=contribution-? WHERE char_id=? AND sect_id=?",
                    (entry[1], char['id'], my_sect['id']))
                ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (char['id'], it['id']), one=True)
                if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?",
                           (char['id'], it['id']))
                else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)",
                           (char['id'], it['id']))
                _week_bought_inc(char['id'], iname)
                bought_cnt = _week_bought(char['id'], iname)
                flash(f'兑换【{iname}】成功！消耗贡献 {entry[1]}（本周已兑换 {bought_cnt}/{SECT_SHOP_WEEKLY_LIMIT}）', 'success')
                log(char['id'], 'social', f'以 {entry[1]} 贡献兑换宗门商品【{iname}】。')
                my_contrib -= entry[1]

    # 构建商品列表（带物品描述 + 本周已购次数）
    shop_goods = []
    for iname, cost in SECT_SHOP_ITEMS:
        it = q("SELECT * FROM items WHERE name=?", (iname,), one=True)
        if it:
            bought = _week_bought(char['id'], iname)
            shop_goods.append({'name': iname, 'cost': cost, 'item': it,
                               'can_buy': my_contrib >= cost and bought < SECT_SHOP_WEEKLY_LIMIT,
                               'week_bought': bought,
                               'week_limit': SECT_SHOP_WEEKLY_LIMIT})

    return render_template('sect_shop.html', char=char, my_sect=my_sect,
                           my_contrib=my_contrib, shop_goods=shop_goods)

# ── 师徒 ───────────────────────────────────────────────────────────────────────

@app.route('/game/disciples', methods=['GET','POST'])
@login_required
def disciples():
    char        = me()
    shifu, my_ds = get_shifu(char['id'])
    my_disciples = q("""SELECT ds.*, c.name as tudi_name, c.zi as tudi_zi, c.realm_idx as tudi_realm,
        c.spirit_root as tudi_root, c.id as tudi_char_id
        FROM discipleships ds JOIN characters c ON c.id=ds.tudi_id
        WHERE ds.shifu_id=? ORDER BY ds.status, ds.formed_at""", (char['id'],))
    pending_shifu = q("""SELECT i.*, c.name as from_name, c.realm_idx as from_realm, c.spirit_root as from_root
        FROM interactions i JOIN characters c ON c.id=i.from_char
        WHERE i.to_char=? AND i.type='拜师' AND i.status='pending'""", (char['id'],))

    if request.method == 'POST':
        action = request.form.get('action')
        my_sect = get_char_sect(char['id'])

        if action == 'take_disciple':
            target_name = request.form.get('target_name','').strip()
            target = q("SELECT * FROM characters WHERE name=? AND is_npc=0 AND status='alive'", (target_name,), one=True)
            if not target:
                flash('未找到该修士', 'error')
            elif char['realm_idx'] < SHIFU_MIN_REALM:
                flash(f'需达到【{REALMS[SHIFU_MIN_REALM]["name"]}】方可收徒', 'error')
            elif target['realm_idx'] >= char['realm_idx']:
                flash('对方境界不低于你，无法收为弟子', 'error')
            elif not my_sect:
                flash('师父和徒弟须在同一宗门，请先加入或创建宗门', 'error')
            elif not get_char_sect(target['id']) or get_char_sect(target['id'])['id'] != my_sect['id']:
                flash('对方不在你的宗门，无法结为师徒', 'error')
            elif len([d for d in my_disciples if d['status']=='active']) >= SHIFU_MAX_DISCIPLES:
                flash(f'已有 {SHIFU_MAX_DISCIPLES} 名活跃弟子，无法再收徒', 'error')
            elif q("SELECT 1 FROM discipleships WHERE tudi_id=? AND status='active'", (target['id'],), one=True):
                flash('对方已有师父', 'error')
            else:
                run("""INSERT INTO interactions (from_char,to_char,type,status,created_at)
                    VALUES (?,?,'拜师','pending',?)""", (char['id'], target['id'], now_ts()))
                log(target['id'], 'social', f'【{char["name"]}】向你发出收徒邀请！')
                flash(f'已向【{target_name}】发出收徒邀请', 'success')

        elif action == 'accept_disciple':
            inter_id = int(request.form.get('inter_id', 0))
            inter = q("SELECT * FROM interactions WHERE id=? AND to_char=? AND type='拜师' AND status='pending'",
                      (inter_id, char['id']), one=True)
            if inter:
                shifu_ch = q("SELECT * FROM characters WHERE id=?", (inter['from_char'],), one=True)
                my_sect  = get_char_sect(char['id'])
                if not my_sect or not get_char_sect(inter['from_char']) or \
                   get_char_sect(inter['from_char'])['id'] != my_sect['id']:
                    run("UPDATE interactions SET status='expired' WHERE id=?", (inter_id,))
                    flash('宗门条件不符，拜师失败', 'error')
                else:
                    run("UPDATE interactions SET status='accepted' WHERE id=?", (inter_id,))
                    existing_ds = q("SELECT id FROM discipleships WHERE tudi_id=?", (char['id'],), one=True)
                    if existing_ds:
                        run("""UPDATE discipleships SET shifu_id=?,status='active',
                               formed_at=?,graduated_at=0,last_teach=0 WHERE id=?""",
                            (inter['from_char'], now_ts(), existing_ds['id']))
                    else:
                        run("INSERT INTO discipleships (shifu_id,tudi_id,formed_at) VALUES (?,?,?)",
                            (inter['from_char'], char['id'], now_ts()))
                    log(char['id'],            'social', f'拜【{shifu_ch["name"]}】为师，开始师徒修炼之路！')
                    log(inter['from_char'],    'social', f'【{char["name"]}】正式拜入门下，成为记名弟子。')
                    world_log_add('sect', f'【{char["name"]}】拜【{shifu_ch["name"]}】为师！')
                    flash(f'已拜【{shifu_ch["name"]}】为师！修炼速度将提升 15%。', 'success')

        elif action == 'decline_disciple':
            inter_id = int(request.form.get('inter_id', 0))
            run("UPDATE interactions SET status='declined' WHERE id=? AND to_char=?", (inter_id, char['id']))
            flash('已婉拒收徒邀请', 'info')

        elif action == 'teach':
            tudi_id = int(request.form.get('tudi_id', 0))
            tech_id = int(request.form.get('tech_id', 0))
            ds = q("SELECT * FROM discipleships WHERE shifu_id=? AND tudi_id=? AND status='active'",
                   (char['id'], tudi_id), one=True)
            if not ds:
                flash('师徒关系不存在', 'error')
            elif now_ts() - (ds['last_teach'] or 0) < TEACH_COOLDOWN:
                left = (ds['last_teach'] + TEACH_COOLDOWN - now_ts()) // 86400
                flash(f'传授绝招冷却中，还需 {left+1} 天', 'error')
            elif not q("SELECT 1 FROM char_techniques WHERE char_id=? AND tech_id=?", (char['id'], tech_id), one=True):
                flash('你未习得此功法', 'error')
            elif q("SELECT 1 FROM char_techniques WHERE char_id=? AND tech_id=?", (tudi_id, tech_id), one=True):
                flash('徒弟已习得此功法', 'error')
            else:
                run("INSERT INTO char_techniques (char_id,tech_id,learned_at) VALUES (?,?,?)", (tudi_id, tech_id, now_ts()))
                run("UPDATE discipleships SET last_teach=? WHERE shifu_id=? AND tudi_id=?", (now_ts(), char['id'], tudi_id))
                tech = q("SELECT name FROM techniques WHERE id=?", (tech_id,), one=True)
                tudi = q("SELECT name FROM characters WHERE id=?", (tudi_id,), one=True)
                log(char['id'], 'social', f'将功法【{tech["name"]}】传授给徒弟【{tudi["name"]}】。')
                log(tudi_id,    'social', f'师父传授功法【{tech["name"]}】，如获至宝！')
                flash(f'已将【{tech["name"]}】传授给徒弟！', 'success')

        elif action == 'grant_zi':
            # 师父直接赐字给弟子
            tudi_id = int(request.form.get('tudi_id', 0))
            zi_val  = request.form.get('zi', '').strip()[:12]
            ds = q("SELECT * FROM discipleships WHERE shifu_id=? AND tudi_id=? AND status='active'",
                   (char['id'], tudi_id), one=True)
            if not ds:
                flash('师徒关系不存在', 'error')
            elif not zi_val:
                flash('字不能为空', 'error')
            else:
                tudi = q("SELECT name FROM characters WHERE id=?", (tudi_id,), one=True)
                run("UPDATE characters SET zi=? WHERE id=?", (zi_val, tudi_id))
                log(char['id'], 'social', f'赐徒弟【{tudi["name"]}】字【{zi_val}】。')
                log(tudi_id, 'social', f'师父赐字【{zi_val}】，感怀师恩。')
                flash(f'已赐【{tudi["name"]}】字【{zi_val}】', 'success')


        elif action == 'dismiss':
            tudi_id = int(request.form.get('tudi_id', 0))
            ds = q("SELECT * FROM discipleships WHERE shifu_id=? AND tudi_id=? AND status='active'",
                   (char['id'], tudi_id), one=True)
            if ds:
                run("UPDATE discipleships SET status='dismissed',graduated_at=? WHERE id=?", (now_ts(), ds['id']))
                tudi = q("SELECT name FROM characters WHERE id=?", (tudi_id,), one=True)
                log(char['id'], 'social', f'驱逐弟子【{tudi["name"]}】。')
                log(tudi_id,    'social', f'被师父驱逐，师徒缘分已尽。')
                flash('已驱逐该弟子', 'info')

        my_disciples = q("""SELECT ds.*, c.name as tudi_name, c.realm_idx as tudi_realm,
            c.spirit_root as tudi_root, c.id as tudi_char_id
            FROM discipleships ds JOIN characters c ON c.id=ds.tudi_id
            WHERE ds.shifu_id=? ORDER BY ds.status, ds.formed_at""", (char['id'],))
        shifu, my_ds = get_shifu(char['id'])
        pending_shifu = q("""SELECT i.*, c.name as from_name FROM interactions i
            JOIN characters c ON c.id=i.from_char
            WHERE i.to_char=? AND i.type='拜师' AND i.status='pending'""", (char['id'],))

    # 我的技能（可传授给徒弟）
    my_techs = q("""SELECT t.* FROM techniques t
        JOIN char_techniques ct ON ct.tech_id=t.id WHERE ct.char_id=?
        ORDER BY t.type, t.realm_required""", (char['id'],))

    return render_template('disciples.html', char=char,
        shifu=shifu, my_ds=my_ds,
        my_disciples=my_disciples, my_techs=my_techs,
        pending_shifu=pending_shifu,
        SHIFU_MIN_REALM=SHIFU_MIN_REALM,
        SHIFU_MAX_DISCIPLES=SHIFU_MAX_DISCIPLES,
        TEACH_COOLDOWN_DAYS=TEACH_COOLDOWN//86400,
        SHIFU_INVITE_COOLDOWN_DAYS=SHIFU_INVITE_COOLDOWN//86400)

# ── 成就 ───────────────────────────────────────────────────────────────────────

@app.route('/game/achievements')
@login_required
def achievements():
    char  = me()
    defs  = q("SELECT * FROM achievement_defs ORDER BY category, id")
    my    = {r['ach_key']: r for r in
             q("SELECT * FROM char_achievements WHERE char_id=?", (char['id'],))}
    cats  = {}
    for a in defs:
        cats.setdefault(a['category'], []).append(a)
    total     = len(defs)
    completed = sum(1 for r in my.values() if r['completed'])
    return render_template('achievements.html', char=char,
        defs=defs, my=my, cats=cats, total=total, completed=completed)

# ── Boss 活动 玩家端 ────────────────────────────────────────────────────────────

@app.route('/game/event', methods=['GET','POST'])
@login_required
def event_page():
    char  = me()
    event = get_active_event()
    energy = cur_energy(char)
    my_hit = None
    if event:
        my_hit = q("SELECT * FROM event_hits WHERE event_id=? AND char_id=?",
                   (event['id'], char['id']), one=True)

    result = None
    if request.method == 'POST' and event:
        if is_in_seclusion(char):
            flash('闭关中无法进行此操作', 'error')
        elif energy < BOSS_HIT_ENERGY:
            flash(f'灵力不足（需 {BOSS_HIT_ENERGY}）', 'error')
        elif event['boss_hp_remaining'] <= 0:
            flash('Boss 已被击杀', 'error')
        else:
            # 检查每日攻击次数限制（每人每个Boss每天最多20次）
            if my_hit and my_hit['hits'] >= 20:
                flash('今日攻击此Boss已达上限（20次）', 'error')
                return redirect(url_for('event_page'))
            dmg   = boss_hit_damage(char)
            dmg   = min(dmg, event['boss_hp_remaining'])
            new_hp = max(0, event['boss_hp_remaining'] - dmg)
            run("UPDATE world_events SET boss_hp_remaining=? WHERE id=?", (new_hp, event['id']))
            # 获取当前累积次数
            my_hit_before = q("SELECT hits FROM event_hits WHERE event_id=? AND char_id=?",
                             (event['id'], char['id']), one=True)
            current_hits = (my_hit_before['hits'] if my_hit_before else 0)
            # 更新伤害和次数
            run("""INSERT INTO event_hits (event_id,char_id,damage,hits) VALUES (?,?,?,1)
                ON CONFLICT(event_id,char_id) DO UPDATE SET damage=damage+?,hits=hits+1""",
                (event['id'], char['id'], dmg, dmg))
            set_energy(char['id'], energy - BOSS_HIT_ENERGY)
            drop_parts = boss_hit_drop(event, char, current_hits)
            log(char['id'], 'combat', f'攻击Boss【{event["name"]}】，造成 {dmg} 伤害。{"  ".join(drop_parts)}')
            # 里程碑公告
            pct_before = int((event['boss_hp_remaining'] + dmg) / event['boss_hp_total'] * 100)
            pct_after  = int(new_hp / event['boss_hp_total'] * 100)
            for milestone in [75, 50, 25]:
                if pct_before > milestone >= pct_after:
                    world_log_add('boss', f'⚔ Boss【{event["name"]}】气血剩余 {milestone}%！')
            if new_hp <= 0:
                boss_check_clear(q("SELECT * FROM world_events WHERE id=?", (event['id'],), one=True))
            event = get_active_event()
            char  = me()
            my_hit = q("SELECT * FROM event_hits WHERE event_id=? AND char_id=?",
                       (event['id'] if event else 0, char['id']), one=True) if event else None
            result = {'dmg': dmg, 'drops': drop_parts, 'hp': new_hp}

    leaderboard = []
    if event:
        leaderboard = q("""SELECT eh.damage, eh.hits, c.name, c.realm_idx
            FROM event_hits eh JOIN characters c ON c.id=eh.char_id
            WHERE eh.event_id=? ORDER BY eh.damage DESC LIMIT 20""", (event['id'],))

    # 计算剩余攻击次数
    remaining_hits = 20 - (my_hit['hits'] if my_hit else 0)

    return render_template('event.html', char=char, event=event,
        energy=energy, my_hit=my_hit, leaderboard=leaderboard, result=result,
        remaining_hits=remaining_hits, BOSS_HIT_ENERGY=BOSS_HIT_ENERGY)

