@app.route('/game/tourney', methods=['GET','POST'])
@login_required
def tourney():
    char = me()
    ev   = get_tourney_event()
    roll_result = None

    if request.method == 'POST' and ev:
        if is_in_seclusion(char):
            flash('闭关中无法参加大典', 'error')
        elif request.form.get('action') == 'roll':
            roll_result = _tourney_do_roll(char, ev)
            if roll_result.get('error'):
                flash(roll_result['error'], 'error')
            char = me()

    # ── 页面数据：棋盘全貌 + 全服位置 + 我的进度 ──
    squares = []
    for i in range(1, TOURNEY_BOARD_LENGTH + 1):
        kind, zone = _tourney_square_info(i)
        squares.append({'pos': i, 'kind': kind, 'zone': zone})
    board_players = []
    positions_map = {}
    my_prog = None
    day_left = TOURNEY_ROLLS_PER_DAY
    today = time.strftime('%Y-%m-%d', time.localtime())
    contest_board = []
    if ev:
        board_players = q("""SELECT tp.*, c.name, c.realm_idx FROM tourney_progress tp
            JOIN characters c ON c.id=tp.char_id
            WHERE tp.event_id=? ORDER BY tp.finished_at DESC, tp.position DESC, tp.total_attempts ASC""",
            (ev['id'],))
        for p in board_players:
            positions_map.setdefault(p['position'], []).append(p)
        my_prog = next((p for p in board_players if p['char_id'] == char['id']), None)
        if my_prog:
            used = my_prog['day_attempts'] if my_prog['day'] == today else 0
            day_left = max(0, TOURNEY_ROLLS_PER_DAY - used)
        contest_board = sorted([p for p in board_players if p['points'] > 0],
                                key=lambda p: (-p['points'], -p['wins']))[:10]

    return render_template('tourney.html', char=char, ev=ev,
        squares=squares, positions_map=positions_map, board_players=board_players,
        my_prog=my_prog, day_left=day_left, contest_board=contest_board,
        roll_result=roll_result,
        TOURNEY_BOARD_LENGTH=TOURNEY_BOARD_LENGTH, TOURNEY_ROLLS_PER_DAY=TOURNEY_ROLLS_PER_DAY,
        TOURNEY_ZONES=TOURNEY_ZONES, TOURNEY_FINISH_TITLE=TOURNEY_FINISH_TITLE,
        TOURNEY_FINISH_WEAPON=TOURNEY_FINISH_WEAPON, TOURNEY_CONTEST_TOP_N=TOURNEY_CONTEST_TOP_N,
        TOURNEY_CONTEST_PRIZES=TOURNEY_CONTEST_PRIZES)

