# ── 摇钱树限时活动 ──────────────────────────────────────────────────────────────

def yqs_active():
    row = q("SELECT value FROM site_config WHERE key='yqs_ends_at'", one=True)
    if not row: return False
    ends = int(row['value'] or 0)
    return ends > now_ts()

def yqs_refresh_tickets(char):
    """懒计算：按经过时间更新 yqs_tickets，返回 (新ticket数, 下次积累还需秒数)。"""
    last   = char['yqs_last_tick'] or 0
    ticks  = char['yqs_tickets'] or 0
    elapsed = now_ts() - last
    earned  = elapsed // YQS_TICK_SECS
    if earned > 0:
        ticks = min(YQS_MAX_TICKETS, ticks + earned)
        last  = last + earned * YQS_TICK_SECS
        run("UPDATE characters SET yqs_tickets=?, yqs_last_tick=? WHERE id=?",
            (ticks, last, char['id']))
    secs_to_next = YQS_TICK_SECS - (now_ts() - last)
    return ticks, max(0, secs_to_next)

def yqs_do_draw(char_id):
    """执行一次摇钱树抽卡，返回 (display_name, rarity, detail_str, err)。"""
    char = q("SELECT * FROM characters WHERE id=?", (char_id,), one=True)
    if not char: return '', '', '', '角色不存在'
    tickets, _ = yqs_refresh_tickets(char)
    if tickets < 1: return '', '', '', '积累次数不足，请等待30分钟'

    weights = [p[4] for p in YQS_POOL]
    chosen  = random.choices(YQS_POOL, weights=weights, k=1)[0]
    itype, ival, iname, rarity, _ = chosen

    detail = iname
    if itype == 'stones':
        run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?", (ival, char_id))
    elif itype == 'exp':
        run("UPDATE characters SET exp=exp+? WHERE id=?", (ival, char_id))
    elif itype == 'item_name':
        it = q("SELECT id FROM items WHERE name=?", (ival,), one=True)
        if it:
            ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (char_id, it['id']), one=True)
            if ex: run("UPDATE inventory SET quantity=quantity+1 WHERE char_id=? AND item_id=?", (char_id, it['id']))
            else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,1)", (char_id, it['id']))

    run("UPDATE characters SET yqs_tickets=yqs_tickets-1 WHERE id=?", (char_id,))

    if rarity == 'legendary':
        world_log_add('gacha', f'🌳【{char["name"]}】摇钱树中获得传说奖励【{detail}】！')

    log(char_id, 'market', f'摇钱树：获得【{detail}】。')
    return iname, rarity, detail, None

@app.route('/game/companion', methods=['GET','POST'])
@login_required
def companion():
    char = me()
    if request.method == 'POST':
        action = request.form.get('action')
        ckey   = request.form.get('companion_key', '')
        active_keys = get_active_companion_keys(char)
        if action in ('equip', 'unequip', 'unequip_all') and gate_equip_locked(char):
            flash('异世之门活动期间攻击力已锁定，无法更换上阵伙伴。', 'error')
        elif action == 'equip':
            owned = q("SELECT 1 FROM char_companions WHERE char_id=? AND companion_key=?",
                      (char['id'], ckey), one=True)
            if not owned or ckey not in COMPANION_MAP:
                flash('伙伴不存在。', 'error')
            elif ckey in active_keys:
                flash('该伙伴已在上阵中。', 'error')
            elif len(active_keys) >= COMPANION_MAX_ACTIVE:
                flash(f'上阵栏已满（最多 {COMPANION_MAX_ACTIVE} 位），请先撤回一位。', 'error')
            else:
                active_keys.append(ckey)
                run("UPDATE characters SET active_companions=? WHERE id=?",
                    (json.dumps(active_keys), char['id']))
                flash(f'【{COMPANION_MAP[ckey][1]}】已上阵（{len(active_keys)}/{COMPANION_MAX_ACTIVE}）。', 'success')
        elif action == 'unequip':
            if ckey in active_keys:
                active_keys.remove(ckey)
                run("UPDATE characters SET active_companions=? WHERE id=?",
                    (json.dumps(active_keys), char['id']))
                flash(f'【{COMPANION_MAP[ckey][1]}】已撤回。', 'success')
        elif action == 'unequip_all':
            run("UPDATE characters SET active_companions='[]' WHERE id=?", (char['id'],))
            flash('已清空上阵伙伴。', 'success')
        char = me()

    owned_keys  = {r['companion_key'] for r in
                   q("SELECT companion_key FROM char_companions WHERE char_id=?", (char['id'],))}
    active_keys = get_active_companion_keys(char)
    owned_comps = [c for c in COMPANION_TYPES if c[0] in owned_keys]
    active_comps = [COMPANION_MAP[k] for k in active_keys if k in COMPANION_MAP]
    pity        = char['companion_pity'] or 0
    # 限时池是否开放
    ltd_row = q("SELECT value FROM site_config WHERE key='limited_companion_ends_at'", one=True)
    limited_ends_at = int(ltd_row['value'] or 0) if ltd_row else 0
    limited_open = limited_ends_at > now_ts()
    unowned_comps = [c for c in COMPANION_TYPES if c[0] not in owned_keys]
    custom_pools_open = [p for p in CUSTOM_POOLS.values()
                         if p['is_active'] and p['items'] and not (p['ends_at'] and now_ts() > p['ends_at'])]
    return render_template('companion.html', char=char,
        owned_comps=owned_comps, unowned_comps=unowned_comps,
        active_comps=active_comps, active_keys=active_keys,
        COMPANION_RARITY_LABEL=COMPANION_RARITY_LABEL,
        COMPANION_RARITY_COLOR=COMPANION_RARITY_COLOR, COMPANION_MAP=COMPANION_MAP,
        COMPANION_REGULAR_COST=COMPANION_REGULAR_COST,
        COMPANION_PITY_MAX=COMPANION_PITY_MAX, pity=pity, owned_keys=owned_keys,
        COMPANION_MAX_ACTIVE=COMPANION_MAX_ACTIVE, COMPANION_LIMITED_KEYS=COMPANION_LIMITED_KEYS,
        limited_open=limited_open, limited_ends_at=limited_ends_at,
        custom_pools_open=custom_pools_open)

