XIAN_REALM_IDX = next(i for i, r in enumerate(REALMS) if r['major'] == '真仙')

@app.route('/rankings')
def rankings():
    # 封仙榜：已成仙者（隐藏的也显示，只隐藏修仙榜）
    immortals = q("""SELECT c.name, c.spirit_root, c.realm_idx, c.exp, c.spirit_stones,
        c.elements, c.daolv_id, c.age, c.ancient_awakened, c.ancient_blessing_id, c.immortal_seat, u.username
        FROM characters c JOIN users u ON u.id=c.user_id
        WHERE c.is_npc=0 AND c.status='alive' AND c.realm_idx >= ?
        ORDER BY c.exp DESC""", (XIAN_REALM_IDX,))
    # 修仙榜：未成仙且未隐藏
    top = q("""SELECT c.name, c.spirit_root, c.realm_idx, c.exp, c.spirit_stones,
        c.elements, c.daolv_id, c.ancient_awakened, c.ancient_blessing_id, u.username
        FROM characters c JOIN users u ON u.id=c.user_id
        WHERE c.is_npc=0 AND c.status='alive' AND c.realm_idx < ?
          AND (c.hide_ranking IS NULL OR c.hide_ranking=0)
        ORDER BY c.realm_idx DESC, c.exp DESC LIMIT 50""", (XIAN_REALM_IDX,))
    return render_template('rankings.html', top=top, immortals=immortals,
        ANCIENT_BLESSING_MAP=ANCIENT_BLESSING_MAP)

