@app.route('/game/log')
@login_required
def activity_log():
    char   = me()
    if not char:
        return redirect(url_for('dashboard'))
    page   = max(1, int(request.args.get('page', 1)))
    per    = 30
    offset = (page-1)*per
    logs   = q("SELECT * FROM char_logs WHERE char_id=? ORDER BY created_at DESC LIMIT ? OFFSET ?",
               (char['id'], per, offset))
    total  = q("SELECT COUNT(*) n FROM char_logs WHERE char_id=?", (char['id'],), one=True)['n']
    pages  = (total + per - 1) // per
    return render_template('log.html', char=char, logs=logs, page=page, pages=pages)

