@app.route('/admin')
@login_required
@admin_required
def admin():
    stats = {
        'users':      q("SELECT COUNT(*) n FROM users", one=True)['n'],
        'chars':      q("SELECT COUNT(*) n FROM characters WHERE is_npc=0 AND status='alive'", one=True)['n'],
        'chars_dead': q("SELECT COUNT(*) n FROM characters WHERE is_npc=0 AND status!='alive'", one=True)['n'],
        'item_count': q("SELECT COUNT(*) n FROM items WHERE is_active=1", one=True)['n'],
        'monsters':   q("SELECT COUNT(*) n FROM monsters WHERE is_active=1", one=True)['n'],
        'invites_unused': q("SELECT COUNT(*) n FROM invite_codes WHERE used_by IS NULL", one=True)['n'],
        'invites_total':  q("SELECT COUNT(*) n FROM invite_codes", one=True)['n'],
    }
    alive_chars = q("SELECT * FROM characters WHERE is_npc=0 AND status='alive'")
    overdue = [c for c in alive_chars if c['age'] > lifespan(c)]
    pvp_top3 = q("""SELECT c.name, c.pvp_score, c.pvp_wins FROM characters c
                    WHERE c.is_npc=0 AND c.status='alive' AND c.pvp_score > 0
                    ORDER BY c.pvp_score DESC LIMIT 3""")
