@app.route('/admin/advance_all_time', methods=['POST'])
@login_required
@admin_required
def admin_advance_all_time():
    alive_chars = q("SELECT * FROM characters WHERE is_npc=0 AND status='alive'")
    advanced, deceased = 0, []
    for char in alive_chars:
        changed = advance_time(char)
        if changed:
            advanced += 1
        # advance_time 内部已处理超寿陨落，这里补抓一下名字
        after = q("SELECT name, status FROM characters WHERE id=?", (char['id'],), one=True)
        if after and after['status'] == 'deceased' and char['status'] == 'alive':
            deceased.append(after['name'])
    msg = f'已为 {advanced} 位修士推进时光。'
    if deceased:
        msg += f' {len(deceased)} 位寿元耗尽陨落：{"、".join(deceased)}'
    flash(msg, 'success')
    return redirect(url_for('admin'))

@app.route('/admin/bulk_gift', methods=['POST'])
@login_required
@admin_required
def admin_bulk_gift():
    action  = request.form.get('gift_type')
    amount  = max(0, int(request.form.get('amount', 0) or 0))
    item_id = int(request.form.get('item_id', 0) or 0)
    qty     = max(1, int(request.form.get('qty', 1) or 1))
    players = q("SELECT id, name FROM characters WHERE is_npc=0 AND status='alive'")
    count   = len(players)

    if action == 'stones' and amount > 0:
        run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE is_npc=0 AND status='alive'", (amount,))
        for p in players:
            log(p['id'], 'system', f'[管理员全服] 赠予灵石 +{amount}。')
        flash(f'已向全服 {count} 名修士赠予灵石 +{amount}', 'success')

    elif action == 'exp' and amount > 0:
        run("UPDATE characters SET exp=exp+? WHERE is_npc=0 AND status='alive'", (amount,))
        for p in players:
            log(p['id'], 'system', f'[管理员全服] 赠予修为 +{amount}。')
        flash(f'已向全服 {count} 名修士赠予修为 +{amount}', 'success')

    elif action == 'item' and item_id > 0:
        item = q("SELECT name FROM items WHERE id=?", (item_id,), one=True)
        if not item:
            flash('物品不存在', 'error')
        else:
            for p in players:
                ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (p['id'], item_id), one=True)
                if ex: run("UPDATE inventory SET quantity=quantity+? WHERE char_id=? AND item_id=?", (qty, p['id'], item_id))
                else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,?)", (p['id'], item_id, qty))
                log(p['id'], 'system', f'[管理员全服] 赠予【{item["name"]}】×{qty}。')
            flash(f'已向全服 {count} 名修士赠予【{item["name"]}】×{qty}', 'success')

    elif action == 'mail' and amount > 0:
        subject = request.form.get('mail_subject', '管理员邮件').strip() or '管理员邮件'
        body    = request.form.get('mail_body', '').strip()
        mail_item_id = int(request.form.get('mail_item_id', 0) or 0)
        mail_qty     = max(1, int(request.form.get('mail_qty', 1) or 1))
        mail_item = q("SELECT name FROM items WHERE id=?", (mail_item_id,), one=True) if mail_item_id else None
        for p in players:
            send_system_mail(p['id'], subject, body,
                             item_id=mail_item_id or None,
                             item_qty=mail_qty if mail_item_id else 0,
                             stones=amount)
        flash(f'已向全服 {count} 名修士发送邮件（灵石+{amount}{"，附"+mail_item["name"] if mail_item else ""}）', 'success')
    else:
        flash('请填写有效的赠予内容', 'error')

    return redirect(url_for('admin'))

@app.route('/admin/settle_pvp', methods=['POST'])
@login_required
@admin_required
def admin_settle_pvp():
    top3 = q("""SELECT c.id, c.name FROM characters c
                WHERE c.is_npc=0 AND c.status='alive' AND c.pvp_score > 0
                ORDER BY c.pvp_score DESC LIMIT 20""")
    if not top3:
        flash('当前无有效积分，无需结算', 'info')
        return redirect(url_for('admin'))
    def _pvp_reward(rank):
        if rank == 1:   return 5000, 50000, '🥇 第一名'
        if rank == 2:   return 3000, 30000, '🥈 第二名'
        if rank == 3:   return 1500, 15000, '🥉 第三名'
        if rank <= 5:   return  800,  8000, f'第 {rank} 名'
        if rank <= 10:  return  300,  3000, f'第 {rank} 名'
        if rank <= 20:  return  100,  1000, f'第 {rank} 名'
        return 0, 0, f'第 {rank} 名'

    settled = []
    for rank, row in enumerate(top3, 1):
        stones, exp, label = _pvp_reward(rank)
        if stones == 0:
            continue
        send_system_mail(row['id'], f'切磋积分榜·{label}',
                         f'恭喜你在本赛季切磋积分榜中荣获{label}！\n奖励：{stones} 灵石、{exp} 修为，请前往邮件箱领取。',
                         stones=stones, exp=exp)
        log(row['id'], 'system', f'[管理员] 切磋积分榜结算，{label}，邮件奖励灵石 {stones}、修为 {exp}。')
        settled.append(f'{label}·{row["name"]}')
    run("UPDATE characters SET pvp_score=0, pvp_wins=0, pvp_losses=0, pvp_streak=0 WHERE is_npc=0")
    world_log_add('system', f'⚔ 切磋积分榜赛季结算！{settled[0] if settled else ""}荣登榜首！')
    flash(f'已结算并清零积分。获奖：{"、".join(settled)}', 'success')
    return redirect(url_for('admin'))

@app.route('/admin/settle_lifespan', methods=['POST'])
@login_required
@admin_required
def admin_settle_lifespan():
    alive_chars = q("SELECT * FROM characters WHERE is_npc=0 AND status='alive'")
    settled = []
    for char in alive_chars:
        if char['age'] > lifespan(char):
            run("UPDATE characters SET status='deceased' WHERE id=?", (char['id'],))
            log(char['id'], 'system', f'[管理员结算] 寿元耗尽，于 {char["age"]} 岁坐化而逝。')
            world_log_add('system', f'【{char["name"]}】寿元耗尽，于 {char["age"]} 岁坐化而逝。')
            break_daolv_on_death(char['id'], char['name'])
            settled.append(char['name'])
    if settled:
        flash(f'已结算 {len(settled)} 位超寿修士：{"、".join(settled)}', 'success')
    else:
        flash('当前无超寿修士需要结算', 'info')
    return redirect(url_for('admin'))

@app.route('/admin/players')
@login_required
@admin_required
def admin_players():
    show_dead = request.args.get('show_dead') == '1'
    if show_dead:
        rows = q("""SELECT c.*, u.username, u.role, u.last_login
            FROM characters c JOIN users u ON u.id=c.user_id
            WHERE c.is_npc=0
            ORDER BY c.status DESC, c.realm_idx DESC, c.exp DESC""")
    else:
        rows = q("""SELECT c.*, u.username, u.role, u.last_login
            FROM characters c JOIN users u ON u.id=c.user_id
            WHERE c.is_npc=0 AND c.status='alive'
            ORDER BY c.realm_idx DESC, c.exp DESC""")
    cauldron_ids = {r['char_id'] for r in q(
        """SELECT DISTINCT i.char_id FROM inventory i JOIN items it ON it.id=i.item_id
           WHERE it.type='cauldron' AND i.quantity>0""")}
    liquid_gift_map = {r['char_id']: r['count'] for r in q(
        "SELECT char_id, count FROM daily_counters WHERE key=? AND day='total'",
        (ALCHEMY_LIQUID_GIFT_TOTAL_KEY,))}
    players = []
    for row in rows:
        p = dict(row)
        fs = _build_fighter_stats(p)
        p['eff_atk']       = fs['atk']
        p['crit_rate_pct'] = round(fs['crit_rate'] * 100, 1)
        p['dodge_rate_pct']= round(fs['dodge_rate'] * 100, 1)
        p['lifesteal_pct'] = round(fs['lifesteal'], 1)
        p['is_alchemist']  = p['id'] in cauldron_ids
        p['liquid_gift_total'] = liquid_gift_map.get(p['id'], 0)
        players.append(p)
    dead_count = q("SELECT COUNT(*) n FROM characters WHERE is_npc=0 AND status!='alive'", one=True)['n']
    return render_template('admin/players.html', players=players,
                           show_dead=show_dead, dead_count=dead_count,
                           ALCHEMY_LIQUID_GIFT_MAX_TOTAL=ALCHEMY_LIQUID_GIFT_MAX_TOTAL)

@app.route('/admin/player/<int:cid>', methods=['GET','POST'])
@login_required
@admin_required
def admin_player(cid):
    _char_row = q("SELECT c.*, u.username FROM characters c JOIN users u ON u.id=c.user_id WHERE c.id=?", (cid,), one=True)
    if not _char_row:
        flash('角色不存在', 'error')
        return redirect(url_for('admin_players'))
    char = dict(_char_row)

    if request.method == 'POST':
        act = request.form.get('action')
        if act == 'add_life_sold':
            years = int(request.form.get('years', 0))
            if years != 0:
                run("UPDATE characters SET life_sold_total = MAX(0, life_sold_total+?) WHERE id=?", (years, cid))
                log(cid, 'system', f'[管理员] 寿元典当记录修正 {years:+d} 年。')
            flash(f'已修正典当记录 {years:+d} 年', 'success')
        elif act == 'stones':
            amt = int(request.form.get('amount', 0))
            run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?", (amt, cid))
            log(cid, 'system', f'管理员赠予灵石 {amt}。')
            flash(f'已赠予 {amt} 灵石', 'success')
        elif act == 'set_stones':
            val = max(0, int(request.form.get('value', 0)))
            run("UPDATE characters SET spirit_stones=? WHERE id=?", (val, cid))
            log(cid, 'system', f'管理员直接设定灵石为 {val}。')
            flash(f'已将灵石设为 {val}', 'success')
        elif act == 'set_lingfu':
            val = max(0, int(request.form.get('value', 0)))
            run("UPDATE characters SET lingfu=? WHERE id=?", (val, cid))
            log(cid, 'system', f'管理员直接设定灵符为 {val}。')
            flash(f'已将灵符设为 {val}', 'success')
        elif act == 'set_liquid_gift_total':
            val = max(0, int(request.form.get('value', 0)))
            run("""INSERT INTO daily_counters (char_id,key,day,count) VALUES (?,?,'total',?)
                ON CONFLICT(char_id,key,day) DO UPDATE SET count=excluded.count""",
                (cid, ALCHEMY_LIQUID_GIFT_TOTAL_KEY, val))
            log(cid, 'system', f'[管理员] 直接设定造化灵液累计获赠份数为 {val}。')
            flash(f'已将造化灵液累计获赠份数设为 {val}', 'success')
        elif act == 'set_exp':
            val = max(0, int(request.form.get('value', 0)))
            run("UPDATE characters SET exp=? WHERE id=?", (val, cid))
            log(cid, 'system', f'管理员直接设定修为为 {val}。')
            flash(f'已将修为设为 {val}', 'success')
        elif act == 'exp':
            amt = int(request.form.get('amount', 0))
            run("UPDATE characters SET exp=exp+? WHERE id=?", (amt, cid))
            log(cid, 'system', f'管理员赠予修为 {amt}。')
            flash(f'已赠予 {amt} 修为', 'success')
        elif act == 'body_exp':
            amt    = int(request.form.get('amount', 0))
            lv     = char['body_level'] or 0
            b_exp  = max(0, (char['body_exp'] or 0) + amt)
            new_lv = lv
            while new_lv + 1 < len(BODY_LEVELS) and b_exp >= BODY_LEVELS[new_lv + 1]['exp'] \
                    and char['realm_idx'] >= BODY_LEVELS[new_lv + 1]['realm']:
                new_lv += 1
            run("UPDATE characters SET body_exp=?, body_level=? WHERE id=?", (b_exp, new_lv, cid))
            log(cid, 'system', f'管理员赠予炼体经验 {amt}。')
            flash(f'已赠予 {amt} 炼体经验（当前 {b_exp}，{BODY_LEVELS[new_lv]["name"]}）', 'success')
        elif act == 'set_energy':
            val = max(0, min(energy_cap(char), int(request.form.get('value', 0))))
            set_energy(cid, val)
            log(cid, 'system', f'[管理员] 直接设定灵力为 {val}。')
            flash(f'已将灵力设为 {val}', 'success')
        elif act == 'heal':
            max_hp, _, _ = realm_stats(char['realm_idx'])
            max_hp += bone_hp_bonus(cid)
            set_hp(cid, max_hp)
            log(cid, 'system', '管理员补满气血。')
            flash('气血已补满', 'success')
        elif act == 'cave_force_settle':
            mode = char.get('cave_mode')
            if not mode or mode == 'off':
                flash('该角色洞府未开启自动修炼/炼体模式', 'error')
            else:
                process_cave(cid)
                log(cid, 'system', '[管理员] 手动补结算一次洞府收益。')
                flash('已手动补结算一次洞府收益', 'success')
        elif act == 'item':
            iid = int(request.form.get('item_id', 0))
            qty = max(1, int(request.form.get('qty', 1)))
            it  = q("SELECT * FROM items WHERE id=?", (iid,), one=True)
            if it:
                ex = q("SELECT 1 FROM inventory WHERE char_id=? AND item_id=?", (cid, iid), one=True)
                if ex: run("UPDATE inventory SET quantity=quantity+? WHERE char_id=? AND item_id=?", (qty, cid, iid))
                else:  run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,?)", (cid, iid, qty))
                log(cid, 'system', f'管理员赠予【{it["name"]}】×{qty}。')
                flash(f'已赠予 {it["name"]} ×{qty}', 'success')
        elif act == 'grant_furniture':
            fkey = request.form.get('furniture_key', '')
            f    = FURNITURE_MAP.get(fkey)
            if not f:
                flash('家具不存在', 'error')
            elif q("SELECT 1 FROM cave_purchases WHERE char_id=? AND item_key=?", (cid, fkey), one=True):
                flash(f'该修士已拥有【{f["name"]}】', 'error')
            else:
                equipped_count = q("SELECT COUNT(*) n FROM cave_purchases WHERE char_id=? AND is_equipped=1",
                                   (cid,), one=True)['n']
                auto_equip = 1 if equipped_count < cave_slots_for(char) else 0
                run("INSERT INTO cave_purchases (char_id,item_key,slot,is_equipped,bought_at) VALUES (?,?,0,?,?)",
                    (cid, fkey, auto_equip, now_ts()))
                old_lv = (char.get('cave_decor') or 0) // CAVE_DECOR_PER_LV
                run("UPDATE characters SET cave_decor=COALESCE(cave_decor,0)+10 WHERE id=?", (cid,))
                new_lv = ((char.get('cave_decor') or 0) + 10) // CAVE_DECOR_PER_LV
                log(cid, 'system', f'管理员赠予洞府家具【{f["name"]}】，装饰值 +10。')
                if new_lv > old_lv:
                    perk = random.choice(CAVE_PERK_POOL)
                    run("INSERT INTO cave_perks (char_id,perk_key,perk_name,value,earned_at) VALUES (?,?,?,?,?)",
                        (cid, perk['key'], perk['name'], perk['val'], now_ts()))
                    send_system_mail(cid, f'🏔 洞府感悟·{perk["name"]}',
                        f'{perk["narrative"]}\n\n'
                        f'【{perk["name"]}】已永久刻入你的洞府修炼之道。')
                flash(f'已赠予家具【{f["name"]}】', 'success')
        elif act == 'realm':
            ri = int(request.form.get('realm_idx', 0))
            if 0 <= ri < len(REALMS):
                nh, _, _ = realm_stats(ri)
                run("UPDATE characters SET realm_idx=?,exp=?,hp=?,hp_updated=? WHERE id=?",
                    (ri, REALMS[ri]['exp'], nh, now_ts(), cid))
                log(cid, 'system', f'管理员调整境界至【{REALMS[ri]["name"]}】。')
                flash('境界已调整', 'success')
        elif act == 'set_spirit_root':
            new_root = request.form.get('spirit_root', '').strip()
            elems    = [e for e in request.form.getlist('elements') if e in ELEMENTS]
            spec     = [e for e in request.form.getlist('special_elements') if e in SPECIAL_ELEMENT_SOURCES]
            if new_root not in SPIRIT_ROOTS:
                flash('无效灵根', 'error')
            else:
                need = {"天灵根":1,"变异灵根":1,"双灵根":2,"三灵根":3,"四灵根":4,"五灵根":5}[new_root]
                if not elems:
                    elems = rand_elements(new_root)
                elif len(elems) > need:
                    elems = elems[:need]
                elif len(elems) < need:
                    pool = [e for e in ELEMENTS if e not in elems]
                    elems = elems + random.sample(pool, min(need - len(elems), len(pool)))
                run("UPDATE characters SET spirit_root=?, elements=?, special_elements=? WHERE id=?",
                    (new_root, json.dumps(elems, ensure_ascii=False),
                     json.dumps(spec, ensure_ascii=False), cid))
                # 本命法宝元素不匹配则解除契合
                destiny_row = q("SELECT id, effect_json FROM items WHERE id=(SELECT destiny_id FROM characters WHERE id=?)", (cid,), one=True)
                if destiny_row:
                    req_elem = json.loads(destiny_row['effect_json'] or '{}').get('element')
                    if req_elem and req_elem not in [SPECIAL_ELEMENT_SOURCES.get(e, e) for e in elems]:
                        run("UPDATE characters SET destiny_id=NULL WHERE id=?", (cid,))
                        log(cid, 'system', f'灵根变化，本命法宝元素【{req_elem}】与新灵根不符，已自动解除契合。')
                log(cid, 'system', f'管理员调整灵根为【{new_root}】，五行：{"、".join(elems)}，变体：{"、".join(spec) or "无"}。')
                flash(f'灵根已设为【{new_root}】', 'success')
        elif act == 'remove_item':
            iid = int(request.form.get('item_id', 0))
            qty = max(1, int(request.form.get('qty', 1)))
            row = q("SELECT i.name, inv.quantity FROM items i JOIN inventory inv ON inv.item_id=i.id WHERE inv.char_id=? AND i.id=?", (cid, iid), one=True)
            if row:
                if qty >= row['quantity']:
                    run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (cid, iid))
                    log(cid, 'system', f'管理员从背包扣除【{row["name"]}】×{row["quantity"]}（全部）。')
                    flash(f'已扣除 {row["name"]} ×{row["quantity"]}（全部清空）', 'success')
                else:
                    run("UPDATE inventory SET quantity=quantity-? WHERE char_id=? AND item_id=?", (qty, cid, iid))
                    log(cid, 'system', f'管理员从背包扣除【{row["name"]}】×{qty}。')
                    flash(f'已扣除 {row["name"]} ×{qty}', 'success')
            else:
                flash('该玩家背包中没有此物品', 'error')
        elif act == 'toggle_hide_ranking':
            cur = char['hide_ranking'] or 0
            run("UPDATE characters SET hide_ranking=? WHERE id=?", (1 - cur, cid))
            flash('排行榜可见性已切换', 'success')
        elif act == 'reset_gate_pool':
            ev = q("SELECT * FROM gate_event WHERE is_active=1", one=True)
            if ev:
                today_str = time.strftime('%Y-%m-%d', time.localtime())
                run("DELETE FROM gate_ghost_pool WHERE char_id=? AND event_id=? AND day=?",
                    (cid, ev['id'], today_str))
            run("UPDATE gate_help_board SET is_resolved=1 WHERE requester_id=?", (cid,))
            flash(f'已重置【{char["name"]}】的今日鬼魔池', 'success')
            return redirect(url_for('admin_player', cid=cid))
        elif act == 'reset_gate_charges':
            run("UPDATE characters SET ghost_atk_ts=0, ghost_atk_charges=0 WHERE id=?", (cid,))
            flash(f'已重置【{char["name"]}】的攻击次数', 'success')
            return redirect(url_for('admin_player', cid=cid))
        elif act == 'refresh_gate_cd':
            cur_charges = char.get('ghost_atk_charges') or 0
            new_charges = max(cur_charges, 1)
            run("UPDATE characters SET ghost_atk_charges=?, ghost_atk_ts=? WHERE id=?",
                (new_charges, now_ts(), cid))
            flash(f'已刷新【{char["name"]}】的战斗冷却，当前可立即攻击（剩余次数 {new_charges}）', 'success')
            return redirect(url_for('admin_player', cid=cid))
        elif act == 'refresh_combat_pool':
            run("DELETE FROM char_combat_pool WHERE char_id=?", (cid,))
            flash(f'已刷新【{char["name"]}】的战斗场冷却，下次进入战斗场将立即刷新妖物池', 'success')
            return redirect(url_for('admin_player', cid=cid))
        elif act == 'fallen':
            if char['status'] == 'deceased':
                flash('该角色已是陨落状态', 'error')
            else:
                _fallen_msgs = [
                    "渡劫之时天雷异变，道体崩散，元神随之消逝于虚空之中。",
                    "闭关冲击瓶颈之际，走火入魔，于一声轰鸣中化为飞灰。",
                    "独入禁地寻访机缘，触动上古封印，魂飞魄散于异域秘境。",
                    "御剑追敌途中，误入空间裂缝，自此音讯全无，只余一缕残魂飘散。",
                    "遭遇天地异变，灵气逆流冲刷经脉，道基溃散，就此悄然陨落。",
                    "苦苦追寻一门上古传承，未料机缘暗藏杀机，于恍惚间含笑而逝。",
                    "突破瓶颈之际天劫提前降临，几番抵挡后力竭，终究未能撑过最后一道雷。",
                    "历经数百年修炼，寿元终至尽头，于晨曦中盘坐圆寂，面容安详。",
                    "踏上寻访仙缘之路，船覆于惊涛骇浪，从此再未归来，江湖上只留传说。",
                    "与一位神秘强者偶然相遇，对方出手毫无预兆，一击之下阴阳两隔。",
                    "秘境深处遭遇上古妖兽，以命换命护住同伴，自身元神散尽。",
                    "感悟天道之时，心中执念骤起化作心魔，道心崩溃，魂归大道。",
                ]
                msg = random.choice(_fallen_msgs)
                run("UPDATE characters SET status='deceased' WHERE id=?", (cid,))
                log(cid, 'system', f'【陨落】{msg}')
                break_daolv_on_death(cid, char['name'])
                flash(f'已令【{char["name"]}】陨落。', 'success')
        elif act == 'pill_usage':
            iid  = int(request.form.get('pill_item_id', 0))
            cnt  = int(request.form.get('pill_count', 0))
            item = q("SELECT name FROM items WHERE id=? AND type='pill'", (iid,), one=True)
            if not item:
                flash('物品不存在或非丹药', 'error')
            elif cnt < 0:
                flash('次数不可为负数', 'error')
            else:
                run("""INSERT INTO pill_usage (char_id,item_id,count) VALUES (?,?,?)
                       ON CONFLICT(char_id,item_id) DO UPDATE SET count=?""",
                    (cid, iid, cnt, cnt))
                log(cid, 'system', f'管理员设定【{item["name"]}】服用次数为 {cnt}。')
                flash(f'已将【{item["name"]}】的服用次数设为 {cnt}', 'success')
        elif act == 'set_destiny_weapon':
            dw_id = int(request.form.get('dw_id', 0))
            dw = q("SELECT * FROM destiny_weapons WHERE id=? AND char_id=?", (dw_id, cid), one=True)
            if not dw:
                flash('本命武器不存在或不属于该角色', 'error')
            else:
                try:
                    new_level    = max(0, int(request.form.get('enhance_level', dw['enhance_level'])))
                    new_base_atk = max(1, int(request.form.get('base_attack', dw['base_attack'])))
                    claim_json_raw = request.form.get('claim_buffs_json', '').strip() or '{}'
                    enh_json_raw   = request.form.get('enhance_json', '').strip() or '{}'
                    claim_buffs = json.loads(claim_json_raw)
                    enh_buffs   = json.loads(enh_json_raw)
                    if not isinstance(claim_buffs, dict) or not isinstance(enh_buffs, dict):
                        raise ValueError('必须是 JSON 对象')
                    for k, v in list(claim_buffs.items()) + list(enh_buffs.items()):
                        float(v)  # 校验数值合法
                except (ValueError, TypeError, json.JSONDecodeError) as e:
                    flash(f'数据格式错误：{e}', 'error')
                else:
                    run("""UPDATE destiny_weapons SET enhance_level=?, base_attack=?,
                           claim_buffs_json=?, enhance_json=? WHERE id=?""",
                        (new_level, new_base_atk, json.dumps(claim_buffs), json.dumps(enh_buffs), dw_id))
                    log(cid, 'system', f'[管理员] 修正本命武器【{dw["custom_name"] or dw["weapon_type"]}】属性数据。')
                    flash(f'已更新【{dw["custom_name"] or dw["weapon_type"]}】的属性', 'success')

        elif act == 'remove_pet':
            pid = int(request.form.get('pet_id', 0))
            pet = q("SELECT cp.id, pt.name FROM char_pets cp JOIN pet_types pt ON pt.id=cp.pet_type_id WHERE cp.id=? AND cp.char_id=?", (pid, cid), one=True)
            if pet:
                run("DELETE FROM char_pets WHERE id=?", (pid,))
                if char['active_pet_id'] == pid:
                    run("UPDATE characters SET active_pet_id=NULL WHERE id=?", (cid,))
                if char['active_pet2_id'] == pid:
                    run("UPDATE characters SET active_pet2_id=NULL WHERE id=?", (cid,))
                log(cid, 'system', f'管理员移除灵宠【{pet["name"]}】。')
                flash(f'已移除灵宠【{pet["name"]}】', 'success')
            else:
                flash('灵宠不存在或不属于该角色', 'error')
        elif act == 'rename':
            new_name = request.form.get('new_name', '').strip()[:12]
            if not new_name:
                flash('名字不能为空', 'error')
            elif q("SELECT 1 FROM characters WHERE name=? AND id!=?", (new_name, cid), one=True):
                flash('该名字已被使用', 'error')
            else:
                old_name = char['name']
                run("UPDATE characters SET name=? WHERE id=?", (new_name, cid))
                log(cid, 'system', f'[管理员] 道号由【{old_name}】改为【{new_name}】。')
                flash(f'已将道号改为【{new_name}】', 'success')
        elif act == 'craft_exp':
            path = request.form.get('path')
            amt  = int(request.form.get('amount', 0))
            PATH_EXP_COLS = {
                'alchemy':  ('alchemy_exp',  'alchemy_level',  'ALCHEMY_LEVELS'),
                'forge':    ('forge_exp',     'forge_level',    'FORGE_LEVELS'),
                'fulu':     ('fulu_exp',      'fulu_level',     'FULU_LEVELS'),
                'heqing':   ('heqing_exp',    'heqing_level',   'HEQING_LEVELS'),
                'sword':    ('sword_exp',     'sword_level',    'SWORD_LEVELS'),
                'beast':    ('beast_exp',     'beast_level',    'BEAST_LEVELS'),
            }
            LEVELS_MAP = {
                'alchemy': ALCHEMY_LEVELS, 'forge': FORGE_LEVELS, 'fulu': FULU_LEVELS,
                'heqing': HEQING_LEVELS,  'sword': SWORD_LEVELS,  'beast': BEAST_LEVELS,
            }
            if path not in PATH_EXP_COLS or amt == 0:
                flash('无效路线或经验值', 'error')
            else:
                exp_col, lv_col, _ = PATH_EXP_COLS[path]
                levels = LEVELS_MAP[path]
                new_exp = max(0, (char[exp_col] or 0) + amt)
                new_lv  = 0
                for i, lvl in enumerate(levels):
                    if new_exp >= lvl['exp']: new_lv = i
                run(f"UPDATE characters SET {exp_col}=?, {lv_col}=? WHERE id=?",
                    (new_exp, new_lv, cid))
                path_names = {'alchemy':'丹修','forge':'器修','fulu':'符修',
                              'heqing':'合欢修','sword':'剑修','beast':'御灵修'}
                log(cid, 'system', f'[管理员] {path_names[path]}经验 {amt:+d}，当前 {new_exp}，等级 {levels[new_lv]["name"]}。')
                flash(f'{path_names[path]}经验 {amt:+d}，等级：{levels[new_lv]["name"]}', 'success')
        elif act == 'set_equip':
            slot  = request.form.get('slot')   # equipped_weapon / equipped_artifact / destiny_id
            iid   = request.form.get('item_id', '')
            valid_slots = ('equipped_weapon', 'equipped_artifact', 'destiny_id')
            if slot not in valid_slots:
                flash('无效装备槽', 'error')
            else:
                val = int(iid) if iid else None
                run(f"UPDATE characters SET {slot}=? WHERE id=?", (val, cid))
                label = {'equipped_weapon':'飞剑','equipped_artifact':'法宝','destiny_id':'本命法宝'}[slot]
                item_name = q("SELECT name FROM items WHERE id=?", (val,), one=True)['name'] if val else '（卸下）'
                log(cid, 'system', f'[管理员] 直接设定{label}为【{item_name}】。')
                flash(f'{label} 已设为【{item_name}】', 'success')
        elif act == 'set_sect_rank':
            new_rank      = request.form.get('rank', 'member')
            new_cult_rank = int(request.form.get('cult_rank', 0))
            sm = q("SELECT id FROM sect_members WHERE char_id=?", (cid,), one=True)
            if not sm:
                flash('该角色不在任何宗门', 'error')
            elif new_rank not in ('leader', 'elder', 'member'):
                flash('无效职位', 'error')
            else:
                run("UPDATE sect_members SET rank=?, cult_rank=? WHERE char_id=?",
                    (new_rank, new_cult_rank, cid))
                rank_name = {'leader':'宗主','elder':'长老','member':'弟子'}[new_rank]
                cult_names = {0:'外门',1:'内门',2:'核心弟子',3:'长老'}
                log(cid, 'system', f'[管理员] 设定宗门职位为{rank_name}·{cult_names.get(new_cult_rank,"")}。')
                flash(f'宗门职位已设为 {rank_name}·{cult_names.get(new_cult_rank,"")}', 'success')
        elif act == 'remove_sword_path':
            token_item = q("SELECT i.id, i.market_price FROM items i JOIN inventory inv ON inv.item_id=i.id WHERE inv.char_id=? AND i.type='sword_token' AND inv.quantity>0", (cid,), one=True)
            if not token_item:
                flash('该角色背包中没有飞剑令', 'error')
            else:
                refund = token_item['market_price']
                run("DELETE FROM inventory WHERE char_id=? AND item_id=?", (cid, token_item['id']))
                run("UPDATE characters SET sword_token_id=NULL, spirit_stones=spirit_stones+? WHERE id=?", (refund, cid))
                log(cid, 'system', f'[管理员] 强制移除剑修资格（飞剑令），退还灵石 {refund}。')
                flash(f'已移除剑修路线，退还灵石 {refund}', 'success')
        elif act == 'add_bones':
            amt = max(0, int(request.form.get('amount', 0)))
            owned_ids = {r['bone_id'] for r in q("SELECT bone_id FROM char_bones WHERE char_id=?", (cid,))}
            old_count = len(owned_ids)
            remaining = [i for i in range(BONE_TOTAL) if i not in owned_ids]
            grant_ids = random.sample(remaining, min(amt, len(remaining)))
            for bid in grant_ids:
                run("INSERT INTO char_bones (char_id,bone_id,found_at) VALUES (?,?,?)", (cid, bid, now_ts()))
            new_count = old_count + len(grant_ids)
            crossed = [m for m in BONE_MILESTONES if old_count < m <= new_count]
            for _ in crossed:
                grant_perk(cid, {'key': 'cultivate_pct', 'val': BONE_MILESTONE_CULTIVATE_PCT}, BONE_MILESTONE_PERK_LABEL)
            log(cid, 'system', f'[管理员] 补全仙骨 {len(grant_ids)} 块（当前 {new_count}/{BONE_TOTAL}）。')
            msg = f'已补全 {len(grant_ids)} 块仙骨（当前 {new_count}/{BONE_TOTAL}）'
            if crossed:
                msg += f'，顺带触发 {len(crossed)} 次隐藏感悟（修炼速度 +{int(len(crossed)*BONE_MILESTONE_CULTIVATE_PCT*100)}%）'
            flash(msg, 'success')
        char = dict(q("SELECT c.*, u.username FROM characters c JOIN users u ON u.id=c.user_id WHERE c.id=?", (cid,), one=True))

    all_items  = q("SELECT * FROM items WHERE is_active=1 ORDER BY type,name")
    all_pills  = q("SELECT * FROM items WHERE is_active=1 AND type='pill' ORDER BY name")
    inv        = q("SELECT i.id as item_id, i.name, inv.quantity FROM items i JOIN inventory inv ON inv.item_id=i.id WHERE inv.char_id=?", (cid,))
    pill_usage_rows = q("""SELECT i.id as item_id, i.name, pu.count
                            FROM pill_usage pu JOIN items i ON i.id=pu.item_id
                            WHERE pu.char_id=? ORDER BY pu.count DESC""", (cid,))
    char_pets  = q("""SELECT cp.id, cp.nickname, cp.level, pt.name as type_name, pt.rarity,
                            (cp.id = c.active_pet_id) as is_slot1,
                            (cp.id = c.active_pet2_id) as is_slot2
                     FROM char_pets cp
                     JOIN pet_types pt ON pt.id=cp.pet_type_id
                     JOIN characters c ON c.id=cp.char_id
                     WHERE cp.char_id=?
                     ORDER BY pt.rarity DESC, cp.level DESC""", (cid,))
    plogs      = q("SELECT * FROM char_logs WHERE char_id=? ORDER BY created_at DESC LIMIT 20", (cid,))
    max_hp, base_atk, base_def = realm_stats(char['realm_idx'])
    max_hp += bone_hp_bonus(cid)
    equip_atk, equip_def = get_equip_bonuses(char)
    atk_techs  = q("""SELECT t.power FROM techniques t JOIN char_techniques ct ON ct.tech_id=t.id
                       WHERE ct.char_id=? AND t.type='attack'""", (cid,))
    tech_atk   = sum(r['power'] for r in atk_techs)
    pet_bonus  = get_pet_bonus(char)
    dw_bonus   = get_destiny_weapon_bonus(char)
    body_atk_pct, body_def_pct = get_body_bonus(char)
    fighter_stats = _build_fighter_stats(char)
    panel_atk_pct = fighter_stats['atk_pct']
    panel_def_pct = fighter_stats['def_pct']
    total_atk_pct = body_atk_pct + panel_atk_pct
    total_def_pct = body_def_pct + panel_def_pct
    eff_atk = fighter_stats['atk']
    eff_def = fighter_stats['def']
    combat_stats = {
        'max_hp': max_hp, 'cur_hp': cur_hp(char),
        'base_atk': base_atk, 'equip_atk': equip_atk, 'tech_atk': tech_atk,
        'base_def': base_def, 'equip_def': equip_def,
        'atk_pct': round(total_atk_pct, 1), 'def_pct': round(total_def_pct, 1),
        'eff_atk': eff_atk, 'eff_def': eff_def,
        'crit_rate': round(fighter_stats['crit_rate'] * 100, 1),
        'crit_dmg': round(fighter_stats['crit_dmg'], 2),
        'dodge_rate': round(fighter_stats['dodge_rate'] * 100, 1),
        'lifesteal': round(fighter_stats['lifesteal'], 1),
    }
    char_sect  = get_char_sect(cid)
    # 大比奖池物品（不限 is_active，按奖池名单查）
    prize_names = [p['name'] for p in TOURNAMENT_PRIZE_POOL]
    tournament_prizes = q(f"SELECT id, name FROM items WHERE name IN ({','.join('?'*len(prize_names))})",
                          prize_names)
    # 背包中可装备的武器/法宝/本命法宝
    equip_items = {
        'weapon':  q("SELECT i.id, i.name FROM items i JOIN inventory inv ON inv.item_id=i.id WHERE inv.char_id=? AND i.type='weapon' AND inv.quantity>0 ORDER BY i.name", (cid,)),
        'artifact':q("SELECT i.id, i.name FROM items i JOIN inventory inv ON inv.item_id=i.id WHERE inv.char_id=? AND i.type='artifact' AND inv.quantity>0 ORDER BY i.name", (cid,)),
        'destiny': q("SELECT i.id, i.name FROM items i JOIN inventory inv ON inv.item_id=i.id WHERE inv.char_id=? AND i.type='destiny' AND inv.quantity>0 ORDER BY i.name", (cid,)),
    }
    owned_furniture_keys = {r['item_key'] for r in
        q("SELECT item_key FROM cave_purchases WHERE char_id=?", (cid,))}
    char_dws = q("SELECT * FROM destiny_weapons WHERE char_id=? ORDER BY is_claimed DESC, created_at DESC", (cid,))
    gate_atk_charges, gate_atk_cd_left, _ = gate_calc_atk_charges(char)
    combat_pool_row = q("SELECT generated_at FROM char_combat_pool WHERE char_id=?", (cid,), one=True)
    combat_pool_cd_left = max(0, COMBAT_POOL_REFRESH - (now_ts() - combat_pool_row['generated_at'])) if combat_pool_row else 0
    _liquid_gift_row = q("SELECT count FROM daily_counters WHERE char_id=? AND key=? AND day='total'",
        (cid, ALCHEMY_LIQUID_GIFT_TOTAL_KEY), one=True)
    liquid_gift_total = _liquid_gift_row['count'] if _liquid_gift_row else 0
    return render_template('admin/player_detail.html', char=char, all_items=all_items,
        all_pills=all_pills, pill_usage_rows=pill_usage_rows,
        inv=inv, char_pets=char_pets, plogs=plogs, max_hp=max_hp,
        combat_stats=combat_stats, char_sect=char_sect, equip_items=equip_items,
        tournament_prizes=tournament_prizes,
        FURNITURE_POOL=FURNITURE_POOL, owned_furniture_keys=owned_furniture_keys,
        total_years_pawned=char['life_sold_total'] or 0, char_dws=char_dws,
        gate_atk_charges=gate_atk_charges, gate_atk_cd_left=gate_atk_cd_left,
        combat_pool_cd_left=combat_pool_cd_left, BODY_LEVELS=BODY_LEVELS,
        liquid_gift_total=liquid_gift_total, ALCHEMY_LIQUID_GIFT_MAX_TOTAL=ALCHEMY_LIQUID_GIFT_MAX_TOTAL,
        bone_owned=bone_owned_count(cid), BONE_TOTAL=BONE_TOTAL)

@app.route('/admin/items', methods=['GET','POST'])
@login_required
@admin_required
def admin_items():
    if request.method == 'POST':
        act = request.form.get('action')
        if act == 'add':
            name = request.form.get('name','').strip()
            desc = request.form.get('description','').strip()
            typ  = request.form.get('type','misc')
            eff  = request.form.get('effect_json','{}').strip()
            rar  = request.form.get('rarity','common')
            pri  = int(request.form.get('market_price',0))
            try: json.loads(eff)
            except: eff = '{}'
            if name:
                run("INSERT INTO items (name,description,type,effect_json,rarity,market_price) VALUES (?,?,?,?,?,?)",
                    (name,desc,typ,eff,rar,pri))
                flash(f'已添加【{name}】', 'success')
        elif act == 'toggle':
            run("UPDATE items SET is_active=1-is_active WHERE id=?", (int(request.form.get('item_id',0)),))
        elif act == 'price':
            run("UPDATE items SET market_price=? WHERE id=?",
                (int(request.form.get('price',0)), int(request.form.get('item_id',0))))
            flash('价格已更新', 'success')
    items = q("SELECT * FROM items ORDER BY type,name")
    return render_template('admin/items.html', items=items)


@app.route('/admin/transfer', methods=['GET','POST'])
@login_required
@admin_required
def admin_transfer():
    result = None
    from_char = None
    to_char   = None
    from_items = []

    from_name = request.form.get('from_name', '').strip()
    to_name   = request.form.get('to_name', '').strip()
    action    = request.form.get('action', '')

    if from_name:
        from_char = q("SELECT id,name,zi FROM characters WHERE name=? AND status='alive' AND is_npc=0",
                      (from_name,), one=True)
        if from_char:
            from_items = q("""SELECT i.id as inv_id, it.id as item_id, it.name, it.type,
                               it.rarity, i.quantity
                               FROM inventory i JOIN items it ON it.id=i.item_id
                               WHERE i.char_id=? AND i.quantity>0
                               ORDER BY it.type, it.name""", (from_char['id'],))

    if action == 'transfer' and from_name and to_name:
        item_ids = request.form.getlist('item_ids')
        if not from_char:
            result = ('error', f'找不到玩家【{from_name}】')
        else:
            to_char = q("SELECT id,name,zi FROM characters WHERE name=? AND status='alive' AND is_npc=0",
                        (to_name,), one=True)
            if not to_char:
                result = ('error', f'找不到玩家【{to_name}】')
            elif from_char['id'] == to_char['id']:
                result = ('error', '不能转移给自己')
            elif not item_ids:
                result = ('error', '请选择至少一件物品')
            else:
                transferred = []
                for inv_id in item_ids:
                    inv = q("SELECT i.*, it.name as item_name FROM inventory i JOIN items it ON it.id=i.item_id WHERE i.id=? AND i.char_id=?",
                            (int(inv_id), from_char['id']), one=True)
                    if not inv:
                        continue
                    qty = inv['quantity']
                    ex = q("SELECT id FROM inventory WHERE char_id=? AND item_id=?",
                           (to_char['id'], inv['item_id']), one=True)
                    if ex:
                        run("UPDATE inventory SET quantity=quantity+? WHERE char_id=? AND item_id=?",
                            (qty, to_char['id'], inv['item_id']))
                    else:
                        run("INSERT INTO inventory (char_id,item_id,quantity) VALUES (?,?,?)",
                            (to_char['id'], inv['item_id'], qty))
                    run("DELETE FROM inventory WHERE id=?", (inv['id'],))
                    transferred.append(f'【{inv["item_name"]}】×{qty}')
                if transferred:
                    log(from_char['id'], 'system', f'后台转移物品给【{to_char["name"]}】：{"、".join(transferred)}')
                    log(to_char['id'],   'system', f'后台收到来自【{from_char["name"]}】的物品：{"、".join(transferred)}')
                    result = ('success', f'已将 {len(transferred)} 件物品从【{from_char["name"]}】转移至【{to_char["name"]}】：{"、".join(transferred)}')
                    from_items = q("""SELECT i.id as inv_id, it.id as item_id, it.name, it.type,
                                       it.rarity, i.quantity
                                       FROM inventory i JOIN items it ON it.id=i.item_id
                                       WHERE i.char_id=? AND i.quantity>0
                                       ORDER BY it.type, it.name""", (from_char['id'],))
                else:
                    result = ('error', '未转移任何物品')

    return render_template('admin/transfer.html',
                           from_name=from_name, to_name=to_name,
                           from_char=from_char, from_items=from_items, result=result)


