@app.route('/admin/config', methods=['GET','POST'])
@login_required
@admin_required
def admin_config():
    if request.method == 'POST':
        action = request.form.get('action')
        if action == 'maintenance':
            mode = request.form.get('mode', '0')
            msg  = request.form.get('maintenance_msg', '').strip() or '服务器维护中，请稍后再来。'
            run("INSERT OR REPLACE INTO site_config (key,value) VALUES ('maintenance_mode',?)", (mode,))
            run("INSERT OR REPLACE INTO site_config (key,value) VALUES ('maintenance_msg',?)", (msg,))
            flash(f'停服维护{"已开启" if mode=="1" else "已关闭"}', 'success' if mode=='0' else 'info')
        elif action == 'save_gift':
            t = request.form.get('daily_energy_time', '').strip()
            a = request.form.get('daily_energy_amount', '').strip()
            if t:
                run("INSERT OR REPLACE INTO site_config (key,value) VALUES ('daily_energy_time',?)", (t,))
            if a:
                run("INSERT OR REPLACE INTO site_config (key,value) VALUES ('daily_energy_amount',?)", (a,))
            flash('灵力馈赠设置已保存。', 'success')
        elif action == 'furnace_refund':
            done = q("SELECT 1 FROM site_config WHERE key='furnace_refund_done'", one=True)
            if done:
                flash('退款已执行过，不可重复操作。', 'error')
            else:
                db = get_db()
                rows = db.execute("""
                    SELECT c.id as char_id, i.name as item_name, i.market_price, ci.quantity
                    FROM characters c
                    JOIN inventory ci ON ci.char_id=c.id
                    JOIN items i ON i.id=ci.item_id
                    WHERE i.type IN ('cauldron','forge') AND c.status='alive' AND c.is_npc=0
                """).fetchall()
                total_refund = 0
                for r in rows:
                    refund = r['market_price'] * r['quantity']
                    db.execute("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
                               (refund, r['char_id']))
                    db.execute("DELETE FROM inventory WHERE char_id=? AND item_id=(SELECT id FROM items WHERE name=? LIMIT 1)",
                               (r['char_id'], r['item_name']))
                    db.execute("INSERT INTO char_logs (char_id,type,content,created_at) VALUES (?,?,?,?)",
                               (r['char_id'], 'system',
                                f'系统退款：【{r["item_name"]}】原价退还 {refund} 灵石。', now_ts()))
                    total_refund += refund
                db.execute("UPDATE characters SET cauldron_id=NULL WHERE cauldron_id IS NOT NULL AND is_npc=0")
                db.execute("UPDATE characters SET forge_id=NULL WHERE forge_id IS NOT NULL AND is_npc=0")
                db.execute("INSERT OR REPLACE INTO site_config (key,value) VALUES ('furnace_refund_done','1')")
                db.commit()
                flash(f'退款完成，共退还 {total_refund} 灵石，已卸下所有炉具。', 'success')
        elif action == 'yqs':
            days = request.form.get('yqs_days', '').strip()
            if request.form.get('yqs_close'):
                run("INSERT OR REPLACE INTO site_config (key,value) VALUES ('yqs_ends_at','0')")
                flash('摇钱树活动已关闭。', 'success')
            elif days.isdigit() and int(days) > 0:
                ends = now_ts() + int(days) * 86400
                run("INSERT OR REPLACE INTO site_config (key,value) VALUES ('yqs_ends_at',?)", (str(ends),))
                flash(f'摇钱树活动已开启，持续 {days} 天。', 'success')
            else:
                flash('请输入有效天数。', 'error')
        elif action == 'gate_reinforce':
            mode = request.form.get('mode', '0')
            run("INSERT OR REPLACE INTO site_config (key,value) VALUES ('gate_ghost_reinforce',?)", (mode,))
            flash(f'鬼魔尽歼补发{"已开启" if mode=="1" else "已关闭"}', 'success')
        elif action == 'superior_auction_slots':
            val = request.form.get('value', '').strip()
            if val.isdigit() and int(val) > 0:
                run("INSERT OR REPLACE INTO site_config (key,value) VALUES ('superior_auction_slots',?)", (val,))
                flash(f'上等灵石拍卖行每日拍卖位已设为 {val} 个', 'success')
            else:
                flash('请输入正整数', 'error')
        elif action == 'limited2':
            days = request.form.get('limited2_days', '').strip()
            if request.form.get('limited2_close'):
                run("INSERT OR REPLACE INTO site_config (key,value) VALUES ('limited2_companion_ends_at','0')")
                flash('符道召唤池已关闭。', 'success')
            elif days.isdigit() and int(days) > 0:
                ends = now_ts() + int(days) * 86400
                run("INSERT OR REPLACE INTO site_config (key,value) VALUES ('limited2_companion_ends_at',?)", (str(ends),))
                flash(f'符道召唤池已开启，持续 {days} 天。', 'success')
            else:
                flash('请输入有效天数。', 'error')
        else:
            for k in ['site_name','site_desc','welcome_msg']:
                v = request.form.get(k,'').strip()
                if v: run("INSERT OR REPLACE INTO site_config (key,value) VALUES (?,?)", (k,v))
            flash('配置已保存', 'success')
    cfg = {r['key']: r['value'] for r in q("SELECT * FROM site_config")}
    cap, alch_count, forge_count, fulu_count, beast_count, heqing_count, sword_count = craft_quota()
    refund_done = bool(cfg.get('furnace_refund_done'))
    def _path_players(itype, col):
        return q("""SELECT c.name, c.realm_idx FROM characters c
            WHERE c.status='alive' AND c.is_npc=0
              AND EXISTS (SELECT 1 FROM inventory i JOIN items it ON it.id=i.item_id
                          WHERE i.char_id=c.id AND it.type=? AND i.quantity>0)
            ORDER BY c.realm_idx DESC""", (itype,))
    craft_players = {
        'alch':    _path_players('cauldron',      'cauldron_id'),
        'forge':   _path_players('forge',         'forge_id'),
        'fulu':    _path_players('brush',         'fulu_id'),
        'beast':   _path_players('beast_token',   'beast_token_id'),
        'heqing':  _path_players('heqing_token',  'heqing_token_id'),
        'sword':   _path_players('sword_token',   'sword_token_id'),
    }
    return render_template('admin/config.html', cfg=cfg,
                           craft_cap=cap, alch_count=alch_count, forge_count=forge_count,
                           fulu_count=fulu_count, beast_count=beast_count, heqing_count=heqing_count,
                           sword_count=sword_count, craft_players=craft_players,
                           refund_done=refund_done,
                           superior_auction_slots_cur=superior_auction_slots())

@app.route('/admin/enlighten', methods=['GET','POST'])
@login_required
@admin_required
def admin_enlighten():
    if request.method == 'POST':
        act = request.form.get('action')
        if act == 'open':
            try:
                hours = max(1, int(request.form.get('hours', 72)))
            except Exception:
                hours = 72
            end_ts = now_ts() + hours * 3600
            run("INSERT OR REPLACE INTO site_config (key,value) VALUES ('enlighten_window_end',?)",
                (str(end_ts),))
            flash(f'仙人试炼活动已开启，持续 {hours} 小时。', 'success')
        elif act == 'close':
            run("INSERT OR REPLACE INTO site_config (key,value) VALUES ('enlighten_window_end','0')")
            flash('仙人试炼活动已关闭（进行中的试炼不受影响）。', 'info')
    row = q("SELECT value FROM site_config WHERE key='enlighten_window_end'", one=True)
    end_ts   = int(row['value']) if row else 0
    active   = end_ts > now_ts()
    sessions = q("""SELECT es.*, c.name, c.realm_idx FROM enlighten_sessions es
                    JOIN characters c ON c.id=es.char_id
                    ORDER BY es.started_at DESC LIMIT 50""")
    # 预处理 sessions，避免模板做位运算
    for s in sessions:
        s_scores = json.loads(s['scores_json'] or '[]')
        done_count = sum(1 for i in range(5) if (s['stages_done'] >> i) & 1)
        total_score = sum(x for x in s_scores if isinstance(x, (int, float)))
        realm_name = REALMS[s['realm_idx']]['name'] if 0 <= s['realm_idx'] < len(REALMS) else '未知'
        # sqlite3.Row 不可直接赋值，转为 dict
        pass
    sessions_data = []
    for s in sessions:
        s_scores = json.loads(s['scores_json'] or '[]')
        sessions_data.append({
            'name':        s['name'],
            'realm_name':  REALMS[s['realm_idx']]['name'] if 0 <= s['realm_idx'] < len(REALMS) else '未知',
            'done_count':  sum(1 for i in range(5) if (s['stages_done'] >> i) & 1),
            'total_score': sum(x for x in s_scores if isinstance(x, (int, float))),
            'resolved':    s['resolved'],
            'result':      s['result'],
            'started_at':  s['started_at'],
        })
    return render_template('admin/enlighten.html', active=active, end_ts=end_ts, sessions=sessions_data)

@app.route('/admin/vein', methods=['GET','POST'])
@login_required
@admin_required
def admin_vein():
    if request.method == 'POST':
        act = request.form.get('action')
        if act == 'start':
            if q("SELECT 1 FROM vein_event WHERE is_active=1", one=True):
                flash('已有进行中的灵脉活动', 'error')
            else:
                now = now_ts()
                run("INSERT INTO vein_event (started_at, ends_at, is_active, total_progress) VALUES (?,?,1,0)",
                    (now, now + VEIN_DURATION))
                world_log_add('system', '🪨 上古灵脉现世！修士们可前往【开凿灵脉】页面参与协力开凿，共享灵脉感悟！')
                flash('灵脉活动已开启（2天）', 'success')
        elif act == 'end':
            ev = q("SELECT * FROM vein_event WHERE is_active=1", one=True)
            if ev:
                _close_vein_event(ev)
                flash('灵脉活动已提前结束，奖励已发放', 'info')
            else:
                flash('当前无进行中的灵脉活动', 'error')
        elif act == 'adjust_progress':
            ev = q("SELECT * FROM vein_event WHERE is_active=1", one=True)
            if ev:
                try:
                    new_val = max(0, int(request.form.get('progress', 0)))
                    run("UPDATE vein_event SET total_progress=? WHERE id=?", (new_val, ev['id']))
                    flash(f'全服进度已调整为 {new_val}', 'success')
                except Exception:
                    flash('数值无效', 'error')

    ev    = q("SELECT * FROM vein_event WHERE is_active=1", one=True)
    past  = q("SELECT * FROM vein_event WHERE is_active=0 ORDER BY id DESC LIMIT 5")
    contribs = []
    if ev:
        contribs = q("""SELECT vc.*, c.name, c.realm_idx FROM vein_contributions vc
            JOIN characters c ON c.id=vc.char_id
            WHERE vc.event_id=? ORDER BY vc.contribution DESC""", (ev['id'],))
    return render_template('admin/vein.html', ev=ev, past=past, contribs=contribs,
        VEIN_TARGET=VEIN_TARGET, VEIN_THRESHOLD=VEIN_THRESHOLD,
        VEIN_DURATION=VEIN_DURATION, REALMS=REALMS)

@app.route('/admin/gate', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_gate():
    preview_rows = []
    if request.method == 'POST':
        act = request.form.get('action')
        if act == 'start':
            if q("SELECT 1 FROM gate_event WHERE is_active=1", one=True):
                flash('已有进行中的异世之门活动', 'error')
            else:
                now = now_ts()
                run("INSERT INTO gate_event (started_at,ends_at,is_active) VALUES (?,?,1)",
                    (now, now + GATE_DURATION))
                # 新活动视为从头开始，清零所有人的攻击次数积攒计时
                run("UPDATE characters SET ghost_atk_ts=0, ghost_atk_charges=0 WHERE is_npc=0")
                world_log_add('system',
                    '⚠ 灵脉异动，异世之门骤然开启！鬼魔接连涌出，修士们速往【灵台→异世之门】迎战！')
                flash('异世之门活动已开启（48小时）', 'success')
        elif act == 'end':
            ev = q("SELECT * FROM gate_event WHERE is_active=1", one=True)
            if ev:
                run("UPDATE gate_event SET is_active=0, actual_ended_at=? WHERE id=?", (now_ts(), ev['id']))
                run("UPDATE characters SET pollution=0 WHERE is_npc=0")
                world_log_add('system', '🌀 异世之门已关闭，灵界恢复平静，所有污染值清零。')
                flash('活动已结束，污染值已清零', 'info')
            else:
                flash('当前无进行中的活动', 'error')
        elif act == 'refresh_pool':
            ev_now = q("SELECT * FROM gate_event WHERE is_active=1", one=True)
            if not ev_now:
                flash('当前无进行中的活动', 'error')
            else:
                today_str = time.strftime('%Y-%m-%d', time.localtime())
                # 删掉今天所有玩家的鬼魔池，下次进入时自动重新生成
                r = run("DELETE FROM gate_ghost_pool WHERE event_id=? AND day=?",
                        (ev_now['id'], today_str))
                cnt = r.rowcount
                world_log_add('system', f'⚡ 异世之门骚动！今日鬼魔大军已换防，修士们速往应敌！')
                flash(f'已刷新今日鬼魔池（清除 {cnt} 名玩家的当日记录），玩家下次进入将重新生成新一批怪物', 'success')
        elif act == 'preview_4h_attack':
            ev_now = q("SELECT * FROM gate_event WHERE is_active=1", one=True)
            if not ev_now:
                flash('当前无进行中的活动', 'error')
            else:
                init_cnt = _gate_init_missing_pools(ev_now)
                hour_label = request.form.get('attack_hour', '').strip()
                preview_hour = int(hour_label) % 24 if hour_label.isdigit() else datetime.now(TZ).hour
                today_str = time.strftime('%Y-%m-%d', time.localtime())
                pools = q("""SELECT ggp.*, c.name FROM gate_ghost_pool ggp
                    JOIN characters c ON c.id=ggp.char_id
                    WHERE ggp.event_id=? AND ggp.day=? AND c.status='alive' AND c.is_npc=0""",
                    (ev_now['id'], today_str))
                for pool in pools:
                    ghosts   = json.loads(pool['ghosts_json'] or '[]')
                    defeated = set(json.loads(pool['defeated_ids'] or '[]'))
                    unbeaten = [g for g in ghosts if g['idx'] not in defeated]
                    if unbeaten:
                        target = random.choice(unbeaten)
                        preview_rows.append({
                            'name': pool['name'],
                            'text': f'【{preview_hour}点】【{target["icon"]}{target["name"]}】突破防线，吸走你的精粹！'
                                    f'年龄 +{GATE_AGE_HIT}岁，污染 +{GATE_POLLUTION_HIT}。'
                        })
                flash(f'以下是模拟预览（已为 {init_cnt} 名还没打开过异世门的玩家补建今日鬼魔池），没有真的扣任何东西。确认没问题再点正式的"补发X点攻击"。', 'info')
        elif act == 'trigger_4h_attack':
            ev_now = q("SELECT * FROM gate_event WHERE is_active=1", one=True)
            if not ev_now:
                flash('当前无进行中的活动', 'error')
            else:
                init_cnt = _gate_init_missing_pools(ev_now)
                hour_label = request.form.get('attack_hour', '').strip()
                hour = int(hour_label) % 24 if hour_label.isdigit() else datetime.now(TZ).hour
                today_str = time.strftime('%Y-%m-%d', time.localtime())
                pools = q("SELECT * FROM gate_ghost_pool WHERE event_id=? AND day=?",
                          (ev_now['id'], today_str))
                hit_cnt = 0
                for pool in pools:
                    cid = pool['char_id']
                    char = q("SELECT * FROM characters WHERE id=? AND status='alive' AND is_npc=0", (cid,), one=True)
                    if not char:
                        continue
                    ghosts   = json.loads(pool['ghosts_json'] or '[]')
                    defeated = set(json.loads(pool['defeated_ids'] or '[]'))
                    unbeaten = [g for g in ghosts if g['idx'] not in defeated]
                    if unbeaten:
                        target = random.choice(unbeaten)
                        gate_apply_ghost_attack(cid, target, hour=hour)
                        hit_cnt += 1
                run("""INSERT INTO gate_admin_action_log (event_id,admin_name,action,detail,created_at)
                       VALUES (?,?,?,?,?)""",
                    (ev_now['id'], S.get('uname', '?'), 'trigger_4h_attack',
                     f'手动补发【{hour}点】鬼魔攻击，{hit_cnt}人被偷袭，{init_cnt}人补建池子', now_ts()))
                flash(f'已手动补发【{hour}点】鬼魔攻击，共 {hit_cnt} 名玩家被偷袭'
                      f'{f"（含 {init_cnt} 名刚补建鬼魔池的人）" if init_cnt else ""}', 'success')
        elif act == 'give_charges':
            amount = max(1, min(24, int(request.form.get('amount', 5))))
            run("""UPDATE characters SET ghost_atk_charges=MIN(ghost_atk_charges+?, ?)
                   WHERE is_npc=0 AND status='alive'""", (amount, GATE_ATK_MAX_CHARGES))
            cnt = q("SELECT COUNT(*) as c FROM characters WHERE is_npc=0 AND status='alive'", one=True)['c']
            flash(f'已为全体 {cnt} 名玩家各发放 {amount} 次攻击机会', 'success')
        elif act == 'give_charges_single':
            target_name = request.form.get('give_name', '').strip()
            amount      = max(1, int(request.form.get('give_amount', 1)))
            target = q("SELECT id, name, ghost_atk_charges FROM characters WHERE name=? AND is_npc=0",
                       (target_name,), one=True)
            if not target:
                flash(f'找不到玩家「{target_name}」', 'error')
            else:
                cur = target['ghost_atk_charges'] or 0
                new = min(GATE_ATK_MAX_CHARGES, cur + amount)
                run("UPDATE characters SET ghost_atk_charges=? WHERE id=?", (new, target['id']))
                flash(f'已为【{target["name"]}】发放 {amount} 次攻击机会（{cur} → {new}）', 'success')
        elif act == 'revoke_charges':
            target_name = request.form.get('revoke_name', '').strip()
            amount      = max(1, int(request.form.get('revoke_amount', 1)))
            target = q("SELECT id, name, ghost_atk_charges FROM characters WHERE name=? AND is_npc=0",
                       (target_name,), one=True)
            if not target:
                flash(f'找不到玩家「{target_name}」', 'error')
            else:
                cur = target['ghost_atk_charges'] or 0
                new = max(0, cur - amount)
                run("UPDATE characters SET ghost_atk_charges=? WHERE id=?", (new, target['id']))
                flash(f'已撤回【{target["name"]}】{amount} 次攻击机会（{cur} → {new}）', 'success')
        elif act == 'clear_ghosts_single':
            ev_now = q("SELECT * FROM gate_event WHERE is_active=1", one=True)
            target_name = request.form.get('clear_name', '').strip()
            target = q("SELECT id, name FROM characters WHERE name=? AND is_npc=0", (target_name,), one=True)
            if not ev_now:
                flash('当前无进行中的活动', 'error')
            elif not target:
                flash(f'找不到玩家「{target_name}」', 'error')
            else:
                today_str = time.strftime('%Y-%m-%d', time.localtime())
                pool = q("SELECT * FROM gate_ghost_pool WHERE char_id=? AND event_id=? AND day=?",
                         (target['id'], ev_now['id'], today_str), one=True)
                if not pool:
                    flash(f'【{target["name"]}】今日尚无鬼魔记录', 'error')
                else:
                    ghosts    = json.loads(pool['ghosts_json'] or '[]')
                    defeated  = set(json.loads(pool['defeated_ids'] or '[]'))
                    remaining = [g for g in ghosts if g['idx'] not in defeated]
                    if not remaining:
                        flash(f'【{target["name"]}】今日鬼魔已全部击败，无需处理', 'info')
                    else:
                        prev_defeated_count = len(defeated)
                        stones_got = 0
                        shard_by_law = {}
                        for g in remaining:
                            g['hp'] = 0
                            g['defeated'] = True
                            defeated.add(g['idx'])
                            stones_got += g['stones']
                            if random.random() < g.get('shard_chance', 0.30):
                                got = random.randint(1, g.get('shard_max', 1))
                                shard_by_law[g['law']] = shard_by_law.get(g['law'], 0) + got
                        run("""UPDATE gate_ghost_pool SET ghosts_json=?, defeated_ids=?
                               WHERE char_id=? AND event_id=? AND day=?""",
                            (json.dumps(ghosts), json.dumps(list(defeated)), target['id'], ev_now['id'], today_str))
                        if stones_got:
                            run("UPDATE characters SET spirit_stones=spirit_stones+? WHERE id=?",
                                (stones_got, target['id']))
                        for law, qty in shard_by_law.items():
                            _gate_give_shard(target['id'], law, qty)
                        bonus_txt = _gate_daily_clear_bonus(target['id'], prev_defeated_count, len(defeated), len(ghosts))
                        shard_txt = '、'.join(f'{law}法则碎片{qty}片' for law, qty in shard_by_law.items())
                        shard_txt = f'，{shard_txt}' if shard_txt else ''
                        names = '、'.join(f'{g["icon"]}{g["name"]}' for g in remaining)
                        log(target['id'], 'combat',
                            f'（管理员协助）道友出手相助，一举击退剩余全部鬼魔：{names}，获得灵石 {stones_got} 枚{shard_txt}{bonus_txt}。')
                        run("""INSERT INTO gate_admin_action_log (event_id,admin_name,action,detail,created_at)
                               VALUES (?,?,?,?,?)""",
                            (ev_now['id'], S.get('uname', '?'), 'clear_ghosts_single',
                             f'一键清空【{target["name"]}】剩余 {len(remaining)} 只鬼魔，发放灵石 {stones_got}{shard_txt}', now_ts()))
                        flash(f'已为【{target["name"]}】一键击退剩余 {len(remaining)} 只鬼魔，发放灵石 {stones_got} 枚{shard_txt}', 'success')
        elif act == 'revoke_all_charges':
            amount = max(1, min(24, int(request.form.get('revoke_all_amount', 1))))
            run("UPDATE characters SET ghost_atk_charges=MAX(0, ghost_atk_charges-?) WHERE is_npc=0", (amount,))
            cnt = q("SELECT COUNT(*) c FROM characters WHERE is_npc=0 AND status='alive'", one=True)['c']
            flash(f'已撤回全体 {cnt} 名玩家各 {amount} 次攻击机会', 'success')
        elif act == 'clear_demonic':
            run("UPDATE characters SET is_demonic=0, regen_mult=1.0 WHERE is_demonic=1 AND is_npc=0")
            flash('已清除所有玩家的魔修状态', 'success')
        elif act == 'rollback':
            # 撤回指定活动的所有收益
            rollback_ev_id = int(request.form.get('rollback_ev_id', 0))
            rollback_ev = q("SELECT * FROM gate_event WHERE id=?", (rollback_ev_id,), one=True)
            if not rollback_ev:
                flash('找不到该活动记录', 'error')
            else:
                # 1. 统计每位玩家从本次活动获得的灵石（遍历所有鬼魔池中已击败的鬼）
                pools = q("SELECT * FROM gate_ghost_pool WHERE event_id=?", (rollback_ev_id,))
                stone_debt = {}  # char_id -> stones_to_deduct
                for pool in pools:
                    ghosts   = json.loads(pool['ghosts_json'] or '[]')
                    defeated = set(json.loads(pool['defeated_ids'] or '[]'))
                    earned   = sum(g['stones'] for g in ghosts if g['idx'] in defeated)
                    if earned:
                        stone_debt[pool['char_id']] = stone_debt.get(pool['char_id'], 0) + earned

                # 2. 扣除灵石（不足则为负数债务），并记录撤回日志
                rollback_ts = int(time.time())
                for cid, stones in stone_debt.items():
                    run("UPDATE characters SET spirit_stones=spirit_stones-? WHERE id=?", (stones, cid))
                    char_row = q("SELECT name FROM characters WHERE id=?", (cid,), one=True)
                    run("""INSERT INTO gate_rollback_log (event_id, char_id, char_name, stones, created_at)
                           VALUES (?,?,?,?,?)""",
                        (rollback_ev_id, cid, char_row['name'] if char_row else '未知', stones, rollback_ts))

                # 3. 移除所有法则碎片
                shard_ids = [row['id'] for row in q("SELECT id FROM items WHERE name LIKE '%法则碎片'") or []]
                if shard_ids:
                    run(f"DELETE FROM inventory WHERE item_id IN ({','.join('?'*len(shard_ids))})", shard_ids)

                # 4. 撤回法则感悟（regen_mult ÷ GATE_INSIGHT_REGEN_MULT）并删记录
                insights = q("SELECT char_id FROM gate_law_insights")
                for ins in (insights or []):
                    run("UPDATE characters SET regen_mult=regen_mult/? WHERE id=?",
                        (GATE_INSIGHT_REGEN_MULT, ins['char_id']))
                run("DELETE FROM gate_law_insights")

                # 5. 撤回魔修状态（regen_mult ÷ GATE_DEMONIC_REGEN_MULT）并清零污染
                demonic = q("SELECT id FROM characters WHERE is_demonic=1 AND is_npc=0")
                for d in (demonic or []):
                    run("UPDATE characters SET regen_mult=regen_mult/? WHERE id=?",
                        (GATE_DEMONIC_REGEN_MULT, d['id']))
                run("UPDATE characters SET is_demonic=0, pollution=0 WHERE is_npc=0")

                # 6. 移除清污丹库存
                qwdan = q("SELECT id FROM items WHERE name='清污丹'", one=True)
                if qwdan:
                    run("DELETE FROM inventory WHERE item_id=?", (qwdan['id'],))

                # 7. 标记活动为已结束（如仍进行中）；分界线只在首次失活时打上，避免延迟撤回把边界打晚
                run("""UPDATE gate_event SET is_active=0,
                       actual_ended_at=COALESCE(actual_ended_at, ?) WHERE id=?""",
                    (rollback_ts, rollback_ev_id))

                # 8. 清空鬼魔池记录
                run("DELETE FROM gate_ghost_pool WHERE event_id=?", (rollback_ev_id,))

                total_players = len(stone_debt)
                total_stones  = sum(stone_debt.values())
                flash(f'已撤回活动 #{rollback_ev_id}：扣除 {total_players} 名玩家共 {total_stones} 灵石（不足者欠债），清除所有法则/魔修/污染/碎片收益。', 'success')

    ev   = q("SELECT * FROM gate_event WHERE is_active=1", one=True)
    past = q("SELECT * FROM gate_event WHERE is_active=0 ORDER BY id DESC LIMIT 5")
    demonic_chars = q("""SELECT name, realm_idx, pollution, age FROM characters
        WHERE is_demonic=1 AND is_npc=0 ORDER BY name""")
    pools_today = []
    if ev:
        today_str = time.strftime('%Y-%m-%d', time.localtime())
        pools_today_raw = q("""SELECT ggp.*, c.name, c.realm_idx, c.ghost_atk_charges, c.ghost_atk_ts
            FROM gate_ghost_pool ggp JOIN characters c ON c.id=ggp.char_id
            WHERE ggp.event_id=? AND ggp.day=? ORDER BY c.name""",
            (ev['id'], today_str))
        pools_today = []
        for row in pools_today_raw:
            d = dict(row)
            d['ghost_atk_charges'] = gate_calc_atk_charges(row)[0]  # 实时计算，而非读取陈旧的存储值
            pools_today.append(d)
        today_start_ts = int(time.mktime(time.strptime(today_str, '%Y-%m-%d')))
        gate_logs = q("""SELECT cl.char_id, c.name, cl.content, cl.created_at
            FROM char_logs cl JOIN characters c ON c.id=cl.char_id
            WHERE cl.type='combat' AND cl.created_at>=?
              AND (cl.content LIKE '%击败%' OR cl.content LIKE '%交手%' OR cl.content LIKE '%突破防线%')
            ORDER BY cl.created_at DESC LIMIT 200""", (today_start_ts,))
    rollback_rows = q("""SELECT event_id, char_name, stones, created_at
        FROM gate_rollback_log ORDER BY created_at DESC""")
    rollback_events = {}
    for r in (rollback_rows or []):
        rollback_events.setdefault(r['event_id'], {
            'event_id': r['event_id'], 'created_at': r['created_at'],
            'total_stones': 0, 'players': []
        })
        g = rollback_events[r['event_id']]
        g['total_stones'] += r['stones']
        g['players'].append({'name': r['char_name'], 'stones': r['stones']})
    rollback_history = sorted(rollback_events.values(), key=lambda g: -g['created_at'])
    rollback_total_stones = sum(g['total_stones'] for g in rollback_history)
    admin_action_log = q("""SELECT * FROM gate_admin_action_log ORDER BY created_at DESC LIMIT 30""")

    return render_template('admin/gate.html',
        ev=ev, past=past, demonic_chars=demonic_chars, pools_today=pools_today,
        gate_logs=gate_logs if ev else [],
        rollback_history=rollback_history, rollback_total_stones=rollback_total_stones,
        preview_rows=preview_rows, admin_action_log=admin_action_log,
        REALMS=REALMS, GATE_DURATION=GATE_DURATION)


@app.route('/admin/tianmo_clone_sim', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_tianmo_clone_sim():
    chars = q("""SELECT id, name, realm_idx FROM characters
                 WHERE is_npc=0 AND status='alive' ORDER BY realm_idx DESC, name""")
    result = None
    selected_id = None
    if request.method == 'POST':
        selected_id = int(request.form.get('char_id', 0))
        target = q("SELECT * FROM characters WHERE id=?", (selected_id,), one=True)
        if not target:
            flash('角色不存在', 'error')
        else:
            trials = max(20, min(500, int(request.form.get('trials', 300) or 300)))
            result = _simulate_tianmo_clone_attempts(dict(target), trials=trials)
            result['char_name'] = target['name']
    return render_template('admin/tianmo_clone_sim.html',
        chars=chars, result=result, selected_id=selected_id, REALMS=REALMS)

@app.route('/admin/tourney', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_tourney():
    if request.method == 'POST':
        act = request.form.get('action')
        if act == 'start':
            if q("SELECT 1 FROM tourney_event WHERE is_active=1", one=True):
                flash('已有进行中的靖世大典', 'error')
            else:
                now = now_ts()
                run("INSERT INTO tourney_event (started_at,ends_at,is_active) VALUES (?,?,1)",
                    (now, now + TOURNEY_DURATION))
                world_log_add('tourney',
                    '🏮 天魔既逐，四海清晏！向晚仙君开坛设宴，举办【靖世大典】：'
                    '设「问道棋盘」，人人掷骰前行，符丹器三厅各有道韵加持，'
                    '沿途机缘险境不断，登临问道台者皆获仙铸神兵！大典为期三日，速往【活动→靖世大典】！')
                flash('靖世大典已上线（为期 3 天），问道棋盘已铺开', 'success')
        elif act == 'settle':
            ev = q("SELECT * FROM tourney_event WHERE is_active=1", one=True)
            if ev:
                _settle_tourney(ev)
                flash('大典已提前结算，棋盘慰劳与论道虚影奖励均已发放', 'success')
            else:
                flash('当前无进行中的大典', 'error')
        elif act == 'cancel':
            ev = q("SELECT * FROM tourney_event WHERE is_active=1", one=True)
            if ev:
                run("UPDATE tourney_event SET is_active=0, settled=1 WHERE id=?", (ev['id'],))
                world_log_add('tourney', '🏮 靖世大典提前散场，仙君抚须而去，未留封赏。')
                flash('大典已取消（不发放任何奖励）', 'info')
            else:
                flash('当前无进行中的大典', 'error')
        return redirect(url_for('admin_tourney'))

    ev = q("SELECT * FROM tourney_event WHERE is_active=1 ORDER BY id DESC", one=True)
    if ev and now_ts() > ev['ends_at']:
        _settle_tourney(ev)
        ev = None
    board_players = []
    if ev:
        board_players = q("""SELECT tp.*, c.name, c.realm_idx FROM tourney_progress tp
            JOIN characters c ON c.id=tp.char_id
            WHERE tp.event_id=? ORDER BY tp.finished_at DESC, tp.position DESC""", (ev['id'],))
    past = q("SELECT * FROM tourney_event WHERE is_active=0 ORDER BY id DESC LIMIT 5")
    return render_template('admin/tourney.html', ev=ev, board_players=board_players, past=past,
        TOURNEY_ZONES=TOURNEY_ZONES, TOURNEY_BOARD_LENGTH=TOURNEY_BOARD_LENGTH,
        TOURNEY_ROLLS_PER_DAY=TOURNEY_ROLLS_PER_DAY, TOURNEY_FINISH_TITLE=TOURNEY_FINISH_TITLE,
        TOURNEY_FINISH_WEAPON=TOURNEY_FINISH_WEAPON, TOURNEY_CONTEST_TOP_N=TOURNEY_CONTEST_TOP_N,
        TOURNEY_CONTEST_PRIZES=TOURNEY_CONTEST_PRIZES, TOURNEY_DURATION=TOURNEY_DURATION)

@app.route('/admin/events', methods=['GET','POST'])
@login_required
@admin_required
def admin_events():
    if request.method == 'POST':
        act = request.form.get('action')
        if act == 'launch':
            tpl_idx = int(request.form.get('template', 0))
            days    = max(1, min(7, int(request.form.get('days', 2))))
            if 0 <= tpl_idx < len(BOSS_TEMPLATES):
                t = BOSS_TEMPLATES[tpl_idx]
                run("UPDATE world_events SET is_active=0 WHERE is_active=1")
                run("""INSERT INTO world_events
                    (name,description,icon,boss_hp_total,boss_hp_remaining,is_active,
                     ends_at,created_at,hit_drops_json,clear_drops_json,
                     clear_bonus_stones,clear_bonus_lingfu)
                    VALUES (?,?,?,?,?,1,?,?,?,'[]',?,?)""",
                    (t['name'], t['description'], t['icon'], t['hp'], t['hp'],
                     now_ts()+days*86400, now_ts(),
                     json.dumps(t['hit_drops']),
                     t['clear_stones'], t['clear_lingfu']))
                world_log_add('boss', f'⚠️ 世界Boss【{t["name"]}】现身！全服修士共同讨伐！')
                flash(f'已发布 Boss【{t["name"]}】，持续 {days} 天', 'success')
        elif act == 'end':
            eid   = int(request.form.get('event_id', 0))
            event = q("SELECT * FROM world_events WHERE id=?", (eid,), one=True)
            if event:
                # 关闭前先结算奖励
                if event['boss_hp_remaining'] <= 0:
                    # Boss 已被击杀，发放通关奖励
                    run("UPDATE world_events SET is_active=1 WHERE id=?", (eid,))
                    boss_check_clear(q("SELECT * FROM world_events WHERE id=?", (eid,), one=True))
                else:
                    # Boss 未被击杀，发安慰奖后关闭
                    run("UPDATE world_events SET is_active=1, ends_at=? WHERE id=?", (now_ts()-1, eid))
                    boss_check_expired()
                run("UPDATE world_events SET is_active=0 WHERE id=?", (eid,))
            flash('活动已结束，奖励已结算', 'success')
        elif act == 'execute_custom':
            eid     = int(request.form.get('event_id', 0))
            is_give = request.form.get('is_give', '1') == '1'
            label   = request.form.get('label', '操作')
            event   = q("SELECT * FROM world_events WHERE id=?", (eid,), one=True)
            if not event:
                flash('活动不存在', 'error')
            else:
                participants = q("SELECT char_id FROM event_hits WHERE event_id=?", (eid,))
                n = 0
                for p in participants:
                    cid = p['char_id']
                    try:
                        stones = max(0, int(request.form.get(f'stones_{cid}', 0)))
                        lingfu = max(0, int(request.form.get(f'lingfu_{cid}', 0)))
                    except Exception:
                        continue
                    if stones == 0 and lingfu == 0:
                        continue
                    if is_give:
                        run("UPDATE characters SET spirit_stones=spirit_stones+?, lingfu=lingfu+? WHERE id=?",
                            (stones, lingfu, cid))
                        log(cid, 'system', f'[{label}] 灵石 +{stones}，灵符 +{lingfu}')
                    else:
                        ch = q("SELECT spirit_stones, lingfu FROM characters WHERE id=?", (cid,), one=True)
                        if not ch: continue
                        st_a  = min(stones, ch['spirit_stones'] or 0)
                        lf_a  = min(lingfu, ch['lingfu'] or 0)
                        exp_d = (stones - st_a) * 100 + (lingfu - lf_a) * 500
                        run("UPDATE characters SET spirit_stones=spirit_stones-?, lingfu=lingfu-?, exp=MAX(0,exp-?) WHERE id=?",
                            (st_a, lf_a, exp_d, cid))
                        parts = [f'灵石 -{st_a}']
                        if lf_a:  parts.append(f'灵符 -{lf_a}')
                        if exp_d: parts.append(f'修为 -{exp_d}')
                        log(cid, 'system', f'[{label}] {"，".join(parts)}')
                    n += 1
                flash(f'已对 {n} 名玩家执行【{label}】', 'success')
        elif act == 'revoke_consolation':
            # 撤回安慰奖（30%奖励），times=多发次数
            eid   = int(request.form.get('event_id', 0))
            times = max(1, min(5, int(request.form.get('times', 1))))
            event = q("SELECT * FROM world_events WHERE id=?", (eid,), one=True)
            if not event:
                flash('活动不存在', 'error')
            else:
                participants = q("SELECT char_id, damage, hits FROM event_hits WHERE event_id=?", (eid,))
                total_damage = sum(p['damage'] for p in participants) or 1
                total_energy = sum(p['hits'] * BOSS_HIT_ENERGY for p in participants) or 1
                consolation_stones = int(event['clear_bonus_stones'] * 0.30)
                consolation_lingfu = int(event['clear_bonus_lingfu'] * 0.30)
                n = 0
                for p in participants:
                    dr = p['damage'] / total_damage
                    er = (p['hits'] * BOSS_HIT_ENERGY) / total_energy
                    ratio = (dr + er) / 2
                    stone_take  = int(consolation_stones * len(participants) * ratio * times)
                    lingfu_take = int(consolation_lingfu * len(participants) * ratio * times)
                    ch = q("SELECT spirit_stones, lingfu FROM characters WHERE id=?", (p['char_id'],), one=True)
                    if not ch: continue
                    stone_actual  = min(stone_take,  ch['spirit_stones'] or 0)
                    lingfu_actual = min(lingfu_take, ch['lingfu'] or 0)
                    exp_deduct    = (stone_take - stone_actual) * 100 + (lingfu_take - lingfu_actual) * 500
                    run("UPDATE characters SET spirit_stones=spirit_stones-?, lingfu=lingfu-?, exp=MAX(0,exp-?) WHERE id=?",
                        (stone_actual, lingfu_actual, exp_deduct, p['char_id']))
                    parts = [f'灵石 -{stone_actual}']
                    if lingfu_actual: parts.append(f'灵符 -{lingfu_actual}')
                    if exp_deduct: parts.append(f'修为 -{exp_deduct}')
                    log(p['char_id'], 'system', f'撤回 {times} 次多发安慰奖：{"，".join(parts)}')
                    n += 1
                flash(f'已撤回 {n} 名参与者的 {times} 次安慰奖', 'success')
        elif act == 'recall_boss_mail':
            # 撤回错发的通关奖励邮件：删除未领取邮件 + 扣回已直接发的灵符
            eid = int(request.form.get('event_id', 0))
            event = q("SELECT * FROM world_events WHERE id=?", (eid,), one=True)
            if not event:
                flash('活动不存在', 'error')
            else:
                subject_kw = f'妖王击杀奖励·{event["name"]}'
                # 找到所有未领取的该奖励邮件
                wrong_mails = q("SELECT * FROM mail WHERE subject=? AND claimed=0", (f'🏆 {subject_kw}',))
                del_count = 0
                for m in wrong_mails:
                    run("DELETE FROM mail WHERE id=?", (m['id'],))
                    del_count += 1
                # 扣回已直接发放的灵符（旧错误公式发放量）
                participants = q("SELECT char_id, damage, hits FROM event_hits WHERE event_id=?", (eid,))
                total_damage = sum(p['damage'] for p in participants) or 1
                total_energy = sum(p['hits'] * BOSS_HIT_ENERGY for p in participants) or 1
                n = len(participants)
                base_lingfu  = event['clear_bonus_lingfu']
                extra_lingfu = base_lingfu * n  # 旧错误公式
                lf_count = 0
                for p in participants:
                    dr = p['damage'] / total_damage
                    er = (p['hits'] * BOSS_HIT_ENERGY) / total_energy
                    ratio = (dr + er) / 2
                    wrong_lingfu = int(base_lingfu + extra_lingfu * ratio)  # 旧公式多发的量
                    if wrong_lingfu > 0:
                        ch = q("SELECT lingfu FROM characters WHERE id=?", (p['char_id'],), one=True)
                        actual = min(wrong_lingfu, ch['lingfu'] or 0) if ch else 0
                        if actual > 0:
                            run("UPDATE characters SET lingfu=lingfu-? WHERE id=?", (actual, p['char_id']))
                            log(p['char_id'], 'system', f'撤回错误通关奖励：灵符 -{actual}')
                            lf_count += 1
                flash(f'已删除 {del_count} 封未领取邮件，扣回 {lf_count} 名玩家的错误灵符', 'success')

        elif act == 'restore_revoke':
            # 仅恢复石头/灵符，不动修为（修为由管理员另行处理）
            eid   = int(request.form.get('event_id', 0))
            times = max(1, min(5, int(request.form.get('times', 1))))
            event = q("SELECT * FROM world_events WHERE id=?", (eid,), one=True)
            if not event:
                flash('活动不存在', 'error')
            else:
                participants = q("SELECT char_id, damage, hits FROM event_hits WHERE event_id=?", (eid,))
                total_damage = sum(p['damage'] for p in participants) or 1
                total_energy = sum(p['hits'] * BOSS_HIT_ENERGY for p in participants) or 1
                base_stones  = event['clear_bonus_stones']
                base_lingfu  = event['clear_bonus_lingfu']
                extra_stones = base_stones * len(participants)
                extra_lingfu = base_lingfu * len(participants)
                n = 0
                for p in participants:
                    dr = p['damage'] / total_damage
                    er = (p['hits'] * BOSS_HIT_ENERGY) / total_energy
                    ratio = (dr + er) / 2
                    stone_back  = int((base_stones + extra_stones * ratio) * times)
                    lingfu_back = int((base_lingfu + extra_lingfu * ratio) * times)
                    run("UPDATE characters SET spirit_stones=spirit_stones+?, lingfu=lingfu+? WHERE id=? AND status='alive'",
                        (stone_back, lingfu_back, p['char_id']))
                    log(p['char_id'], 'system',
                        f'管理员紧急恢复撤回操作：灵石 +{stone_back}，灵符 +{lingfu_back}')
                    n += 1
                flash(f'已恢复 {n} 名参与者灵石/灵符（不含修为）', 'success')
        elif act == 'deduct_exp':
            # 对指定活动参与者扣除多余修为（用于修复restore_revoke误加修为）
            eid      = int(request.form.get('event_id', 0))
            exp_rate = max(1, int(request.form.get('exp_rate', 100)))  # 每灵石折多少修为
            times    = max(1, min(5, int(request.form.get('times', 1))))
            event    = q("SELECT * FROM world_events WHERE id=?", (eid,), one=True)
            if not event:
                flash('活动不存在', 'error')
            else:
                participants = q("SELECT char_id, damage, hits FROM event_hits WHERE event_id=?", (eid,))
                total_damage = sum(p['damage'] for p in participants) or 1
                total_energy = sum(p['hits'] * BOSS_HIT_ENERGY for p in participants) or 1
                base_stones  = event['clear_bonus_stones']
                base_lingfu  = event['clear_bonus_lingfu']
                extra_stones = base_stones * len(participants)
                extra_lingfu = base_lingfu * len(participants)
                n = 0
                for p in participants:
                    dr = p['damage'] / total_damage
                    er = (p['hits'] * BOSS_HIT_ENERGY) / total_energy
                    ratio = (dr + er) / 2
                    stone_amt  = int((base_stones + extra_stones * ratio) * times)
                    lingfu_amt = int((base_lingfu + extra_lingfu * ratio) * times)
                    exp_deduct = stone_amt * exp_rate + lingfu_amt * 500
                    run("UPDATE characters SET exp=MAX(0,exp-?) WHERE id=?", (exp_deduct, p['char_id']))
                    log(p['char_id'], 'system', f'扣除误加修为：修为 -{exp_deduct}')
                    n += 1
                flash(f'已从 {n} 名参与者扣除多余修为', 'success')
        elif act == 'revoke_rewards':
            eid   = int(request.form.get('event_id', 0))
            times = max(1, min(5, int(request.form.get('times', 1))))
            event = q("SELECT * FROM world_events WHERE id=?", (eid,), one=True)
            if not event:
                flash('活动不存在', 'error')
            else:
                participants = q("SELECT char_id, damage, hits FROM event_hits WHERE event_id=?", (eid,))
                if not participants:
                    flash('无参与者记录', 'error')
                else:
                    total_damage = sum(p['damage'] for p in participants) or 1
                    total_energy = sum(p['hits'] * BOSS_HIT_ENERGY for p in participants) or 1
                    base_stones  = event['clear_bonus_stones']
                    base_lingfu  = event['clear_bonus_lingfu']
                    extra_stones = base_stones * len(participants)
                    extra_lingfu = base_lingfu * len(participants)
                    n_clawed = 0
                    for p in participants:
                        dr = p['damage'] / total_damage
                        er = (p['hits'] * BOSS_HIT_ENERGY) / total_energy
                        ratio = (dr + er) / 2
                        stone_take  = int((base_stones + extra_stones * ratio) * times)
                        lingfu_take = int((base_lingfu + extra_lingfu * ratio) * times)
                        ch = q("SELECT spirit_stones, lingfu, exp FROM characters WHERE id=?",
                               (p['char_id'],), one=True)
                        if not ch: continue
                        # 灵石：不足部分转修为（1灵石=100修为）
                        stone_actual = min(stone_take, ch['spirit_stones'] or 0)
                        stone_exp    = (stone_take - stone_actual) * 100
                        # 灵符：不足部分转修为（1灵符=500修为）
                        lingfu_actual = min(lingfu_take, ch['lingfu'] or 0)
                        lingfu_exp    = (lingfu_take - lingfu_actual) * 500
                        exp_deduct    = stone_exp + lingfu_exp
                        run("UPDATE characters SET spirit_stones=spirit_stones-?, lingfu=lingfu-?, exp=MAX(0,exp-?) WHERE id=?",
                            (stone_actual, lingfu_actual, exp_deduct, p['char_id']))
                        parts = [f'灵石 -{stone_actual}']
                        if lingfu_actual: parts.append(f'灵符 -{lingfu_actual}')
                        if exp_deduct: parts.append(f'修为 -{exp_deduct}（折算不足部分）')
                        log(p['char_id'], 'system',
                            f'管理员撤回 {times} 次重复奖励：{"，".join(parts)}')
                        n_clawed += 1
                    flash(f'已从 {n_clawed} 名参与者撤回 {times} 次奖励', 'success')
        elif act == 'resend_rewards':
            # 对已关闭活动补发奖励（boss 已击杀的情况）
            eid   = int(request.form.get('event_id', 0))
            event = q("SELECT * FROM world_events WHERE id=?", (eid,), one=True)
            if not event:
                flash('活动不存在', 'error')
            elif event['boss_hp_remaining'] > 0:
                # 未击杀：临时激活让 boss_check_expired 处理
                run("UPDATE world_events SET is_active=1, ends_at=? WHERE id=?", (now_ts()-1, eid))
                boss_check_expired()
                run("UPDATE world_events SET is_active=0 WHERE id=?", (eid,))
                flash('已补发安慰奖（Boss 未击杀）', 'success')
            else:
                # 已击杀：发通关奖励
                run("UPDATE world_events SET is_active=1 WHERE id=?", (eid,))
                boss_check_clear(q("SELECT * FROM world_events WHERE id=?", (eid,), one=True))
                run("UPDATE world_events SET is_active=0 WHERE id=?", (eid,))
                flash('已补发通关奖励（Boss 已击杀）', 'success')
        elif act == 'update_boss':
            eid = int(request.form.get('event_id', 0))
            stones = int(request.form.get('clear_stones', 0))
            lingfu = int(request.form.get('clear_lingfu', 0))
            hp = int(request.form.get('boss_hp_remaining', 0))
            if eid:
                updates = []
                if stones >= 0:
                    run("UPDATE world_events SET clear_bonus_stones=? WHERE id=?", (stones, eid))
                    updates.append(f'灵石 {stones}')
                if lingfu >= 0:
                    run("UPDATE world_events SET clear_bonus_lingfu=? WHERE id=?", (lingfu, eid))
                    updates.append(f'灵符 {lingfu}')
                if hp >= 0:
                    run("UPDATE world_events SET boss_hp_remaining=? WHERE id=?", (hp, eid))
                    updates.append(f'HP {hp}')
                if updates:
                    flash(f'已修改：{", ".join(updates)}', 'success')
        elif act == 'grant_lingfu':
            char_name = request.form.get('char_name','').strip()
            amt = int(request.form.get('amount', 10))
            ch = q("SELECT id FROM characters WHERE name=?", (char_name,), one=True)
            if ch:
                run("UPDATE characters SET lingfu=lingfu+? WHERE id=?", (amt, ch['id']))
                flash(f'已赠予【{char_name}】{amt} 灵符', 'success')
            else:
                flash('角色不存在', 'error')

    event   = get_active_event()
    history = q("SELECT * FROM world_events ORDER BY created_at DESC LIMIT 10")
    return render_template('admin/events.html', event=event, history=history,
        BOSS_TEMPLATES=BOSS_TEMPLATES)

@app.route('/admin/events/preview')
@login_required
@admin_required
def admin_events_preview():
    """奖励预览页：展示每人发放/撤回方案，确认后才执行。"""
    eid    = int(request.args.get('event_id', 0))
    action = request.args.get('action', '')
    times  = max(1, min(5, int(request.args.get('times', 1))))
    event  = q("SELECT * FROM world_events WHERE id=?", (eid,), one=True)
    if not event:
        flash('活动不存在', 'error')
        return redirect(url_for('admin_events'))

    participants = q("""SELECT eh.char_id, eh.damage, eh.hits,
            c.name, c.spirit_stones, c.lingfu
        FROM event_hits eh JOIN characters c ON c.id=eh.char_id
        WHERE eh.event_id=? ORDER BY eh.damage DESC""", (eid,))
    if not participants:
        flash('无参与者记录', 'error')
        return redirect(url_for('admin_events'))

    total_dmg = sum(p['damage'] for p in participants) or 1
    total_en  = sum(p['hits'] * BOSS_HIT_ENERGY for p in participants) or 1
    n = len(participants)

    # 计算每人金额
    base_st = event['clear_bonus_stones']
    base_lf = event['clear_bonus_lingfu']
    rows = []
    total_stones = total_lingfu = 0
    for p in participants:
        dr    = p['damage'] / total_dmg
        er    = (p['hits'] * BOSS_HIT_ENERGY) / total_en
        ratio = (dr + er) / 2
        if action == 'resend_clear':
            st = int((base_st + base_st * n * ratio))
            lf = int((base_lf + base_lf * n * ratio))
        elif action in ('resend_consolation', 'revoke_consolation'):
            st = int(base_st * 0.30 * n * ratio * times)
            lf = int(base_lf * 0.30 * n * ratio * times)
        elif action == 'revoke_rewards':
            st = int((base_st + base_st * n * ratio) * times)
            lf = int((base_lf + base_lf * n * ratio) * times)
        elif action == 'restore_revoke':
            st = int((base_st + base_st * n * ratio) * times)
            lf = int((base_lf + base_lf * n * ratio) * times)
        else:
            st = lf = 0
        total_stones += st
        total_lingfu += lf
        rows.append({'char_id': p['char_id'], 'name': p['name'], 'stones': st, 'lingfu': lf,
                     'cur_stones': p['spirit_stones'], 'cur_lingfu': p['lingfu'] or 0,
                     'damage': p['damage']})

    ACTION_LABELS = {
        'resend_clear':       ('补发通关奖励', True),
        'resend_consolation': ('补发安慰奖（30%）', True),
        'revoke_consolation': ('撤回安慰奖（30%）', False),
        'revoke_rewards':     ('撤回通关奖励', False),
        'restore_revoke':     ('恢复误撤回', True),
    }
    label, is_give = ACTION_LABELS.get(action, (action, True))

    return render_template('admin/events_preview.html',
        event=event, rows=rows, action=action, times=times,
        label=label, is_give=is_give,
        total_stones=total_stones, total_lingfu=total_lingfu)

@app.route('/admin/gacha', methods=['GET','POST'])
@login_required
@admin_required
def admin_gacha():
    if request.method == 'POST':
        act = request.form.get('action')
        if act == 'create_pool':
            name = request.form.get('name','').strip()
            desc = request.form.get('description','').strip()
            icon = request.form.get('icon','🎴').strip()[:2]
            cost = max(1, int(request.form.get('cost', 10)))
            pity = max(10, int(request.form.get('pity_max', 90)))
            if name:
                run("INSERT INTO gacha_pools (name,description,icon,cost,pity_max,is_active,created_at) VALUES (?,?,?,?,?,1,?)",
                    (name, desc, icon, cost, pity, now_ts()))
                flash(f'卡池【{name}】已创建', 'success')
        elif act == 'toggle_pool':
            run("UPDATE gacha_pools SET is_active=1-is_active WHERE id=?",
                (int(request.form.get('pool_id',0)),))
            flash('卡池状态已切换', 'success')
        elif act == 'add_item':
            pid    = int(request.form.get('pool_id', 0))
            itype  = request.form.get('item_type', 'item')
            iid    = int(request.form.get('item_id', 0))
            iname  = request.form.get('item_name','').strip()
            rarity = request.form.get('rarity','common')
            weight = max(1, int(request.form.get('weight', 100)))
            run("INSERT INTO gacha_pool_items (pool_id,item_type,item_id,item_name,rarity,weight,is_active) VALUES (?,?,?,?,?,?,1)",
                (pid, itype, iid, iname, rarity, weight))
            flash('奖品已添加', 'success')
        elif act == 'toggle_item':
            run("UPDATE gacha_pool_items SET is_active=1-is_active WHERE id=?",
                (int(request.form.get('item_id',0)),))

    pools     = q("SELECT * FROM gacha_pools ORDER BY id")
    all_items = q("SELECT * FROM items WHERE is_active=1 ORDER BY type,name")
    all_pets  = q("SELECT * FROM pet_types WHERE is_active=1 ORDER BY rarity,name")
    pool_items = {}
    for p in pools:
        pool_items[p['id']] = q("SELECT * FROM gacha_pool_items WHERE pool_id=? ORDER BY rarity,weight DESC", (p['id'],))
    return render_template('admin/gacha.html', pools=pools, pool_items=pool_items,
        all_items=all_items, all_pets=all_pets)

COMPANION_EFFECT_KEYS = [
    'exp_pct', 'atk_pct', 'def_pct', 'hp_pct', 'energy_max',
    'alchemy_bonus', 'forge_bonus', 'explore_bonus', 'stones_pct',
    'affinity_pct', 'crit_rate', 'dodge_rate', 'breakthrough_bonus',
    'fulu_bonus', 'spirit_regen_pct',
]

@app.route('/admin/companions', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_companions():
    """伙伴清单：只负责"造一个伙伴"，不涉及具体进哪个池子。"""
    if request.method == 'POST':
        key   = request.form.get('key', '').strip()
        name  = request.form.get('name', '').strip()
        title = request.form.get('title', '').strip()
        rarity = request.form.get('rarity', 'ssr')
        desc  = request.form.get('description', '').strip()
        effects = {}
        for ek in COMPANION_EFFECT_KEYS:
            v = request.form.get(f'eff_{ek}', '').strip()
            if v:
                try:
                    effects[ek] = float(v) if '.' in v else int(v)
                except ValueError:
                    pass
        if not key or not name or not rarity:
            flash('请填写 key、名称、稀有度', 'error')
        elif not re.match(r'^[a-z0-9_]+$', key):
            flash('key 只能用小写字母/数字/下划线', 'error')
        elif key in COMPANION_MAP:
            flash(f'key「{key}」已存在（可能是内置伙伴或已添加过）', 'error')
        else:
            run("""INSERT INTO custom_companions (key,name,title,rarity,description,effects_json,created_at)
                   VALUES (?,?,?,?,?,?,?)""",
                (key, name, title, rarity, desc, json.dumps(effects, ensure_ascii=False), now_ts()))
            _register_companion(key, name, title, rarity, desc, effects)
            msg = f'已新增伙伴【{name}】到清单。'
            default_pool = q("SELECT id, name FROM custom_pools WHERE is_default=1", one=True)
            if default_pool:
                run("INSERT OR IGNORE INTO custom_pool_companions (pool_id,companion_key,weight) VALUES (?,?,4)",
                    (default_pool['id'], key))
                _load_custom_pools()
                msg += f' 已自动加入默认池【{default_pool["name"]}】。'
            else:
                msg += ' 当前没有设默认池，去"池子管理"把它加进某个池子才能被抽到。'
            flash(msg, 'success')

    custom_list = q("SELECT * FROM custom_companions ORDER BY created_at DESC")
    return render_template('admin/companions.html',
        custom_list=custom_list, COMPANION_EFFECT_KEYS=COMPANION_EFFECT_KEYS,
        COMPANION_RARITY_LABEL=COMPANION_RARITY_LABEL)

@app.route('/admin/companion_pools', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_companion_pools():
    """池子管理：新建限定池、设默认池、往池子里加/移除伙伴。"""
    if request.method == 'POST':
        act = request.form.get('action')
        if act == 'create_pool':
            name = request.form.get('name', '').strip()
            icon = request.form.get('icon', '🌟').strip()[:2] or '🌟'
            cost = max(1, int(request.form.get('cost', 280) or 280))
            pity_max = max(1, int(request.form.get('pity_max', 40) or 40))
            desc = request.form.get('description', '').strip()
            is_default = 1 if request.form.get('is_default') else 0
            include_regular = 1 if request.form.get('include_regular', '1') else 0
            duration_days = request.form.get('duration_days', '').strip()
            ends_at = now_ts() + int(float(duration_days) * 86400) if duration_days else None
            if not name:
                flash('请填写池子名称', 'error')
            else:
                if is_default:
                    run("UPDATE custom_pools SET is_default=0")
                old_default = q("SELECT id FROM custom_pools WHERE is_default=1", one=True)
                cur = run("""INSERT INTO custom_pools (name,icon,cost,pity_max,description,is_active,is_default,include_regular,ends_at,created_at)
                       VALUES (?,?,?,?,?,1,?,?,?,?)""",
                    (name, icon, cost, pity_max, desc, is_default, include_regular, ends_at, now_ts()))
                new_pool_id = cur.lastrowid
                copied = 0
                if old_default:
                    members = q("SELECT companion_key, weight FROM custom_pool_companions WHERE pool_id=?",
                                (old_default['id'],))
                    for m in members:
                        run("""INSERT OR IGNORE INTO custom_pool_companions (pool_id,companion_key,weight)
                               VALUES (?,?,?)""", (new_pool_id, m['companion_key'], m['weight']))
                        copied += 1
                _load_custom_pools()
                flash(f'已创建池子【{name}】{"（已设为默认池）" if is_default else ""}'
                      f'{f"，{duration_days}天后自动关闭" if ends_at else ""}'
                      f'{f"，并复制了原默认池的 {copied} 个成员" if copied else ""}', 'success')
        elif act == 'toggle_pool':
            run("UPDATE custom_pools SET is_active=1-is_active WHERE id=?",
                (int(request.form.get('pool_id', 0)),))
            _load_custom_pools()
        elif act == 'set_duration':
            pool_id = int(request.form.get('pool_id', 0))
            days = request.form.get('duration_days', '').strip()
            if days:
                ends_at = now_ts() + int(float(days) * 86400)
                run("UPDATE custom_pools SET ends_at=?, is_active=1 WHERE id=?", (ends_at, pool_id))
                flash(f'已设置 {days} 天后自动关闭', 'success')
            else:
                run("UPDATE custom_pools SET ends_at=NULL WHERE id=?", (pool_id,))
                flash('已取消自动关闭（不限时）', 'success')
            _load_custom_pools()
        elif act == 'set_default':
            run("UPDATE custom_pools SET is_default=0")
            run("UPDATE custom_pools SET is_default=1 WHERE id=?",
                (int(request.form.get('pool_id', 0)),))
            _load_custom_pools()
            flash('默认池已切换', 'success')
        elif act == 'add_member':
            pool_id = int(request.form.get('pool_id', 0))
            ckey    = request.form.get('companion_key', '').strip()
            weight  = max(1, int(request.form.get('weight', 4) or 4))
            if ckey not in COMPANION_MAP:
                flash('伙伴不存在，请先去"伙伴清单"创建', 'error')
            else:
                run("""INSERT INTO custom_pool_companions (pool_id,companion_key,weight) VALUES (?,?,?)
                       ON CONFLICT(pool_id,companion_key) DO UPDATE SET weight=excluded.weight""",
                    (pool_id, ckey, weight))
                _load_custom_pools()
                flash(f'已把【{COMPANION_MAP[ckey][1]}】加入池子（权重{weight}）', 'success')
        elif act == 'remove_member':
            run("DELETE FROM custom_pool_companions WHERE id=?",
                (int(request.form.get('member_id', 0)),))
            _load_custom_pools()
            flash('已从池子移除', 'success')

    pools = q("SELECT * FROM custom_pools ORDER BY id")
    pool_members = {}
    for p in pools:
        pool_members[p['id']] = q("""SELECT * FROM custom_pool_companions
            WHERE pool_id=? ORDER BY weight DESC""", (p['id'],))
    roster = sorted(COMPANION_MAP.values(), key=lambda c: c[0])
    return render_template('admin/companion_pools.html',
        pools=pools, pool_members=pool_members, roster=roster,
        COMPANION_MAP=COMPANION_MAP, COMPANION_RARITY_LABEL=COMPANION_RARITY_LABEL,
        regular_count=len(_COMP_REGULAR), material_count=len(_MAT))

@app.route('/admin/npcs', methods=['GET','POST'])
@login_required
@admin_required
def admin_npcs():
    if request.method == 'POST':
        act = request.form.get('action')
        if act == 'add':
            name   = request.form.get('name','').strip()[:12]
            root   = request.form.get('spirit_root','三灵根')
            realm  = int(request.form.get('realm_idx', 9))
            bio    = request.form.get('bio','').strip()[:100]
            if name and not q("SELECT 1 FROM characters WHERE name=?", (name,), one=True):
                db = get_db()
                cur = db.execute("INSERT INTO users (username,password_hash,role,created_at) VALUES (?,?,'npc',?)",
                    (f'__npc_{name}_{now_ts()}', '!', now_ts()))
                uid = cur.lastrowid
                max_hp, _, _ = realm_stats(realm)
                elems = rand_elements(root)
                db.execute("""INSERT INTO characters
                    (user_id,name,spirit_root,elements,realm_idx,exp,energy,energy_updated,
                     hp,hp_updated,spirit_stones,age,age_updated,status,is_npc,bio)
                    VALUES (?,?,?,?,?,?,100,?,?,?,0,?,?,'alive',1,?)""",
                    (uid, name, root, json.dumps(elems), realm, REALMS[realm]['exp'],
                     now_ts(), max_hp, now_ts(), START_AGE+random.randint(20,200), now_ts(), bio))
                db.commit()
                flash(f'NPC【{name}】已添加', 'success')
            else:
                flash('名字重复或为空', 'error')
        elif act == 'revive':
            nid = int(request.form.get('npc_id', 0))
            npc = q("SELECT * FROM characters WHERE id=? AND is_npc=1", (nid,), one=True)
            if npc:
                max_hp, _, _ = realm_stats(npc['realm_idx'])
                run("UPDATE characters SET status='alive', age=?, age_updated=?, hp=? WHERE id=?",
                    (START_AGE+20, now_ts(), max_hp, nid))
                flash(f'NPC【{npc["name"]}】已复活', 'success')
        elif act == 'delete':
            nid = int(request.form.get('npc_id', 0))
            npc = q("SELECT name FROM characters WHERE id=? AND is_npc=1", (nid,), one=True)
            if npc:
                run("UPDATE characters SET daolv_id=NULL WHERE daolv_id=?", (nid,))
                run("DELETE FROM sect_members WHERE char_id=?", (nid,))
                run("DELETE FROM characters WHERE id=?", (nid,))
                flash(f'NPC【{npc["name"]}】已删除', 'success')

    npcs = q("SELECT * FROM characters WHERE is_npc=1 ORDER BY status, realm_idx DESC")
    return render_template('admin/npcs.html', npcs=npcs, REALMS=REALMS, SPIRIT_ROOTS=SPIRIT_ROOTS)

# ── 后台：礼包码管理 ────────────────────────────────────────────────────────────

def _gen_gift_code():
    import string
    chars = string.ascii_uppercase + string.digits
    return ''.join(random.choices(chars, k=12))

@app.route('/admin/impersonate/<int:cid>', methods=['POST'])
@login_required
@admin_required
def admin_impersonate(cid):
    target = q("SELECT u.id, u.username, u.role FROM characters c JOIN users u ON u.id=c.user_id WHERE c.id=?",
               (cid,), one=True)
    if not target:
        flash('角色不存在', 'error')
        return redirect(url_for('admin_players'))
    S['admin_uid']   = S['uid']
    S['admin_uname'] = S['uname']
    S['uid']   = target['id']
    S['uname'] = target['username']
    S['role']  = target['role']
    return redirect(url_for('dashboard'))

@app.route('/admin/unimpersonate', methods=['POST'])
@login_required
def admin_unimpersonate():
    if 'admin_uid' not in S:
        return redirect(url_for('dashboard'))
    S['uid']   = S.pop('admin_uid')
    S['uname'] = S.pop('admin_uname')
    S['role']  = 'admin'
    return redirect(url_for('admin'))

@app.route('/admin/logs')
@login_required
@admin_required
def admin_logs():
    type_filter = request.args.get('type', '')
    name_filter = request.args.get('name', '').strip()
    params = []
    conds  = ["c.is_npc=0"]
    if type_filter:
        conds.append("l.type=?")
        params.append(type_filter)
    if name_filter:
        conds.append("c.name LIKE ?")
        params.append(f'%{name_filter}%')
    where = ' AND '.join(conds)
    logs = q(f"""SELECT l.*, c.name as char_name
        FROM char_logs l JOIN characters c ON c.id=l.char_id
        WHERE {where}
        ORDER BY l.created_at DESC LIMIT 100""", params)
    types = [r['type'] for r in q("SELECT DISTINCT type FROM char_logs ORDER BY type")]
    return render_template('admin/logs.html', logs=logs, types=types,
                           type_filter=type_filter, name_filter=name_filter)


@app.route('/admin/snapshots')
@login_required
@admin_required
def admin_snapshots():
    try:
        get_db().execute("CREATE TABLE IF NOT EXISTS char_snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, char_name TEXT NOT NULL, realm_idx INTEGER NOT NULL, exp INTEGER NOT NULL, spirit_stones INTEGER NOT NULL, lingfu INTEGER NOT NULL)")
        get_db().execute("CREATE INDEX IF NOT EXISTS idx_snap_ts ON char_snapshots(ts)")
    except Exception:
        pass
    char_name = request.args.get('name', '').strip()
    # 所有存档时间点（去重）
    snap_times = q("SELECT DISTINCT ts FROM char_snapshots ORDER BY ts DESC LIMIT 100")
    # 指定玩家的存档历史
    char_snaps = []
    if char_name:
        char_snaps = q("""SELECT ts, realm_idx, exp, spirit_stones, lingfu
            FROM char_snapshots WHERE char_name=? ORDER BY ts DESC LIMIT 50""", (char_name,))
    # 最新一次存档的全部玩家数据
    latest_ts = snap_times[0]['ts'] if snap_times else None
    latest_snap = []
    if latest_ts:
        latest_snap = q("""SELECT char_name, realm_idx, exp, spirit_stones, lingfu
            FROM char_snapshots WHERE ts=? ORDER BY exp DESC""", (latest_ts,))
    return render_template('admin/snapshots.html',
        snap_times=snap_times, char_name=char_name,
        char_snaps=char_snaps, latest_snap=latest_snap, latest_ts=latest_ts)


@app.route('/admin/gift_codes', methods=['GET','POST'])
@login_required
@admin_required
def admin_gift_codes():
    if request.method == 'POST':
        act = request.form.get('action')

        if act == 'create':
            code_str  = request.form.get('code','').strip().upper()
            if not code_str:
                code_str = _gen_gift_code()
                while q("SELECT 1 FROM gift_codes WHERE code=?", (code_str,), one=True):
                    code_str = _gen_gift_code()
            elif q("SELECT 1 FROM gift_codes WHERE code=?", (code_str,), one=True):
                flash('该码已存在', 'error')
                return redirect(url_for('admin_gift_codes'))

            desc      = request.form.get('desc','').strip()[:40]
            max_uses  = max(1, int(request.form.get('max_uses', 1) or 1))
            stones    = max(0, int(request.form.get('stones', 0) or 0))
            exp_val   = max(0, int(request.form.get('exp', 0) or 0))
            expires   = 0
            exp_days  = request.form.get('expires_days','').strip()
            if exp_days:
                expires = now_ts() + int(exp_days) * 86400

            # 物品
            items_json = []
            for i in range(1, 6):
                iname = request.form.get(f'item_name_{i}','').strip()
                iqty  = int(request.form.get(f'item_qty_{i}', 1) or 1)
                if iname and q("SELECT 1 FROM items WHERE name=? AND is_active=1", (iname,), one=True):
                    items_json.append({'name': iname, 'qty': max(1, iqty)})

            rwd = {}
            if stones:  rwd['spirit_stones'] = stones
            if exp_val: rwd['exp'] = exp_val
            if items_json: rwd['items'] = items_json

            run("""INSERT INTO gift_codes (code,description,rewards_json,max_uses,used_count,expires_at,is_active,created_at)
                VALUES (?,?,?,?,0,?,1,?)""",
                (code_str, desc, json.dumps(rwd), max_uses, expires, now_ts()))
            flash(f'礼包码【{code_str}】已创建', 'success')

        elif act == 'toggle':
            gid = int(request.form.get('gift_id', 0))
            gc  = q("SELECT is_active FROM gift_codes WHERE id=?", (gid,), one=True)
            if gc:
                run("UPDATE gift_codes SET is_active=? WHERE id=?", (1 - gc['is_active'], gid))
                flash('状态已切换', 'success')

        elif act == 'delete':
            gid = int(request.form.get('gift_id', 0))
            run("DELETE FROM gift_code_uses WHERE code_id=?", (gid,))
            run("DELETE FROM gift_codes WHERE id=?", (gid,))
            flash('已删除', 'success')

    codes = q("""SELECT gc.*,
        (SELECT COUNT(*) FROM gift_code_uses WHERE code_id=gc.id) as use_cnt
        FROM gift_codes gc ORDER BY gc.created_at DESC LIMIT 200""")
    return render_template('admin/gift_codes.html', codes=codes)

